def default_projects_dir() -> str:
    return get_projects_root_directory(
        st.session_state.get("settings", {}),
        os.path.join(APP_ROOT, DEFAULT_PROJECTS_DIR_NAME),
    )


def default_new_project_dir(project_name: str = "MyProject") -> str:
    clean_name = str(project_name or "").strip() or "MyProject"
    expanded_name = os.path.expanduser(clean_name)
    if os.path.isabs(expanded_name):
        return os.path.abspath(expanded_name)
    return os.path.abspath(os.path.join(default_projects_dir(), expanded_name))

# --- State Management ---
def normalize_agraph_selection(return_value, project):
    if not return_value:
        return []

    raw_items = return_value if isinstance(return_value, list) else [return_value]
    ids = []

    for item in raw_items:
        if isinstance(item, str):
            ids.append(item)
        elif isinstance(item, dict):
            if "id" in item:
                ids.append(item["id"])
            elif "node" in item:
                ids.append(item["node"])
        else:
            if hasattr(item, "id"):
                ids.append(item.id)

    valid_ids = []
    for nid in ids:
        if nid in project.nodes and nid not in valid_ids:
            valid_ids.append(nid)

    return valid_ids

def sanitize_selected_node_ids(project=None):
    project = project or st.session_state.get("project")
    valid_project_nodes = getattr(project, "nodes", {}) if project else {}
    selected_node_ids = st.session_state.get("selected_node_ids", [])

    if not valid_project_nodes or not selected_node_ids:
        st.session_state.selected_node_ids = []
        return []

    valid_ids = []
    for nid in selected_node_ids:
        if nid in valid_project_nodes and nid not in valid_ids:
            valid_ids.append(nid)

    st.session_state.selected_node_ids = valid_ids
    return valid_ids

