def open_management_workspace(target) -> bool:
    clean_target = normalize_management_workspace_target(target)
    if not clean_target:
        reset_management_workspace_session_state()
        return False
    st.session_state[ACTIVE_MANAGEMENT_WORKSPACE_KEY] = clean_target
    return True


def get_active_management_workspace() -> str:
    stored_target = st.session_state.get(ACTIVE_MANAGEMENT_WORKSPACE_KEY, "")
    clean_target = normalize_management_workspace_target(stored_target)
    if stored_target != clean_target:
        st.session_state[ACTIVE_MANAGEMENT_WORKSPACE_KEY] = clean_target
    return clean_target


def render_management_workspace_launchers() -> None:
    st.sidebar.markdown("---")
    st.sidebar.subheader("Workspace")
    st.sidebar.caption("Open a dedicated management or configuration workspace.")
    launchers = (
        (
            "Project Management",
            "project_management",
            "open_project_management_workspace",
        ),
        (
            "Module / Attribute Authoring",
            "module_attribute_authoring",
            "open_module_attribute_authoring_workspace",
        ),
        (
            "ComfyUI Settings",
            "comfyui_settings",
            "open_comfyui_settings_workspace",
        ),
    )
    for label, target, widget_key in launchers:
        if st.sidebar.button(label, key=widget_key, width="stretch"):
            open_management_workspace(target)
            st.rerun()


def render_management_workspace_shell(target: str) -> None:
    workspace = MANAGEMENT_WORKSPACE_TARGETS[target]
    header_col, close_col = st.columns([4, 1])
    with header_col:
        st.title(workspace["title"])
        st.caption("Session-only workspace")
    with close_col:
        if st.button(
            "Back",
            key="close_active_management_workspace",
            width="stretch",
        ):
            reset_management_workspace_session_state()
            st.rerun()

    if target == "project_management":
        render_project_management_workspace()
        return

    if target == "module_attribute_authoring":
        render_module_attribute_authoring_workspace()
        return

    if target == "module_attribute_apply":
        render_module_attribute_apply_workspace()
        return

    if target == "comfyui_settings":
        render_comfyui_settings_workspace()
        return


def _invalidate_lightweight_fork_discovery_cache() -> None:
    st.session_state.pop("lightweight_fork_discovery_cache", None)
    generation = st.session_state.get("lightweight_fork_discovery_refresh_generation", 0)
    st.session_state.lightweight_fork_discovery_refresh_generation = int(generation or 0) + 1


def request_project_directory_discovery_refresh() -> None:
    generation = st.session_state.get(
        "project_directory_discovery_refresh_generation",
        0,
    )
    st.session_state.project_directory_discovery_refresh_generation = (
        int(generation or 0) + 1
    )


def _get_project_directory_discovery_snapshot(project_root: str) -> dict:
    snapshot, cache_entry, _cache_hit = resolve_cached_project_discovery(
        st.session_state.get("project_directory_discovery_cache"),
        root=project_root,
        refresh_generation=st.session_state.get(
            "project_directory_discovery_refresh_generation",
            0,
        ),
        current_open_project_path=st.session_state.get("current_project_path", ""),
    )
    st.session_state.project_directory_discovery_cache = cache_entry
    return snapshot


def _normalize_project_directory_browser_selection(
    project_root: str,
    project_entries: list[dict],
) -> str:
    normalized_root = normalize_project_discovery_path(project_root)
    if st.session_state.get("project_directory_selection_root") != normalized_root:
        st.session_state.project_directory_selection_root = normalized_root
        st.session_state.pop("project_directory_selected_path", None)

    available_paths = [
        str(entry.get("project_path") or "")
        for entry in project_entries
        if str(entry.get("project_path") or "")
    ]
    selected_path = str(
        st.session_state.get("project_directory_selected_path", "") or ""
    )
    if selected_path not in available_paths:
        selected_path = available_paths[0] if available_paths else ""
        if selected_path:
            st.session_state.project_directory_selected_path = selected_path
        else:
            st.session_state.pop("project_directory_selected_path", None)
    return selected_path


def render_project_directory_browser() -> None:
    st.markdown("**Projectディレクトリから選択**")
    project_root = normalize_project_discovery_path(default_projects_dir())
    st.caption("Project root")
    st.code(project_root or default_projects_dir(), language="text")

    if st.button(
        "一覧を更新",
        key="refresh_project_directory_browser",
    ):
        request_project_directory_discovery_refresh()

    snapshot = _get_project_directory_discovery_snapshot(project_root)
    counts = snapshot.get("counts", {})
    st.caption(
        f"Projects: {int(counts.get('normal_projects', 0) or 0)} / "
        f"Derived Projects: {int(counts.get('fork_projects', 0) or 0)}"
    )

    status = snapshot.get("status")
    if status == "missing":
        st.info("Project rootはまだ存在しません。New Project作成時に作成されます。")
    elif status == "not_directory":
        st.warning("Project rootがディレクトリではありません。")
    elif not snapshot.get("valid"):
        st.warning(format_core_message_for_display(snapshot.get("reason")) or "Project rootを読み取れませんでした。")

    project_entries = list(snapshot.get("projects") or [])
    selected_path = _normalize_project_directory_browser_selection(
        project_root,
        project_entries,
    )
    labels_by_path = {
        entry.get("project_path"): entry.get("display_label")
        for entry in project_entries
    }
    selected_path = st.selectbox(
        "Project選択",
        [entry.get("project_path") for entry in project_entries],
        format_func=lambda path: labels_by_path.get(path, path),
        key="project_directory_selected_path",
        disabled=not bool(project_entries),
        label_visibility="collapsed",
    )
    selected_entry = next(
        (
            entry
            for entry in project_entries
            if entry.get("project_path") == selected_path
        ),
        None,
    )

    selected_open_path = ""
    selected_open_error = ""
    selected_is_current = False
    if selected_entry:
        kind_label = "Derived Project" if selected_entry.get("kind") == "fork" else "Project"
        st.caption(f"種別: {kind_label}")
        st.caption(f"Project: {selected_entry.get('project_name') or '-'}")
        st.caption(f"JSON: {selected_entry.get('project_file_name') or '-'}")
        st.caption("Path")
        st.code(selected_entry.get("project_path") or "", language="text")
        if selected_entry.get("kind") == "fork" and not selected_entry.get(
            "manifest_available"
        ):
            st.caption("Derived Project manifest unavailable。Project JSON本体は開けます。")
        selected_is_current = bool(selected_entry.get("currently_open"))
        if selected_is_current:
            st.info("現在開いています。")
        selected_open_path, selected_open_error = validate_project_discovery_open_path(
            selected_entry.get("project_path", ""),
            project_root,
        )
        if selected_open_error:
            st.warning(selected_open_error)
    elif snapshot.get("valid"):
        st.info("Project root内にPromptGraph Projectが見つかりませんでした。")

    diagnostic_items = [
        f"{entry.get('path')}: {format_core_message_for_display(entry.get('reason'))}"
        for entry in snapshot.get("rejected", [])
    ] + [
        format_core_message_for_display(item)
        for item in snapshot.get("diagnostics") or []
    ]
    if diagnostic_items:
        st.caption("Discovery diagnostics")
        st.caption(
            f"{len(diagnostic_items)}件のJSON／directoryをProjectとして認識できませんでした。"
        )
        for diagnostic in diagnostic_items[:3]:
            st.caption(f"- {diagnostic}")
        if len(diagnostic_items) > 3:
            st.caption(f"ほか {len(diagnostic_items) - 3} 件。")

    if st.button(
        "選択したプロジェクトを開く",
        key="open_selected_project_directory",
        disabled=(
            not bool(selected_entry)
            or selected_is_current
            or bool(selected_open_error)
        ),
    ):
        selected_open_path, selected_open_error = validate_project_discovery_open_path(
            selected_entry.get("project_path", ""),
            project_root,
        )
        if selected_open_error:
            st.warning(selected_open_error)
        else:
            try:
                if load_project_json_into_session(selected_open_path):
                    st.success("プロジェクトを読み込みました。")
                    st.rerun()
            except Exception as exc:
                st.error(f"プロジェクトを読み込めませんでした: {exc}")


def _get_lightweight_fork_discovery_snapshot(source_project_path: str) -> dict:
    normalized_source = normalize_lightweight_fork_path(source_project_path)
    search_root = os.path.join(os.path.dirname(normalized_source), "forks") if normalized_source else ""
    snapshot, cache_entry, _cache_hit = resolve_cached_lightweight_fork_discovery(
        st.session_state.get("lightweight_fork_discovery_cache"),
        source_project_path=normalized_source,
        search_root=search_root,
        refresh_generation=st.session_state.get("lightweight_fork_discovery_refresh_generation", 0),
        current_open_project_path=st.session_state.get("current_project_path", ""),
    )
    st.session_state.lightweight_fork_discovery_cache = cache_entry
    return snapshot


def _remember_materialized_fork_project(project_path: str, project_name: str = "") -> bool:
    normalized_path = os.path.abspath(os.path.expanduser(str(project_path or "")))
    if not normalized_path or not os.path.isfile(normalized_path):
        return False
    st.session_state.settings = remember_project(
        st.session_state.settings,
        normalized_path,
        project_name=project_name or None,
        update_last_project=False,
    )
    save_settings(st.session_state.settings)
    return True


