    source_info = source_info if isinstance(source_info, dict) else {}
    source_prompt = str(source_info.get("source_prompt") or "").strip()
    current_prompt = str(getattr(line, "current_text", "") or "").strip()

    _render_prompt_diff_block(
        title="Source vs Current Prompt Diff",
        caption="Read-only comparison. Editing the working prompt does not change the source snapshot.",
        source_label="Source prompt preview",
        current_label="Current prompt preview",
        source_text=source_prompt,
        current_text=current_prompt,
        no_source_message="No source prompt is preserved for this line.",
        identical_message="Source prompt and current prompt are identical.",
    )


