def render_source_generation_info(line):
    source_info = getattr(line, "source_generation_info", {}) or {}
    source_info = source_info if isinstance(source_info, dict) else {}

    with st.expander("Source Generation Info", expanded=False):
        st.caption("Read-only provenance. Editing the working prompt or negative prompt does not change this source snapshot.")
        if not source_info:
            st.info("No preserved source generation info for this line.")
            return

        source_kind = source_info.get("source_kind")
        source_image_path = source_info.get("source_image_path")
        source_metadata_id = source_info.get("source_metadata_id") or source_info.get("image_metadata_id")
        details = []
        if source_kind:
            details.append(f"kind: {source_kind}")
        if source_metadata_id:
            details.append(f"metadata id: {source_metadata_id}")
        if details:
            st.caption(" / ".join(details))
        if source_image_path:
            st.caption("Source Image Path")
            st.code(str(source_image_path), language="text")

        source_prompt = source_info.get("source_prompt")
        if source_prompt:
            st.caption("Source Prompt")
            st.code(str(source_prompt), language="text")

        source_negative_prompt = source_info.get("source_negative_prompt")
        if source_negative_prompt:
            st.caption("Source Negative Prompt")
            st.code(str(source_negative_prompt), language="text")

        source_generation_settings = source_info.get("source_generation_settings")
        if isinstance(source_generation_settings, dict) and source_generation_settings:
            st.caption("Source Generation Settings")
            st.dataframe(
                [
                    {"Field": str(key), "Value": str(value)}
                    for key, value in source_generation_settings.items()
                ],
                hide_index=True,
                width="stretch",
            )

        source_raw_metadata = source_info.get("source_raw_metadata")
        if isinstance(source_raw_metadata, dict) and source_raw_metadata:
            with st.expander("Source Raw Metadata Preview", expanded=False):
                st.code(json.dumps(source_raw_metadata, indent=2, ensure_ascii=False), language="json")

