def render_line_metadata_inspector(project, line, expanded=True):
    if not line:
        return

    image_metadata = find_image_metadata_for_line(project, line)
    source_image_path = getattr(line, "image_path", None) or (image_metadata or {}).get("path")
    if not source_image_path and not image_metadata:
        return

    with st.expander("Illustration Metadata", expanded=expanded):
        if source_image_path:
            st.caption("Source Image")
            st.code(source_image_path, language="text")
        st.caption(f"Original filename: {getattr(line, 'original_file_name', '') or 'Unknown'}")

        metadata_keys = (image_metadata or {}).get("metadata_keys", [])
        if metadata_keys:
            st.caption("Metadata Keys")
            st.code(", ".join(metadata_keys), language="text")
        else:
            st.caption("Metadata Keys: none")

        source_engine = (image_metadata or {}).get("source_engine") or ""
        metadata_sources = (image_metadata or {}).get("metadata_sources", [])
        metadata_sources = metadata_sources if isinstance(metadata_sources, list) else []
        generation_params = (image_metadata or {}).get("generation_params", {})
        generation_params = generation_params if isinstance(generation_params, dict) else {}
        if metadata_sources:
            st.caption("Metadata Sources")
            st.code(", ".join(str(source) for source in metadata_sources), language="text")
        if source_engine or metadata_sources:
            st.caption("Generation Metadata")
            st.markdown(f"- A1111 parameters: {'found' if 'a1111_parameters' in metadata_sources else 'missing'}")
            st.markdown(f"- source engine: {source_engine or 'unknown'}")
            st.markdown(f"- NovelAI EXIF prompt: {'found' if 'novelai_exif' in metadata_sources and (image_metadata or {}).get('prompt_text') else 'missing'}")
            st.markdown(f"- full positive prompt: {'found' if (image_metadata or {}).get('prompt_text') else 'missing'}")
            st.markdown(f"- negative prompt: {'found' if (image_metadata or {}).get('negative_prompt') else 'missing'}")
            st.markdown(f"- generation params: {len(generation_params)}")
            if generation_params:
                st.code(", ".join(generation_params.keys()), language="text")

        prompt_preview = (image_metadata or {}).get("prompt_text") or (image_metadata or {}).get("prompt_preview") or getattr(line, "current_text", "")
        if prompt_preview:
            st.caption("Prompt Preview")
            st.text_area(
                "Prompt Preview",
                prompt_preview,
                height=90,
                disabled=True,
                label_visibility="collapsed",
                key=f"line_metadata_prompt_preview_{line.id}",
            )

        raw_metadata = (image_metadata or {}).get("raw_metadata", {})
        raw_metadata = raw_metadata if isinstance(raw_metadata, dict) else {}
        if raw_metadata:
            workflow_text = next(
                (value for key, value in raw_metadata.items() if str(key).lower() in ("workflow", "prompt") and _load_json_from_text(value) is not None),
                "",
            )
            if workflow_text:
                with st.expander("Raw ComfyUI Workflow", expanded=False):
                    st.text_area(
                        "Raw ComfyUI Workflow",
                        workflow_text,
                        height=240,
                        disabled=True,
                        label_visibility="collapsed",
                        key=f"line_metadata_workflow_{line.id}",
                    )
            raw_parameters = (image_metadata or {}).get("raw_parameters", "")
            if raw_parameters:
                with st.expander("Raw A1111 Parameters", expanded=False):
                    st.text_area(
                        "Raw A1111 Parameters",
                        raw_parameters,
                        height=240,
                        disabled=True,
                        label_visibility="collapsed",
                        key=f"line_metadata_a1111_parameters_{line.id}",
                    )
            generation_params = (image_metadata or {}).get("generation_params", {})
            if isinstance(generation_params, dict) and generation_params:
                with st.expander("Parsed Generation Parameters", expanded=False):
                    st.code(json.dumps(generation_params, indent=2, ensure_ascii=False), language="json")
            with st.expander("Raw Metadata", expanded=False):
                st.code(json.dumps(raw_metadata, indent=2, ensure_ascii=False), language="json")

def _load_json_from_text(value: str):
    if not isinstance(value, str) or not value.strip():
        return None
    try:
        return json.loads(value)
    except json.JSONDecodeError:
        return None


def _is_executable_comfy_workflow(value) -> bool:
    if not isinstance(value, dict):
        return False
    return any(
        isinstance(node, dict) and isinstance(node.get("inputs"), dict)
        for node in value.values()
    )


def _workflow_text_from_line_metadata(project, line):
    image_metadata = find_image_metadata_for_line(project, line)
    raw_metadata = (image_metadata or {}).get("raw_metadata", {})
    if not isinstance(raw_metadata, dict):
        return "", "", image_metadata

    lowered_metadata = {str(key).lower(): value for key, value in raw_metadata.items()}
    for key in ("prompt", "workflow"):
        workflow_text = lowered_metadata.get(key)
        workflow_json = _load_json_from_text(workflow_text) if isinstance(workflow_text, str) else None
        if _is_executable_comfy_workflow(workflow_json):
            return workflow_text, f"line metadata `{key}`", image_metadata
    return "", "", image_metadata


def _workflow_metadata_debug_status(image_metadata):
    raw_metadata = (image_metadata or {}).get("raw_metadata", {})
    raw_metadata = raw_metadata if isinstance(raw_metadata, dict) else {}
    lowered_metadata = {str(key).lower(): value for key, value in raw_metadata.items()}
    metadata_sources = (image_metadata or {}).get("metadata_sources", [])
    metadata_sources = metadata_sources if isinstance(metadata_sources, list) else []
    has_a1111_parameters = "a1111_parameters" in metadata_sources
    has_novelai_exif = "novelai_exif" in metadata_sources
    has_source_metadata = bool(metadata_sources)

    prompt_text = lowered_metadata.get("prompt")
    workflow_text = lowered_metadata.get("workflow")
    prompt_json = _load_json_from_text(prompt_text) if isinstance(prompt_text, str) else None
    workflow_json = _load_json_from_text(workflow_text) if isinstance(workflow_text, str) else None
    executable_prompt = _is_executable_comfy_workflow(prompt_json)
    executable_workflow = _is_executable_comfy_workflow(workflow_json)

    selected_source = ""
    fallback_reason = ""
    force_shared = bool(
        st.session_state.get(
            "force_shared_comfy_workflow",
            st.session_state.settings.get("force_shared_comfy_workflow", False),
        )
    )

    if force_shared:
        selected_source = "shared workflow JSON fallback (forced)"
        fallback_reason = "embedded workflow metadata is ignored by setting"
    elif executable_prompt:
        selected_source = "line metadata `prompt`"
    elif executable_workflow:
        selected_source = "line metadata `workflow`"
    else:
        selected_source = "shared workflow JSON fallback"
        if prompt_text or workflow_text:
            fallback_reason = "metadata workflow fields were found, but no executable ComfyUI API workflow was detected"
        elif has_source_metadata:
            fallback_reason = "source metadata was found, but it is not an executable ComfyUI workflow"
        else:
            fallback_reason = "no workflow metadata fields were found on this line"

    return {
        "metadata_sources": metadata_sources,
        "has_a1111_parameters": has_a1111_parameters,
        "has_novelai_exif": has_novelai_exif,
        "source_engine": (image_metadata or {}).get("source_engine") or "",
        "has_prompt_metadata": "prompt" in lowered_metadata,
        "has_workflow_metadata": "workflow" in lowered_metadata,
        "executable_prompt": executable_prompt,
        "executable_workflow": executable_workflow,
        "has_executable_workflow": executable_prompt or executable_workflow,
        "force_shared": force_shared,
        "selected_source": selected_source,
        "fallback_reason": fallback_reason,
    }


def _build_line_workflow_from_text(workflow_text, line, settings, project=None, disabled_modules=None, image_metadata=None):
    line_prompt = getattr(line, "current_text", "") or ""
    mapping = settings.get("comfy_mapping")
    if mapping and "group_map" in mapping:
        workflow_json = json.loads(workflow_text)
        if project is not None:
            from core.comfyui import build_prompt_by_group
            grouped = build_prompt_by_group(project, line, disabled_modules or set())
        else:
            grouped = {"default": [line_prompt]}
        return inject_prompt_to_workflow(
            workflow_json,
            grouped,
            mapping,
            fallback_prompt=line_prompt,
        ), ""

    warning = ""
    if "__PROMPT__" in workflow_text:
        workflow_text = workflow_text.replace("__PROMPT__", json.dumps(line_prompt)[1:-1])
        return json.loads(workflow_text), warning

    workflow_json = json.loads(workflow_text)
    if _replace_clip_text_prompts(workflow_json, line, image_metadata=image_metadata) == 0:
        warning = "The workflow JSON does not contain '__PROMPT__'. The prompt may not be injected."
    return workflow_json, warning


def build_single_line_workflow(workflow_path, line, settings, project=None, disabled_modules=None):
    force_shared = bool(settings.get("force_shared_comfy_workflow", False))
    workflow_text, _source_label, image_metadata = (
        ("", "", None)
        if force_shared
        else (_workflow_text_from_line_metadata(project, line) if project is not None else ("", "", None))
    )
    if not workflow_text:
        workflow_path, _workflow_source_kind = resolve_effective_comfy_workflow_path(workflow_path)
        with open(workflow_path, "r", encoding="utf-8") as f:
            workflow_text = f.read()

    injection_line = line
    if project is not None:
        disabled_modules = disabled_modules if disabled_modules is not None else st.session_state.get("disabled_modules", set())
        fallback_prompt = settings.get("fallback_prompt", "(masterpiece:1.0)")
        active_tokens = get_active_tokens(
            line,
            disabled_modules,
            fallback_prompt=fallback_prompt,
            module_library=getattr(project, "module_library", {}),
        )
        injection_line = copy.deepcopy(line)
        injection_line.current_text = ", ".join(active_tokens)

    return _build_line_workflow_from_text(
        workflow_text,
        injection_line,
        settings,
        project=project,
        disabled_modules=disabled_modules,
        image_metadata=image_metadata,
    )


def _build_focus_line_workflow_preview(project, line):
    force_shared = bool(
        st.session_state.get(
            "force_shared_comfy_workflow",
            st.session_state.settings.get("force_shared_comfy_workflow", False),
        )
    )
    line_workflow_text, line_workflow_label, line_image_metadata = (
        ("", "", None) if force_shared else _workflow_text_from_line_metadata(project, line)
    )
    workflow_path = st.session_state.get("comfy_workflow_path") or st.session_state.settings.get("comfyui_workflow_path", "workflow_api.json")
    resolved_workflow_path, workflow_source_kind = resolve_effective_comfy_workflow_path(workflow_path)

    source_kind = "line metadata" if line_workflow_text else "shared workflow"
    source_label = line_workflow_label if line_workflow_text else (resolved_workflow_path or "(not available)")
    workflow_text = line_workflow_text

    if not workflow_text:
        if not resolved_workflow_path or not os.path.exists(resolved_workflow_path):
            return {
                "source_kind": "(not available)",
                "source_label": "(not available)",
                "resolved_workflow_path": resolved_workflow_path,
                "workflow_json": None,
                "warning": f"Workflow JSON not found at {resolved_workflow_path or workflow_path}",
            }
        with open(resolved_workflow_path, "r", encoding="utf-8") as f:
            workflow_text = f.read()
        if workflow_source_kind == "preset":
            source_kind = "workflow preset"

    fallback_prompt = st.session_state.settings.get("fallback_prompt", "(masterpiece:1.0)")
    active_tokens = get_active_tokens(
        line,
        st.session_state.disabled_modules,
        fallback_prompt=fallback_prompt,
        module_library=getattr(project, "module_library", {}),
    )
    injection_line = copy.deepcopy(line)
    injection_line.current_text = ", ".join(active_tokens)
    workflow_json, warning = _build_line_workflow_from_text(
        workflow_text,
        injection_line,
        st.session_state.settings,
        project=project,
        disabled_modules=st.session_state.disabled_modules,
        image_metadata=line_image_metadata,
    )
    return {
        "source_kind": source_kind,
        "source_label": source_label,
        "resolved_workflow_path": resolved_workflow_path,
        "workflow_json": workflow_json,
        "warning": warning,
    }


def render_comfy_workflow_debug_preview(project, line):
    with st.expander("Debug: ComfyUI Workflow Preview", expanded=False):
        force_shared = bool(
            st.session_state.get(
                "force_shared_comfy_workflow",
                st.session_state.settings.get("force_shared_comfy_workflow", False),
            )
        )
        line_workflow_text, line_workflow_label, line_image_metadata = (
            ("", "", None) if force_shared else _workflow_text_from_line_metadata(project, line)
        )
        workflow_path = st.session_state.get("comfy_workflow_path") or st.session_state.settings.get("comfyui_workflow_path", "workflow_api.json")
        resolved_workflow_path, workflow_source_kind = resolve_effective_comfy_workflow_path(workflow_path)
        metadata_status = _workflow_metadata_debug_status(find_image_metadata_for_line(project, line))

        st.markdown("**Workflow metadata status**")
        if metadata_status["metadata_sources"]:
            st.markdown(f"- metadata sources: {', '.join(str(source) for source in metadata_status['metadata_sources'])}")
        if metadata_status["source_engine"]:
            st.markdown(f"- source engine: {metadata_status['source_engine']}")
        st.markdown(f"- NovelAI EXIF prompt: {'found' if metadata_status['has_novelai_exif'] else 'missing'}")
        st.markdown(f"- A1111 parameters: {'found' if metadata_status['has_a1111_parameters'] else 'missing'}")
        st.markdown(f"- ComfyUI prompt metadata: {'found' if metadata_status['has_prompt_metadata'] else 'not found'}")
        st.markdown(f"- ComfyUI workflow metadata: {'found' if metadata_status['has_workflow_metadata'] else 'not found'}")
        st.markdown(f"- executable workflow: {'yes' if metadata_status['has_executable_workflow'] else 'no'}")
        st.markdown(f"- force shared workflow: {'yes' if metadata_status['force_shared'] else 'no'}")
        st.markdown(f"- selected source: {metadata_status['selected_source']}")
        if metadata_status["fallback_reason"]:
            st.markdown(f"- fallback reason: {metadata_status['fallback_reason']}")

        if line_workflow_text:
            st.caption("Workflow source")
            st.code(line_workflow_label, language="text")
            st.caption("Using line-specific workflow metadata.")
        else:
            st.caption("Workflow source")
            st.code(resolved_workflow_path or "(not available)", language="text")
            if workflow_source_kind == "preset":
                st.caption("Using selected shared workflow preset.")
            else:
                st.caption("Using fallback shared workflow JSON path.")

        if not line_workflow_text:
            st.caption("Resolved shared workflow path")
            st.code(resolved_workflow_path or "(not available)", language="text")

        try:
            preview = _build_focus_line_workflow_preview(project, line)
            if preview.get("warning"):
                st.warning(preview["warning"])
            workflow_json = preview.get("workflow_json")
            if workflow_json is None:
                return
            st.caption("Final injected workflow JSON")
            st.code(json.dumps(workflow_json, indent=2, ensure_ascii=False), language="json")
        except Exception as exc:
            st.warning(f"Could not build workflow preview: {exc}")


def resolve_comfy_workflow_path(workflow_path):
    if not workflow_path:
        return ""
    expanded_path = os.path.expanduser(workflow_path)
    if os.path.isabs(expanded_path):
        return os.path.abspath(expanded_path)

    current_project_path = st.session_state.get("current_project_path")
    if current_project_path:
        return os.path.abspath(os.path.join(os.path.dirname(current_project_path), expanded_path))
    return os.path.abspath(expanded_path)


def list_comfy_workflow_presets():
    if not os.path.isdir(WORKFLOW_PRESET_DIR):
        return []
    presets = []
    for file_name in sorted(os.listdir(WORKFLOW_PRESET_DIR), key=str.casefold):
        if os.path.splitext(file_name)[1].lower() != ".json":
            continue
        preset_path = os.path.join(WORKFLOW_PRESET_DIR, file_name)
        if os.path.isfile(preset_path):
            presets.append(file_name)
    return presets


def resolve_comfy_workflow_preset_path(preset_name):
    clean_name = os.path.basename(str(preset_name or "").strip())
    if not clean_name:
        return ""
    preset_path = os.path.abspath(os.path.join(WORKFLOW_PRESET_DIR, clean_name))
    preset_root = os.path.abspath(WORKFLOW_PRESET_DIR)
    if os.path.dirname(preset_path) != preset_root:
        return ""
    if os.path.splitext(preset_path)[1].lower() != ".json":
        return ""
    return preset_path


def resolve_effective_comfy_workflow_path(workflow_path=None):
    configured_workflow_path = (
        workflow_path
        if workflow_path is not None
        else st.session_state.get("comfy_workflow_path") or st.session_state.settings.get("comfyui_workflow_path", "workflow_api.json")
    )
    selected_preset = st.session_state.get(
        "comfy_workflow_preset",
        st.session_state.settings.get("comfyui_workflow_preset", ""),
    )
    preset_path = resolve_comfy_workflow_preset_path(selected_preset)
    force_shared = bool(
        st.session_state.get(
            "force_shared_comfy_workflow",
            st.session_state.settings.get("force_shared_comfy_workflow", False),
        )
    )
    if force_shared and preset_path and os.path.exists(preset_path):
        return preset_path, "preset"

    resolved_project_path = resolve_comfy_workflow_path(configured_workflow_path)
    if resolved_project_path and os.path.exists(resolved_project_path):
        return resolved_project_path, "project"

    if preset_path and os.path.exists(preset_path):
        return preset_path, "preset"

    return resolved_project_path, "fallback"


def ensure_comfy_settings_session_state():
    settings = st.session_state.settings
    defaults = {
        "comfy_url": settings.get("comfyui_url", "127.0.0.1:8188"),
        "comfy_workflow_path": settings.get(
            "comfyui_workflow_path",
            "workflow_api.json",
        ),
        "force_shared_comfy_workflow": bool(
            settings.get("force_shared_comfy_workflow", False)
        ),
    }
    for key, value in defaults.items():
        if key not in st.session_state:
            st.session_state[key] = value

    workflow_preset_options = [""] + list_comfy_workflow_presets()
    stored_workflow_preset = settings.get("comfyui_workflow_preset", "")
    if stored_workflow_preset not in workflow_preset_options:
        stored_workflow_preset = ""
    if "comfy_workflow_preset" not in st.session_state:
        st.session_state.comfy_workflow_preset = stored_workflow_preset
    return workflow_preset_options


def update_comfy_settings():
    settings = st.session_state.settings
    settings["comfyui_url"] = st.session_state.comfy_url
    settings["comfyui_workflow_path"] = st.session_state.comfy_workflow_path
    settings["comfyui_workflow_preset"] = st.session_state.comfy_workflow_preset
    settings["force_shared_comfy_workflow"] = bool(
        st.session_state.force_shared_comfy_workflow
    )
    save_settings(settings)


