def resolve_image_root_directory(image_root_dir=None):
    root_dir = (
        image_root_dir
        if image_root_dir is not None
        else st.session_state.settings.get("image_root_directory", "")
    )
    root_dir = str(root_dir or "").strip()
    if not root_dir:
        return ""
    return os.path.abspath(os.path.expanduser(root_dir))


def _has_supported_image_file(file_names) -> bool:
    return any(
        os.path.splitext(str(file_name))[1].lower() in IMAGE_METADATA_EXTENSIONS
        for file_name in file_names
    )


def _image_set_display_path(root_dir: str, directory: str) -> str:
    relative_path = os.path.relpath(directory, root_dir)
    if relative_path in ("", "."):
        return ""
    return relative_path.replace("\\", "/")


def _image_set_path_parts(image_set_name) -> list[str]:
    raw_name = str(image_set_name or "").strip()
    if not raw_name or os.path.isabs(raw_name):
        return []
    normalized = raw_name.replace("\\", "/").strip("/")
    parts = [part.strip() for part in normalized.split("/") if part.strip()]
    if not parts or any(part in {".", ".."} for part in parts):
        return []
    return parts


def list_image_sets(image_root_dir=None, max_depth=IMAGE_SET_MAX_SCAN_DEPTH):
    root_dir = resolve_image_root_directory(image_root_dir)
    if not root_dir or not os.path.isdir(root_dir):
        return []

    try:
        max_depth = max(0, int(max_depth))
    except (TypeError, ValueError):
        max_depth = IMAGE_SET_MAX_SCAN_DEPTH
    if max_depth <= 0:
        return []

    image_sets = []
    try:
        for current_dir, child_dirs, file_names in os.walk(root_dir, followlinks=False):
            child_dirs.sort(key=natural_sort_key)
            relative_path = os.path.relpath(current_dir, root_dir)
            depth = 0 if relative_path in ("", ".") else len(relative_path.split(os.sep))
            if depth >= max_depth:
                child_dirs[:] = []
            if depth == 0:
                continue
            if depth > max_depth:
                continue
            if _has_supported_image_file(file_names):
                display_path = _image_set_display_path(root_dir, current_dir)
                if display_path:
                    image_sets.append(display_path)
    except OSError:
        return []
    return sorted(image_sets, key=natural_sort_key)


def resolve_image_set_path(image_set_name, image_root_dir=None):
    root_dir = resolve_image_root_directory(image_root_dir)
    path_parts = _image_set_path_parts(image_set_name)
    if not root_dir or not path_parts:
        return ""
    image_set_path = os.path.abspath(os.path.join(root_dir, *path_parts))
    try:
        root_norm = os.path.normcase(root_dir)
        image_set_norm = os.path.normcase(image_set_path)
        if os.path.commonpath([root_norm, image_set_norm]) != root_norm:
            return ""
    except ValueError:
        return ""
    if not os.path.isdir(image_set_path):
        return ""
    return image_set_path


def _get_comfyui_analysis_workspace_drafts() -> dict:
    drafts = st.session_state.get("comfyui_analysis_workspace_drafts")
    if not isinstance(drafts, dict):
        drafts = {}
        st.session_state.comfyui_analysis_workspace_drafts = drafts
    for section_name in (
        "inspector",
        "prompt_injection",
        "lora_mapping",
        "lora_injection",
    ):
        if not isinstance(drafts.get(section_name), dict):
            drafts[section_name] = {}
    if not isinstance(drafts["lora_injection"].get("strengths"), dict):
        drafts["lora_injection"]["strengths"] = {}
    return drafts


def _normalize_comfyui_draft_scalar(value, default):
    if isinstance(default, bool):
        return value if isinstance(value, bool) else default
    if isinstance(default, float):
        if isinstance(value, bool):
            return default
        try:
            return float(value)
        except (TypeError, ValueError):
            return default
    if isinstance(default, str):
        return value if isinstance(value, str) else default
    return default


def _prepare_comfyui_draft_widget(
    section_name: str,
    draft_key: str,
    widget_key: str,
    default,
):
    section = _get_comfyui_analysis_workspace_drafts()[section_name]
    value = st.session_state.get(widget_key, section.get(draft_key, default))
    value = _normalize_comfyui_draft_scalar(value, default)
    st.session_state[widget_key] = value
    section[draft_key] = value
    return value


def _snapshot_comfyui_draft_widget(
    section_name: str,
    draft_key: str,
    widget_key: str,
    value,
    default,
):
    normalized = _normalize_comfyui_draft_scalar(value, default)
    _get_comfyui_analysis_workspace_drafts()[section_name][draft_key] = normalized
    return normalized


def _comfyui_draft_option_id(option, identity_key: str | None):
    if identity_key is None:
        return str(option or "")
    if isinstance(option, dict):
        return str(option.get(identity_key) or "")
    return str(option or "")


def _prepare_comfyui_draft_option(
    section_name: str,
    draft_key: str,
    widget_key: str,
    options: list,
    *,
    identity_key: str | None = None,
    default_index: int = 0,
):
    section = _get_comfyui_analysis_workspace_drafts()[section_name]
    requested = ""
    has_requested = False
    if widget_key in st.session_state:
        widget_value = st.session_state.get(widget_key)
        has_requested = (
            isinstance(widget_value, str)
            if identity_key is None
            else (
                isinstance(widget_value, dict)
                and isinstance(widget_value.get(identity_key), str)
            )
        )
        if has_requested:
            requested = _comfyui_draft_option_id(
                widget_value,
                identity_key,
            )
    elif draft_key in section:
        draft_value = section.get(draft_key)
        has_requested = isinstance(draft_value, str)
        if has_requested:
            requested = draft_value
    normalized_index = (
        min(max(int(default_index or 0), 0), len(options) - 1)
        if options
        else 0
    )
    if not options:
        selected = None
    elif not has_requested:
        selected = options[normalized_index]
    else:
        selected = next(
            (
                option
                for option in options
                if _comfyui_draft_option_id(option, identity_key) == requested
            ),
            options[normalized_index],
        )
    if selected is None:
        st.session_state.pop(widget_key, None)
        section[draft_key] = ""
        return None
    st.session_state[widget_key] = selected
    section[draft_key] = _comfyui_draft_option_id(selected, identity_key)
    return selected


def _normalize_comfyui_draft_option(
    section_name: str,
    draft_key: str,
    options: list,
    *,
    identity_key: str | None = None,
    default_index: int = 0,
):
    section = _get_comfyui_analysis_workspace_drafts()[section_name]
    has_requested = draft_key in section and isinstance(
        section.get(draft_key),
        str,
    )
    requested = section.get(draft_key, "") if has_requested else ""
    normalized_index = (
        min(max(int(default_index or 0), 0), len(options) - 1)
        if options
        else 0
    )
    if not options:
        selected = None
    elif not has_requested:
        selected = options[normalized_index]
    else:
        selected = next(
            (
                option
                for option in options
                if _comfyui_draft_option_id(option, identity_key) == requested
            ),
            options[normalized_index],
        )
    section[draft_key] = (
        _comfyui_draft_option_id(selected, identity_key)
        if selected is not None
        else ""
    )
    return selected


def _snapshot_comfyui_draft_option(
    section_name: str,
    draft_key: str,
    widget_key: str,
    value,
    *,
    identity_key: str | None = None,
):
    _get_comfyui_analysis_workspace_drafts()[section_name][draft_key] = (
        _comfyui_draft_option_id(value, identity_key)
    )
    return value


def _clear_comfy_workflow_inspector_state() -> None:
    drafts = _get_comfyui_analysis_workspace_drafts()
    drafts["inspector"] = {
        "text": "",
        "show_fields": False,
        "active_input": "",
    }
    st.session_state.comfy_workflow_inspector_raw_text = ""
    st.session_state.comfy_workflow_inspector_source = "workflow JSON"
    st.session_state.pop("comfy_workflow_inspector_text", None)
    st.session_state.pop("comfy_workflow_inspector_show_fields", None)


def _render_comfy_workflow_inspection(raw_text: str, source_label: str, container=st):
    if not raw_text or not raw_text.strip():
        container.info("Load or paste a workflow JSON to inspect nodes.")
        return

    try:
        workflow_data = parse_workflow_json(raw_text)
    except ValueError as exc:
        container.error(str(exc))
        return

    shape = detect_workflow_shape(workflow_data)
    rows = summarize_workflow_nodes(workflow_data)
    if shape == "unknown" or not rows:
        container.error("Unsupported or empty ComfyUI workflow-like JSON. Expected API-style node map or UI-style nodes array.")
        return

    table_rows = [
        {
            "node id": row["node_id"],
            "node class/type": row["class_type"],
            "inferred role": row["role"],
            "key editable fields": ", ".join(row["editable_fields"].keys()) if row["editable_fields"] else "",
        }
        for row in rows
    ]
    role_counts = {}
    for row in rows:
        role_counts[row["role"]] = role_counts.get(row["role"], 0) + 1

    container.success(f"Loaded {len(rows)} node(s) from {source_label}. Shape: {shape}.")
    container.dataframe(table_rows, hide_index=True, width="stretch")
    container.caption(
        "Role inference is conservative. Candidate/Unknown means PromptGraph did not prove the node's exact purpose."
    )
    if role_counts:
        container.code(json.dumps(role_counts, ensure_ascii=False, indent=2), language="json")
    _prepare_comfyui_draft_widget(
        "inspector",
        "show_fields",
        "comfy_workflow_inspector_show_fields",
        False,
    )
    show_fields = container.checkbox(
        "Show detected editable field values",
        key="comfy_workflow_inspector_show_fields",
    )
    show_fields = _snapshot_comfyui_draft_widget(
        "inspector",
        "show_fields",
        "comfy_workflow_inspector_show_fields",
        show_fields,
        False,
    )
    if show_fields:
        field_rows = [
            {
                "node_id": row["node_id"],
                "class_type": row["class_type"],
                "role": row["role"],
                "editable_fields": row["editable_fields"],
            }
            for row in rows
            if row["editable_fields"]
        ]
        if field_rows:
            container.json(field_rows)
        else:
            container.caption("No known editable fields were detected.")


def _comfy_candidate_label(candidate: dict) -> str:
    preview = candidate.get("text_preview") or ""
    preview_text = f" - {preview}" if preview else ""
    return f"{candidate['node_id']} - {candidate['class_type']} - {candidate['role']}{preview_text}"


def _candidate_default_index(candidates: list[dict], role: str, fallback_index: int = 0) -> int:
    for index, candidate in enumerate(candidates):
        if candidate.get("role") == role:
            return index
    return fallback_index if candidates else 0


def _line_export_prompt_text(line) -> str:
    return getattr(line, "current_text", "") or ""


def render_comfy_prompt_injection_export(raw_text: str, source_label: str, container=st):
    container.markdown("---")
    container.markdown("**Prompt Injection Export**")
    container.caption("Inject one PromptGraph line into selected API-style CLIP text nodes and download the rewritten workflow JSON.")

    if not raw_text or not raw_text.strip():
        container.info("Load or paste a workflow JSON before exporting an injected workflow.")
        return

    try:
        workflow_data = parse_workflow_json(raw_text)
    except ValueError as exc:
        container.error(str(exc))
        return

    shape = detect_workflow_shape(workflow_data)
    if shape == "ui":
        container.info("Prompt injection export currently supports API-style workflows only.")
        return
    if shape != "api":
        container.error("Unsupported or empty ComfyUI workflow-like JSON. Prompt injection export requires an API-style workflow.")
        return

    project = st.session_state.get("project")
    visible_lines = get_visible_prompt_lines(project)
    if not visible_lines:
        container.info("Load a PromptGraph project with prompt lines before exporting an injected workflow.")
        return

    candidates = get_text_encode_candidates(workflow_data)
    if not candidates:
        container.warning("No text encode candidates were found in this API-style workflow.")
        return

    line_options = [line.id for line in visible_lines]
    line_by_id = {line.id: line for line in visible_lines}
    _prepare_comfyui_draft_option(
        "prompt_injection",
        "line_id",
        "comfy_prompt_injection_line_id",
        line_options,
    )
    selected_line_id = container.selectbox(
        "Source PromptGraph line",
        options=line_options,
        format_func=lambda line_id: get_prompt_line_label(line_by_id[line_id]),
        key="comfy_prompt_injection_line_id",
    )
    selected_line_id = _snapshot_comfyui_draft_option(
        "prompt_injection",
        "line_id",
        "comfy_prompt_injection_line_id",
        selected_line_id,
    )
    selected_line = line_by_id.get(selected_line_id)
    positive_text = _line_export_prompt_text(selected_line)
    line_negative_text = (getattr(selected_line, "negative_prompt", "") or "").strip()

    positive_index = _candidate_default_index(candidates, "Positive prompt candidate")
    negative_candidates = [{"node_id": "", "class_type": "(none)", "role": "Leave unchanged", "text_preview": ""}] + candidates
    negative_index = 0
    inferred_negative_index = _candidate_default_index(candidates, "Negative prompt candidate")
    if candidates and candidates[inferred_negative_index].get("role") == "Negative prompt candidate":
        negative_index = inferred_negative_index + 1

    _prepare_comfyui_draft_option(
        "prompt_injection",
        "positive_node_id",
        "comfy_prompt_injection_positive_node",
        candidates,
        identity_key="node_id",
        default_index=positive_index,
    )
    positive_candidate = container.selectbox(
        "Positive text encode node",
        options=candidates,
        format_func=_comfy_candidate_label,
        key="comfy_prompt_injection_positive_node",
    )
    positive_candidate = _snapshot_comfyui_draft_option(
        "prompt_injection",
        "positive_node_id",
        "comfy_prompt_injection_positive_node",
        positive_candidate,
        identity_key="node_id",
    )
    _prepare_comfyui_draft_option(
        "prompt_injection",
        "negative_node_id",
        "comfy_prompt_injection_negative_node",
        negative_candidates,
        identity_key="node_id",
        default_index=negative_index,
    )
    negative_candidate = container.selectbox(
        "Negative text encode node (optional)",
        options=negative_candidates,
        format_func=_comfy_candidate_label,
        key="comfy_prompt_injection_negative_node",
    )
    negative_candidate = _snapshot_comfyui_draft_option(
        "prompt_injection",
        "negative_node_id",
        "comfy_prompt_injection_negative_node",
        negative_candidate,
        identity_key="node_id",
    )
    _prepare_comfyui_draft_widget(
        "prompt_injection",
        "manual_negative",
        "comfy_prompt_injection_manual_negative",
        "",
    )
    manual_negative_text = container.text_area(
        "Manual negative prompt fallback",
        height=80,
        key="comfy_prompt_injection_manual_negative",
        help="Used only when the selected line has no negative prompt. Leave blank to keep the workflow negative prompt unchanged.",
    )
    manual_negative_text = _snapshot_comfyui_draft_widget(
        "prompt_injection",
        "manual_negative",
        "comfy_prompt_injection_manual_negative",
        manual_negative_text,
        "",
    )

    negative_text = line_negative_text or manual_negative_text.strip()
    negative_node_id = negative_candidate.get("node_id") or ""
    if line_negative_text:
        container.caption(f"Negative prompt source: selected line metadata ({len(line_negative_text)} chars).")
    elif manual_negative_text.strip():
        container.caption(f"Negative prompt source: manual fallback ({len(manual_negative_text.strip())} chars).")
    else:
        container.caption("Negative prompt source: none; workflow negative node will be left unchanged.")

    if not positive_text.strip():
        container.warning("Selected line has no positive prompt text.")
        return

    try:
        injected_workflow = inject_prompts_into_api_workflow(
            workflow_data,
            positive_candidate["node_id"],
            positive_text,
            negative_node_id=negative_node_id if negative_text else None,
            negative_text=negative_text if negative_text else None,
        )
        injected_json = workflow_to_json_text(injected_workflow)
        parse_workflow_json(injected_json)
    except ValueError as exc:
        container.error(str(exc))
        return

    preview_rows = {
        "source": source_label,
        "positive_node_id": positive_candidate["node_id"],
        "negative_node_id": negative_node_id if negative_text else "",
        "positive_prompt_chars": len(positive_text),
        "negative_prompt_chars": len(negative_text) if negative_text else 0,
    }
    container.json(preview_rows)
    container.download_button(
        "Download injected workflow JSON",
        data=injected_json,
        file_name="promptgraph_injected_workflow.json",
        mime="application/json",
        key="comfy_prompt_injection_download",
    )


def render_lora_directory_mapping(container=st):
    container.markdown("---")
    container.markdown("**LoRA Directory Mapping**")
    container.caption("Read-only scan that compares LoRA references in current prompts with files in a local LoRA directory.")

    project = st.session_state.get("project")
    visible_lines = get_visible_prompt_lines(project)
    if not visible_lines:
        container.info("Load a PromptGraph project with prompt lines to inspect LoRA references.")
        return

    references = extract_lora_references_from_lines(visible_lines)
    if not references:
        container.info("No LoRA tags were found in visible prompt lines.")
        return

    _prepare_comfyui_draft_widget(
        "lora_mapping",
        "directory",
        "lora_mapping_directory",
        "",
    )
    lora_dir = container.text_input(
        "Local LoRA directory",
        key="lora_mapping_directory",
        help="Scans recursively for .safetensors, .pt, and .ckpt files. File contents are not loaded.",
    )
    lora_dir = _snapshot_comfyui_draft_widget(
        "lora_mapping",
        "directory",
        "lora_mapping_directory",
        lora_dir,
        "",
    )
    reference_signature = _lora_reference_signature(references)

    if container.button("Scan LoRA Directory", key="lora_mapping_scan"):
        try:
            files = scan_lora_directory(lora_dir)
            results = match_lora_references_to_files(references, files)
            st.session_state.lora_mapping_results = results
            st.session_state.lora_mapping_files = files
            st.session_state.lora_mapping_references = references
            st.session_state.lora_mapping_reference_signature = reference_signature
            st.session_state.lora_mapping_scanned_directory = lora_dir
            st.session_state.lora_mapping_error = ""
        except ValueError as exc:
            st.session_state.lora_mapping_results = []
            st.session_state.lora_mapping_files = []
            st.session_state.lora_mapping_references = references
            st.session_state.lora_mapping_reference_signature = reference_signature
            st.session_state.lora_mapping_scanned_directory = lora_dir
            st.session_state.lora_mapping_error = str(exc)

    has_current_scan = (
        st.session_state.get("lora_mapping_reference_signature") == reference_signature
        and st.session_state.get("lora_mapping_scanned_directory", "") == lora_dir
    )
    error = st.session_state.get("lora_mapping_error", "") if has_current_scan else ""
    if error:
        container.error(error)

    results = st.session_state.get("lora_mapping_results", []) if has_current_scan else []
    files = st.session_state.get("lora_mapping_files", []) if has_current_scan else []
    stored_references = st.session_state.get("lora_mapping_references", references) if has_current_scan else references
    if not results and references and not error:
        container.caption(f"Referenced LoRAs found in prompts: {len({ref['name'] for ref in references})}. Scan a directory to map them.")
        return

    if results:
        summary = summarize_mapping_results(results)
        summary_cols = container.columns(4)
        summary_cols[0].metric("Referenced", summary["total"])
        summary_cols[1].metric("Found", summary["found"])
        summary_cols[2].metric("Candidates", summary["candidates"])
        summary_cols[3].metric("Missing", summary["missing"])

        table_rows = []
        for result in results:
            matched_or_candidates = result["matches"] if result["matches"] else result["candidates"]
            table_rows.append({
                "LoRA name": result["name"],
                "observed weight(s)": ", ".join(result["weights"]),
                "source line count": len(result["line_ids"]),
                "status": result["status"],
                "matched/candidate files": "\n".join(matched_or_candidates),
            })
        container.dataframe(table_rows, hide_index=True, width="stretch")
        container.caption(f"Scanned LoRA files: {len(files)}. Matching is exact, case-insensitive, then conservative normalized partial candidates.")

    with container.expander("LoRA mapping details", expanded=False):
        container.markdown("**Raw references**")
        container.json(stored_references)
        if files:
            container.markdown("**Scanned files**")
            container.json(files[:200])
            if len(files) > 200:
                container.caption(f"Showing first 200 of {len(files)} scanned files.")


def _lora_loader_candidate_label(candidate: dict) -> str:
    missing = candidate.get("missing_fields") or []
    missing_text = f" - missing: {', '.join(missing)}" if missing else ""
    return (
        f"{candidate['node_id']} - {candidate['class_type']}"
        f" - {candidate.get('lora_name', '')}"
        f" - model={candidate.get('strength_model', '')}"
        f" - clip={candidate.get('strength_clip', '')}"
        f"{missing_text}"
    )


def _lora_ref_weight_label(reference: dict) -> str:
    model_weight = reference.get("model_weight") or ""
    clip_weight = reference.get("clip_weight") or ""
    if model_weight and clip_weight:
        return f"{model_weight}/{clip_weight}"
    return model_weight or clip_weight or ""


def _dedupe_lora_reference_options(references: list[dict]) -> list[dict]:
    grouped = {}
    for ref in references:
        name = ref.get("name", "")
        if not name:
            continue
        option = grouped.setdefault(name, {
            "name": name,
            "weights": [],
            "model_weight": "",
            "clip_weight": "",
        })
        weight_label = _lora_ref_weight_label(ref)
        if weight_label and weight_label not in option["weights"]:
            option["weights"].append(weight_label)
        if not option["model_weight"] and ref.get("model_weight"):
            option["model_weight"] = ref["model_weight"]
        if not option["clip_weight"] and ref.get("clip_weight"):
            option["clip_weight"] = ref["clip_weight"]
    return sorted(grouped.values(), key=lambda item: item["name"].lower())


def _lora_reference_option_label(option: dict) -> str:
    weights = ", ".join(option.get("weights") or [])
    return f"{option['name']} - weights: {weights}" if weights else option["name"]


def _safe_float_or_default(value, default: float) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def _lora_strength_defaults(model_weight="", clip_weight="") -> tuple[float, float]:
    model = _safe_float_or_default(model_weight, 1.0)
    clip = _safe_float_or_default(clip_weight, model)
    return model, clip


def _lora_reference_signature(references: list[dict]) -> tuple:
    return tuple(sorted((ref.get("line_id", ""), ref.get("raw", "")) for ref in references))


def _lora_mapping_file_options(reference_signature: tuple, lora_dir: str) -> list[dict]:
    has_current_scan = (
        st.session_state.get("lora_mapping_reference_signature") == reference_signature
        and st.session_state.get("lora_mapping_scanned_directory", "") == lora_dir
    )
    if not has_current_scan:
        return []

    options = []
    for result in st.session_state.get("lora_mapping_results", []) or []:
        if result.get("status") != "found":
            continue
        for file_info in result.get("match_files", []) or []:
            lora_name = lora_file_injection_name(file_info)
            if not lora_name or os.path.isabs(lora_name):
                continue
            options.append({
                "label": f"{result.get('name', '')} -> {lora_name}",
                "lora_name": lora_name,
                "weights": result.get("weights", []),
            })
    return options


def _mapped_lora_option_label(option: dict) -> str:
    weights = ", ".join(option.get("weights") or [])
    return f"{option['label']} - weights: {weights}" if weights else option["label"]


def _key_fragment(value) -> str:
    text = str(value or "")
    return "".join(ch if ch.isalnum() else "_" for ch in text)[:80] or "empty"


def render_lora_loader_injection_export(raw_text: str, source_label: str, container=st):
    container.markdown("---")
    container.markdown("**LoRA Loader Injection Export**")
    container.caption("Update one existing API-style LoraLoader node in memory and download the rewritten workflow JSON.")

    if not raw_text or not raw_text.strip():
        container.info("Load or paste a workflow JSON before exporting a LoRA-injected workflow.")
        return

    try:
        workflow_data = parse_workflow_json(raw_text)
    except ValueError as exc:
        container.error(str(exc))
        return

    shape = detect_workflow_shape(workflow_data)
    if shape == "ui":
        container.info("LoRA loader injection export currently supports API-style workflows only.")
        return
    if shape != "api":
        container.error("Unsupported or empty ComfyUI workflow-like JSON. LoRA loader injection export requires an API-style workflow.")
        return

    lora_candidates = get_lora_loader_candidates(workflow_data)
    if not lora_candidates:
        container.info("No existing LoraLoader nodes were found. v1 only updates existing nodes.")
        return

    injectable_candidates = [candidate for candidate in lora_candidates if candidate.get("can_inject")]
    missing_candidates = [candidate for candidate in lora_candidates if not candidate.get("can_inject")]
    if missing_candidates:
        container.caption("Some LoraLoader-like nodes are missing lora_name / strength_model / strength_clip and are not injectable in v1.")
    if not injectable_candidates:
        container.warning("No injectable LoraLoader nodes were found. v1 requires existing lora_name, strength_model, and strength_clip fields.")
        return

    _prepare_comfyui_draft_option(
        "lora_injection",
        "target_node_id",
        "comfy_lora_loader_injection_target",
        injectable_candidates,
        identity_key="node_id",
    )
    target_candidate = container.selectbox(
        "Target existing LoraLoader node",
        options=injectable_candidates,
        format_func=_lora_loader_candidate_label,
        key="comfy_lora_loader_injection_target",
    )
    target_candidate = _snapshot_comfyui_draft_option(
        "lora_injection",
        "target_node_id",
        "comfy_lora_loader_injection_target",
        target_candidate,
        identity_key="node_id",
    )

    project = st.session_state.get("project")
    visible_lines = get_visible_prompt_lines(project)
    lora_references = extract_lora_references_from_lines(visible_lines)
    extracted_options = _dedupe_lora_reference_options(lora_references)
    mapped_options = _lora_mapping_file_options(
        _lora_reference_signature(lora_references),
        st.session_state.get("lora_mapping_directory", ""),
    )
    _normalize_comfyui_draft_option(
        "lora_injection",
        "extracted_name",
        extracted_options,
        identity_key="name",
    )
    _normalize_comfyui_draft_option(
        "lora_injection",
        "mapped_name",
        mapped_options,
        identity_key="lora_name",
    )
    source_options = ["Manual"]
    if extracted_options:
        source_options.append("Extracted prompt LoRA")
    if mapped_options:
        source_options.append("Mapped local LoRA")

    _prepare_comfyui_draft_option(
        "lora_injection",
        "source",
        "comfy_lora_loader_injection_source",
        source_options,
    )
    source_choice = container.radio(
        "LoRA source",
        options=source_options,
        key="comfy_lora_loader_injection_source",
    )
    source_choice = _snapshot_comfyui_draft_option(
        "lora_injection",
        "source",
        "comfy_lora_loader_injection_source",
        source_choice,
    )

    selected_lora_name = ""
    default_model_strength = 1.0
    default_clip_strength = 1.0
    if source_choice == "Manual":
        _prepare_comfyui_draft_widget(
            "lora_injection",
            "manual_name",
            "comfy_lora_loader_manual_name",
            "",
        )
        selected_lora_name = container.text_input(
            "Manual LoRA name",
            key="comfy_lora_loader_manual_name",
            help="Preserved exactly. For mapped local files, use the Mapped source instead to avoid absolute paths.",
        )
        selected_lora_name = _snapshot_comfyui_draft_widget(
            "lora_injection",
            "manual_name",
            "comfy_lora_loader_manual_name",
            selected_lora_name,
            "",
        )
    elif source_choice == "Extracted prompt LoRA":
        _prepare_comfyui_draft_option(
            "lora_injection",
            "extracted_name",
            "comfy_lora_loader_extracted_lora",
            extracted_options,
            identity_key="name",
        )
        extracted_option = container.selectbox(
            "Extracted prompt LoRA",
            options=extracted_options,
            format_func=_lora_reference_option_label,
            key="comfy_lora_loader_extracted_lora",
        )
        extracted_option = _snapshot_comfyui_draft_option(
            "lora_injection",
            "extracted_name",
            "comfy_lora_loader_extracted_lora",
            extracted_option,
            identity_key="name",
        )
        selected_lora_name = extracted_option["name"]
        default_model_strength, default_clip_strength = _lora_strength_defaults(
            extracted_option.get("model_weight"),
            extracted_option.get("clip_weight"),
        )
    else:
        _prepare_comfyui_draft_option(
            "lora_injection",
            "mapped_name",
            "comfy_lora_loader_mapped_lora",
            mapped_options,
            identity_key="lora_name",
        )
        mapped_option = container.selectbox(
            "Mapped local LoRA",
            options=mapped_options,
            format_func=_mapped_lora_option_label,
            key="comfy_lora_loader_mapped_lora",
        )
        mapped_option = _snapshot_comfyui_draft_option(
            "lora_injection",
            "mapped_name",
            "comfy_lora_loader_mapped_lora",
            mapped_option,
            identity_key="lora_name",
        )
        selected_lora_name = mapped_option["lora_name"]
        first_weight = (mapped_option.get("weights") or [""])[0]
        if "/" in first_weight:
            model_weight, clip_weight = first_weight.split("/", 1)
        else:
            model_weight, clip_weight = first_weight, first_weight
        default_model_strength, default_clip_strength = _lora_strength_defaults(model_weight, clip_weight)

    strength_key = _key_fragment(f"{source_choice}_{target_candidate['node_id']}_{selected_lora_name}")
    strengths = _get_comfyui_analysis_workspace_drafts()["lora_injection"]["strengths"]
    strength_draft = strengths.get(strength_key)
    if not isinstance(strength_draft, dict):
        strength_draft = {}
        strengths[strength_key] = strength_draft
    strength_model_key = f"comfy_lora_loader_strength_model_{strength_key}"
    strength_clip_key = f"comfy_lora_loader_strength_clip_{strength_key}"
    if strength_model_key not in st.session_state:
        st.session_state[strength_model_key] = _normalize_comfyui_draft_scalar(
            strength_draft.get("model"),
            float(default_model_strength),
        )
    if strength_clip_key not in st.session_state:
        st.session_state[strength_clip_key] = _normalize_comfyui_draft_scalar(
            strength_draft.get("clip"),
            float(default_clip_strength),
        )
    strength_model = container.number_input(
        "strength_model",
        step=0.05,
        format="%.3f",
        key=strength_model_key,
    )
    strength_clip = container.number_input(
        "strength_clip",
        step=0.05,
        format="%.3f",
        key=strength_clip_key,
    )
    strength_model = _normalize_comfyui_draft_scalar(
        strength_model,
        float(default_model_strength),
    )
    strength_clip = _normalize_comfyui_draft_scalar(
        strength_clip,
        float(default_clip_strength),
    )
    strength_draft["model"] = strength_model
    strength_draft["clip"] = strength_clip

    if not selected_lora_name.strip():
        container.warning("Choose or enter a LoRA name before exporting.")
        return

    try:
        injected_workflow = inject_lora_into_api_workflow(
            workflow_data,
            target_candidate["node_id"],
            selected_lora_name,
            strength_model,
            strength_clip,
        )
        injected_json = workflow_to_json_text(injected_workflow)
        parse_workflow_json(injected_json)
    except ValueError as exc:
        container.error(str(exc))
        return

    preview_rows = {
        "source": source_label,
        "target_node_id": target_candidate["node_id"],
        "injected_lora_name": selected_lora_name,
        "injected_strength_model": strength_model,
        "injected_strength_clip": strength_clip,
    }
    container.json(preview_rows)
    container.download_button(
        "Download LoRA-injected workflow JSON",
        data=injected_json,
        file_name="promptgraph_lora_injected_workflow.json",
        mime="application/json",
        key="comfy_lora_loader_injection_download",
    )


def _format_percent(value: float) -> str:
    return f"{float(value or 0.0) * 100:.1f}%"


def _compact_label_list(labels: list[str], limit: int = 4) -> str:
    labels = [str(label) for label in labels if str(label)]
    if len(labels) <= limit:
        return ", ".join(labels)
    return ", ".join(labels[:limit]) + f", +{len(labels) - limit} more"


def _format_comma_tags(tags) -> str:
    if not isinstance(tags, list):
        return ""
    return ", ".join(str(tag).strip() for tag in tags if str(tag).strip())


def _parse_comma_tags(text: str) -> list[str]:
    tags = []
    seen = set()
    for part in str(text or "").split(","):
        tag = part.strip()
        if not tag or tag in seen:
            continue
        seen.add(tag)
        tags.append(tag)
    return tags


def render_generation_settings_consistency_panel(container=st):
    container.markdown("**Generation Settings Consistency**")
    container.caption("Read-only check for shared sampler, model, and generation settings across visible prompt lines.")

    project = st.session_state.get("project")
    visible_lines = get_visible_prompt_lines(project)
    if not visible_lines:
        container.info("Load a PromptGraph project with prompt lines to analyze generation settings.")
        return

    analysis = analyze_generation_settings(
        visible_lines,
        metadata_lookup=lambda line: find_image_metadata_for_line(project, line),
    )
    metric_cols = container.columns(3)
    metric_cols[0].metric("Visible lines", analysis["total_lines"])
    metric_cols[1].metric("With settings", analysis["lines_with_settings"])
    metric_cols[2].metric("Without settings", analysis["lines_without_settings"])

    if not analysis["lines_with_settings"]:
        container.info("No generation settings were found on visible lines or their imported metadata.")
        return

    field_rows = [
        {
            "field": row["label"],
            "present": row["present_count"],
            "unique values": row["unique_count"],
            "most common value": row["most_common_value"],
            "most common count": row["most_common_count"],
            "presence coverage": _format_percent(row["presence_coverage"]),
            "value coverage": _format_percent(row["value_coverage"]),
            "status": row["status"],
        }
        for row in analysis["field_rows"]
    ]
    container.markdown("**Field consistency**")
    container.dataframe(field_rows, hide_index=True, width="stretch")

    with container.expander("Common Generation Profile Candidate", expanded=False) as profile_expander:
        profile_expander.caption(
            "This is a read-only candidate. Generation Profile persistence/export is future work."
        )
        constant_rows = [
            {"field": row["label"], "value": row["value"], "status": "constant"}
            for row in analysis["constant_fields"]
        ]
        if constant_rows:
            profile_expander.markdown("**Constant fields**")
            profile_expander.dataframe(constant_rows, hide_index=True, width="stretch")
        else:
            profile_expander.info("No constant generation settings were found.")

        profile_expander.caption("Mostly/partial fields are shown in the consistency table, not as strict candidates.")

    difference_rows = []
    for field in analysis["mostly_constant_fields"] + analysis["partial_fields"] + analysis["varied_fields"]:
        for value_row in field["values"]:
            difference_rows.append({
                "field": field["label"],
                "status": field["status"],
                "line": value_row["line_label"],
                "line id": value_row["line_id"],
                "value": value_row["value"],
            })
    if difference_rows:
        with container.expander("Per-line setting differences", expanded=False) as diff_expander:
            diff_expander.dataframe(difference_rows, hide_index=True, width="stretch")


def render_negative_prompt_consistency_panel(container=st):
    container.markdown("**Negative Prompt Consistency**")
    container.caption("Read-only check for shared negative prompt templates across visible prompt lines.")

    project = st.session_state.get("project")
    visible_lines = get_visible_prompt_lines(project)
    if not visible_lines:
        container.info("Load a PromptGraph project with prompt lines to analyze negative prompts.")
        return

    analysis = analyze_negative_prompts(
        visible_lines,
        metadata_lookup=lambda line: find_image_metadata_for_line(project, line),
    )
    metric_cols = container.columns(5)
    metric_cols[0].metric("Visible lines", analysis["total_lines"])
    metric_cols[1].metric("With negative", analysis["lines_with_negative"])
    metric_cols[2].metric("Without negative", analysis["lines_without_negative"])
    metric_cols[3].metric("Unique texts", analysis["unique_negative_count"])
    metric_cols[4].metric("Top coverage", _format_percent(analysis["most_common_ratio"]))

    if not analysis["lines_with_negative"]:
        container.info("No negative prompts were found on visible lines or their imported metadata.")
        return

    if analysis["all_identical"]:
        container.info("All detected negative prompts are identical.")
    else:
        container.caption(
            f"Most common negative prompt appears in {analysis['most_common_count']} "
            f"of {analysis['lines_with_negative']} detected lines ({_format_percent(analysis['most_common_ratio'])})."
        )

    if analysis["most_common_negative"]:
        with container.expander("Most common negative prompt", expanded=analysis["all_identical"]):
            container.code(analysis["most_common_negative"], language="text")

    token_rows = [
        {
            "token": row["token"],
            "line count": row["line_count"],
            "coverage": _format_percent(row["coverage"]),
            "type": row["kind"],
        }
        for row in analysis["token_rows"]
    ]
    if token_rows:
        container.markdown("**Common negative tokens**")
        container.dataframe(token_rows, hide_index=True, width="stretch")
    else:
        container.caption("No repeated negative tokens were found with the current threshold.")

    variant_rows = [
        {
            "variant": f"V{index + 1}",
            "negative prompt preview": variant["preview"],
            "count": variant["count"],
            "coverage": _format_percent(variant["coverage"]),
            "source lines": _compact_label_list(variant["line_labels"]),
        }
        for index, variant in enumerate(analysis["variants"])
    ]
    if variant_rows:
        container.markdown("**Negative prompt variants**")
        container.dataframe(variant_rows, hide_index=True, width="stretch")

    detail_rows = [
        {
            "line": row["line_label"],
            "variant": row["variant_id"] or "(none)",
            "negative chars": row["negative_prompt_length"],
            "line-specific additions": ", ".join(row["line_specific_tokens"]) if row["line_specific_tokens"] else "",
        }
        for row in analysis["per_line"]
        if row["negative_prompt"]
    ]
    if detail_rows:
        with container.expander("Per-line negative prompt details", expanded=False):
            container.dataframe(detail_rows, hide_index=True, width="stretch")

    preview = build_global_negative_delta_preview(analysis)
    with container.expander("Global Negative / Delta Preview", expanded=False) as preview_expander:
        preview_expander.caption(
            "This is a read-only preview. Global Negative and Illustration Delta persistence are future work."
        )
        summary_cols = preview_expander.columns(3)
        summary_cols[0].metric("Candidate tokens", len(preview["candidate_tokens"]))
        summary_cols[1].metric("Illustrations with negative", preview["lines_with_negative"])
        summary_cols[2].metric("Illustrations with delta", preview["delta_line_count"])
        preview_expander.markdown(f"Candidate type: `{preview['candidate_type']}`")
        if preview["candidate_text"]:
            preview_expander.markdown("**Global Negative candidate**")
            preview_expander.code(preview["candidate_text"], language="text")
        else:
            preview_expander.info("No safe all-line global negative candidate was found.")

        delta_rows = [
            {
                "line": row["line_label"],
                "line id": row["line_id"],
                "variant": row["variant_id"] or "(none)",
                "delta tokens": row["delta_text"] or "",
                "negative chars": row["negative_prompt_length"],
            }
            for row in preview["delta_rows"]
        ]
        if delta_rows:
            delta_label = "Per-line Negative Delta preview" if preview["candidate_tokens"] else "Unshared tokens preview"
            preview_expander.markdown(f"**{delta_label}**")
            preview_expander.dataframe(delta_rows, hide_index=True, width="stretch")


def render_comfy_workflow_inspector(container=st):
    drafts = _get_comfyui_analysis_workspace_drafts()
    render_generation_settings_consistency_panel(container=container)
    container.markdown("---")
    render_negative_prompt_consistency_panel(container=container)
    container.markdown("---")
    container.markdown("**Comfy Workflow Inspector**")
    container.caption(
        "Read-only inspector for identifying prompt, negative prompt, sampler, checkpoint, LoRA, VAE, and save nodes before future workflow injection."
    )

    uploaded_workflow = container.file_uploader(
        "Upload workflow JSON",
        type=["json"],
        key="comfy_workflow_inspector_upload",
    )
    inspector_draft = drafts["inspector"]
    previous_pasted_draft = _normalize_comfyui_draft_scalar(
        inspector_draft.get("text"),
        "",
    )
    _prepare_comfyui_draft_widget(
        "inspector",
        "text",
        "comfy_workflow_inspector_text",
        "",
    )
    pasted_workflow = container.text_area(
        "Paste workflow JSON",
        key="comfy_workflow_inspector_text",
        height=160,
    )
    pasted_workflow = _snapshot_comfyui_draft_widget(
        "inspector",
        "text",
        "comfy_workflow_inspector_text",
        pasted_workflow,
        "",
    )

    raw_text = st.session_state.get("comfy_workflow_inspector_raw_text", "")
    source_label = st.session_state.get("comfy_workflow_inspector_source", "workflow JSON")
    active_input = inspector_draft.get("active_input", "")
    if active_input not in ("pasted", "uploaded", "path", ""):
        active_input = ""
    pasted_workflow_changed = pasted_workflow != previous_pasted_draft
    if pasted_workflow and pasted_workflow.strip() and (
        pasted_workflow_changed or active_input in ("", "pasted")
    ):
        raw_text = pasted_workflow
        source_label = "pasted JSON"
        st.session_state.comfy_workflow_inspector_raw_text = raw_text
        st.session_state.comfy_workflow_inspector_source = source_label
        inspector_draft["active_input"] = "pasted"
    if uploaded_workflow is not None:
        raw_text = uploaded_workflow.getvalue().decode("utf-8", errors="replace")
        source_label = uploaded_workflow.name or "uploaded JSON"
        st.session_state.comfy_workflow_inspector_raw_text = raw_text
        st.session_state.comfy_workflow_inspector_source = source_label
        inspector_draft["active_input"] = "uploaded"

    path_to_load, path_source_kind = resolve_effective_comfy_workflow_path(
        st.session_state.get("comfy_workflow_path")
        or st.session_state.settings.get("comfyui_workflow_path", "workflow_api.json")
    )
    if container.button("Load configured Workflow JSON Path", key="comfy_workflow_inspector_load_path"):
        if not path_to_load or not os.path.exists(path_to_load):
            container.error(f"Workflow JSON not found at {path_to_load or '(not set)'}.")
        else:
            try:
                with open(path_to_load, "r", encoding="utf-8") as f:
                    raw_text = f.read()
                source_label = f"{path_source_kind}: {path_to_load}" if path_source_kind == "preset" else path_to_load
                st.session_state.comfy_workflow_inspector_raw_text = raw_text
                st.session_state.comfy_workflow_inspector_source = source_label
                inspector_draft["active_input"] = "path"
            except OSError as exc:
                container.error(f"Could not read workflow JSON: {exc}")
                return

    if container.button(
        "Clear inspector",
        key="comfy_workflow_inspector_clear",
        on_click=_clear_comfy_workflow_inspector_state,
    ):
        raw_text = ""
        source_label = "workflow JSON"

    _render_comfy_workflow_inspection(raw_text, source_label, container=container)
    render_comfy_prompt_injection_export(raw_text, source_label, container=container)
    render_lora_directory_mapping(container=container)
    render_lora_loader_injection_export(raw_text, source_label, container=container)


def _append_comfy_execution_log(entry, limit=20):
    log = st.session_state.setdefault("comfy_execution_log", [])
    log.append(entry)
    if len(log) > limit:
        del log[:-limit]


def _line_candidate_key(line):
    return str(getattr(line, "id", ""))


def _candidate_path(candidate):
    if isinstance(candidate, dict):
        return str(candidate.get("path") or "")
    return str(candidate) if candidate else ""


def _runtime_asset_path(path):
    with profile_block("Image path resolution"):
        return resolve_project_asset_path(path, st.session_state.get("current_project_path"))


def _gallery_thumbnail_cache_dir() -> str:
    current_project_path = st.session_state.get("current_project_path")
    if not current_project_path:
        return ""
    project_dir = os.path.dirname(os.path.abspath(current_project_path))
    return os.path.join(project_dir, ".promptgraph_cache", "thumbnails")


def _gallery_thumbnail_cache_path(resolved_image_path: str, modified_ns: int) -> str:
    current_project_path = st.session_state.get("current_project_path")
    cache_dir = _gallery_thumbnail_cache_dir()
    if not current_project_path or not cache_dir:
        return ""
    key_text = (
        f"{GALLERY_THUMBNAIL_CACHE_VERSION}|"
        f"{GALLERY_THUMBNAIL_MAX_EDGE}|"
        f"{GALLERY_THUMBNAIL_JPEG_QUALITY}|"
        f"{os.path.normcase(os.path.abspath(resolved_image_path))}|"
        f"{modified_ns}"
    )
    digest = hashlib.sha256(key_text.encode("utf-8", errors="replace")).hexdigest()
    return os.path.join(cache_dir, f"{digest}.jpg")


def _save_gallery_thumbnail(source_path: str, thumbnail_path: str) -> bool:
    try:
        from PIL import Image, ImageOps
    except ImportError:
        return False

    try:
        os.makedirs(os.path.dirname(thumbnail_path), exist_ok=True)
        with Image.open(source_path) as image:
            image = ImageOps.exif_transpose(image)
            if image.mode not in ("RGB", "L"):
                image = image.convert("RGB")
            elif image.mode == "L":
                image = image.convert("RGB")
            image.thumbnail((GALLERY_THUMBNAIL_MAX_EDGE, GALLERY_THUMBNAIL_MAX_EDGE), Image.LANCZOS)
            image.save(
                thumbnail_path,
                format="JPEG",
                quality=GALLERY_THUMBNAIL_JPEG_QUALITY,
                optimize=True,
            )
        return True
    except Exception:
        return False


def _gallery_thumbnail_display_path(resolved_image_path: str) -> str:
    if not resolved_image_path:
        return ""
    try:
        stat = os.stat(resolved_image_path)
    except OSError:
        return resolved_image_path

    thumbnail_path = _gallery_thumbnail_cache_path(resolved_image_path, getattr(stat, "st_mtime_ns", int(stat.st_mtime * 1_000_000_000)))
    if not thumbnail_path:
        return resolved_image_path
    if profiled_path_exists(thumbnail_path):
        record_profile_timing("Thumbnail cache hit", 0.0)
        return thumbnail_path

    record_profile_timing("Thumbnail cache miss", 0.0)
    with profile_block("Thumbnail generation"):
        if _save_gallery_thumbnail(resolved_image_path, thumbnail_path):
            return thumbnail_path
    return resolved_image_path


def _project_generation_output_dir_path(project):
    current_project_path = st.session_state.get("current_project_path")
    if current_project_path:
        project_dir = os.path.dirname(os.path.abspath(current_project_path))
        output_dir = os.path.join(project_dir, "generated")
    else:
        output_dir = os.path.join(getattr(project, "source_directory", "") or ".", "generated")
    return os.path.abspath(output_dir)


def _project_generation_output_dir(project):
    output_dir = _project_generation_output_dir_path(project)
    os.makedirs(output_dir, exist_ok=True)
    return output_dir


def _project_final_image_export_dir():
    current_project_path = st.session_state.get("current_project_path")
    if not current_project_path:
        return ""
    project_dir = os.path.dirname(os.path.abspath(current_project_path))
    return os.path.join(project_dir, "exports", "final")


def _normalize_candidate_path(path):
    if not path:
        return ""
    path = str(path)
    if os.path.isabs(path):
        return os.path.abspath(path)
    return path.replace("\\", "/")


def _resolve_generated_output_path(path, output_dir=None):
    if not path:
        return ""
    path = os.path.expanduser(str(path))
    if os.path.isabs(path):
        return os.path.abspath(path)

    if output_dir:
        output_candidate = os.path.abspath(os.path.join(output_dir, path))
        if os.path.exists(output_candidate):
            return output_candidate

    runtime_candidate = _runtime_asset_path(path)
    if runtime_candidate and profiled_path_exists(runtime_candidate):
        return os.path.abspath(runtime_candidate)

    return _normalize_candidate_path(path)


def _normalize_candidate_record(candidate):
    if isinstance(candidate, dict):
        path = _candidate_path(candidate)
        if not path:
            return None
        record = dict(candidate)
        record["path"] = _normalize_candidate_path(path)
        return record

    path = _candidate_path(candidate)
    if not path:
        return None
    return {"path": _normalize_candidate_path(path)}


def _normalize_candidate_records(candidates):
    normalized = []
    seen = set()
    for candidate in candidates or []:
        record = _normalize_candidate_record(candidate)
        if not record:
            continue
        path = record["path"]
        if path not in seen:
            normalized.append(record)
            seen.add(path)
    return normalized


def _make_generated_candidate_record(path, line, source, run_index=None):
    if not path:
        return None
    record = {
        "path": _normalize_candidate_path(path),
        "created_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "prompt_text": getattr(line, "current_text", "") or "",
        "negative_prompt": getattr(line, "negative_prompt", "") or "",
        "source": source,
        "origin_line_id": getattr(line, "id", "") or "",
        "origin_line_index": getattr(line, "current_index", None),
        "seed": None,
        "seed_mode": "existing_comfyui_helper_randomized",
    }
    if run_index is not None:
        record["run_index"] = run_index
    return record


def _copy_candidate_image_metadata_fields(record: dict, image_metadata: dict):
    if not isinstance(record, dict) or not isinstance(image_metadata, dict):
        return record

    for key in (
        "source_engine",
        "metadata_sources",
        "raw_parameters",
        "prompt_text",
        "negative_prompt",
        "raw_generation_params",
        "generation_params",
        "workflow_metadata_keys",
        "raw_metadata",
        "metadata_keys",
        "has_metadata",
        "has_comfy_workflow",
        "prompt_preview",
        "warning",
    ):
        value = image_metadata.get(key)
        if value in (None, "", [], {}):
            continue
        record[key] = copy.deepcopy(value)

    if record.get("prompt_text") or record.get("negative_prompt"):
        record["candidate_prompt_source"] = "imported_image_metadata"
    return record


def _make_imported_candidate_record(path, line):
    if not path:
        return None
    record = {
        "path": _normalize_candidate_path(path),
        "created_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "source": "manual_import",
        "origin_line_id": getattr(line, "id", "") or "",
        "origin_line_index": getattr(line, "current_index", None),
        "seed": None,
        "seed_mode": "imported_image",
    }
    image_metadata = extract_image_metadata_for_path(_runtime_asset_path(path))
    return _copy_candidate_image_metadata_fields(record, image_metadata)


def _candidate_prompt_metadata(candidate) -> dict:
    if not isinstance(candidate, dict):
        return {}

    if candidate.get("source") == "manual_import" and candidate.get("candidate_prompt_source") != "imported_image_metadata":
        return {}

    positive_prompt = str(
        candidate.get("prompt_text")
        or candidate.get("positive_prompt")
        or candidate.get("source_prompt")
        or ""
    ).strip()
    negative_prompt = str(
        candidate.get("negative_prompt")
        or candidate.get("source_negative_prompt")
        or candidate.get("negative")
        or ""
    ).strip()
    if not positive_prompt and not negative_prompt:
        return {}
    return {
        "positive_prompt": positive_prompt,
        "negative_prompt": negative_prompt,
    }


def _apply_candidate_prompt_to_line(line, candidate) -> bool:
    prompt_metadata = _candidate_prompt_metadata(candidate)
    if not prompt_metadata:
        return False

    changed = False
    positive_prompt = prompt_metadata.get("positive_prompt", "")
    if positive_prompt and positive_prompt != (getattr(line, "current_text", "") or ""):
        line.current_text = positive_prompt
        line.tokens = parse_prompt(positive_prompt)
        changed = True

    negative_prompt = prompt_metadata.get("negative_prompt", "")
    if negative_prompt and negative_prompt != (getattr(line, "negative_prompt", "") or ""):
        line.negative_prompt = negative_prompt
        changed = True

    if changed:
        line.edited = True
    return changed


def get_original_prompt_text(line) -> str:
    return str(getattr(line, "original_text", "") or "").strip()


def normalize_prompt_for_revert_compare(text: str) -> list[str]:
    text = str(text or "")
    if not text.strip():
        return []
    try:
        return [str(token).strip() for token in parse_prompt(text) if str(token).strip()]
    except Exception:
        return [part.strip() for part in re.split(r"\s*,\s*", text.strip()) if part.strip()]


def is_line_prompt_changed_from_original(line) -> bool:
    original_text = get_original_prompt_text(line)
    if not original_text:
        return False
    current_text = str(getattr(line, "current_text", "") or "").strip()
    return normalize_prompt_for_revert_compare(current_text) != normalize_prompt_for_revert_compare(original_text)


def _set_line_current_prompt(line, prompt_text: str) -> bool:
    prompt_text = str(prompt_text or "")
    previous_text = str(getattr(line, "current_text", "") or "")
    line.current_text = prompt_text
    line.tokens = parse_prompt(prompt_text)
    line.edited = is_line_prompt_changed_from_original(line)
    return previous_text != prompt_text


def revert_line_prompt_to_original(line) -> dict:
    original_text = get_original_prompt_text(line)
    if not original_text:
        return {
            "ok": False,
            "changed": False,
            "message": "元画像Promptがないため、Revertできません。",
        }
    changed = _set_line_current_prompt(line, original_text)
    return {
        "ok": True,
        "changed": changed,
        "message": "元画像Promptに戻しました。" if changed else "すでに元画像Promptです。",
    }


def _looks_like_workflow_json_prompt(text: str) -> bool:
    clean_text = str(text or "").strip()
    if not clean_text or clean_text[0] not in "{[":
        return False
    try:
        parsed = json.loads(clean_text)
    except Exception:
        return False
    return isinstance(parsed, (dict, list))


def _candidate_nested_value(candidate: dict, section_key: str, value_key: str):
    section = candidate.get(section_key)
    if isinstance(section, dict):
        return section.get(value_key)
    return None


def get_candidate_prompt_text(candidate) -> str:
    if not isinstance(candidate, dict):
        return ""
    top_level_keys = (
        "source_prompt",
        "prompt_text",
        "prompt",
        "positive_prompt",
        "positive",
    )
    nested_sections = (
        "source_generation_info",
        "metadata",
        "source_raw_metadata",
    )
    nested_keys = (
        "source_prompt",
        "prompt_text",
        "prompt",
        "positive_prompt",
        "positive",
    )
    values = [candidate.get(key) for key in top_level_keys]
    values.extend(
        _candidate_nested_value(candidate, section_key, value_key)
        for section_key in nested_sections
        for value_key in nested_keys
    )
    for value in values:
        if not isinstance(value, str):
            continue
        prompt_text = value.strip()
        if prompt_text and not _looks_like_workflow_json_prompt(prompt_text):
            return prompt_text
    return ""


def apply_candidate_prompt_to_current_text(line, candidate) -> dict:
    if _candidate_is_trashed(candidate):
        return {
            "ok": False,
            "changed": False,
            "message": "Trash済みCandidateは通常操作の対象外です。Restoreしてから使ってください。",
        }
    prompt_text = get_candidate_prompt_text(candidate)
    if not prompt_text:
        return {
            "ok": False,
            "changed": False,
            "message": "このCandidateには適用できるPromptがありません。",
        }
    changed = _set_line_current_prompt(line, prompt_text)
    return {
        "ok": True,
        "changed": changed,
        "message": "CandidateのPromptをこのイラストに適用しました。" if changed else "すでにこのCandidateのPromptです。",
    }


def apply_candidate_prompt_to_current_text_from_ui(project, line, candidate) -> dict:
    if _candidate_is_trashed(candidate):
        return {
            "ok": False,
            "changed": False,
            "message": "Trash済みCandidateは通常操作の対象外です。Restoreしてから使ってください。",
        }
    prompt_text = get_candidate_prompt_text(candidate)
    if not prompt_text:
        return {
            "ok": False,
            "changed": False,
            "message": "このCandidateには適用できるPromptがありません。",
        }
    if str(getattr(line, "current_text", "") or "") != prompt_text:
        push_history()
    result = apply_candidate_prompt_to_current_text(line, candidate)
    if result.get("ok") and result.get("changed"):
        previous_focused_line_id = st.session_state.get("focused_line_id")
        st.session_state.project = build_graph(project)
        restore_focus_after_graph_update(previous_focused_line_id)
        _queue_gallery_prompt_widget_sync(getattr(line, "id", ""))
        save_current_project_if_possible("candidate prompt adopted")
    return result


def revert_line_prompt_to_original_from_ui(project, line) -> dict:
    original_text = get_original_prompt_text(line)
    if not original_text:
        return {
            "ok": False,
            "changed": False,
            "message": "元画像Promptがないため、Revertできません。",
        }
    if str(getattr(line, "current_text", "") or "") != original_text:
        push_history()
    result = revert_line_prompt_to_original(line)
    if result.get("ok") and result.get("changed"):
        previous_focused_line_id = st.session_state.get("focused_line_id")
        st.session_state.project = build_graph(project)
        restore_focus_after_graph_update(previous_focused_line_id)
        _queue_gallery_prompt_widget_sync(getattr(line, "id", ""))
        save_current_project_if_possible("gallery prompt reverted to original")
    return result


def _queue_gallery_prompt_widget_sync(line_ids):
    if isinstance(line_ids, str):
        line_ids = [line_ids]
    pending = st.session_state.setdefault("gallery_prompt_widget_sync_pending", [])
    for line_id in line_ids or []:
        if line_id and line_id not in pending:
            pending.append(line_id)


def _consume_gallery_prompt_widget_sync(line):
    pending = st.session_state.get("gallery_prompt_widget_sync_pending")
    if not isinstance(pending, list) or getattr(line, "id", "") not in pending:
        return
    key = f"pro_gallery_text_{line.id}"
    st.session_state[key] = getattr(line, "current_text", "") or ""
    st.session_state.gallery_prompt_widget_sync_pending = [
        line_id for line_id in pending if line_id != getattr(line, "id", "")
    ]


def _prompt_original_status_label(line) -> str:
    if not get_original_prompt_text(line):
        return "Prompt: no original"
    if is_line_prompt_changed_from_original(line):
        return "Prompt: edited"
    return "Prompt: original"


def _get_persistent_line_candidates(line):
    candidates = getattr(line, "generated_candidates", None)
    if not isinstance(candidates, list):
        candidates = []
    candidates = _normalize_candidate_records(candidates)
    line.generated_candidates = candidates
    return candidates


def _append_persistent_line_candidates(line, candidates_to_add):
    if isinstance(candidates_to_add, (str, dict)):
        candidates_to_add = [candidates_to_add]
    candidates = _get_persistent_line_candidates(line)
    seen = {_candidate_path(candidate) for candidate in candidates}
    for candidate in candidates_to_add or []:
        record = _normalize_candidate_record(candidate)
        if not record:
            continue
        path = record["path"]
        if path and path not in seen:
            candidates.append(record)
            seen.add(path)
    line.generated_candidates = candidates


def _get_session_line_generated_candidates(line):
    candidates_by_line = st.session_state.setdefault("line_generated_candidates", {})
    return candidates_by_line.setdefault(_line_candidate_key(line), [])


def _sync_line_generated_candidates_to_session(line, candidates):
    candidates_by_line = st.session_state.setdefault("line_generated_candidates", {})
    candidates_by_line[_line_candidate_key(line)] = list(candidates)


def _get_line_generated_candidates(line):
    persistent_candidates = _get_persistent_line_candidates(line)
    session_candidates = _get_session_line_generated_candidates(line)
    if persistent_candidates:
        merged = _normalize_candidate_records([*persistent_candidates, *session_candidates])
    else:
        merged = _normalize_candidate_records(session_candidates)
    _append_persistent_line_candidates(line, merged)
    _sync_line_generated_candidates_to_session(line, merged)
    return _get_persistent_line_candidates(line)


def _line_generated_candidate_count(line) -> int:
    return len(_line_active_generated_candidates(line))


def _append_line_generated_candidates(line, candidates):
    if isinstance(candidates, (str, dict)):
        candidates = [candidates]
    _append_persistent_line_candidates(line, candidates)
    _sync_line_generated_candidates_to_session(line, _get_persistent_line_candidates(line))


def _candidate_record_for_path(line, candidate_image_path):
    target_path = _normalize_candidate_path(candidate_image_path)
    if not target_path:
        return {}
    for candidate in _line_active_generated_candidates(line):
        if _normalize_candidate_path(_candidate_path(candidate)) == target_path:
            return dict(candidate)
    return {}


def _status_output_paths(status, output_dir=None):
    paths = []
    if not isinstance(status, dict):
        return paths
    if status.get("path"):
        paths.append(str(status["path"]))
    for path in status.get("paths") or []:
        if path:
            paths.append(str(path))
    for image in status.get("images") or []:
        if isinstance(image, dict) and image.get("path"):
            paths.append(str(image["path"]))

    unique_paths = []
    seen = set()
    for path in paths:
        resolved_path = _resolve_generated_output_path(path, output_dir=output_dir)
        norm_path = os.path.normcase(os.path.abspath(resolved_path))
        if norm_path in seen:
            continue
        unique_paths.append(resolved_path)
        seen.add(norm_path)
    return unique_paths

def _status_output_debug(status, output_dir=None):
    if not isinstance(status, dict):
        return {}
    debug_keys = [
        "prompt_id",
        "output_node_ids",
        "output_keys_by_node",
        "image_like_fields",
        "images",
        "comfy_output_diagnostics",
        "attempted_view_urls",
        "saved_paths",
        "paths",
        "path",
        "download_errors",
    ]
    debug = {key: status.get(key) for key in debug_keys if key in status}
    paths = _status_output_paths(status, output_dir=output_dir)
    if paths:
        debug["path_exists"] = {path: os.path.exists(_runtime_asset_path(path)) for path in paths}
    return debug


def _clear_line_generated_candidates(line):
    line.generated_candidates = []
    candidates_by_line = st.session_state.setdefault("line_generated_candidates", {})
    candidates_by_line.pop(_line_candidate_key(line), None)


def _render_candidate_gallery_compare_image(label, image_path, missing_caption):
    st.caption(label)
    if not image_path:
        st.caption(missing_caption)
        return
    display_path = _runtime_asset_path(image_path)
    if not profiled_path_exists(display_path):
        st.caption("Image file missing.")
        return
    try:
        st.image(display_path, width="stretch")
    except Exception:
        st.caption("Could not show image.")


def _candidate_metadata_caption(candidate):
    parts = []
    created_at = candidate.get("created_at") if isinstance(candidate, dict) else None
    source = candidate.get("source") if isinstance(candidate, dict) else None
    run_index = candidate.get("run_index") if isinstance(candidate, dict) else None
    origin_line_index = candidate.get("origin_line_index") if isinstance(candidate, dict) else None
    if created_at:
        parts.append(str(created_at))
    if source:
        parts.append(str(source))
    if run_index is not None:
        parts.append(f"run {run_index}")
    if origin_line_index is not None:
        parts.append(f"line {origin_line_index}")
    return " / ".join(parts)


def _candidate_is_pinned(candidate):
    return bool(candidate.get("pinned")) if isinstance(candidate, dict) else False


def _candidate_is_trashed(candidate):
    return bool(candidate.get("trashed")) if isinstance(candidate, dict) else False


def _active_candidates(candidates):
    return [candidate for candidate in candidates or [] if not _candidate_is_trashed(candidate)]


def _trashed_candidates(candidates):
    return [candidate for candidate in candidates or [] if _candidate_is_trashed(candidate)]


def _line_active_generated_candidates(line):
    return _active_candidates(_get_line_generated_candidates(line))


def _line_trashed_generated_candidates(line):
    return _trashed_candidates(_get_line_generated_candidates(line))


def _set_candidate_trashed(line, candidate_path, trashed=True):
    if not line or not candidate_path:
        return False
    candidates = _get_persistent_line_candidates(line)
    changed = False
    trashed_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
    for candidate in candidates:
        if not _candidate_path_matches(_candidate_path(candidate), candidate_path):
            continue
        if trashed:
            if not candidate.get("trashed"):
                candidate["trashed"] = True
                candidate["trashed_at"] = trashed_at
                changed = True
        else:
            if candidate.pop("trashed", None) is not None:
                changed = True
            if candidate.pop("trashed_at", None) is not None:
                changed = True
        break
    if changed:
        line.generated_candidates = candidates
        _sync_line_generated_candidates_to_session(line, candidates)
    return changed


def _candidate_page_state_key(key_prefix, line):
    return f"{key_prefix}_candidate_page_{_line_candidate_key(line)}"


def _clamp_candidate_page(key, total_count):
    total_pages = max(1, (total_count + CANDIDATE_PAGE_SIZE - 1) // CANDIDATE_PAGE_SIZE)
    page = int(st.session_state.get(key, 0) or 0)
    page = max(0, min(page, total_pages - 1))
    st.session_state[key] = page
    return page, total_pages


def _candidate_page_slice(candidates, key_prefix, line):
    total_count = len(candidates)
    if total_count <= CANDIDATE_PAGE_SIZE:
        return candidates, 0, total_count, 0, 1
    key = _candidate_page_state_key(key_prefix, line)
    page, total_pages = _clamp_candidate_page(key, total_count)
    start = page * CANDIDATE_PAGE_SIZE
    end = min(start + CANDIDATE_PAGE_SIZE, total_count)
    return candidates[start:end], start, end, page, total_pages


def _render_candidate_pagination_controls(total_count, start, end, page, total_pages, key_prefix, line):
    if total_count <= CANDIDATE_PAGE_SIZE:
        return
    key = _candidate_page_state_key(key_prefix, line)
    st.caption(f"Showing {start + 1}-{end} of {total_count} candidates / Page {page + 1} / {total_pages}")
    prev_col, next_col, _spacer = st.columns([1, 1, 3])
    with prev_col:
        if st.button("Prev", key=f"{key_prefix}_candidate_prev_{_line_candidate_key(line)}", disabled=page <= 0):
            st.session_state[key] = max(0, page - 1)
            st.rerun()
    with next_col:
        if st.button("Next", key=f"{key_prefix}_candidate_next_{_line_candidate_key(line)}", disabled=page >= total_pages - 1):
            st.session_state[key] = min(total_pages - 1, page + 1)
            st.rerun()


def _candidate_display_image_path(path):
    resolved_path = _runtime_asset_path(path)
    if not resolved_path or not profiled_path_exists(resolved_path):
        return ""
    return _gallery_thumbnail_display_path(resolved_path)


def _selected_candidate_path(line):
    return getattr(line, "selected_candidate_path", None) or getattr(line, "generated_image_path", None)


def _line_main_image_reference(line):
    for attr_name in ("selected_candidate_path", "generated_image_path", "image_path"):
        image_path = getattr(line, attr_name, None)
        if not image_path:
            continue
        display_path = _runtime_asset_path(image_path)
        if display_path and profiled_path_exists(display_path):
            return {
                "path": _normalize_candidate_path(image_path),
                "resolved_path": display_path,
                "field": attr_name,
            }
    return {}


def _resolved_line_main_image_path(line):
    main_image = _line_main_image_reference(line)
    if main_image:
        return str(main_image.get("resolved_path") or "")
    return ""


def _line_has_representative_image(line):
    return bool(_resolved_line_main_image_path(line))


def _candidate_prompt_value(candidate, *keys):
    if not isinstance(candidate, dict):
        return ""
    for key in keys:
        value = candidate.get(key)
        if value:
            return value
    return ""


def _candidate_path_matches(path_a, path_b):
    normalized_a = _normalize_candidate_path(path_a)
    normalized_b = _normalize_candidate_path(path_b)
    if not normalized_a or not normalized_b:
        return False
    if normalized_a == normalized_b:
        return True
    try:
        resolved_a = os.path.normcase(os.path.abspath(_runtime_asset_path(normalized_a)))
        resolved_b = os.path.normcase(os.path.abspath(_runtime_asset_path(normalized_b)))
        return resolved_a == resolved_b
    except (OSError, ValueError):
        return False


def _line_candidate_has_path(line, candidate_path):
    return any(
        _candidate_path_matches(_candidate_path(candidate), candidate_path)
        for candidate in _get_line_generated_candidates(line)
    )


def _mark_candidate_record_swapped_to_main(line, candidate_path, swap_info):
    candidates = _get_line_generated_candidates(line)
    updated = []
    matched = False
    for candidate in candidates:
        record = dict(candidate)
        if _candidate_path_matches(record.get("path"), candidate_path):
            record["adoption_mode"] = "main_image_candidate_swap"
            record["swapped_to_main_at"] = swap_info.get("swapped_at")
            record["previous_main_image_path"] = swap_info.get("previous_main_image_path")
            matched = True
        updated.append(record)
    if matched:
        line.generated_candidates = _normalize_candidate_records(updated)
        _sync_line_generated_candidates_to_session(line, line.generated_candidates)


def _candidate_image_swap_lineage_info(candidate, candidate_path, previous_main, swapped_at):
    swap_info = {
        "mode": "swap_main_image_with_candidate",
        "new_main_image_path": candidate_path,
        "previous_main_image_path": previous_main.get("path") or "",
        "previous_main_image_field": previous_main.get("field") or "",
        "swapped_at": swapped_at,
    }
    if isinstance(candidate, dict):
        candidate_source = candidate.get("source")
        if candidate_source:
            swap_info["candidate_source"] = str(candidate_source)
        candidate_seed = candidate.get("seed")
        if candidate_seed is not None:
            swap_info["candidate_seed"] = candidate_seed
        candidate_workflow = _candidate_prompt_value(candidate, "workflow", "workflow_path", "workflow_name")
        if candidate_workflow:
            swap_info["candidate_workflow"] = str(candidate_workflow)
    return swap_info


def set_candidate_as_empty_line_image(project, line, candidate):
    if _candidate_is_trashed(candidate):
        return {
            "ok": False,
            "message": "Trash済みCandidateは通常操作の対象外です。Restoreしてから使ってください。",
        }
    if _line_has_representative_image(line):
        return {
            "ok": False,
            "message": "このイラストには既に画像があります。候補での置き換えは行いません。",
        }

    candidate_path = _normalize_candidate_path(_candidate_path(candidate))
    resolved_candidate_path = _runtime_asset_path(candidate_path)
    if not candidate_path or not resolved_candidate_path or not profiled_path_exists(resolved_candidate_path):
        return {
            "ok": False,
            "message": "候補画像ファイルが見つかりません。",
        }

    push_history()
    line.generated_image_path = candidate_path
    line.selected_candidate_path = candidate_path

    lineage_info = getattr(line, "lineage_info", None)
    if not isinstance(lineage_info, dict):
        lineage_info = {}
    adoption_info = {
        "mode": "set_main_image_empty_slot",
        "candidate_image_path": candidate_path,
        "adopted_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
    }
    if isinstance(candidate, dict):
        candidate_source = candidate.get("source")
        if candidate_source:
            adoption_info["candidate_source"] = str(candidate_source)
        candidate_seed = candidate.get("seed")
        if candidate_seed is not None:
            adoption_info["candidate_seed"] = candidate_seed
        candidate_workflow = _candidate_prompt_value(candidate, "workflow", "workflow_path", "workflow_name")
        if candidate_workflow:
            adoption_info["candidate_workflow"] = str(candidate_workflow)
    lineage_info["candidate_image_adoption"] = adoption_info
    line.lineage_info = lineage_info

    previous_focused_line_id = st.session_state.get("focused_line_id")
    st.session_state.project = build_graph(project)
    restore_focus_after_graph_update(previous_focused_line_id)
    save_current_project_if_possible("candidate set as empty line image")
    return {
        "ok": True,
        "message": "候補画像をこのイラストの画像に設定しました。",
    }


def swap_line_main_image_with_candidate(project, line, candidate):
    if _candidate_is_trashed(candidate):
        return {
            "ok": False,
            "message": "Trash済みCandidateは通常操作の対象外です。Restoreしてから使ってください。",
        }
    previous_main = _line_main_image_reference(line)
    if not previous_main:
        return {
            "ok": False,
            "message": "このイラストには本編画像がありません。候補を画像として設定してください。",
        }

    candidate_path = _normalize_candidate_path(_candidate_path(candidate))
    resolved_candidate_path = _runtime_asset_path(candidate_path)
    if not candidate_path or not resolved_candidate_path or not profiled_path_exists(resolved_candidate_path):
        return {
            "ok": False,
            "message": "候補画像ファイルが見つかりません。",
        }

    previous_main_path = previous_main.get("path") or ""
    if not previous_main_path:
        return {
            "ok": False,
            "message": "本編画像の退避に失敗したため、入れ替えを中止しました。",
        }

    swapped_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
    push_history()

    if not _line_candidate_has_path(line, previous_main_path):
        previous_record = {
            "path": previous_main_path,
            "created_at": swapped_at,
            "source": "previous_main_image",
            "swap_mode": "main_image_candidate_swap",
            "swapped_at": swapped_at,
            "previous_role": "main_image",
            "previous_main_image_field": previous_main.get("field") or "",
            "origin_line_id": getattr(line, "id", "") or "",
            "origin_line_index": getattr(line, "current_index", None),
        }
        _append_line_generated_candidates(line, previous_record)
    else:
        _set_candidate_trashed(line, previous_main_path, False)

    line.generated_image_path = candidate_path
    line.selected_candidate_path = candidate_path

    swap_info = _candidate_image_swap_lineage_info(candidate, candidate_path, previous_main, swapped_at)
    _mark_candidate_record_swapped_to_main(line, candidate_path, swap_info)

    lineage_info = getattr(line, "lineage_info", None)
    if not isinstance(lineage_info, dict):
        lineage_info = {}
    lineage_info["candidate_image_swap"] = swap_info
    line.lineage_info = lineage_info

    previous_focused_line_id = st.session_state.get("focused_line_id")
    st.session_state.project = build_graph(project)
    restore_focus_after_graph_update(previous_focused_line_id)
    save_current_project_if_possible("candidate swapped with main image")
    return {
        "ok": True,
        "message": "本編画像と候補画像を入れ替えました。",
    }


def set_candidate_as_main_image(project, line, candidate):
    if _candidate_is_trashed(candidate):
        return {
            "ok": False,
            "message": "Trash済みCandidateは通常操作の対象外です。Restoreしてから使ってください。",
        }

    candidate_path = _normalize_candidate_path(_candidate_path(candidate))
    current_main = _line_main_image_reference(line)
    if current_main and _candidate_path_matches(candidate_path, current_main.get("path")):
        return {
            "ok": False,
            "message": "この画像はすでに本編画像です。",
        }

    if _line_has_representative_image(line):
        return swap_line_main_image_with_candidate(project, line, candidate)
    return set_candidate_as_empty_line_image(project, line, candidate)


def _get_line_gallery_variants(line):
    variants = getattr(line, "gallery_variants", None)
    if not isinstance(variants, list):
        variants = []
    normalized = []
    seen = set()
    for variant in variants:
        if not isinstance(variant, dict):
            continue
        record = dict(variant)
        path = _normalize_candidate_path(str(record.get("path") or "").strip())
        if not path:
            continue
        key = str(record.get("id") or path)
        if key in seen:
            continue
        record["path"] = path
        normalized.append(record)
        seen.add(key)
    line.gallery_variants = normalized
    return normalized


def _is_appended_gallery_variant_record(variant):
    if not isinstance(variant, dict):
        return False
    return (
        variant.get("kind") == "gallery_variant"
        or variant.get("source") == "batch_candidate_adoption"
        or str(variant.get("id") or "").startswith("variant_")
    )


def _variant_path_exists(line, candidate_path):
    return _find_existing_gallery_variant(line, candidate_path) is not None


def _gallery_variant_path_matches(variant_path, candidate_path):
    normalized_variant_path = _normalize_candidate_path(variant_path)
    normalized_candidate_path = _normalize_candidate_path(candidate_path)
    if not normalized_variant_path or not normalized_candidate_path:
        return False
    if normalized_variant_path == normalized_candidate_path:
        return True
    try:
        resolved_variant_path = os.path.normcase(os.path.abspath(_runtime_asset_path(normalized_variant_path)))
        resolved_candidate_path = os.path.normcase(os.path.abspath(_runtime_asset_path(normalized_candidate_path)))
        return resolved_variant_path == resolved_candidate_path
    except (OSError, ValueError):
        return False


def _find_existing_gallery_variant(line, candidate_path):
    variants = getattr(line, "gallery_variants", None)
    if not isinstance(variants, list) or not variants:
        return None
    for variant in _get_line_gallery_variants(line):
        if not _is_appended_gallery_variant_record(variant):
            continue
        if _gallery_variant_path_matches(variant.get("path"), candidate_path):
            return variant
    return None


def _appended_gallery_variant_count(line):
    return sum(
        1
        for variant in _get_line_gallery_variants(line)
        if _is_appended_gallery_variant_record(variant)
    )


def _build_gallery_variant_record(line, candidate):
    candidate_path = _normalize_candidate_path(_candidate_path(candidate))
    candidate_metadata = dict(candidate) if isinstance(candidate, dict) else {}
    source_generation_info = build_source_generation_info_from_candidate(
        line,
        candidate_path,
        candidate_metadata,
    )
    lineage_info = build_lineage_info_from_candidate(
        line,
        candidate_path,
        candidate_metadata,
    )
    current_adopted_image = _selected_candidate_path(line) or getattr(line, "image_path", None) or ""
    if current_adopted_image:
        lineage_info["parent_image_path"] = str(current_adopted_image)
    lineage_info["lineage_kind"] = "gallery_variant_append"
    return {
        "id": f"variant_{uuid.uuid4().hex[:8]}",
        "kind": "gallery_variant",
        "path": candidate_path,
        "created_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "source": "batch_candidate_adoption",
        "source_generation_info": source_generation_info,
        "lineage_info": lineage_info,
        "candidate_metadata": candidate_metadata,
    }


def _variant_record_for_promotion(variant):
    if not isinstance(variant, dict):
        return {}
    record = dict(variant.get("candidate_metadata") if isinstance(variant.get("candidate_metadata"), dict) else {})
    path = str(variant.get("path") or "").strip()
    if path:
        record["path"] = _normalize_candidate_path(path)
    if variant.get("created_at") and not record.get("created_at"):
        record["created_at"] = variant["created_at"]
    record["source"] = record.get("source") or "gallery_variant_promotion"
    return record


def _candidate_adoption_line_label(line):
    label = getattr(line, "original_file_name", "") or getattr(line, "id", "")
    line_number = getattr(line, "original_index", None)
    if line_number is not None:
        return f"{label}:{line_number + 1}"
    return label


def _candidate_for_batch_adoption(line, source: str):
    candidates = list(_line_active_generated_candidates(line))
    if not candidates:
        return None
    if source == "first":
        return candidates[0]
    return candidates[-1]


def preview_gallery_candidate_adoption(project, target_line_ids=None, source="latest", mode="replace", example_limit=8):
    target_line_set = set(target_line_ids or []) if target_line_ids is not None else None
    target_lines = [
        line
        for line in getattr(project, "prompt_lines", [])
        if not getattr(line, "deleted", False)
        and is_gallery_operation_prompt_line(line)
        and (target_line_set is None or getattr(line, "id", "") in target_line_set)
    ]
    examples = []
    candidates_found = 0
    candidates_missing = 0
    affected_line_count = 0
    already_variant_count = 0
    missing_line_ids = []
    for line in target_lines:
        candidate = _candidate_for_batch_adoption(line, source)
        candidate_path = _candidate_path(candidate)
        resolved_candidate_path = _runtime_asset_path(candidate_path)
        if not candidate or not candidate_path or not profiled_path_exists(resolved_candidate_path):
            candidates_missing += 1
            missing_line_ids.append(getattr(line, "id", ""))
            continue

        candidates_found += 1
        matched_variant = _find_existing_gallery_variant(line, candidate_path) if mode == "append" else None
        already_variant = matched_variant is not None
        if already_variant:
            already_variant_count += 1
        if mode == "replace" or not already_variant:
            affected_line_count += 1
        if len(examples) < example_limit:
            examples.append({
                "line_id": getattr(line, "id", ""),
                "display_id": _candidate_adoption_line_label(line),
                "line_index": getattr(line, "current_index", getattr(line, "original_index", 0)),
                "current_image": _selected_candidate_path(line) or getattr(line, "image_path", None) or "",
                "candidate_image": candidate_path,
                "candidate_metadata": _candidate_metadata_caption(candidate),
                "already_variant": already_variant,
                "gallery_variants_count": _appended_gallery_variant_count(line),
                "matched_variant_id": str(matched_variant.get("id") or "") if isinstance(matched_variant, dict) else "",
                "matched_variant_path": str(matched_variant.get("path") or "") if isinstance(matched_variant, dict) else "",
            })

    return {
        "source": source,
        "mode": mode,
        "target_line_count": len(target_lines),
        "candidates_found": candidates_found,
        "candidates_missing": candidates_missing,
        "missing_line_ids": missing_line_ids,
        "affected_line_count": affected_line_count,
        "already_variant_count": already_variant_count,
        "append_supported": True,
        "examples": examples,
    }


def preview_route_batch_candidate_adoption(
    project,
    *,
    scope: str,
    route_id: str = "",
    selected_line_ids=None,
    selected_route_ids=None,
    source: str = "latest",
    example_limit: int = 20,
):
    if scope == "selected_routes":
        return build_selected_routes_candidate_adoption_preview(
            project,
            selected_route_ids or [],
            source=source,
            project_path=st.session_state.get("current_project_path", ""),
            resolve_path=_runtime_asset_path,
            path_exists=profiled_path_exists,
            example_limit=example_limit,
        )
    target_resolution = resolve_gallery_operation_targets(
        project,
        scope,
        route_id=route_id,
        selected_line_ids=selected_line_ids or [],
        include_lines_without_images=True,
    )
    preview = build_route_batch_candidate_adoption_preview(
        target_resolution.get("target_lines", []),
        source=source,
        scope=target_resolution.get("scope", scope),
        route_id=target_resolution.get("route_id", ""),
        route_label=target_resolution.get("route_label", ""),
        resolve_path=_runtime_asset_path,
        path_exists=profiled_path_exists,
        example_limit=example_limit,
    )
    preview["target_line_ids"] = target_resolution.get("target_line_ids", [])
    preview["scope_warnings"] = target_resolution.get("warnings", [])
    preview["route_line_count"] = target_resolution.get("route_line_count")
    return preview


def apply_route_batch_candidate_adoption(
    project,
    *,
    scope: str,
    route_id: str = "",
    selected_line_ids=None,
    selected_route_ids=None,
    expected_signature: str = "",
    source: str = "latest",
):
    if scope == "selected_routes":
        return apply_selected_routes_candidate_adoption(
            project,
            selected_route_ids or [],
            expected_signature=expected_signature,
            source=source,
            project_path=st.session_state.get("current_project_path", ""),
            resolve_path=_runtime_asset_path,
            path_exists=profiled_path_exists,
        )
    target_resolution = resolve_gallery_operation_targets(
        project,
        scope,
        route_id=route_id,
        selected_line_ids=selected_line_ids or [],
        include_lines_without_images=True,
    )
    resolved_scope = target_resolution.get("scope", scope)
    result = apply_route_batch_candidate_adoption_preview(
        target_resolution.get("target_lines", []),
        scope=resolved_scope,
        source=source,
        route_id=target_resolution.get("route_id", ""),
        route_label=target_resolution.get("route_label", ""),
        resolve_path=_runtime_asset_path,
        path_exists=profiled_path_exists,
    )
    applied_line_ids = set(result.get("applied_line_ids") or [])
    for line in getattr(project, "prompt_lines", []):
        if getattr(line, "id", "") in applied_line_ids:
            _sync_line_generated_candidates_to_session(line, _get_persistent_line_candidates(line))
    result["scope_warnings"] = target_resolution.get("warnings", [])
    return result


def apply_gallery_candidate_adoption(project, target_line_ids=None, source="latest", mode="replace"):
    if mode not in ("replace", "append"):
        return {"updated_count": 0, "skipped_count": 0, "unsupported_mode": mode}
    preview = preview_gallery_candidate_adoption(
        project,
        target_line_ids=target_line_ids,
        source=source,
        mode=mode,
        example_limit=1000000,
    )
    updated_count = 0
    skipped_count = 0
    line_lookup = {
        getattr(line, "id", ""): line
        for line in getattr(project, "prompt_lines", [])
        if not getattr(line, "deleted", False)
    }
    for example in preview["examples"]:
        line = line_lookup.get(example["line_id"])
        candidate_path = example.get("candidate_image", "")
        if not line or not candidate_path:
            skipped_count += 1
            continue
        candidate = _candidate_for_batch_adoption(line, source)
        if mode == "append":
            if _variant_path_exists(line, candidate_path):
                skipped_count += 1
                continue
            variants = _get_line_gallery_variants(line)
            variants.append(_build_gallery_variant_record(line, candidate))
            line.gallery_variants = variants
        else:
            line.generated_image_path = candidate_path
            line.selected_candidate_path = candidate_path
            _sync_line_generated_candidates_to_session(line, _get_persistent_line_candidates(line))
        updated_count += 1

    return {
        "updated_count": updated_count,
        "skipped_count": skipped_count + preview["candidates_missing"],
        "unsupported_mode": "",
    }


def _render_route_batch_candidate_adoption_image(label: str, path: str) -> None:
    st.caption(label)
    if not path:
        st.caption("(none)")
        return
    display_path = _candidate_display_image_path(path)
    if display_path:
        st.image(display_path, width="stretch")
    st.caption(_short_preview(path, 160))


def _render_route_batch_candidate_adoption_preview(preview: dict) -> None:
    for warning in preview.get("scope_warnings", []) or []:
        st.warning(warning)

    st.warning(preview.get("drift_warning", ""))

    metric_cols = st.columns(5)
    metric_cols[0].metric("Targeted lines", preview.get("targeted_line_count", 0))
    metric_cols[1].metric("Will adopt", preview.get("will_adopt_count", 0))
    metric_cols[2].metric("First main image", preview.get("first_main_image_count", 0))
    metric_cols[3].metric("Swaps with retreat", preview.get("swap_with_retreat_count", 0))
    metric_cols[4].metric("Skipped", preview.get("skipped_count", 0))

    if preview.get("scope") == "selected_routes":
        st.caption(
            "Selected Scenes in Project order: "
            + ", ".join(preview.get("selected_route_labels") or preview.get("selected_route_ids") or [])
        )
        for route in preview.get("route_summaries", []) or []:
            st.caption(
                f"{route.get('route_label') or '(unnamed Scene)'}: "
                f"targets {route.get('targeted_line_count', 0)} / "
                f"will adopt {route.get('will_adopt_count', 0)} / "
                f"no-op {route.get('no_op_count', 0)} / "
                f"skipped {route.get('skipped_count', 0)} / "
                f"drift {route.get('drift_count', 0)}"
            )
        st.caption(
            f"Applicable {preview.get('applicable_count', 0)} / "
            f"no-op {preview.get('no_op_count', 0)} / "
            f"blocked {preview.get('blocked_count', 0)} / "
            f"missing {preview.get('missing_count', 0)} / "
            f"invalid {preview.get('invalid_count', 0)} / "
            f"drift {preview.get('drift_count', 0)}"
        )

    if preview.get("entry_count", 0) > len(preview.get("entries", [])):
        st.caption(
            f"Showing first {len(preview.get('entries', []))} of {preview.get('entry_count', 0)} preview entries."
        )

    if not preview.get("entries"):
        st.info("No target lines were resolved for this preview.")
    for entry in preview.get("entries", []):
        operation = entry.get("operation") or "skipped"
        with st.container(border=True):
            st.markdown(f"**{entry.get('display_id') or entry.get('line_id') or 'Illustration'}**")
            st.caption(
                f"Illustration id: `{entry.get('line_id') or ''}` / "
                f"index: {entry.get('line_index')} / operation: `{operation}`"
            )
            if entry.get("route_label") or entry.get("route_id"):
                st.caption(f"Scene: {entry.get('route_label') or '(unnamed)'} ({entry.get('route_id') or ''})")
            if entry.get("skip_reason"):
                st.caption(f"Skip reason: {format_core_message_for_display(entry.get('skip_reason'))}")
            if entry.get("adoption_source"):
                st.caption(f"Adoption source: {entry.get('adoption_source')}")
            if entry.get("candidate_id"):
                st.caption(f"Candidate id: `{entry.get('candidate_id')}`")
            if entry.get("drift_classifications"):
                st.caption("Drift: " + ", ".join(entry.get("drift_classifications") or []))
            st.caption("Prompt text is unchanged:")
            st.code(entry.get("prompt_preview") or "(empty prompt)", language="text")
            if entry.get("candidate_prompt_preview"):
                st.caption("Candidate prompt preview:")
                st.code(entry.get("candidate_prompt_preview"), language="text")
            image_cols = st.columns(2)
            with image_cols[0]:
                _render_route_batch_candidate_adoption_image("Before", entry.get("before_image_path") or "")
            with image_cols[1]:
                _render_route_batch_candidate_adoption_image("After", entry.get("after_image_path") or "")


def _candidate_route_line_base_label(line) -> str:
    label = get_prompt_line_label(line)
    if label:
        return label
    return getattr(line, "original_file_name", "") or getattr(line, "id", "") or "Illustration"


def _candidate_route_label(project, source_line, reserved_labels: set[str] | None = None) -> str:
    if reserved_labels is None:
        reserved_labels = set()
    existing_labels = {
        route_separator_label(line).strip()
        for line in getattr(project, "prompt_lines", [])
        if not getattr(line, "deleted", False) and is_route_separator(line)
    }
    base_label = f"{_candidate_route_line_base_label(source_line)} Candidates"
    candidate = base_label
    suffix = 2
    while candidate in existing_labels or candidate in reserved_labels:
        candidate = f"{base_label} {suffix}"
        suffix += 1
    reserved_labels.add(candidate)
    return candidate


def _candidate_route_duplicate_exists(project, parent_line_id: str, candidate_path: str) -> bool:
    if not parent_line_id or not candidate_path:
        return False
    for line in getattr(project, "prompt_lines", []):
        if getattr(line, "deleted", False):
            continue
        lineage_info = getattr(line, "lineage_info", None)
        if not isinstance(lineage_info, dict):
            continue
        if lineage_info.get("source") != "candidate_route_creation":
            continue
        if str(lineage_info.get("parent_line_id") or "") != str(parent_line_id):
            continue
        lineage_candidate_path = (
            lineage_info.get("candidate_path")
            or lineage_info.get("candidate_image_path")
            or ""
        )
        if _candidate_path_matches(lineage_candidate_path, candidate_path):
            return True
    return False


def _candidate_route_candidate_workflow(candidate) -> str:
    return str(_candidate_prompt_value(candidate, "workflow", "workflow_path", "workflow_name") or "")


def _candidate_route_candidate_seed(candidate):
    if isinstance(candidate, dict):
        return candidate.get("seed")
    return None


def _candidate_route_target_lines(project, scope: str, selected_line_ids: list[str] | None = None) -> dict:
    active_lines = [
        line
        for line in getattr(project, "prompt_lines", [])
        if not getattr(line, "deleted", False)
    ]
    line_lookup = {getattr(line, "id", ""): line for line in active_lines}
    selected_line_ids = [line_id for line_id in (selected_line_ids or []) if line_id]
    warnings = []
    route_resolution = None

    if scope == "focused_line":
        focused_line = get_line_by_id(project, st.session_state.get("focused_line_id"))
        candidates = [focused_line] if focused_line else []
        if not focused_line:
            warnings.append("フォーカス中のイラストがありません。")
    elif scope == "selected_lines":
        candidates = [line_lookup[line_id] for line_id in selected_line_ids if line_id in line_lookup]
        if not candidates:
            warnings.append("選択中のイラストがありません。")
    elif scope == "current_route":
        anchor_line_id = _gallery_route_anchor_line_id(project, selected_line_ids)
        route_resolution = resolve_gallery_route_for_line(project, anchor_line_id)
        route_line_ids = set(route_resolution.get("line_ids", []))
        candidates = [line for line in active_lines if getattr(line, "id", "") in route_line_ids]
        warnings.extend(route_resolution.get("warnings", []))
    else:
        candidates = list(active_lines)

    target_lines = [
        line for line in candidates
        if is_gallery_operation_prompt_line(line)
    ]
    return {
        "target_lines": target_lines,
        "warnings": warnings,
        "route_resolution": route_resolution,
    }


def preview_candidate_route_creation(project, scope: str, selected_line_ids=None, example_limit=8) -> dict:
    target_resolution = _candidate_route_target_lines(project, scope, selected_line_ids)
    target_lines = target_resolution["target_lines"]
    examples = []
    candidate_line_count = 0
    route_count = 0
    add_line_count = 0
    skip_count = 0
    missing_count = 0
    duplicate_count = 0
    no_candidate_count = 0
    reserved_labels = set()

    for line in target_lines:
        candidates = list(_line_active_generated_candidates(line))
        route_candidates = []
        if not candidates:
            no_candidate_count += 1
            skip_count += 1
            continue
        for candidate_index, candidate in enumerate(candidates):
            candidate_path = _normalize_candidate_path(_candidate_path(candidate))
            resolved_candidate_path = _runtime_asset_path(candidate_path)
            if not candidate_path or not resolved_candidate_path or not profiled_path_exists(resolved_candidate_path):
                missing_count += 1
                skip_count += 1
                continue
            if _candidate_route_duplicate_exists(project, getattr(line, "id", ""), candidate_path):
                duplicate_count += 1
                skip_count += 1
                continue
            route_candidates.append({
                "candidate_index": candidate_index,
                "candidate_path": candidate_path,
                "candidate_metadata": _candidate_metadata_caption(candidate),
            })

        if not route_candidates:
            continue

        candidate_line_count += 1
        route_count += 1
        add_line_count += len(route_candidates)
        route_label = _candidate_route_label(project, line, reserved_labels)
        if len(examples) < example_limit:
            examples.append({
                "line_id": getattr(line, "id", ""),
                "display_id": _candidate_route_line_base_label(line),
                "line_index": getattr(line, "current_index", getattr(line, "original_index", 0)),
                "route_label": route_label,
                "candidate_count": len(route_candidates),
                "candidate_paths": [item["candidate_path"] for item in route_candidates[:4]],
            })

    return {
        "scope": scope,
        "target_line_count": len(target_lines),
        "candidate_line_count": candidate_line_count,
        "route_count": route_count,
        "add_line_count": add_line_count,
        "skip_count": skip_count,
        "missing_count": missing_count,
        "duplicate_count": duplicate_count,
        "no_candidate_count": no_candidate_count,
        "warnings": target_resolution["warnings"],
        "route_resolution": target_resolution.get("route_resolution"),
        "examples": examples,
    }


def _build_candidate_route_line(source_line, candidate, candidate_path: str, candidate_index: int, route_id: str, parent_route_id: str, created_at: str):
    candidate_metadata = dict(candidate) if isinstance(candidate, dict) else {}
    new_line = copy.deepcopy(source_line)
    new_line.id = f"line_{uuid.uuid4().hex[:8]}"
    new_line.original_file_name = os.path.basename(str(candidate_path)) or source_line.original_file_name
    new_line.original_text = source_line.current_text
    new_line.current_text = source_line.current_text
    new_line.tokens = parse_prompt(source_line.current_text)
    new_line.negative_prompt = getattr(source_line, "negative_prompt", "") or ""
    new_line.duplicated_from = source_line.id
    new_line.edited = True
    new_line.deleted = False
    new_line.line_type = None
    new_line.separator_label = None
    new_line.separator_color = None
    new_line.image_path = candidate_path
    new_line.generated_image_path = None
    new_line.selected_candidate_path = None
    new_line.generated_candidates = []
    new_line.gallery_variants = []
    normalize_candidate_line_for_main_sequence(new_line)
    _apply_candidate_prompt_to_line(new_line, candidate_metadata)
    new_line.source_generation_info = build_source_generation_info_from_candidate(
        source_line,
        candidate_path,
        candidate_metadata,
    )
    lineage_info = build_lineage_info_from_candidate(
        source_line,
        candidate_path,
        candidate_metadata,
    )
    lineage_info.update({
        "source": "candidate_route_creation",
        "lineage_kind": "candidate_route_creation",
        "parent_line_id": str(getattr(source_line, "id", "") or ""),
        "parent_line_index": getattr(source_line, "current_index", None),
        "parent_route_id": parent_route_id,
        "candidate_path": candidate_path,
        "candidate_image_path": candidate_path,
        "candidate_index": candidate_index,
        "candidate_seed": _candidate_route_candidate_seed(candidate),
        "candidate_workflow": _candidate_route_candidate_workflow(candidate),
        "created_route_id": route_id,
        "created_at": created_at,
    })
    new_line.lineage_info = lineage_info
    return new_line


def apply_candidate_route_creation(project, scope: str, selected_line_ids=None) -> dict:
    target_resolution = _candidate_route_target_lines(project, scope, selected_line_ids)
    target_lines = target_resolution["target_lines"]
    line_lookup = {getattr(line, "id", ""): line for line in getattr(project, "prompt_lines", [])}
    reserved_labels = set()
    route_plans = []
    skipped_count = 0
    missing_count = 0
    duplicate_count = 0
    no_candidate_count = 0

    for line in target_lines:
        source_line = line_lookup.get(getattr(line, "id", ""))
        if not source_line:
            skipped_count += 1
            continue
        candidates = list(_line_active_generated_candidates(source_line))
        if not candidates:
            no_candidate_count += 1
            skipped_count += 1
            continue
        valid_candidates = []
        for candidate_index, candidate in enumerate(candidates):
            candidate_path = _normalize_candidate_path(_candidate_path(candidate))
            resolved_candidate_path = _runtime_asset_path(candidate_path)
            if not candidate_path or not resolved_candidate_path or not profiled_path_exists(resolved_candidate_path):
                missing_count += 1
                skipped_count += 1
                continue
            if _candidate_route_duplicate_exists(project, getattr(source_line, "id", ""), candidate_path):
                duplicate_count += 1
                skipped_count += 1
                continue
            valid_candidates.append((candidate_index, candidate, candidate_path))
        if not valid_candidates:
            continue
        route_plans.append({
            "line": source_line,
            "route_label": _candidate_route_label(project, source_line, reserved_labels),
            "candidates": valid_candidates,
        })

    if not route_plans:
        return {
            "route_count": 0,
            "line_count": 0,
            "skipped_count": skipped_count,
            "missing_count": missing_count,
            "duplicate_count": duplicate_count,
            "no_candidate_count": no_candidate_count,
            "first_separator_id": "",
        }

    push_history()
    created_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
    created_route_count = 0
    created_line_count = 0
    first_separator_id = ""
    parent_route_cache = {}

    for plan in reversed(route_plans):
        source_line = plan["line"]
        source_line_id = getattr(source_line, "id", "")
        parent_route = parent_route_cache.get(source_line_id)
        if parent_route is None:
            parent_route = resolve_gallery_route_for_line(project, source_line_id)
            parent_route_cache[source_line_id] = parent_route
        route_id = f"separator_{uuid.uuid4().hex[:8]}"
        route_label = plan["route_label"]
        separator = PromptLine(
            id=route_id,
            original_file_name=route_label,
            original_index=(getattr(source_line, "current_index", 0) or 0) + 1,
            current_index=(getattr(source_line, "current_index", 0) or 0) + 1,
            original_text=route_label,
            current_text=route_label,
            tokens=[],
            negative_prompt="",
            edited=True,
            line_type="separator",
            separator_label=route_label,
            separator_color="gray",
            lineage_info={
                "source": "candidate_route_creation",
                "parent_line_id": source_line_id,
                "parent_line_index": getattr(source_line, "current_index", None),
                "candidate_count": len(plan["candidates"]),
                "created_at": created_at,
            },
        )
        new_lines = [
            separator,
            *[
                _build_candidate_route_line(
                    source_line,
                    candidate,
                    candidate_path,
                    candidate_index,
                    route_id,
                    str((parent_route or {}).get("route_id") or ""),
                    created_at,
                )
                for candidate_index, candidate, candidate_path in plan["candidates"]
            ],
        ]
        insert_index = next(
            index for index, line in enumerate(project.prompt_lines)
            if getattr(line, "id", "") == source_line_id
        ) + 1
        project.prompt_lines[insert_index:insert_index] = new_lines
        first_separator_id = first_separator_id or route_id
        created_route_count += 1
        created_line_count += len(new_lines) - 1

    _reindex_project_lines(project)
    previous_focused_line_id = st.session_state.get("focused_line_id")
    st.session_state.project = build_graph(project)
    if first_separator_id:
        st.session_state.focused_line_id = first_separator_id
        st.session_state.gallery_selected_route_separator_id = first_separator_id
        st.session_state.gallery_expanded_line_id = first_separator_id
    else:
        restore_focus_after_graph_update(previous_focused_line_id)
    save_current_project_if_possible("candidate routes created")
    return {
        "route_count": created_route_count,
        "line_count": created_line_count,
        "skipped_count": skipped_count,
        "missing_count": missing_count,
        "duplicate_count": duplicate_count,
        "no_candidate_count": no_candidate_count,
        "first_separator_id": first_separator_id,
    }


def _sort_candidates_for_display(candidates):
    return [
        candidate
        for _idx, candidate in sorted(
            enumerate(candidates),
            key=lambda item: (not _candidate_is_pinned(item[1]), item[0]),
        )
    ]


def _set_candidate_pinned(line, candidate_path, pinned):
    if not line or not candidate_path:
        return
    candidates = _get_persistent_line_candidates(line)
    for candidate in candidates:
        if _candidate_path(candidate) == candidate_path:
            candidate["pinned"] = bool(pinned)
            break
    line.generated_candidates = candidates
    _sync_line_generated_candidates_to_session(line, candidates)


def _get_nearby_lines(project, line, radius=1):
    if not project or not line:
        return []
    visible_lines = [
        candidate_line
        for candidate_line in getattr(project, "prompt_lines", [])
        if not getattr(candidate_line, "deleted", False)
    ]
    visible_lines.sort(
        key=lambda candidate_line: (
            getattr(candidate_line, "current_index", None) is None,
            getattr(candidate_line, "current_index", 0) or 0,
        )
    )
    line_ids = [getattr(candidate_line, "id", None) for candidate_line in visible_lines]
    line_id = getattr(line, "id", None)
    if line_id not in line_ids:
        return []

    index = line_ids.index(line_id)
    start = max(0, index - radius)
    end = min(len(visible_lines), index + radius + 1)
    return [
        candidate_line
        for candidate_line in visible_lines[start:end]
        if getattr(candidate_line, "id", None) != line_id
    ]


def _collect_nearby_candidates(project, line, radius=1):
    nearby_candidates = []
    seen_paths = set()
    for nearby_line in _get_nearby_lines(project, line, radius=radius):
        for candidate in _line_active_generated_candidates(nearby_line):
            path = _candidate_path(candidate)
            if not path or path in seen_paths:
                continue
            record = dict(candidate)
            record.setdefault("origin_line_id", getattr(nearby_line, "id", "") or "")
            record.setdefault("origin_line_index", getattr(nearby_line, "current_index", None))
            record["_origin_line"] = nearby_line
            nearby_candidates.append(record)
            seen_paths.add(path)
    return nearby_candidates


def _render_candidate_grid(line, candidates, key_prefix, allow_set_empty_line_image=False):
    with profile_block("Candidate Gallery render grid"):
        display_candidates = _sort_candidates_for_display(candidates)
        page_candidates, start, end, page, total_pages = _candidate_page_slice(display_candidates, key_prefix, line)
        _render_candidate_pagination_controls(len(display_candidates), start, end, page, total_pages, key_prefix, line)
        cols = st.columns(min(4, len(page_candidates)))
        for page_offset, candidate in enumerate(page_candidates):
            idx = start + page_offset
            path = _candidate_path(candidate)
            display_path = _candidate_display_image_path(path)
            pin_target_line = candidate.get("_origin_line") if isinstance(candidate, dict) else None
            if pin_target_line is None:
                pin_target_line = line
            with cols[page_offset % len(cols)]:
                try:
                    st.image(display_path, width="stretch")
                except Exception as exc:
                    st.warning(f"Could not show candidate: {exc}")
                    continue
                st.caption(os.path.basename(path))
                metadata_caption = _candidate_metadata_caption(candidate)
                if metadata_caption:
                    st.caption(metadata_caption)
                if allow_set_empty_line_image:
                    target_main = _line_main_image_reference(line)
                    is_current_main_candidate = _candidate_path_matches(path, target_main.get("path"))
                    if st.button(
                        "本編画像に設定",
                        key=f"{key_prefix}_set_main_image_{_line_candidate_key(line)}_{idx}",
                        disabled=is_current_main_candidate,
                        help=(
                            "この画像はすでに本編画像です。"
                            if is_current_main_candidate
                            else "この画像をイラストの本編画像にします。既存の本編画像がある場合はCandidateへ退避します。"
                        ),
                    ):
                        result = set_candidate_as_main_image(st.session_state.project, line, candidate)
                        st.session_state.gallery_feedback = result["message"]
                        st.session_state.gallery_feedback_kind = "success" if result["ok"] else "warning"
                        st.rerun()
                else:
                    target_main = _line_main_image_reference(pin_target_line)
                    is_current_main_candidate = _candidate_path_matches(path, target_main.get("path"))
                candidate_prompt_text = get_candidate_prompt_text(candidate)
                if st.button(
                    "この画像のプロンプトを使う",
                    key=f"{key_prefix}_adopt_prompt_{_line_candidate_key(line)}_{idx}",
                    disabled=not bool(candidate_prompt_text),
                    help=(
                        "この画像を生成したPromptを、現在のイラストの編集中Promptへ反映します。画像参照は変更しません。"
                        if candidate_prompt_text
                        else "この画像には適用できるPromptがありません。"
                    ),
                ):
                    result = apply_candidate_prompt_to_current_text_from_ui(st.session_state.project, line, candidate)
                    st.session_state.gallery_feedback = result["message"]
                    st.session_state.gallery_feedback_kind = "success" if result["ok"] else "warning"
                    st.rerun()
                if st.button(
                    "削除",
                    key=f"{key_prefix}_trash_{_line_candidate_key(line)}_{idx}",
                    disabled=is_current_main_candidate,
                    help="画像ファイルは削除せず、Candidateをゴミ箱へ移動します。あとで復元できます。",
                ):
                    if _set_candidate_trashed(pin_target_line, path, True):
                        save_current_project_if_possible("candidate sent to trash")
                    st.rerun()
                insert_project = st.session_state.get("project")
                insert_source_line = pin_target_line or line
                with st.expander("追加", expanded=False):
                    if st.button(
                        "次の画像として追加",
                        key=f"{key_prefix}_insert_after_{_line_candidate_key(line)}_{idx}",
                    ):
                        if _insert_candidate_line_from_ui(insert_project, insert_source_line, path, candidate_metadata=candidate):
                            st.rerun()
                    if st.button(
                        "シーン末尾に追加",
                        key=f"{key_prefix}_insert_route_end_{_line_candidate_key(line)}_{idx}",
                    ):
                        if _insert_candidate_line_from_ui(insert_project, insert_source_line, path, candidate_metadata=candidate, placement="route_end"):
                            st.rerun()


def _render_candidate_trash(line, key_prefix):
    trashed = [
        candidate
        for candidate in _line_trashed_generated_candidates(line)
        if _candidate_path(candidate)
    ]
    if not trashed:
        return

    with st.expander(f"Trash済み Candidates ({len(trashed)})", expanded=False):
        st.caption("Trashは非破壊の隔離です。画像ファイル、Candidate metadata、lineage、prompt metadataは削除しません。")
        display_candidates = _sort_candidates_for_display(trashed)
        trash_key_prefix = f"{key_prefix}_trash"
        page_candidates, start, end, page, total_pages = _candidate_page_slice(display_candidates, trash_key_prefix, line)
        _render_candidate_pagination_controls(len(display_candidates), start, end, page, total_pages, trash_key_prefix, line)
        cols = st.columns(min(4, len(page_candidates)))
        for page_offset, candidate in enumerate(page_candidates):
            idx = start + page_offset
            path = _candidate_path(candidate)
            display_path = _candidate_display_image_path(path)
            with cols[page_offset % len(cols)]:
                if display_path:
                    try:
                        st.image(display_path, width="stretch")
                    except Exception as exc:
                        st.warning(f"Could not show trashed candidate: {exc}")
                else:
                    st.caption("Image file missing.")
                st.caption(os.path.basename(path))
                metadata_caption = _candidate_metadata_caption(candidate)
                if metadata_caption:
                    st.caption(metadata_caption)
                trashed_at = candidate.get("trashed_at") if isinstance(candidate, dict) else None
                if trashed_at:
                    st.caption(f"Trashed: {trashed_at}")
                if st.button("元に戻す", key=f"{trash_key_prefix}_restore_{_line_candidate_key(line)}_{idx}"):
                    if _set_candidate_trashed(line, path, False):
                        save_current_project_if_possible("candidate restored from trash")
                    st.rerun()


def _render_gallery_variant_grid(line, key_prefix="variant"):
    with profile_block("Gallery variant grid render"):
        all_variants = [
            variant
            for variant in _get_line_gallery_variants(line)
            if _is_appended_gallery_variant_record(variant)
        ]
        variants = []
        missing_variants = []
        for variant in all_variants:
            path = variant.get("path") if isinstance(variant, dict) else ""
            resolved_path = _runtime_asset_path(path)
            if path and profiled_path_exists(resolved_path):
                variants.append(variant)
            else:
                missing_variants.append({
                    "raw_path": path or "(empty)",
                    "resolved_path": resolved_path or "(unresolved)",
                })
        if missing_variants:
            st.caption(f"{len(missing_variants)} missing variant path(s) skipped.")
            with st.expander("Missing variant path diagnostics", expanded=False):
                for missing in missing_variants[:8]:
                    st.caption(f"Raw: `{missing['raw_path']}`")
                    st.caption(f"Resolved: `{missing['resolved_path']}`")
        if not variants:
            st.caption("No appended variants for this line yet.")
            return

        cols = st.columns(min(4, len(variants)))
        for idx, variant in enumerate(variants):
            path = variant.get("path", "")
            display_path = _runtime_asset_path(path)
            with cols[idx % len(cols)]:
                try:
                    st.image(display_path, width="stretch")
                except Exception as exc:
                    st.warning(f"Could not show variant: {exc}")
                    continue
                st.caption(os.path.basename(path))
                lineage_info = variant.get("lineage_info") if isinstance(variant, dict) else {}
                parent_image = lineage_info.get("parent_image_path") if isinstance(lineage_info, dict) else ""
                if parent_image:
                    st.caption(f"Parent: {_short_preview(parent_image, 120)}")
                if path == _selected_candidate_path(line):
                    st.caption("After選択中")
                if st.button(
                    "比較用Afterに設定",
                    key=f"{key_prefix}_set_after_{_line_candidate_key(line)}_{idx}",
                    help="このVariantを比較用After画像として設定します。",
                ):
                    line.generated_image_path = path
                    line.selected_candidate_path = path
                    source_info = variant.get("source_generation_info") if isinstance(variant, dict) else {}
                    lineage_info = variant.get("lineage_info") if isinstance(variant, dict) else {}
                    if isinstance(source_info, dict):
                        line.source_generation_info = dict(source_info)
                    if isinstance(lineage_info, dict):
                        line.lineage_info = dict(lineage_info)
                    save_current_project_if_possible("variant set as after")
                    st.rerun()
                confirm_promote = st.checkbox(
                    "昇格を確認",
                    key=f"{key_prefix}_promote_confirm_{_line_candidate_key(line)}_{idx}",
                )
                placement = st.radio(
                    "配置",
                    options=["end", "after_parent"],
                    format_func=lambda value: {
                        "end": "Gallery末尾",
                        "after_parent": "親イラストの直後",
                    }[value],
                    horizontal=False,
                    key=f"{key_prefix}_promote_placement_{_line_candidate_key(line)}_{idx}",
                )
                if st.button(
                    "シーンへ昇格",
                    key=f"{key_prefix}_promote_route_{_line_candidate_key(line)}_{idx}",
                    disabled=not confirm_promote,
                ):
                    project = st.session_state.get("project")
                    new_line_id = promote_gallery_variant_to_route(
                        project,
                        getattr(line, "id", ""),
                        variant,
                        placement=placement,
                    )
                    if new_line_id:
                        st.session_state.gallery_feedback = "Variant promoted to a new Gallery route."
                        st.rerun()
                    st.warning("Variant could not be promoted. Check that the variant image path still exists.")


def render_gallery_variant_card_controls(line, key_prefix):
    with profile_block("Gallery variant summary render"):
        variant_count = _appended_gallery_variant_count(line)
        if variant_count <= 0:
            return
        st.caption(f"Variants: {variant_count}")
        show_key = f"{key_prefix}_show_variants"
        is_open = bool(st.session_state.get(show_key, False))
        if st.button(
            "Hide Variants" if is_open else "Show Variants",
            key=f"{key_prefix}_toggle_variants",
        ):
            st.session_state[show_key] = not is_open
            st.rerun()

    if st.session_state.get(show_key, False):
        _render_gallery_variant_grid(line, key_prefix=key_prefix)


def render_current_line_candidate_gallery(line, project=None):
    with st.expander("Candidate Gallery", expanded=True):
        source_image_path = getattr(line, "image_path", None)
        generated_image_path = getattr(line, "generated_image_path", None)
        reference_col, current_after_col = st.columns(2)
        with reference_col:
            _render_candidate_gallery_compare_image(
                "Reference / Original",
                source_image_path,
                "No reference image.",
            )
        with current_after_col:
            _render_candidate_gallery_compare_image(
                "Current After",
                generated_image_path,
                "No current After image.",
            )

        candidates = list(_get_line_generated_candidates(line))
        active_candidates = _active_candidates(candidates)
        existing_candidates = [
            candidate
            for candidate in active_candidates
            if _candidate_path(candidate) and profiled_path_exists(_runtime_asset_path(_candidate_path(candidate)))
        ]
        missing_count = len(active_candidates) - len(existing_candidates)

        if missing_count:
            st.caption(f"{missing_count} missing candidate path(s) skipped.")
        if not existing_candidates:
            if active_candidates:
                st.caption("No displayable active candidates for this line.")
            else:
                st.caption("No active generated candidates for this line yet.")
            if active_candidates and st.button("Clear current line candidates", key=f"clear_candidates_{_line_candidate_key(line)}"):
                _clear_line_generated_candidates(line)
                save_current_project_if_possible("line candidates cleared")
                st.rerun()
        else:
            _render_candidate_grid(line, existing_candidates, "current_candidate", allow_set_empty_line_image=True)
        _render_candidate_trash(line, "current_candidate")

        st.markdown("##### Appended Variants")
        _render_gallery_variant_grid(line, key_prefix="candidate_gallery_variant")

        if existing_candidates and st.button("Clear current line candidates", key=f"clear_candidates_{_line_candidate_key(line)}"):
            _clear_line_generated_candidates(line)
            save_current_project_if_possible("line candidates cleared")
            st.rerun()

        if project:
            st.markdown("##### Nearby Candidates")
            nearby_candidates = _collect_nearby_candidates(project, line)
            existing_nearby_candidates = [
                candidate
                for candidate in nearby_candidates
                if _candidate_path(candidate) and profiled_path_exists(_runtime_asset_path(_candidate_path(candidate)))
            ]
            missing_nearby_count = len(nearby_candidates) - len(existing_nearby_candidates)
            if missing_nearby_count:
                st.caption(f"{missing_nearby_count} missing nearby candidate path(s) skipped.")
            if existing_nearby_candidates:
                _render_candidate_grid(line, existing_nearby_candidates, "nearby_candidate")
            else:
                st.caption("No nearby candidates.")


def _build_focus_line_generation_workflow(project, line):
    force_shared = bool(
        st.session_state.get(
            "force_shared_comfy_workflow",
            st.session_state.settings.get("force_shared_comfy_workflow", False),
        )
    )
    line_workflow_text, _line_workflow_label, line_image_metadata = (
        ("", "", None) if force_shared else _workflow_text_from_line_metadata(project, line)
    )
    workflow_path = st.session_state.get("comfy_workflow_path") or st.session_state.settings.get("comfyui_workflow_path", "workflow_api.json")
    resolved_workflow_path, _workflow_source_kind = resolve_effective_comfy_workflow_path(workflow_path)
    if not line_workflow_text and (not resolved_workflow_path or not os.path.exists(resolved_workflow_path)):
        raise FileNotFoundError(f"Workflow JSON not found at {resolved_workflow_path or workflow_path}")

    if line_workflow_text:
        workflow_text = line_workflow_text
    else:
        with open(resolved_workflow_path, "r", encoding="utf-8") as f:
            workflow_text = f.read()

    fallback_prompt = st.session_state.settings.get("fallback_prompt", "(masterpiece:1.0)")
    active_tokens = get_active_tokens(
        line,
        st.session_state.disabled_modules,
        fallback_prompt=fallback_prompt,
        module_library=getattr(project, "module_library", {}),
    )
    injection_line = copy.deepcopy(line)
    injection_line.current_text = ", ".join(active_tokens)
    return _build_line_workflow_from_text(
        workflow_text,
        injection_line,
        st.session_state.settings,
        project=project,
        disabled_modules=st.session_state.disabled_modules,
        image_metadata=line_image_metadata,
    )


def _run_current_line_comfy_multiple(
    project,
    line,
    run_count,
    build_workflow,
    file_prefix,
    candidate_source="multi_generate",
    set_after_on_generate=True,
):
    comfy_url = st.session_state.get("comfy_url") or st.session_state.settings.get("comfyui_url", "127.0.0.1:8188")
    output_dir = _project_generation_output_dir(project)
    progress_bar = st.progress(0.0)
    status_text = st.empty()
    summary_text = st.empty()
    success_count = 0
    failure_count = 0
    last_error = ""
    generated_paths = []
    generated_candidate_records = []
    comfy_debug_records = []
    submitted_prompt_debug_records = []
    warning_seen = ""
    total_runs = int(run_count)

    for run_index in range(1, total_runs + 1):
        run_generated_paths = []
        status_text.markdown(f"**Run {run_index}/{total_runs}:** preparing workflow")
        try:
            workflow_json, warning = build_workflow()
            if warning and warning != warning_seen:
                st.warning(warning)
                warning_seen = warning
            submitted_prompt_debug = _workflow_submitted_prompt_debug(workflow_json, line)
            submitted_prompt_debug_records.append({
                "run": run_index,
                **submitted_prompt_debug,
            })

            for status in generate_image_with_progress(
                workflow_json,
                comfy_url,
                output_dir,
                f"{file_prefix}_run{run_index}",
            ):
                if "value" in status:
                    progress_value = ((run_index - 1) + status["value"]) / total_runs
                    progress_bar.progress(min(max(progress_value, 0.0), 1.0))
                if "text" in status:
                    status_text.markdown(f"**Run {run_index}/{total_runs}:** {status['text']}")
                if status.get("type") == "warning":
                    comfy_debug_records.append({"run": run_index, "warning": status.get("text")})
                if status.get("type") == "done":
                    status_debug = _status_output_debug(status, output_dir=output_dir)
                    if status_debug:
                        comfy_debug_records.append({"run": run_index, "done_status": status_debug})
                    run_generated_paths.extend(_status_output_paths(status, output_dir=output_dir))

            if run_generated_paths:
                unique_run_paths = []
                seen_run_paths = set()
                for generated_path in run_generated_paths:
                    norm_path = os.path.normcase(os.path.abspath(generated_path))
                    if norm_path in seen_run_paths:
                        continue
                    unique_run_paths.append(generated_path)
                    seen_run_paths.add(norm_path)
                success_count += 1
                generated_paths.extend(unique_run_paths)
                for output_index, generated_path in enumerate(unique_run_paths, start=1):
                    generated_candidate_records.append(
                        _make_generated_candidate_record(
                            generated_path,
                            line,
                            candidate_source,
                            run_index if len(unique_run_paths) == 1 else f"{run_index}-{output_index}",
                        )
                    )
            else:
                failure_count += 1
                last_error = "Generation completed, but output path was not detected."
                comfy_debug_records.append({
                    "run": run_index,
                    "error": last_error,
                    "detected_paths": [],
                })
                st.warning(f"Run {run_index} completed without a detected output path.")
        except Exception as exc:
            failure_count += 1
            last_error = str(exc)
            exception_record = {"run": run_index, "exception": last_error}
            comfy_diagnostics = getattr(exc, "diagnostics", None)
            if comfy_diagnostics:
                exception_record["diagnostics"] = comfy_diagnostics
            comfy_debug_records.append(exception_record)
            if "No image was output" in last_error:
                st.warning(f"Run {run_index}: 生成は完了しましたが、出力画像を取得できませんでした。{last_error}")
            else:
                st.warning(f"Run {run_index} failed: {last_error}")

        summary_text.markdown(
            f"**Summary:** {success_count} succeeded / {failure_count} failed"
        )

    progress_bar.progress(1.0)
    target_line = get_line_by_id(st.session_state.project, getattr(line, "id", "")) or line
    if set_after_on_generate and generated_paths:
        target_line.generated_image_path = generated_paths[-1]
        target_line.selected_candidate_path = generated_paths[-1]
    _append_line_generated_candidates(target_line, generated_candidate_records)
    if generated_candidate_records:
        save_current_project_if_possible("comfy candidates generated")
    _append_comfy_execution_log({
        "line_id": getattr(line, "id", ""),
        "line_index": getattr(line, "current_index", None),
        "prompt_text": getattr(line, "current_text", "") or "",
        "run_count": total_runs,
        "seed_mode": "existing_comfyui_helper",
        "timestamp": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "success_count": success_count,
        "failure_count": failure_count,
        "generated_paths": generated_paths,
        "last_error": last_error,
        "capture_debug": comfy_debug_records,
        "submitted_prompt_debug": submitted_prompt_debug_records,
    })

    if success_count:
        st.success(f"Generated {success_count} image(s). Last image: {generated_paths[-1]}")
    if failure_count:
        st.error(f"{failure_count} run(s) failed. Last error: {last_error}")
    if submitted_prompt_debug_records:
        with st.expander("Debug: Submitted Comfy prompts", expanded=False):
            st.json(submitted_prompt_debug_records)
    if comfy_debug_records and (failure_count or not generated_paths):
        with st.expander("Debug: Comfy output capture", expanded=False):
            st.json(comfy_debug_records)
    if not generated_paths and not failure_count:
        st.info("Generation queued/completed, but output path was not detected.")
    return generated_paths

def render_single_line_comfy_execution(project, line):
    # Legacy selected-line panel; the active Focus Edit Generate / Compare panel is wired separately below.
    st.markdown("#### Single Illustration ComfyUI Execution")
    if not line:
        st.info("Focus or highlight a prompt line to generate it once.")
        return

    st.caption("Selected Illustration")
    st.write(f"**{line.id}** / {getattr(line, 'original_file_name', '') or 'Unknown source'}")
    st.text_area(
        "Selected Illustration Prompt",
        getattr(line, "current_text", "") or "",
        height=90,
        disabled=True,
        label_visibility="collapsed",
        key=f"single_line_comfy_prompt_{line.id}",
    )

    if st.session_state.edition == "FREE":
        st.info("Single line ComfyUI execution is available in the Pro edition.")
        return

    workflow_path = st.session_state.get("comfy_workflow_path") or st.session_state.settings.get("comfyui_workflow_path", "workflow_api.json")
    resolved_workflow_path, workflow_source_kind = resolve_effective_comfy_workflow_path(workflow_path)
    line_workflow_text, line_workflow_label, _line_image_metadata = _workflow_text_from_line_metadata(project, line)
    st.caption("Resolved Workflow Path")
    st.code(line_workflow_label or resolved_workflow_path or "(not set)", language="text")
    if line_workflow_label:
        st.caption("Using line-specific ComfyUI workflow metadata.")
    elif workflow_source_kind == "preset":
        st.caption("Using selected shared workflow preset.")
    if not line_workflow_text and resolved_workflow_path and not os.path.exists(resolved_workflow_path):
        st.warning("Set an absolute workflow_api.json path in ComfyUI Integration settings.")

    if st.button("Generate Current Illustration Once", key=f"single_line_comfy_generate_{line.id}"):
        if st.session_state.edition == "FREE":
            show_upgrade_dialog("Single line ComfyUI execution is available in the Pro edition.")
            st.stop()

        comfy_url = st.session_state.get("comfy_url") or st.session_state.settings.get("comfyui_url", "127.0.0.1:8188")
        if not line_workflow_text and (not resolved_workflow_path or not os.path.exists(resolved_workflow_path)):
            st.error(f"Workflow JSON not found at {resolved_workflow_path or workflow_path}")
            st.info("Set an absolute workflow_api.json path in ComfyUI Integration settings.")
            return

        try:
            workflow_json, warning = build_single_line_workflow(resolved_workflow_path, line, st.session_state.settings, project=project)
            if warning:
                st.warning(warning)

            output_dir = _project_generation_output_dir(project)
            progress_bar = st.progress(0.0)
            status_text = st.empty()
            generated_paths = []
            for status in generate_image_with_progress(
                workflow_json,
                comfy_url,
                output_dir,
                f"single_{line.id}",
            ):
                if "value" in status:
                    progress_bar.progress(status["value"])
                if "text" in status:
                    status_text.markdown(f"**Status:** {status['text']}")
                if status.get("type") == "done":
                    generated_paths.extend(_status_output_paths(status, output_dir=output_dir))

            if generated_paths:
                line.generated_image_path = generated_paths[-1]
                line.selected_candidate_path = generated_paths[-1]
                _append_line_generated_candidates(
                    line,
                    [
                        _make_generated_candidate_record(
                            generated_path,
                            line,
                            "single_generate",
                            index,
                        )
                        for index, generated_path in enumerate(generated_paths, start=1)
                    ],
                )
                save_current_project_if_possible("single-line candidate generated")
                st.success(f"Generated {len(generated_paths)} image(s). Last image: {generated_paths[-1]}")
                st.rerun()
            else:
                st.info("Generation queued/completed, but output path was not detected.")
        except Exception as exc:
            st.error(f"Single line generation failed: {exc}")

    st.markdown("##### Multi-generate")
    st.caption("Uses the existing ComfyUI execution path. Seeds follow the current ComfyUI helper behavior.")
    run_count = st.number_input(
        "Runs",
        min_value=1,
        max_value=20,
        value=3,
        step=1,
        key=f"single_line_comfy_run_count_{line.id}",
    )
    if st.button("Generate Current Illustration Multiple Times", key=f"single_line_comfy_generate_multi_{line.id}"):
        if not line_workflow_text and (not resolved_workflow_path or not os.path.exists(resolved_workflow_path)):
            st.error(f"Workflow JSON not found at {resolved_workflow_path or workflow_path}")
            st.info("Set an absolute workflow_api.json path in ComfyUI Integration settings.")
            return

        _run_current_line_comfy_multiple(
            project,
            line,
            run_count,
            lambda: build_single_line_workflow(
                resolved_workflow_path,
                line,
                st.session_state.settings,
                project=project,
            ),
            f"single_{line.id}",
        )

def render_line_before_after_preview(line):
    source_image_path = getattr(line, "image_path", None)
    source_display_path = _runtime_asset_path(source_image_path)
    main_image_reference = _line_main_image_reference(line)
    generated_image_path = (
        main_image_reference.get("path")
        if main_image_reference.get("field") in ("selected_candidate_path", "generated_image_path")
        else ""
    )
    generated_display_path = main_image_reference.get("resolved_path") if generated_image_path else ""
    source_exists = bool(source_image_path and os.path.exists(source_display_path))
    generated_exists = bool(generated_image_path and os.path.exists(generated_display_path))

    st.markdown("#### Before / After")
    if not source_exists and not generated_exists:
        st.caption("No source or generated image available for this line.")
        return

    if source_exists and generated_exists:
        source_col, generated_col = st.columns(2)
        with source_col:
            st.caption("Source Image")
            st.image(source_display_path, width="stretch")
        with generated_col:
            st.caption("Generated Image")
            st.image(generated_display_path, width="stretch")
        return

    if source_exists:
        st.caption("Source Image")
        st.image(source_display_path, width="stretch")
    if generated_exists:
        st.caption("Generated Image")
        st.image(generated_display_path, width="stretch")

def render_selected_line_panel(project, line, include_generation=True):
    if not line:
        return

    with st.container(border=True):
        st.markdown("### Selected Illustration Panel")
        st.caption("Focused line is used first; highlighted line is used when no focus is active.")
        render_line_before_after_preview(line)
        render_selected_line_negative_prompt_editor(line)
        render_source_current_prompt_diff(line)
        render_source_current_negative_prompt_diff(line)
        render_source_generation_info(line)
        render_lineage_info(line)
        render_line_metadata_inspector(project, line)
        if include_generation:
            render_single_line_comfy_execution(project, line)


def render_selected_line_negative_prompt_editor(line):
    stored_negative_prompt = getattr(line, "negative_prompt", "") or ""
    text_key = f"selected_line_negative_text_{line.id}"
    if text_key not in st.session_state:
        st.session_state[text_key] = stored_negative_prompt

    with st.expander("Selected Illustration Negative Prompt", expanded=False):
        st.caption("Stored per-line negative prompt. Future Global Negative / Delta support will build on this.")
        st.markdown(f"Illustration: `{get_prompt_line_label(line)}` / `{line.id}`")
        draft_negative_prompt = st.text_area(
            "Negative prompt",
            key=text_key,
            height=100,
            help="Stored on this Illustration only. It does not change the positive prompt or prompt graph.",
        )
        changed = draft_negative_prompt != stored_negative_prompt
        action_cols = st.columns(2)
        if action_cols[0].button(
            "Apply Negative Prompt",
            key=f"selected_line_negative_apply_{line.id}",
            disabled=not changed,
        ):
            update_line_prompts(line.id, new_negative_prompt=draft_negative_prompt)
            st.rerun()
        if action_cols[1].button(
            "Reset Draft",
            key=f"selected_line_negative_reset_{line.id}",
            disabled=not changed,
        ):
            st.session_state[text_key] = stored_negative_prompt
            st.rerun()

