def render_duplicate_project_management_section() -> None:
    with st.expander("プロジェクトを複製", expanded=False):
        st.caption("現在のプロジェクトディレクトリ全体をコピーし、複製先を自動で開きます。")
        duplicate_default_name = _default_duplicate_project_dir_name()
        duplicate_source_path = st.session_state.get("current_project_path", "")
        if (
            "duplicate_project_dir_name" not in st.session_state
            or st.session_state.get("duplicate_project_source_path")
            != duplicate_source_path
        ):
            st.session_state.duplicate_project_dir_name = duplicate_default_name
            st.session_state.duplicate_project_source_path = duplicate_source_path
        duplicate_project_name = st.text_input(
            "複製先プロジェクト名 / フォルダ名",
            key="duplicate_project_dir_name",
        )
        duplicate_destination_dir = _duplicate_project_destination_dir(
            duplicate_project_name
        )
        confirm_duplicate_project = st.checkbox(
            "プロジェクトディレクトリを複製して開くことを確認しました。",
            value=False,
            key="duplicate_project_confirm",
        )
        if duplicate_destination_dir:
            st.caption(f"複製先: {duplicate_destination_dir}")
        st.caption(
            "refs / candidates / routes / exports / workflows などをまとめてコピーします。"
            "サムネイルcacheはコピーしません。"
        )

        duplicate_error = ""
        if not st.session_state.project:
            duplicate_error = "先にプロジェクトを読み込むか作成してください。"
        elif not duplicate_source_path:
            duplicate_error = "現在のプロジェクトパスがありません。"
        elif not os.path.isfile(os.path.abspath(duplicate_source_path)):
            duplicate_error = "元のプロジェクトJSONが見つかりません。"
        elif not _sanitize_duplicate_project_dir_name(duplicate_project_name):
            duplicate_error = "複製先プロジェクト名が必要です。"
