def _project_root_import_external_source(path: object, project_root: str) -> str:
    normalized = normalize_project_import_path(path)
    normalized_root = normalize_project_import_path(project_root)
    if not normalized or not os.path.isfile(normalized):
        return ""
    source_directory = os.path.dirname(normalized)
    try:
        normalized_case_root = os.path.normcase(normalized_root)
        if os.path.commonpath(
            [os.path.normcase(source_directory), normalized_case_root]
        ) == normalized_case_root:
            return ""
    except (OSError, ValueError):
        pass
    return normalized


def _project_root_import_recent_sources(project_root: str) -> list[dict]:
    sources = []
    seen = set()
    for item in get_recent_projects(st.session_state.get("settings", {})):
        path = _project_root_import_external_source(item.get("path", ""), project_root)
        path_key = os.path.normcase(path)
        if not path or path_key in seen:
            continue
        seen.add(path_key)
        sources.append({"name": item.get("name") or os.path.basename(path), "path": path})
    return sources


def _render_project_root_import_preview(preview: dict) -> None:
    counts = preview.get("counts", {})
    st.caption("Import Preview")
    st.caption("Source Project JSON")
    st.code(preview.get("source_project_path", ""), language="text")
    st.caption("Source Project directory")
    st.code(preview.get("source_directory", ""), language="text")
    st.caption("Destination Project directory")
    st.code(preview.get("destination_directory", ""), language="text")
    st.caption("Primary destination JSON")
    st.code(preview.get("destination_project_path", ""), language="text")
    summary_columns = st.columns(4)
    summary_columns[0].metric("Files", int(counts.get("file_count", 0) or 0))
    summary_columns[1].metric("Size", _format_project_assets_bytes(counts.get("total_bytes", 0)))
    summary_columns[2].metric("Project JSONs", int(counts.get("project_json_count", 0) or 0))
    summary_columns[3].metric("Derived Projects", int(counts.get("fork_count", 0) or 0))
    st.caption(
        f"Ignored: {int(counts.get('ignored_count', 0) or 0)} / "
        f"Path rewrites: {int(counts.get('rewrite_count', 0) or 0)} / "
        f"External paths kept: {int(counts.get('external_path_count', 0) or 0)}"
    )
    for blocker in preview.get("blockers", []):
        st.error(blocker)
    for warning in preview.get("warnings", [])[:5]:
        st.warning(warning)
    if len(preview.get("warnings", [])) > 5:
        st.caption(f"ほか {len(preview['warnings']) - 5} 件のwarning")
    inventory_examples = [
        item.get("relative_path", "")
        for item in preview.get("source_inventory", [])
        if item.get("kind") == "file"
    ][:8]
    if inventory_examples:
        st.caption("Copy examples")
        for path in inventory_examples:
            st.caption(f"- {path}")
    rewrite_examples = preview.get("rewrites", [])[:5]
    if rewrite_examples:
        st.caption("Path rewrite examples")
        for item in rewrite_examples:
            st.caption(f"- {item.get('field')}: {item.get('original')} → {item.get('rewritten')}")
    external_examples = preview.get("external_paths", [])[:5]
    if external_examples:
        st.caption("External dependencies retained")
        for item in external_examples:
            st.caption(f"- {item.get('field')}: {item.get('original')}")
    ignored_examples = preview.get("ignored", [])[:5]
    if ignored_examples:
        st.caption("Ignored transient examples")
        for item in ignored_examples:
            st.caption(f"- {item.get('relative_path')}")
    fork_examples = [
        plan.get("relative_path", "")
        for plan in preview.get("project_json_plans", [])
        if str(plan.get("relative_path", "")).casefold().startswith("forks/")
    ][:5]
    if fork_examples:
        st.caption("Derived Project examples")
        for path in fork_examples:
            st.caption(f"- {path}")


def _finalize_project_root_import_success(result: dict) -> dict:
    destination_project_path = str(result.get("destination_project_path") or "")
    settings = remember_project(
        st.session_state.get("settings", {}),
        destination_project_path,
        update_last_project=False,
    )
    st.session_state.settings = settings
    if not save_settings(settings):
        result["settings_warning"] = "Recent Projects設定を保存できませんでした。"
    request_project_directory_discovery_refresh()
    return result


def render_existing_project_import_section() -> None:
    if st.session_state.pop(PROJECT_ROOT_IMPORT_CONFIRM_RESET_PENDING_KEY, False):
        st.session_state.pop(PROJECT_ROOT_IMPORT_CONFIRM_KEY, None)
        st.session_state.pop(PROJECT_ROOT_IMPORT_PHRASE_KEY, None)

