def _format_project_assets_bytes(byte_count) -> str:
    size = max(0, int(byte_count or 0))
    units = ("B", "KiB", "MiB", "GiB", "TiB")
    value = float(size)
    for unit in units:
        if value < 1024 or unit == units[-1]:
            if unit == "B":
                return f"{int(value):,} {unit}"
            return f"{value:,.2f} {unit}"
        value /= 1024
    return f"{size:,} B"


def _sync_project_assets_candidate_session_state(project) -> None:
    st.session_state.line_generated_candidates = {
        _line_candidate_key(line): list(_get_persistent_line_candidates(line))
        for line in getattr(project, "prompt_lines", [])
        if (
            getattr(line, "line_type", None) != "separator"
            and _get_persistent_line_candidates(line)
        )
    }


def _copy_project_assets_and_save_with_session_rollback(
    project,
    project_path,
    expected_signature,
    previous_project,
    previous_candidate_state,
):
    try:
        return copy_candidates_to_project_and_save_atomically(
            project,
            project_path,
            expected_signature=expected_signature,
        )
    except ProjectAssetsPreviewStaleError:
        raise
    except Exception:
        st.session_state.project = previous_project
        st.session_state.line_generated_candidates = previous_candidate_state
        raise


def _project_assets_cleanup_preview_rows(preview, *, limit: int = 100):
    rows = []
    for status_key in ("eligible_items", "protected_items"):
        for item in preview.get(status_key, []) or []:
            rows.append(
                {
                    "source": item.get("source_relative_path", ""),
                    "retained": ", ".join(
                        item.get("retained_relative_paths", []) or []
                    ),
                    "size": _format_project_assets_bytes(
                        item.get("size_bytes", 0)
                    ),
                    "sha256": str(item.get("sha256") or "")[:12],
                    "status": item.get("status", ""),
                    "reason": format_core_message_for_display(item.get("reason", "")),
                }
            )
    for item in preview.get("skipped_items", []) or []:
        rows.append(
            {
                "source": (
                    item.get("relative_path")
                    or item.get("source_relative_path")
                    or ""
                ),
                "retained": "",
                "size": "",
                "sha256": "",
                "status": item.get("status", "skipped"),
                "reason": format_core_message_for_display(item.get("reason", "")),
            }
        )
    return rows[: max(1, int(limit))]


def render_verified_project_asset_duplicate_cleanup(
    project,
    project_path,
) -> None:
    if st.session_state.pop(
        PROJECT_ASSETS_CLEANUP_RESET_PENDING_KEY,
        False,
    ):
        st.session_state[PROJECT_ASSETS_CLEANUP_CONFIRM_KEY] = False
        st.session_state[PROJECT_ASSETS_CLEANUP_PHRASE_KEY] = ""

    st.divider()
    st.markdown("**Verified Duplicate Cleanup / 検証済み重複整理**")
    st.caption(
        "Project Assetsでcandidates/へ保全コピーされた画像のうち、"
        "generated/側がProjectから完全に未参照で、内容が保全コピーと"
        "完全一致するものだけを検出します。"
    )
    st.warning(
        "一般的な未参照ファイル削除ではありません。"
        "candidates/側の保全コピーは削除しません。"
    )
    st.caption(
        "削除されたgenerated/側ファイルはPromptGraphから復元できません。"
        "ただし、同一内容のcandidates/側ファイルがProjectに保持されています。"
    )

    result = st.session_state.get(PROJECT_ASSETS_CLEANUP_RESULT_KEY)
    if isinstance(result, dict):
        status = result.get("status")
        if status == "success":
            st.success("Verified duplicates deleted")
        elif status == "partial_failure":
            st.error(
                "一部削除後にIO failureが発生しました。"
                "成功済みの削除と残りの対象を確認してください。"
            )
        elif status == "partial_stale":
            st.error(
                "一部削除後、次のsourceまたはretained copyが変更されたため"
                "処理を停止しました。成功済みの削除と残りの対象を"
                "確認してください。"
            )
        elif status in {"stale", "validation_failure"}:
            st.warning(
                "Previewが古いか、削除前validationに失敗しました。"
                "1件も削除していません。再scanしてください。"
            )
        if status in {"success", "partial_failure", "partial_stale"}:
            result_col_1, result_col_2 = st.columns(2)
            result_col_1.metric(
                "Deleted",
                f"{result.get('deleted_count', 0):,}",
            )
            result_col_2.metric(
                "Reclaimed",
                _format_project_assets_bytes(
                    result.get("deleted_bytes", 0)
                ),
            )
            if status in {"success", "partial_failure"}:
                st.caption(
                    "Retained candidate copies: "
                    f"{result.get('retained_copy_count', 0):,} / "
                    "Project JSON unchanged / candidates/ unchanged"
                )
            else:
                st.caption(
                    "Retained candidate copies: "
                    f"{result.get('retained_copy_count', 0):,} / "
                    "Project JSON unchanged / "
                    "candidates/ not modified by cleanup"
                )
        if result.get("failed_file"):
            st.caption(
                f"Failed file: {result.get('failed_file')} / "
                f"Error: {result.get('error', '')}"
            )
        remaining = result.get("remaining_eligible_files", []) or []
        if remaining:
            st.caption(
                "Remaining eligible files: "
                + ", ".join(remaining[:10])
            )
        if status in {
            "success",
            "partial_failure",
            "partial_stale",
            "stale",
            "validation_failure",
        }:
            st.info("再scanして現在の状態を確認してください。")

    cleanup_disabled = not bool(
        project
        and project_path
        and os.path.isfile(project_path)
    )
    scan_running = bool(
        st.session_state.get(
            PROJECT_ASSETS_CLEANUP_SCAN_RUNNING_KEY,
            False,
        )
    )
    apply_running = bool(
        st.session_state.get(
            PROJECT_ASSETS_CLEANUP_APPLY_RUNNING_KEY,
            False,
        )
    )
    if st.button(
        "Scan duplicate cleanup candidates",
        disabled=cleanup_disabled or scan_running or apply_running,
        key="project_assets_cleanup_scan",
        width="stretch",
    ):
        st.session_state[PROJECT_ASSETS_CLEANUP_SCAN_RUNNING_KEY] = True
        try:
            preview = (
                preview_verified_project_asset_duplicate_cleanup(
                    project,
                    project_path,
                )
            )
            st.session_state[PROJECT_ASSETS_CLEANUP_PREVIEW_KEY] = preview
            st.session_state.pop(PROJECT_ASSETS_CLEANUP_RESULT_KEY, None)
            st.session_state[PROJECT_ASSETS_CLEANUP_CONFIRM_KEY] = False
            st.session_state[PROJECT_ASSETS_CLEANUP_PHRASE_KEY] = ""
        finally:
            st.session_state[PROJECT_ASSETS_CLEANUP_SCAN_RUNNING_KEY] = False

    preview = st.session_state.get(PROJECT_ASSETS_CLEANUP_PREVIEW_KEY)
    if not isinstance(preview, dict):
        if cleanup_disabled:
            st.caption(
                "Cleanupをscanする前にProjectを保存し、Project JSONの"
                "保存先を確定してください。"
            )
        return
    if not preview.get("valid"):
        st.warning(format_core_message_for_display(preview.get("reason")) or "Cleanup preview is invalid.")
        return

    st.markdown("**Cleanup Preview**")
    st.caption(f"対象Project: {preview.get('project_path', '')}")
    metric_col_1, metric_col_2 = st.columns(2)
    metric_col_1.metric(
        "Scanned generated",
        f"{preview.get('scanned_generated_count', 0):,}",
    )
    metric_col_2.metric(
        "Scanned candidates",
        f"{preview.get('scanned_candidate_count', 0):,}",
    )
    metric_col_3, metric_col_4 = st.columns(2)
    metric_col_3.metric(
        "Duplicate groups",
        f"{preview.get('duplicate_group_count', 0):,}",
    )
    metric_col_4.metric(
        "Cleanup eligible",
        f"{preview.get('eligible_count', 0):,}",
    )
    metric_col_5, metric_col_6 = st.columns(2)
    metric_col_5.metric(
        "Protected",
        f"{preview.get('protected_count', 0):,}",
    )
    metric_col_6.metric(
        "Retained copies",
        f"{preview.get('retained_copy_count', 0):,}",
    )
    st.metric(
        "Reclaimable size",
        _format_project_assets_bytes(preview.get("eligible_bytes", 0)),
    )
    for warning in preview.get("warnings", []) or []:
        st.warning(warning)

    preview_rows = _project_assets_cleanup_preview_rows(preview)
    if preview_rows:
        st.dataframe(
            preview_rows,
            hide_index=True,
            width="stretch",
        )
        total_rows = (
            preview.get("eligible_count", 0)
            + preview.get("protected_count", 0)
            + preview.get("skipped_count", 0)
        )
        if total_rows > len(preview_rows):
            st.caption(
                f"先頭{len(preview_rows):,}件を表示 / 全{total_rows:,}件"
            )
    else:
        st.info("現在、表示できるcleanup候補はありません。")

    confirmed = st.checkbox(
        "candidates/側の保全コピーを保持し、generated/側の未参照duplicate"
        "だけを削除することを確認しました。",
        key=PROJECT_ASSETS_CLEANUP_CONFIRM_KEY,
    )
    phrase = st.text_input(
        "確認のため DELETE VERIFIED DUPLICATES と入力",
        key=PROJECT_ASSETS_CLEANUP_PHRASE_KEY,
    )
    apply_disabled = (
        cleanup_disabled
        or apply_running
        or not preview.get("eligible_count")
        or not confirmed
        or phrase != "DELETE VERIFIED DUPLICATES"
    )
    if st.button(
        "Delete verified source duplicates",
        type="primary",
        disabled=apply_disabled,
        key="project_assets_cleanup_apply",
        width="stretch",
    ):
        st.session_state[PROJECT_ASSETS_CLEANUP_APPLY_RUNNING_KEY] = True
        try:
            cleanup_result = (
                delete_verified_project_asset_source_duplicates(
                    project,
                    project_path,
                    preview,
                )
            )
        except ProjectAssetsPreviewStaleError as exc:
            cleanup_result = {
                "status": "stale",
                "deleted_count": 0,
                "deleted_bytes": 0,
                "error": str(exc),
                "remaining_eligible_files": [],
            }
        except Exception as exc:
            cleanup_result = {
                "status": "validation_failure",
                "deleted_count": 0,
                "deleted_bytes": 0,
                "error": str(exc),
                "remaining_eligible_files": [],
            }
        finally:
            st.session_state[
                PROJECT_ASSETS_CLEANUP_APPLY_RUNNING_KEY
            ] = False

        st.session_state[PROJECT_ASSETS_CLEANUP_RESULT_KEY] = cleanup_result
        reset_project_assets_cleanup_operation_state(keep_result=True)
        st.rerun()


