                ensure_original_image_set_route(project)
                st.session_state.project = build_graph(project)
                restore_focus_after_graph_update(st.session_state.get("focused_line_id"))
                sync_text_areas()
                save_current_project_if_possible("prompt line added")
                if new_line:
                    st.session_state.gallery_expanded_line_id = new_line.id
                st.rerun()

