def validate_manual_candidate_path(path: str) -> tuple[str, str]:
    clean_path = (path or "").strip().strip('"')
    if not clean_path:
        return "", "画像ファイルパスを入力してください。"
    resolved_path = _runtime_asset_path(clean_path)
    if not os.path.exists(resolved_path):
        return "", f"画像ファイルが見つかりません: {clean_path}"
    ext = os.path.splitext(resolved_path)[1].lower()
    if ext not in {".png", ".jpg", ".jpeg", ".webp"}:
        return "", "png / jpg / jpeg / webp の画像ファイルを指定してください。"
    return clean_path, ""

def render_gallery_line_editor(line, project):
    _consume_gallery_prompt_widget_sync(line)
    st.markdown(f"#### 編集: `{get_prompt_line_label(line)}`")
    image_col, edit_col = st.columns([1, 2])
    with image_col:
        thumbnail_path = _line_thumbnail_path(line)
        if thumbnail_path:
            st.image(thumbnail_path, width="stretch")
        else:
            st.info("画像なし")
    with edit_col:
        prompt_text = st.text_area(
            "生成ソース（プロンプト）を直接編集",
            value=getattr(line, "current_text", "") or "",
            key=f"pro_gallery_text_{line.id}",
            height=220,
        )
        negative_prompt = st.text_area(
            "Negative Prompt",
            value=getattr(line, "negative_prompt", "") or "",
            key=f"pro_gallery_negative_text_{line.id}",
            height=90,
        )
        prompt_status = _prompt_original_status_label(line)
        if prompt_status == "Prompt: edited":
            st.warning("元画像Promptから変更あり")
        elif prompt_status == "Prompt: original":
            st.caption("元画像Prompt")
        else:
            st.caption("元画像Promptなし")
        can_revert_prompt = bool(get_original_prompt_text(line)) and is_line_prompt_changed_from_original(line)
        if st.button(
            "元画像Promptに戻す",
            key=f"pro_gallery_revert_prompt_{line.id}",
            disabled=not can_revert_prompt,
            help=(
                "編集中Promptを元画像Promptへ戻します。画像参照とNegative Promptは変更しません。"
                if get_original_prompt_text(line)
                else "元画像Promptがないため、Revertできません。"
            ),
        ):
            result = revert_line_prompt_to_original_from_ui(project, line)
            st.session_state.gallery_feedback = result["message"]
            st.session_state.gallery_feedback_kind = "success" if result["ok"] else "warning"
            st.rerun()
        if st.button("保存", key=f"pro_gallery_save_{line.id}", type="primary"):
            update_line_prompts(
                line.id,
                new_text=prompt_text if prompt_text != line.current_text else _UNCHANGED,
                new_negative_prompt=negative_prompt if negative_prompt != (getattr(line, "negative_prompt", "") or "") else _UNCHANGED,
            )
            save_current_project_if_possible("gallery prompt saved")
            st.session_state.gallery_feedback = "生成ソースを保存しました。"
            st.rerun()
        st.divider()
        st.caption("候補イラスト生成 — 保存未済のプロンプト変更があれば生成前に自動保存されます。")
        run_count = st.number_input(
            "生成回数",
            min_value=1,
            max_value=20,
            value=1,
            step=1,
            key=f"pro_gallery_generate_count_{line.id}",
        )
        if st.button("ComfyUIで生成", key=f"pro_gallery_generate_{line.id}"):
            if prompt_text != line.current_text or negative_prompt != (getattr(line, "negative_prompt", "") or ""):
                update_line_prompts(
                    line.id,
                    new_text=prompt_text if prompt_text != line.current_text else _UNCHANGED,
                    new_negative_prompt=negative_prompt if negative_prompt != (getattr(line, "negative_prompt", "") or "") else _UNCHANGED,
                )
                save_current_project_if_possible("gallery prompt saved before generation")
                line = get_line_by_id(st.session_state.project, line.id) or line
            generated_paths = _run_current_line_comfy_multiple(
                st.session_state.project,
                line,
                run_count,
                lambda: _build_focus_line_generation_workflow(st.session_state.project, line),
                f"gallery_gen_{line.id}",
                candidate_source="gallery_generate",
                set_after_on_generate=False,
            )
            if generated_paths:
                st.session_state.gallery_feedback = f"{len(generated_paths)}件の候補イラストを生成しました。"
                st.rerun()


    st.markdown("##### Appended Variants（本編列追加候補）")
    st.caption("「同一プロンプトの別アングル」として追加された候補です。「シーンへ昇格」で本編列に昇格できます。")
    _render_gallery_variant_grid(line, key_prefix="gallery_editor_variant")

    st.markdown("##### 候補イラスト（生成キュー）")
    st.caption("このラインの生成候補です。「次の画像として追加」で本編列に挿入できます。")

    candidates = list(_get_line_generated_candidates(line))
    active_candidates = _active_candidates(candidates)
    existing_candidates = [
        candidate for candidate in active_candidates
        if _candidate_path(candidate) and os.path.exists(_runtime_asset_path(_candidate_path(candidate)))
    ]
    if existing_candidates:
        _render_candidate_grid(line, existing_candidates, "pro_gallery_candidate", allow_set_empty_line_image=True)
    else:
        st.caption("候補イラストはまだありません。")
    _render_candidate_trash(line, "pro_gallery_candidate")

    with st.expander("候補イラストを追加", expanded=False):
        manual_path = st.text_input("画像ファイルパス", key=f"pro_gallery_manual_candidate_path_{line.id}")
        add_col, insert_col, route_end_col = st.columns(3)
        with add_col:
            if st.button("候補として追加", key=f"pro_gallery_add_candidate_{line.id}"):
                candidate_path, error = validate_manual_candidate_path(manual_path)
                if error:
                    st.warning(error)
                else:
                    push_history()
                    _append_line_generated_candidates(line, _make_imported_candidate_record(candidate_path, line))
                    save_current_project_if_possible("manual candidate added")
                    st.rerun()
        with insert_col:
            if st.button("追加して直後に追加", key=f"pro_gallery_add_insert_candidate_{line.id}"):
                candidate_path, error = validate_manual_candidate_path(manual_path)
                if error:
                    st.warning(error)
                elif _insert_candidate_line_from_ui(project, line, candidate_path, add_to_source_candidates=True):
                    st.session_state.gallery_feedback = "候補イラストを追加し、本編列の直後に追加しました。"
                    st.session_state.gallery_feedback_kind = "success"
                    st.rerun()
        with route_end_col:
            if st.button("追加してシーン末尾に追加", key=f"pro_gallery_add_insert_candidate_route_end_{line.id}"):
                candidate_path, error = validate_manual_candidate_path(manual_path)
                if error:
                    st.warning(error)
                elif _insert_candidate_line_from_ui(project, line, candidate_path, add_to_source_candidates=True, placement="route_end"):
                    st.session_state.gallery_feedback = "候補イラストを追加し、現在のシーン末尾に追加しました。"
                    st.session_state.gallery_feedback_kind = "success"
                    st.rerun()

def _gallery_route_anchor_line_id(project, selected_line_ids):
    focused_line_id = st.session_state.get("focused_line_id") or ""
    if focused_line_id:
        return focused_line_id
    selected_line_ids = [line_id for line_id in (selected_line_ids or []) if line_id]
    if selected_line_ids:
        return selected_line_ids[0]
    expanded_line_id = st.session_state.get("gallery_expanded_line_id") or ""
    if expanded_line_id:
        return expanded_line_id
    selected_route_id = st.session_state.get("gallery_selected_route_separator_id") or ""
    route_ids = {route["route_id"] for route in get_gallery_route_options(project)}
    if selected_route_id in route_ids:
        return selected_route_id
    return ""


def _gallery_operation_scope_label(scope: str) -> str:
    return GALLERY_SCOPE_DISPLAY_LABELS_JA.get(scope, "すべてのイラスト")


def _gallery_route_options_with_counts(project) -> list[dict]:
    route_options = []
    active_lines = get_visible_prompt_lines(project)
    for route in get_gallery_route_options(project):
        route_id = route.get("route_id", "")
        route_options.append({
            **route,
            "line_count": _gallery_route_line_count(active_lines, route_id),
        })
    return route_options


def _format_gallery_route_option(route: dict) -> str:
    route_label = route.get("route_label") or route.get("route_id") or "Scene"
    return f"{route_label} ({int(route.get('line_count', 0) or 0)} lines)"


def resolve_gallery_operation_targets(
    project,
    scope: str,
    route_id: str | None = None,
    selected_line_ids: list[str] | None = None,
    *,
    include_lines_without_images: bool = True,
) -> dict:
    scope = scope if scope in {"all_lines", "current_route", "selected_route", "selected_lines"} else "all_lines"
    active_lines = [
        line
        for line in get_visible_prompt_lines(project)
        if not getattr(line, "deleted", False)
    ]
    active_prompt_lines = [line for line in active_lines if is_gallery_operation_prompt_line(line)]
    warnings = []
    route_resolution = {}

    if scope == "all_lines":
        target_lines = active_prompt_lines
    elif scope == "selected_lines":
        selected_ids = {line_id for line_id in (selected_line_ids or []) if line_id}
        target_lines = [line for line in active_prompt_lines if getattr(line, "id", "") in selected_ids]
        if not target_lines:
            warnings.append("イラストが選択されていません。")
    elif scope == "current_route":
        anchor_line_id = _gallery_route_anchor_line_id(project, selected_line_ids or [])
        route_resolution = resolve_gallery_route_for_line(project, anchor_line_id)
        warnings.extend(route_resolution.get("warnings", []))
        route_line_ids = set(route_resolution.get("line_ids", []))
        target_lines = [line for line in active_prompt_lines if getattr(line, "id", "") in route_line_ids]
    else:
        selected_route_id = str(route_id or "").strip()
        route = next(
            (option for option in _gallery_route_options_with_counts(project) if option.get("route_id") == selected_route_id),
            None,
        )
        if route:
            route_line_ids = set(route.get("line_ids", []))
            target_lines = [line for line in active_prompt_lines if getattr(line, "id", "") in route_line_ids]
            route_resolution = {
                "route_id": route.get("route_id", ""),
                "route_label": route.get("route_label", ""),
                "line_ids": list(route_line_ids),
                "line_count": int(route.get("line_count", 0) or 0),
                "warnings": [],
            }
        else:
            target_lines = []
            warnings.append("シーンが選択されていません。")

    if not include_lines_without_images:
        target_lines = [line for line in target_lines if _line_thumbnail_path(line)]

    if scope in {"current_route", "selected_route"} and not target_lines and not warnings:
        warnings.append("選択されたシーンには対象イラストがありません。")

    return {
        "scope": scope,
        "route_id": route_resolution.get("route_id", ""),
        "route_label": route_resolution.get("route_label", ""),
        "route_line_count": route_resolution.get("line_count"),
        "target_lines": target_lines,
        "target_line_ids": [getattr(line, "id", "") for line in target_lines if getattr(line, "id", "")],
        "warnings": warnings,
    }


def _prompt_revert_target_lines(project, target_line_ids=None) -> list:
    if target_line_ids is not None:
        target_ids = {line_id for line_id in target_line_ids if line_id}
        if not target_ids:
            return []
    else:
        target_ids = set()
    lines = []
    for line in get_visible_prompt_lines(project):
        if not is_gallery_operation_prompt_line(line):
            continue
        if target_ids and getattr(line, "id", "") not in target_ids:
            continue
        lines.append(line)
    return lines


def preview_revert_prompts_to_original(project, target_line_ids=None, example_limit=8) -> dict:
    target_lines = _prompt_revert_target_lines(project, target_line_ids=target_line_ids)
    changed_lines = []
    no_original_count = 0
    unchanged_count = 0
    examples = []
    for line in target_lines:
        original_text = get_original_prompt_text(line)
        if not original_text:
            no_original_count += 1
            continue
        if not is_line_prompt_changed_from_original(line):
            unchanged_count += 1
            continue
        changed_lines.append(line)
        if len(examples) < example_limit:
            examples.append({
                "line_id": getattr(line, "id", ""),
                "line_label": get_prompt_line_label(line),
                "line_index": getattr(line, "current_index", None),
                "before": getattr(line, "current_text", "") or "",
                "after": original_text,
            })
    return {
        "target_line_count": len(target_lines),
        "changed_line_count": len(changed_lines),
        "revertable_line_count": len(changed_lines),
        "skipped_no_original_count": no_original_count,
        "unchanged_count": unchanged_count,
        "examples": examples,
        "target_line_ids": [getattr(line, "id", "") for line in target_lines if getattr(line, "id", "")],
        "changed_line_ids": [getattr(line, "id", "") for line in changed_lines if getattr(line, "id", "")],
    }


def apply_revert_prompts_to_original(project, target_line_ids=None) -> dict:
    target_lines = _prompt_revert_target_lines(project, target_line_ids=target_line_ids)
    changed_line_ids = []
    no_original_count = 0
    unchanged_count = 0
    for line in target_lines:
        original_text = get_original_prompt_text(line)
        if not original_text:
            no_original_count += 1
            continue
        if not is_line_prompt_changed_from_original(line):
            unchanged_count += 1
            continue
        result = revert_line_prompt_to_original(line)
        if result.get("changed"):
            changed_line_ids.append(getattr(line, "id", ""))
    return {
        "target_line_count": len(target_lines),
        "changed_line_count": len(changed_line_ids),
        "skipped_no_original_count": no_original_count,
        "unchanged_count": unchanged_count,
        "changed_line_ids": changed_line_ids,
    }


def _render_gallery_operation_target_summary(resolution: dict) -> None:
    st.caption(f"対象: {_gallery_operation_scope_label(resolution.get('scope', 'all_lines'))}")
    if resolution.get("route_id"):
        st.caption(
            f"シーン: {resolution.get('route_label') or '(名称なし)'} "
            f"({resolution.get('route_id')}, {resolution.get('route_line_count') or 0} lines)"
        )
    st.caption(f"対象イラスト: {len(resolution.get('target_lines', []))}")
    for warning in resolution.get("warnings", [])[:3]:
        st.warning(warning)


def _final_export_scope_label(scope: str) -> str:
    return GALLERY_SCOPE_DISPLAY_LABELS_JA.get(scope, "すべてのイラスト")


def _final_export_route_options(project) -> list[dict]:
    return _gallery_route_options_with_counts(project)


def _format_final_export_route_option(route: dict) -> str:
    return _format_gallery_route_option(route)


def resolve_final_export_lines(
    project,
    scope: str,
    route_id: str | None = None,
    selected_line_ids: list[str] | None = None,
    selected_route_ids: list[str] | None = None,
) -> dict:
    scope = scope if scope in {"all_lines", "current_route", "selected_route", "selected_routes"} else "all_lines"
    active_lines = [
        line
        for line in get_visible_prompt_lines(project)
        if not getattr(line, "deleted", False)
    ]
    active_prompt_lines = [line for line in active_lines if is_gallery_operation_prompt_line(line)]
    warnings = []
    route_resolution = {}

    selected_route_resolution = {}
    if scope == "all_lines":
        target_lines = active_prompt_lines
    elif scope == "current_route":
        anchor_line_id = _gallery_route_anchor_line_id(project, selected_line_ids or [])
        route_resolution = resolve_gallery_route_for_line(project, anchor_line_id)
        warnings.extend(route_resolution.get("warnings", []))
        route_line_ids = set(route_resolution.get("line_ids", []))
        target_lines = [line for line in active_prompt_lines if getattr(line, "id", "") in route_line_ids]
    elif scope == "selected_route":
        selected_route_id = str(route_id or "").strip()
        route = next(
            (option for option in _final_export_route_options(project) if option.get("route_id") == selected_route_id),
            None,
        )
        if route:
            route_line_ids = set(route.get("line_ids", []))
            target_lines = [line for line in active_prompt_lines if getattr(line, "id", "") in route_line_ids]
            route_resolution = {
                "route_id": route.get("route_id", ""),
                "route_label": route.get("route_label", ""),
                "line_ids": list(route_line_ids),
                "line_count": int(route.get("line_count", 0) or 0),
                "warnings": [],
            }
        else:
            target_lines = []
            warnings.append("シーンが選択されていません。")
    else:
        selected_route_resolution = resolve_selected_route_export_lines(
            project,
            selected_route_ids,
        )
        target_lines = list(selected_route_resolution["target_lines"])
        route_resolution = {"line_count": len(target_lines)}
        warnings.extend(selected_route_resolution.get("diagnostics", []))

    if scope != "all_lines" and not target_lines and not warnings:
        warnings.append("選択されたシーンには書き出し対象イラストがありません。")

    return {
        "lines": target_lines,
        "line_ids": [getattr(line, "id", "") for line in target_lines if getattr(line, "id", "")],
        "scope": scope,
        "route_id": route_resolution.get("route_id", ""),
        "route_label": route_resolution.get("route_label", ""),
        "route_line_count": route_resolution.get("line_count"),
        "resolved_route_handles": selected_route_resolution.get("resolved_route_handles", []),
        "resolved_route_labels": selected_route_resolution.get("resolved_route_labels", []),
        "selected_route_count": selected_route_resolution.get("selected_route_count", 0),
        "selected_main_line_count": selected_route_resolution.get("selected_main_line_count", 0),
        "selected_workbench_count": selected_route_resolution.get("selected_workbench_count", 0),
        "selected_deleted_member_count": selected_route_resolution.get("selected_deleted_member_count", 0),
        "selected_candidate_count": selected_route_resolution.get("selected_candidate_count", 0),
        "selected_gallery_variant_count": selected_route_resolution.get("selected_gallery_variant_count", 0),
        "route_summaries": selected_route_resolution.get("route_summaries", []),
        "diagnostics": selected_route_resolution.get("diagnostics", []),
        "warnings": warnings,
    }


def _final_export_preview_signature(
    target_resolution: dict,
    preview: dict,
    *,
    output_dir: str,
    base_filename: str,
    start_index: int,
    digits: int,
    strip_metadata: bool,
) -> str:
    signature_payload = {
        "scope": target_resolution.get("scope", ""),
        "resolved_route_handles": list(target_resolution.get("resolved_route_handles", [])),
        "resolved_route_labels": list(target_resolution.get("resolved_route_labels", [])),
        "route_summaries": list(target_resolution.get("route_summaries", [])),
        "target_line_ids": list(target_resolution.get("line_ids", [])),
        "resolved_images": [
            {
                "line_id": item.get("line_id", ""),
                "project_order": item.get("project_order", item.get("line_index")),
                "source_image_path": item.get("source_image_path", ""),
                "source_image_field": item.get("source_image_field", ""),
                "source_size_bytes": item.get("source_size_bytes"),
                "source_size_available": bool(
                    item.get("source_size_available")
                ),
                "output_filename": item.get("output_filename", ""),
            }
            for item in preview.get("items", [])
        ],
        "skipped_items": [
            {
                "line_id": item.get("line_id", ""),
                "reason": item.get("reason", ""),
            }
            for item in preview.get("skipped_items", [])
        ],
        "output_dir": os.path.abspath(str(output_dir or "")),
        "base_filename": preview.get("base_filename", base_filename),
        "start_index": int(start_index),
        "digits": int(digits),
        "strip_metadata": bool(strip_metadata),
    }
    return hashlib.sha256(
        json.dumps(signature_payload, ensure_ascii=False, sort_keys=True, default=str).encode("utf-8")
    ).hexdigest()

def _sequence_preview_source_label(field_name: str) -> str:
    return {
        "selected_candidate_path": "選択中Candidate",
        "generated_image_path": "生成画像",
        "image_path": "元画像 / 参照画像",
    }.get(str(field_name or ""), "画像")


def _clamp_sequence_preview_index(total_count: int) -> int:
    if total_count <= 0:
        st.session_state.sequence_preview_index = 0
        return 0
    try:
        index = int(st.session_state.get("sequence_preview_index", 0))
    except (TypeError, ValueError):
        index = 0
    index = min(max(index, 0), total_count - 1)
    st.session_state.sequence_preview_index = index
    return index


def render_sequence_preview_panel(project, preview: dict) -> None:
    with st.expander("本編プレビュー", expanded=False):
        st.caption("Final Exportと同じ本編画像解決結果を、書き出し前に前後送りで確認します。シーン区切り / Workbench / 削除済みイラスト / 画像なしイラストは含みません。")
        items = list(preview.get("items", []) or [])
        if not items:
            st.info("プレビューできる本編画像がありません。")
            return

        index = _clamp_sequence_preview_index(len(items))
        nav_cols = st.columns([1, 2, 1])
        with nav_cols[0]:
            if st.button("← 前へ", key="sequence_preview_previous", disabled=index <= 0):
                st.session_state.sequence_preview_index = max(index - 1, 0)
                st.rerun()
        with nav_cols[1]:
            st.markdown(f"**{index + 1} / {len(items)}**")
        with nav_cols[2]:
            if st.button("次へ →", key="sequence_preview_next", disabled=index >= len(items) - 1):
                st.session_state.sequence_preview_index = min(index + 1, len(items) - 1)
                st.rerun()

        item = items[index]
        image_path = str(item.get("source_image_path") or "")
        line = get_line_by_id(project, item.get("line_id", ""))
        if image_path and profiled_path_exists(image_path):
            st.image(image_path, width="stretch")
        else:
            st.warning("プレビュー画像ファイルが見つかりません。")

        line_label = get_prompt_line_label(line) if line else item.get("source_original_filename", "")
        st.caption(f"イラスト: {line_label}")
        route_label = (item.get("route") or {}).get("route_label") or item.get("route_label") or ""
        route_id = (item.get("route") or {}).get("route_id") or item.get("route_id") or ""
        if route_label or route_id:
            st.caption(f"シーン: {route_label or '(名称なし)'} ({route_id})")
        st.caption(f"画像ソース: {_sequence_preview_source_label(item.get('source_image_field'))}")
        st.caption(f"画像ファイル: {os.path.basename(image_path)}")

        prompt_text = str(item.get("prompt_text") or "")
        if prompt_text:
            st.caption(f"Prompt: {_short_preview(prompt_text, 180)}")

        if st.button("Galleryで開く", key="sequence_preview_open_gallery", disabled=not line):
            st.session_state.focused_line_id = item.get("line_id", "")
            st.session_state.highlighted_line_id = item.get("line_id", "")
            st.session_state.gallery_expanded_line_id = item.get("line_id", "")
            st.session_state.gallery_feedback = f"本編プレビューのイラストを開きました: {line_label}"
            st.session_state.gallery_feedback_kind = "success"
            st.rerun()


def _format_duration(seconds: float) -> str:
    if seconds <= 0:
        return "不明"
    seconds = int(round(seconds))
    minutes, secs = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    if hours:
        return f"約{hours}時間{minutes}分"
    if minutes:
        return f"約{minutes}分{secs:02d}秒"
    return f"約{secs}秒"

def _gallery_generation_average_seconds() -> float | None:
    durations = [
        float(value)
        for value in st.session_state.get("gallery_generation_durations", [])
        if isinstance(value, (int, float)) and value > 0
    ]
    if not durations:
        return None
    return sum(durations) / len(durations)


def _selected_routes_generation_options(project, run_count: int) -> dict:
    workflow_path = (
        st.session_state.get("comfy_workflow_path")
        or st.session_state.settings.get("comfyui_workflow_path", "workflow_api.json")
    )
    resolved_workflow_path, workflow_source_kind = resolve_effective_comfy_workflow_path(workflow_path)
    workflow_file_signature = {}
    if resolved_workflow_path and os.path.isfile(resolved_workflow_path):
        try:
            workflow_stat = os.stat(resolved_workflow_path)
            with open(resolved_workflow_path, "rb") as workflow_file:
                workflow_digest = hashlib.sha256(workflow_file.read()).hexdigest()
            workflow_file_signature = {
                "size": int(workflow_stat.st_size),
                "mtime_ns": int(workflow_stat.st_mtime_ns),
                "sha256": workflow_digest,
            }
        except OSError:
            workflow_file_signature = {"unreadable": True}
    return {
        "run_count": int(run_count),
        "settings": copy.deepcopy(st.session_state.get("settings", {})),
        "disabled_modules": sorted(str(value) for value in st.session_state.get("disabled_modules", set())),
        "force_shared_comfy_workflow": bool(
            st.session_state.get(
                "force_shared_comfy_workflow",
                st.session_state.settings.get("force_shared_comfy_workflow", False),
            )
        ),
        "configured_workflow_path": str(workflow_path or ""),
        "resolved_workflow_path": str(resolved_workflow_path or ""),
        "workflow_source_kind": str(workflow_source_kind or ""),
        "workflow_file_signature": workflow_file_signature,
        "comfyui_endpoint": str(
            st.session_state.get("comfy_url")
            or st.session_state.settings.get("comfyui_url", "127.0.0.1:8188")
        ),
        "output_directory": _project_generation_output_dir_path(project),
        "output_prefix_strategy": "gallery_all_{line_id}_{run_index}",
    }


def _build_selected_routes_gallery_generation_plan(
    project,
    run_count: int,
    *,
    full_preflight: bool = False,
) -> dict:
    request_builder = None
    if full_preflight:
        planning_project = copy.deepcopy(project)
        request_builder = lambda line, _run_index: _build_focus_line_generation_workflow(
            planning_project,
            line,
        )
    return build_selected_routes_generation_plan(
        project,
        st.session_state.get("gallery_selected_route_ids", []),
        run_count=run_count,
        generation_options=_selected_routes_generation_options(project, run_count),
        project_path=st.session_state.get("current_project_path", ""),
        request_builder=request_builder,
        example_limit=24,
    )


def _render_selected_routes_gallery_generation_preview(plan: dict) -> None:
    route_labels = plan.get("resolved_route_labels") or []
    st.caption(
        "Selected in Project order: " + ", ".join(route_labels)
        if route_labels
        else "No Scenes selected."
    )
    summary_cols = st.columns(5)
    summary_cols[0].metric("Scenes", int(plan.get("selected_route_count", 0) or 0))
    summary_cols[1].metric("Target Illustrations", int(plan.get("target_line_count", 0) or 0))
    summary_cols[2].metric("Requests", int(plan.get("request_count", 0) or 0))
    summary_cols[3].metric("Expected Candidates", int(plan.get("expected_image_count", 0) or 0))
    summary_cols[4].metric(
        "Skipped / Blocked",
        f"{int(plan.get('skipped_line_count', 0) or 0)} / {int(plan.get('blocked_line_count', 0) or 0)}",
    )
    options = plan.get("generation_options") if isinstance(plan.get("generation_options"), dict) else {}
    st.caption(
        f"Workflow: {options.get('resolved_workflow_path') or '(not available)'} / "
        f"Count: {options.get('run_count') or 0} / "
        f"Output: {options.get('output_directory') or '(not available)'}"
    )
    st.caption("生成結果はCandidateとして追加されます。本編画像とPromptは自動変更されません。")

    route_rows = [
        {
            "Scene": item.get("route_label") or item.get("route_handle"),
            "Handle": item.get("route_handle"),
            "Order": int(item.get("route_order", 0) or 0) + 1,
            "Target Illustrations": item.get("target_line_count", 0),
            "Requests": item.get("request_count", 0),
            "Expected": item.get("expected_image_count", 0),
            "Skipped": item.get("skipped_count", 0),
            "Blocked": item.get("blocked_count", 0),
        }
        for item in plan.get("route_summaries") or []
    ]
    if route_rows:
        st.dataframe(route_rows, hide_index=True, width="stretch")

    line_rows = [
        {
            "Scene": item.get("route_label") or item.get("route_handle"),
            "Illustration": item.get("line_label") or item.get("line_id"),
            "Illustration ID": item.get("line_id"),
            "Project order": item.get("project_order"),
            "Prompt": item.get("prompt_preview", ""),
            "Negative": item.get("negative_prompt_preview", ""),
            "Requests": item.get("request_count", 0),
            "Status": format_core_message_for_display(item.get("blocked_reason")) or "Ready",
        }
        for item in plan.get("line_entries") or []
    ]
    if line_rows:
        with st.expander("Illustration preview", expanded=False):
            st.dataframe(line_rows, hide_index=True, width="stretch")
            hidden_count = int(plan.get("hidden_line_count", 0) or 0)
            if hidden_count:
                st.caption(f"{hidden_count} more Illustrations are hidden.")
    diagnostics = [str(item) for item in plan.get("diagnostics") or [] if str(item).strip()]
    if diagnostics:
        with st.expander("Diagnostics", expanded=False):
            for diagnostic in diagnostics:
                st.warning(format_core_message_for_display(diagnostic))
    if plan.get("reason"):
        st.warning(format_core_message_for_display(plan["reason"]))


def _execute_selected_routes_gallery_generation_plan(project, plan: dict) -> dict:
    comfy_url = str(
        st.session_state.get("comfy_url")
        or st.session_state.settings.get("comfyui_url", "127.0.0.1:8188")
    )
    output_dir = _project_generation_output_dir(project)
    requests = plan.get("request_plan") or []
    total_steps = max(1, len(requests))
    completed_steps = 0
    progress_bar = st.progress(0.0)
    status_text = st.empty()
    eta_text = st.empty()
    warning_seen = set()
    output_paths_by_request = {}

    def submitter(request: dict) -> list[str]:
        nonlocal completed_steps
        run_started_at = time.monotonic()
        line_label = request.get("source_line_label") or request.get("source_line_id")
        run_index = request.get("run_index")
        status_text.markdown(
            f"**Request {completed_steps + 1} / {len(requests)} - Run {run_index}**  `{line_label}`"
        )
        warning = str(request.get("workflow_warning") or "")
        if warning and warning not in warning_seen:
            st.warning(warning)
            warning_seen.add(warning)
        run_paths = []
        try:
            for status in generate_image_with_progress(
                request.get("workflow_json") or {},
                comfy_url,
                output_dir,
                f"gallery_all_{request.get('source_line_id')}_{run_index}",
            ):
                if "value" in status:
                    step_progress = (completed_steps + float(status["value"])) / total_steps
                    progress_bar.progress(min(max(step_progress, 0.0), 1.0))
                if "text" in status:
                    status_text.markdown(
                        f"**Request {completed_steps + 1} / {len(requests)} - Run {run_index}**  "
                        f"{status['text']}"
                    )
                if status.get("type") == "done":
                    run_paths.extend(_status_output_paths(status, output_dir=output_dir))
            unique_paths = []
            seen_paths = set()
            for generated_path in run_paths:
                normalized = os.path.normcase(os.path.abspath(generated_path))
                if normalized in seen_paths:
                    continue
                seen_paths.add(normalized)
                unique_paths.append(generated_path)
            output_paths_by_request[request["request_id"]] = unique_paths
            return unique_paths
        finally:
            duration = time.monotonic() - run_started_at
            if duration > 0:
                st.session_state.gallery_generation_durations.append(duration)
            completed_steps += 1
            progress_bar.progress(min(completed_steps / total_steps, 1.0))
            average_seconds = _gallery_generation_average_seconds()
            if average_seconds and completed_steps < total_steps:
                eta_text.caption(
                    f"推定残り時間: {_format_duration(average_seconds * (total_steps - completed_steps))}"
                )
            elif completed_steps >= total_steps:
                eta_text.caption("完了")

    def candidate_factory(path: str, target_line, request: dict):
        request_paths = output_paths_by_request.get(request.get("request_id"), [])
        output_index = request_paths.index(path) + 1 if path in request_paths else 1
        run_index = request.get("run_index")
        run_label = run_index if len(request_paths) == 1 else f"{run_index}-{output_index}"
        return _make_generated_candidate_record(
            path,
            target_line,
            "gallery_global_generate",
            run_label,
        )

    return execute_gallery_generation_plan(
        st.session_state.project,
        plan,
        submitter=submitter,
        candidate_factory=candidate_factory,
        candidate_appender=_append_line_generated_candidates,
        resolve_path=lambda path: _resolve_generated_output_path(path, output_dir=output_dir),
        path_exists=os.path.isfile,
    )


def _prepare_gallery_operation_widget_state(
    durable_key: str,
    widget_key: str,
    default,
    *,
    options=None,
    legacy_key: str = "",
):
    """Restore one conditionally rendered Gallery widget from durable session state."""

    durable_value = st.session_state.get(durable_key)
    if durable_value is None and legacy_key:
        durable_value = st.session_state.get(legacy_key)
    if options is not None:
        valid_options = list(options)
        normalized_default = default if default in valid_options else (valid_options[0] if valid_options else default)
        if durable_value not in valid_options:
            durable_value = normalized_default
    elif durable_value is None:
        durable_value = default
    st.session_state[durable_key] = durable_value
    st.session_state[widget_key] = durable_value
    if legacy_key and legacy_key not in {durable_key, widget_key}:
        st.session_state.pop(legacy_key, None)
    return durable_value


def _sync_gallery_operation_widget_state(durable_key: str, widget_key: str) -> None:
    st.session_state[durable_key] = st.session_state.get(widget_key)


def _clear_gallery_operation_safety_confirmation() -> None:
    for key in (
        "gallery_generation_selected_routes_confirm",
        "_gallery_generation_selected_routes_confirm_widget",
        "route_batch_candidate_adoption_all_confirm_phrase",
        "route_batch_candidate_adoption_confirm",
        "_route_batch_candidate_adoption_all_confirm_phrase_widget",
        "_route_batch_candidate_adoption_confirm_widget",
        "gallery_candidate_adoption_confirm",
        "_gallery_candidate_adoption_confirm_widget",
    ):
        st.session_state.pop(key, None)


@contextmanager
def _gallery_operation_body_container(label: str, *, expanded: bool, embedded: bool):
    if embedded:
        yield
        return
    with st.expander(label, expanded=expanded):
        yield


def render_gallery_global_generation_controls(
    project,
    active_lines,
    selected_line_ids,
    *,
    embedded: bool = False,
) -> None:
    operation_focus = st.session_state.get("gallery_operation_focus") == "generation"
    if operation_focus:
        st.session_state.pop("gallery_operation_focus", None)
    with _gallery_operation_body_container(
        "Gallery全生成",
        expanded=operation_focus,
        embedded=embedded,
    ):
        st.caption("複数のイラストに対してCandidateだけを生成します。本編列への挿入や元画像の置換は行いません。")

        scope_options = ["all_lines", "current_route", "selected_route", "selected_routes", "selected_lines"]
        _prepare_gallery_operation_widget_state(
            "gallery_generation_scope",
            "_gallery_generation_scope_widget",
            "all_lines",
            options=scope_options,
        )
        scope = st.radio(
            "生成対象",
            scope_options,
            format_func=_gallery_operation_scope_label,
            horizontal=True,
            key="_gallery_generation_scope_widget",
            on_change=_sync_gallery_operation_widget_state,
            args=("gallery_generation_scope", "_gallery_generation_scope_widget"),
        )
        route_options = _gallery_route_options_with_counts(project)
        route_option_lookup = {route.get("route_id", ""): route for route in route_options}
        selected_generation_route_id = ""
        if scope == "selected_route":
            if route_options:
                route_ids = [route.get("route_id", "") for route in route_options]
                _prepare_gallery_operation_widget_state(
                    "gallery_generation_selected_route_id",
                    "_gallery_generation_selected_route_id_widget",
                    route_ids[0],
                    options=route_ids,
                )
                selected_generation_route_id = st.selectbox(
                    "シーンを選択",
                    route_ids,
                    format_func=lambda route_id: _format_gallery_route_option(route_option_lookup.get(route_id, {})),
                    key="_gallery_generation_selected_route_id_widget",
                    on_change=_sync_gallery_operation_widget_state,
                    args=(
                        "gallery_generation_selected_route_id",
                        "_gallery_generation_selected_route_id_widget",
                    ),
                )
            else:
                st.warning("このProjectには選択できるシーンがありません。")
        _prepare_gallery_operation_widget_state(
            "gallery_generation_run_count",
            "_gallery_generation_run_count_widget",
            1,
            options=range(1, 21),
            legacy_key="pro_gallery_global_generation_count",
        )
        run_count = st.number_input(
            "各イラストの生成回数",
            min_value=1,
            max_value=20,
            step=1,
            key="_gallery_generation_run_count_widget",
            on_change=_sync_gallery_operation_widget_state,
            args=("gallery_generation_run_count", "_gallery_generation_run_count_widget"),
        )
        if scope == "selected_routes":
            st.caption(
                "Gallery上部のSelected Scenesで選択した複数シーンを、現在のProject順でCandidate生成します。"
            )
            current_plan = _build_selected_routes_gallery_generation_plan(
                project,
                int(run_count),
                full_preflight=False,
            )
            preview_button_disabled = not current_plan.get("selected_route_count")
            if st.button(
                "Fresh Preview",
                key="gallery_generation_selected_routes_fresh_preview",
                disabled=preview_button_disabled,
            ):
                st.session_state.gallery_generation_selected_routes_preview = (
                    _build_selected_routes_gallery_generation_plan(
                        project,
                        int(run_count),
                        full_preflight=True,
                    )
                )
                st.session_state._gallery_generation_selected_routes_confirm_widget = False

            stored_preview = st.session_state.get("gallery_generation_selected_routes_preview")
            preview_to_render = stored_preview if isinstance(stored_preview, dict) else current_plan
            _render_selected_routes_gallery_generation_preview(preview_to_render)
            submit_validation = validate_selected_routes_generation_submit(stored_preview, current_plan)
            if stored_preview and not submit_validation.get("allowed"):
                st.warning(format_core_message_for_display(submit_validation.get("reason")) or "Fresh Previewを再実行してください。")
            confirmed = st.checkbox(
                "Preview内容を確認しました",
                key="_gallery_generation_selected_routes_confirm_widget",
                disabled=not isinstance(stored_preview, dict) or not stored_preview.get("valid"),
            )
            can_submit = bool(submit_validation.get("allowed") and confirmed)
            if not st.button(
                "Selected ScenesをCandidate生成",
                key="pro_gallery_selected_routes_generate",
                disabled=not can_submit,
                type="primary",
            ):
                return

            fresh_plan = _build_selected_routes_gallery_generation_plan(
                project,
                int(run_count),
                full_preflight=True,
            )
            fresh_validation = validate_selected_routes_generation_submit(stored_preview, fresh_plan)
            if not fresh_validation.get("allowed"):
                st.warning(format_core_message_for_display(fresh_validation.get("reason")) or "Fresh Previewを再実行してください。")
                return

            push_history()
            result = _execute_selected_routes_gallery_generation_plan(project, fresh_plan)
            candidate_count = int(result.get("candidate_count", 0) or 0)
            if candidate_count:
                save_current_project_if_possible("selected Routes gallery candidates generated")
                st.success(
                    f"Selected Scenes生成が完了しました。Candidate {candidate_count} 件を追加しました。"
                )
            failures = result.get("failures") or []
            if failures:
                st.warning(
                    f"{len(failures)} 件のrequestが失敗しました。成功していない出力はCandidate登録していません。"
                )
                with st.expander("Selected Scenes generation errors", expanded=False):
                    st.json(failures)
            result_diagnostics = [
                diagnostic
                for request_result in result.get("request_results") or []
                for diagnostic in request_result.get("diagnostics") or []
            ]
            if result_diagnostics:
                st.warning(
                    f"{len(result_diagnostics)} 件のoutput diagnosticがあります。"
                )
                with st.expander("Selected Scenes output diagnostics", expanded=False):
                    for diagnostic in result_diagnostics:
                        st.caption(format_core_message_for_display(diagnostic))
            if not candidate_count and not failures:
                st.info(format_core_message_for_display(result.get("reason")) or "Candidateは追加されませんでした。")
            return

        target_resolution = resolve_gallery_operation_targets(
            project,
            scope,
            route_id=selected_generation_route_id,
            selected_line_ids=selected_line_ids,
        )
        targets = target_resolution["target_lines"]
        _render_gallery_operation_target_summary(target_resolution)
        st.caption(f"対象イラスト: {len(targets)}件 / 各イラスト {int(run_count)}回")
        average_seconds = _gallery_generation_average_seconds()
        if average_seconds:
            st.caption(f"平均生成時間: {_format_duration(average_seconds)} / 1回")
        else:
            st.caption("平均生成時間: まだ推定できません")

        if not st.button("Gallery全生成", key="pro_gallery_global_generate", disabled=not targets, type="primary"):
            return

        comfy_url = st.session_state.get("comfy_url") or st.session_state.settings.get("comfyui_url", "127.0.0.1:8188")
        output_dir = _project_generation_output_dir(project)
        total_steps = max(1, len(targets) * int(run_count))
        completed_steps = 0
        success_count = 0
        failure_records = []
        progress_bar = st.progress(0.0)
        status_text = st.empty()
        eta_text = st.empty()
        warning_seen = ""
        push_history()

        for line_index, line in enumerate(targets, start=1):
            for run_index in range(1, int(run_count) + 1):
                run_started_at = time.monotonic()
                status_text.markdown(
                    f"**Illustration {line_index} / {len(targets)} — Run {run_index} / {int(run_count)}**  "
                    f"`{getattr(line, 'original_file_name', '')}`"
                )
                average_seconds = _gallery_generation_average_seconds()
                if average_seconds:
                    eta_text.caption(f"推定残り時間: {_format_duration(average_seconds * (total_steps - completed_steps))}")
                else:
                    eta_text.caption("推定残り時間: 計算中")

                run_paths = []
                try:
                    workflow_json, warning = _build_focus_line_generation_workflow(st.session_state.project, line)
                    if warning and warning != warning_seen:
                        st.warning(warning)
                        warning_seen = warning

                    for status in generate_image_with_progress(
                        workflow_json,
                        comfy_url,
                        output_dir,
                        f"gallery_all_{line.id}_{run_index}",
                    ):
                        if "value" in status:
                            step_progress = (completed_steps + float(status["value"])) / total_steps
                            progress_bar.progress(min(max(step_progress, 0.0), 1.0))
                            average_seconds = _gallery_generation_average_seconds()
                            if average_seconds:
                                remaining_steps = max(total_steps - completed_steps - float(status["value"]), 0)
                                eta_text.caption(f"推定残り時間: {_format_duration(average_seconds * remaining_steps)}")
                        if "text" in status:
                            status_text.markdown(
                                f"**Illustration {line_index} / {len(targets)} — Run {run_index} / {int(run_count)}**  "
                                f"{status['text']}"
                            )
                        if status.get("type") == "done":
                            run_paths.extend(_status_output_paths(status, output_dir=output_dir))

                    if run_paths:
                        unique_run_paths = []
                        seen_run_paths = set()
                        for generated_path in run_paths:
                            norm_path = os.path.normcase(os.path.abspath(generated_path))
                            if norm_path in seen_run_paths:
                                continue
                            unique_run_paths.append(generated_path)
                            seen_run_paths.add(norm_path)
                        target_line = get_line_by_id(st.session_state.project, line.id) or line
                        records = [
                            _make_generated_candidate_record(
                                path,
                                target_line,
                                "gallery_global_generate",
                                run_index if len(unique_run_paths) == 1 else f"{run_index}-{output_index}",
                            )
                            for output_index, path in enumerate(unique_run_paths, start=1)
                        ]
                        _append_line_generated_candidates(target_line, records)
                        success_count += len(unique_run_paths)
                    else:
                        failure_records.append({
                            "line": getattr(line, "original_file_name", line.id),
                            "run": run_index,
                            "error": "生成は完了しましたが、出力画像を取得できませんでした。",
                        })
                except Exception as exc:
                    failure_record = {
                        "line": getattr(line, "original_file_name", line.id),
                        "line_id": getattr(line, "id", ""),
                        "run": run_index,
                        "error": str(exc),
                    }
                    comfy_diagnostics = getattr(exc, "diagnostics", None)
                    if comfy_diagnostics:
                        failure_record["diagnostics"] = comfy_diagnostics
                    failure_records.append(failure_record)
                finally:
                    duration = time.monotonic() - run_started_at
                    if duration > 0:
                        st.session_state.gallery_generation_durations.append(duration)
                    completed_steps += 1
                    progress_bar.progress(min(completed_steps / total_steps, 1.0))
                    average_seconds = _gallery_generation_average_seconds()
                    if average_seconds and completed_steps < total_steps:
                        eta_text.caption(f"推定残り時間: {_format_duration(average_seconds * (total_steps - completed_steps))}")
                    elif completed_steps >= total_steps:
                        eta_text.caption("推定残り時間: 約0秒")

        save_current_project_if_possible("gallery-wide candidates generated")
        if success_count:
            st.success(f"Gallery全生成が完了しました。候補イラスト {success_count} 件を追加しました。")
        if success_count and target_resolution.get("route_id"):
            st.info(
                f"{_gallery_operation_scope_label(scope)}: "
                f"{target_resolution.get('route_label') or '(名称なし)'} "
                f"({target_resolution.get('route_line_count') or 0} lines) に候補を追加しました。"
            )
        if failure_records:
            st.warning(f"{len(failure_records)} 件の生成で問題がありました。残りのイラストは処理済みです。")
            with st.expander("Gallery全生成エラー詳細", expanded=False):
                st.json(failure_records)
        if not success_count and not failure_records:
            st.info("生成対象はありましたが、候補イラストは追加されませんでした。")

def render_gallery_batch_candidate_adoption(
    project,
    active_lines,
    selected_line_ids,
    *,
    embedded: bool = False,
) -> None:
    operation_focus = st.session_state.get("gallery_operation_focus") == "candidate_adoption"
    if operation_focus:
        st.session_state.pop("gallery_operation_focus", None)
    with _gallery_operation_body_container(
        "Batch Candidate Adoption（候補の一括採用）",
        expanded=operation_focus,
        embedded=embedded,
    ):
        st.caption(
            "生成したCandidate画像をシーン／Selected Scenes単位で確認し、本編画像へ一括反映します。"
            "Promptは自動変更されないため、PreviewのDrift表示を確認してください。"
        )
        st.markdown("##### Scene Batch Candidate Adoption Preview")
        st.caption("Dry-run only. This preview does not change project data, image references, prompts, candidates, or lineage.")
        preview_source_options = ["latest", "first", GALLERY_VARIANT_PREVIEW_SOURCE]
        _prepare_gallery_operation_widget_state(
            "route_batch_candidate_adoption_preview_source",
            "_route_batch_candidate_adoption_preview_source_widget",
            "latest",
            options=preview_source_options,
        )
        preview_source = st.radio(
            "Preview adoption source",
            options=preview_source_options,
            format_func=lambda value: {
                "latest": "Latest active candidate per line",
                "first": "First active candidate per line",
                GALLERY_VARIANT_PREVIEW_SOURCE: "Latest appended Gallery Variant per line",
            }[value],
            horizontal=True,
            key="_route_batch_candidate_adoption_preview_source_widget",
            on_change=_sync_gallery_operation_widget_state,
            args=(
                "route_batch_candidate_adoption_preview_source",
                "_route_batch_candidate_adoption_preview_source_widget",
            ),
        )
        preview_scope_options = [
            "all_lines",
            "selected_lines",
            "current_route",
            "selected_route",
            "selected_routes",
        ]
        _prepare_gallery_operation_widget_state(
            "route_batch_candidate_adoption_preview_scope",
            "_route_batch_candidate_adoption_preview_scope_widget",
            "all_lines",
            options=preview_scope_options,
        )
        preview_scope = st.radio(
            "Preview scope",
            options=preview_scope_options,
            format_func=lambda value: {
                "all_lines": "All",
                "selected_lines": f"Selected Illustrations ({len(selected_line_ids)})",
                "current_route": "Current Scene",
                "selected_route": "Selected Scene",
                "selected_routes": "Selected Scenes",
            }[value],
            horizontal=True,
            key="_route_batch_candidate_adoption_preview_scope_widget",
            on_change=_sync_gallery_operation_widget_state,
            args=(
                "route_batch_candidate_adoption_preview_scope",
                "_route_batch_candidate_adoption_preview_scope_widget",
            ),
        )
        preview_selected_route_id = ""
        if preview_scope == "selected_route":
            route_options = _gallery_route_options_with_counts(project)
            if route_options:
                route_ids = [route.get("route_id", "") for route in route_options]
                _prepare_gallery_operation_widget_state(
                    "route_batch_candidate_adoption_preview_selected_route_id",
                    "_route_batch_candidate_adoption_preview_selected_route_id_widget",
                    route_ids[0],
                    options=route_ids,
                )
                preview_selected_route_id = st.selectbox(
                    "Scene",
                    options=route_ids,
                    format_func=lambda route_id: _format_gallery_route_option(
                        next((route for route in route_options if route.get("route_id") == route_id), {})
                    ),
                    key="_route_batch_candidate_adoption_preview_selected_route_id_widget",
                    on_change=_sync_gallery_operation_widget_state,
                    args=(
                        "route_batch_candidate_adoption_preview_selected_route_id",
                        "_route_batch_candidate_adoption_preview_selected_route_id_widget",
                    ),
                )
            else:
                st.warning("No Scenes are available for preview.")

        preview_selected_route_ids = []
        if preview_scope == "selected_routes":
            selected_routes_state = sanitize_selected_route_ids(
                project,
                st.session_state.get("gallery_selected_route_ids", []),
            )
            preview_selected_route_ids = list(selected_routes_state.get("selected_route_ids") or [])
            if preview_selected_route_ids:
                st.caption(
                    "Selected Scenes in Project order: "
                    + ", ".join(selected_routes_state.get("selected_route_labels") or preview_selected_route_ids)
                )
            else:
                st.warning("Select one or more Scenes in Gallery before previewing adoption.")

        preview_current_route_anchor_id = ""
        if preview_scope == "current_route":
            preview_current_route_anchor_id = _gallery_route_anchor_line_id(project, selected_line_ids)

        all_scope_line_ids = ()
        all_confirm_phrase = ""
        if preview_scope == "all_lines":
            all_scope_resolution = resolve_gallery_operation_targets(
                project,
                "all_lines",
                include_lines_without_images=True,
            )
            all_scope_line_ids = tuple(all_scope_resolution.get("target_line_ids", []))
            st.warning(
                "All scope can affect every eligible Gallery line in the project. "
                "All apply requires a fresh preview, the confirmation checkbox, "
                f"and the exact `{ALL_APPLY_CONFIRM_PHRASE}` phrase."
            )
            st.caption(
                "Prompt text is not rewritten automatically. Run Candidate Prompt Adoption separately when needed. "
                "Candidate sources and latest appended Gallery Variant source use the same All apply guard."
            )
            all_confirm_phrase = st.text_input(
                f"Type {ALL_APPLY_CONFIRM_PHRASE} to enable All apply.",
                key="_route_batch_candidate_adoption_all_confirm_phrase_widget",
            )

        if preview_scope == "selected_routes":
            preview_signature = build_selected_routes_candidate_adoption_signature(
                project,
                preview_selected_route_ids,
                source=preview_source,
                project_path=st.session_state.get("current_project_path", ""),
                resolve_path=_runtime_asset_path,
                path_exists=profiled_path_exists,
            )
        else:
            preview_signature = build_route_batch_adoption_preview_signature(
                source=preview_source,
                scope=preview_scope,
                selected_route_id=preview_selected_route_id,
                current_route_anchor_id=preview_current_route_anchor_id,
                selected_line_ids=selected_line_ids or [],
                all_scope_line_ids=all_scope_line_ids,
            )
        preview_disabled = (
            (preview_scope == "selected_lines" and not selected_line_ids)
            or (preview_scope == "selected_route" and not preview_selected_route_id)
            or (preview_scope == "selected_routes" and not preview_selected_route_ids)
        )
        if st.button(
            "Preview Scene Candidate Adoption",
            disabled=preview_disabled,
            key="route_batch_candidate_adoption_preview_btn",
        ):
            st.session_state.route_batch_candidate_adoption_preview = {
                "signature": preview_signature,
                "preview": preview_route_batch_candidate_adoption(
                    project,
                    scope=preview_scope,
                    route_id=preview_selected_route_id,
                    selected_line_ids=selected_line_ids,
                    selected_route_ids=preview_selected_route_ids,
                    source=preview_source,
                    example_limit=20,
                ),
            }

        route_preview_state = st.session_state.get("route_batch_candidate_adoption_preview")
        route_preview_current = (
            route_preview_state
            and route_preview_state.get("signature") == preview_signature
        )
        route_apply_result = st.session_state.pop("route_batch_candidate_adoption_apply_result", None)
        if route_apply_result:
            if route_apply_result.get("error"):
                st.error(format_core_message_for_display(route_apply_result.get("error")))
            else:
                st.success(
                    f"Applied {route_apply_result.get('applied_count', 0)} candidate image(s). "
                    f"First main image: {route_apply_result.get('first_main_image_count', 0)} / "
                    f"swaps with retreat: {route_apply_result.get('swap_with_retreat_count', 0)} / "
                    f"skipped: {route_apply_result.get('skipped_count', 0)}."
                )
            skipped_reasons = route_apply_result.get("skipped_reasons") or {}
            if skipped_reasons:
                st.caption(
                    "Skipped reasons: "
                    + ", ".join(
                        f"{format_core_message_for_display(reason)}: {count}"
                        for reason, count in skipped_reasons.items()
                    )
                )
        if route_preview_state and not route_preview_current:
            st.caption("Scene Candidate Adoption preview is out of date. Run preview again.")
        if route_preview_current:
            route_preview = route_preview_state.get("preview", {})
            _render_route_batch_candidate_adoption_preview(route_preview)
            route_apply_supported = is_route_batch_adoption_apply_supported(preview_scope, preview_source)
            if preview_scope == "all_lines":
                if route_apply_supported:
                    st.warning(
                        "All apply is enabled only after a fresh preview, "
                        "the confirmation checkbox, and the exact APPLY ALL phrase."
                    )
                else:
                    st.warning(
                        "All apply is enabled only for latest/first Candidate sources "
                        "and latest appended Gallery Variant source."
                    )
                st.warning(
                    "Review the project-wide target list carefully before applying. "
                    "This can update every eligible Gallery line with an active Candidate or Gallery Variant source."
                )
                st.caption(
                    "All scope summary: "
                    f"target lines {route_preview.get('targeted_line_count', 0)} / "
                    f"will adopt {route_preview.get('will_adopt_count', 0)} / "
                    f"swaps {route_preview.get('swap_with_retreat_count', 0)} / "
                    f"first main images {route_preview.get('first_main_image_count', 0)} / "
                    f"skipped {route_preview.get('skipped_count', 0)}."
                )
            elif preview_scope not in APPLY_SUPPORTED_SCOPES:
                st.warning(
                    "Apply is available for Selected Illustrations, Current Scene, Selected Scene, Selected Scenes, "
                    "and All scope."
                )
            if preview_source == GALLERY_VARIANT_PREVIEW_SOURCE and preview_scope == "all_lines":
                st.caption(
                    "Gallery Variant All apply updates selected_candidate_path only. "
                    "It does not mutate gallery_variants or materialize the variant image into generated_candidates."
                )
            st.caption(
                "Prompt text, negative prompt, image_path, generated_image_path, image files, "
                "Trash state, Workbench behavior, Final Export behavior, Derived Project behavior, "
                "Attribute State, and LineBinding are not changed."
            )
            confirm_route_apply = st.checkbox(
                "I reviewed the Scene-scope preview and understand prompt text will not be changed.",
                key="_route_batch_candidate_adoption_confirm_widget",
            )
            route_apply_enabled = is_route_batch_adoption_apply_button_enabled(
                scope=preview_scope,
                source=preview_source,
                preview_current=bool(route_preview_current),
                will_adopt_count=route_preview.get("will_adopt_count", 0),
                confirmed=bool(confirm_route_apply),
                all_confirm_phrase=all_confirm_phrase,
            )
            if st.button(
                "Apply Scene Candidate Adoption",
                type="primary",
                disabled=not route_apply_enabled,
                key="route_batch_candidate_adoption_apply_btn",
            ):
                prev_focus = st.session_state.get("focused_line_id")
                if preview_scope != "selected_routes":
                    push_history()
                result = apply_route_batch_candidate_adoption(
                    st.session_state.project,
                    scope=preview_scope,
                    route_id=preview_selected_route_id,
                    selected_line_ids=selected_line_ids,
                    selected_route_ids=preview_selected_route_ids,
                    expected_signature=preview_signature,
                    source=preview_source,
                )
                updated_project = result.pop("updated_project", None)
                apply_succeeded = bool(result.get("applied_count", 0)) and (
                    preview_scope != "selected_routes" or result.get("applied")
                )
                if apply_succeeded:
                    if preview_scope == "selected_routes":
                        push_history()
                    if updated_project is not None:
                        st.session_state.project = updated_project
                    st.session_state.project = build_graph(st.session_state.project)
                    applied_line_ids = set(result.get("applied_line_ids") or [])
                    for line in getattr(st.session_state.project, "prompt_lines", []):
                        if getattr(line, "id", "") in applied_line_ids:
                            _sync_line_generated_candidates_to_session(line, _get_persistent_line_candidates(line))
                    restore_focus_after_graph_update(prev_focus)
                    sync_text_areas()
                    save_current_project_if_possible("route-scope candidates batch adopted")
                st.session_state.pop("route_batch_candidate_adoption_preview", None)
                st.session_state.route_batch_candidate_adoption_apply_result = result
                st.rerun()

        st.divider()
        st.markdown("##### Existing Batch Adopt Gallery Candidates")
        st.caption("Existing apply behavior is unchanged and separate from the Scene-scope operation above.")
        source_options = ["latest", "first"]
        _prepare_gallery_operation_widget_state(
            "gallery_candidate_adoption_source",
            "_gallery_candidate_adoption_source_widget",
            "latest",
            options=source_options,
        )
        source = st.radio(
            "Adoption source",
            options=source_options,
            format_func=lambda value: {
                "latest": "Latest candidate per line",
                "first": "First candidate per line",
            }[value],
            horizontal=True,
            key="_gallery_candidate_adoption_source_widget",
            on_change=_sync_gallery_operation_widget_state,
            args=("gallery_candidate_adoption_source", "_gallery_candidate_adoption_source_widget"),
        )
        mode_options = ["replace", "append"]
        _prepare_gallery_operation_widget_state(
            "gallery_candidate_adoption_mode",
            "_gallery_candidate_adoption_mode_widget",
            "replace",
            options=mode_options,
        )
        mode = st.radio(
            "Adoption mode",
            options=mode_options,
            format_func=lambda value: {
                "replace": "Replace current adopted image",
                "append": "Append Variant",
            }[value],
            horizontal=False,
            key="_gallery_candidate_adoption_mode_widget",
            on_change=_sync_gallery_operation_widget_state,
            args=("gallery_candidate_adoption_mode", "_gallery_candidate_adoption_mode_widget"),
        )
        scope_options = ["all"]
        if selected_line_ids:
            scope_options.append("selected")
        _prepare_gallery_operation_widget_state(
            "gallery_candidate_adoption_scope",
            "_gallery_candidate_adoption_scope_widget",
            "all",
            options=scope_options,
        )
        scope = st.radio(
            "Scope",
            options=scope_options,
            format_func=lambda value: {
                "all": "All lines with candidates",
                "selected": f"Selected lines ({len(selected_line_ids)})",
            }[value],
            horizontal=True,
            key="_gallery_candidate_adoption_scope_widget",
            on_change=_sync_gallery_operation_widget_state,
            args=("gallery_candidate_adoption_scope", "_gallery_candidate_adoption_scope_widget"),
        )

        target_line_ids = selected_line_ids if scope == "selected" else None
        signature = {
            "source": source,
            "mode": mode,
            "scope": scope,
            "target_line_ids": tuple(target_line_ids or []),
        }
        preview_disabled = scope == "selected" and not selected_line_ids
        if st.button(
            "Preview Candidate Adoption",
            disabled=preview_disabled,
            key="gallery_candidate_adoption_preview_btn",
        ):
            st.session_state.gallery_candidate_adoption_preview = {
                "signature": signature,
                "preview": preview_gallery_candidate_adoption(
                    project,
                    target_line_ids=target_line_ids,
                    source=source,
                    mode=mode,
                ),
            }

        preview_state = st.session_state.get("gallery_candidate_adoption_preview")
        preview_current = (
            preview_state
            and preview_state.get("signature") == signature
        )
        if preview_state and not preview_current:
            st.caption("Candidate adoption preview is out of date. Run preview again.")
        if not preview_current:
            return

        preview = preview_state["preview"]
        metric_cols = st.columns(5 if mode == "append" else 4)
        metric_cols[0].metric("Target lines", preview["target_line_count"])
        metric_cols[1].metric("Candidates found", preview["candidates_found"])
        metric_cols[2].metric("Missing", preview["candidates_missing"])
        if mode == "append":
            metric_cols[3].metric("Already variants", preview.get("already_variant_count", 0))
            metric_cols[4].metric("Will append", preview["affected_line_count"])
        else:
            metric_cols[3].metric("Will update", preview["affected_line_count"])

        if preview["affected_line_count"] == 0:
            st.info("No candidate images will be adopted.")

        for example in preview["examples"]:
            st.markdown(f"**{example['display_id']}**")
            st.caption(f"Illustration id: `{example['line_id']}` / index: {example['line_index']}")
            st.caption(f"Current adopted image: {_short_preview(example.get('current_image') or '(none)', 180)}")
            st.caption(f"Candidate image: {_short_preview(example.get('candidate_image') or '(none)', 180)}")
            if mode == "append":
                st.caption(f"Gallery variants on line: {example.get('gallery_variants_count', 0)}")
                st.caption("Operation: append variant without changing the current adopted image.")
                if example.get("already_variant"):
                    st.caption("Already appended as a variant; apply will skip this line.")
                    st.caption(f"Matched variant id: `{example.get('matched_variant_id') or '(unknown)'}`")
                    st.caption(f"Matched variant path: {_short_preview(example.get('matched_variant_path') or '(none)', 180)}")
            metadata_caption = example.get("candidate_metadata") or "(no candidate metadata summary)"
            st.caption(f"Candidate metadata: {_short_preview(metadata_caption, 180)}")

        confirm_adoption = st.checkbox(
            "I reviewed the preview and want to apply this candidate adoption.",
            key="_gallery_candidate_adoption_confirm_widget",
        )
        if st.button(
            "Apply Candidate Adoption",
            type="primary",
            disabled=preview["affected_line_count"] == 0 or not confirm_adoption,
            key="gallery_candidate_adoption_apply_btn",
        ):
            push_history()
            prev_focus = st.session_state.get("focused_line_id")
            result = apply_gallery_candidate_adoption(
                st.session_state.project,
                target_line_ids=target_line_ids,
                source=source,
                mode=mode,
            )
            restore_focus_after_graph_update(prev_focus)
            sync_text_areas()
            st.session_state.pop("gallery_candidate_adoption_preview", None)
            save_current_project_if_possible("gallery candidates batch adopted")
            action_label = "Appended" if mode == "append" else "Adopted"
            st.success(
                f"{action_label} {result['updated_count']} candidate image(s). "
                f"Skipped {result['skipped_count']} line(s)."
            )
            st.rerun()


def render_gallery_batch_variant_promotion(project, active_lines, selected_line_ids) -> None:
    with st.expander("Batch Promote Variants（Variantを本編列へ昇格）", expanded=False):
        st.caption(
            "対象イラストのAppended Variantを、新しい通常Galleryイラストとして本編列へ追加します。"
        )
        st.caption(
            "元イラストとVariant recordは変更せず、シーン区切りも新規作成しません。"
        )
        source = st.radio(
            "Variantの選び方",
            options=["latest", "first"],
            format_func=lambda value: {
                "latest": "各イラストの最新Variant",
                "first": "各イラストの最初のVariant",
            }[value],
            horizontal=True,
            key="gallery_variant_promotion_source",
        )
        scope_key = "gallery_variant_promotion_scope"
        stored_scope = st.session_state.get(scope_key)
        normalized_scope = normalize_batch_variant_promotion_scope(stored_scope)
        if stored_scope != normalized_scope:
            st.session_state[scope_key] = normalized_scope
        scope = st.radio(
            "対象範囲",
            options=list(VARIANT_PROMOTION_SCOPES),
            format_func=lambda value: {
                "current_route": "現在のシーン",
                "selected_route": "シーンを選択",
                "selected_routes": "Selected Scenes",
                "selected_lines": f"選択中のイラスト ({len(selected_line_ids)})",
                "all_lines": "すべてのGalleryイラスト",
            }[value],
            horizontal=True,
            key=scope_key,
        )
        route_options = _gallery_route_options_with_counts(project)
        route_handle_counts = Counter(
            str(option.get("route_id") or "")
            for option in route_options
            if str(option.get("route_id") or "")
        )
        route_options = [
            option
            for option in route_options
            if route_handle_counts.get(str(option.get("route_id") or ""), 0) == 1
        ]
        route_by_id = {
            str(option.get("route_id") or ""): option
            for option in route_options
        }
        selected_route_id = ""
        if scope == "selected_route":
            route_ids = list(route_by_id)
            if route_ids:
                route_widget_key = "gallery_variant_promotion_selected_route_id"
                if st.session_state.get(route_widget_key) not in route_ids:
                    st.session_state[route_widget_key] = route_ids[0]
                selected_route_id = st.selectbox(
                    "対象シーン",
                    route_ids,
                    format_func=lambda route_id: _format_gallery_route_option(route_by_id[route_id]),
                    key=route_widget_key,
                )
            else:
                st.warning("選択可能なシーンがありません。")

        placement = st.radio(
            "配置",
            options=["end", "after_parent"],
            format_func=lambda value: {
                "end": "Gallery末尾",
                "after_parent": "親イラストの直後",
            }[value],
            horizontal=True,
            key="gallery_variant_promotion_placement",
        )
        current_anchor_line_id = _gallery_route_anchor_line_id(project, selected_line_ids)
        selected_route_ids = list(st.session_state.get("gallery_selected_route_ids", []))
        project_path = st.session_state.get("current_project_path", "")
        plan_kwargs = {
            "scope": scope,
            "source": source,
            "placement": placement,
            "current_anchor_line_id": current_anchor_line_id,
            "selected_route_id": selected_route_id,
            "selected_route_ids": selected_route_ids,
            "selected_line_ids": selected_line_ids,
            "project_path": project_path,
            "resolve_path": _runtime_asset_path,
        }
        target_resolution = resolve_batch_variant_promotion_targets(
            project,
            scope,
            current_anchor_line_id=current_anchor_line_id,
            selected_route_id=selected_route_id,
            selected_route_ids=selected_route_ids,
            selected_line_ids=selected_line_ids,
        )
        if scope == "selected_routes" and not target_resolution["selected_route_handles"]:
            st.info("Selected Scenesを選択してください。")
        elif not target_resolution["valid"]:
            st.warning(format_core_message_for_display(target_resolution["reason"]) or "対象イラストを解決できませんでした。")
        elif target_resolution["selected_route_labels"]:
            st.caption(
                "対象シーン (Project順): "
                + " -> ".join(target_resolution["selected_route_labels"])
            )

        if st.button(
            "Fresh Preview",
            disabled=not target_resolution["valid"],
            key="gallery_variant_promotion_preview_btn",
        ):
            st.session_state.gallery_variant_promotion_preview = (
                build_batch_variant_promotion_plan(project, **plan_kwargs)
            )
            st.session_state.gallery_variant_promotion_confirm = False

        stored_plan = st.session_state.get("gallery_variant_promotion_preview")
        if not isinstance(stored_plan, dict):
            return
        current_signature = build_batch_variant_promotion_signature(
            project,
            **plan_kwargs,
        )
        preview_current = stored_plan.get("signature") == current_signature
        if not preview_current:
            st.warning("Previewが古くなっています。Fresh Previewを再実行してください。")

        metric_cols = st.columns(5)
        metric_cols[0].metric("対象シーン", stored_plan["selected_route_count"])
        metric_cols[1].metric("対象イラスト", stored_plan["target_line_count"])
        metric_cols[2].metric("検出Variant", stored_plan["variants_found"])
        metric_cols[3].metric("Missing / Invalid", stored_plan["missing_variants"])
        metric_cols[4].metric("昇格予定", stored_plan["will_promote"])

        if stored_plan["selected_route_labels"]:
            st.caption(
                "Preview Scene order: "
                + " -> ".join(stored_plan["selected_route_labels"])
            )
        route_rows = [
            {
                "Scene": summary.get("route_label") or "(Outside Scenes)",
                "Target Illustrations": summary.get("target_line_count", 0),
                "Variants Found": summary.get("variants_found", 0),
                "Missing": summary.get("missing_variants", 0),
                "Will Promote": summary.get("will_promote", 0),
            }
            for summary in stored_plan["route_summaries"]
        ]
        if route_rows:
            st.dataframe(route_rows, hide_index=True, width="stretch")

        with st.expander("Illustration details", expanded=False):
            detail_limit = 100
            detail_rows = [
                {
                    "Scene": entry.get("route_label") or "(Outside Scenes)",
                    "Parent Illustration": entry.get("parent_line_label") or entry.get("parent_line_id"),
                    "Variant": entry.get("variant_path") or "(none)",
                    "Placement": "Gallery末尾" if entry.get("placement") == "end" else "親イラストの直後",
                    "Status": "Ready" if entry.get("promotable") else format_core_message_for_display(entry.get("skip_reason")),
                }
                for entry in stored_plan["entries"][:detail_limit]
            ]
            if detail_rows:
                st.dataframe(detail_rows, hide_index=True, width="stretch")
            hidden_count = max(0, len(stored_plan["entries"]) - detail_limit)
            if hidden_count:
                st.caption(f"{hidden_count} Illustration(s) are hidden from this detail table.")

        if stored_plan["will_promote"] == 0:
            st.info("昇格予定のVariantはありません。")

        confirm_promotion = st.checkbox(
            "Fresh Previewを確認し、これらのVariantsを本編列へ昇格します。",
            key="gallery_variant_promotion_confirm",
            disabled=not preview_current or stored_plan["will_promote"] == 0,
        )
        if st.button(
            "Variantsを本編列へ昇格",
            type="primary",
            disabled=(
                not preview_current
                or stored_plan["will_promote"] == 0
                or not confirm_promotion
            ),
            key="gallery_variant_promotion_apply_btn",
        ):
            result = apply_batch_promote_gallery_variants(
                st.session_state.project,
                stored_plan=stored_plan,
                scope=scope,
                source=source,
                placement=placement,
                current_anchor_line_id=current_anchor_line_id,
                selected_route_id=selected_route_id,
                selected_route_ids=selected_route_ids,
                selected_line_ids=selected_line_ids,
                project_path=project_path,
            )
            if result["stale_preview"]:
                st.warning("Apply前に状態が変わりました。Fresh Previewを再実行してください。")
            elif not result["applied"]:
                st.error(
                    format_core_message_for_display(result["error"])
                    or "Variantsを本編列へ昇格できませんでした。"
                )
            else:
                previous_focused_line_id = st.session_state.get("focused_line_id")
                push_history()
                st.session_state.project = build_graph(result["updated_project"])
                restore_focus_after_graph_update(previous_focused_line_id)
                _set_gallery_selected_route_ids_after_structure_change(st.session_state.project)
                if result["new_line_ids"]:
                    st.session_state.highlighted_line_id = result["new_line_ids"][-1]
                    st.session_state.gallery_expanded_line_id = result["new_line_ids"][-1]
                save_current_project_if_possible("gallery variants batch promoted to main lines")
                st.session_state.pop("gallery_variant_promotion_preview", None)
                if scope == "selected_routes":
                    message = (
                        f"Selected Scenes {result['selected_route_count']}件から、"
                        f"{result['promoted_count']}件のVariantを本編列へ昇格しました。"
                    )
                else:
                    message = (
                        f"Promoted {result['promoted_count']} Variants to main Gallery Illustrations. "
                        f"Skipped {result['skipped_count']} Illustrations."
                    )
                st.session_state.gallery_feedback = message
                st.session_state.gallery_feedback_kind = "success"
                st.rerun()


def render_candidate_route_creation_section(project) -> None:
    st.markdown("#### Candidateから別案シーンを作成")
    st.caption(
        "選択したイラストのCandidatesを、シーン区切り付きの同一シーン別案として本編列へ追加します。"
        "Candidate自体は削除しません。"
    )
    gallery_selected_line_ids = [
        line_id
        for line_id, selected in st.session_state.get("gallery_move_targets", {}).items()
        if selected
    ]
    selected_line_ids = gallery_selected_line_ids or get_selected_line_ids(project)
    scope = st.radio(
        "対象範囲",
        options=["focused_line", "selected_lines", "current_route", "all_lines"],
        format_func=lambda value: {
            "focused_line": "フォーカス中のイラスト",
            "selected_lines": f"選択中のイラスト ({len(selected_line_ids)})",
            "current_route": "現在のシーン",
            "all_lines": "すべてのイラスト",
        }[value],
        horizontal=True,
        key="gallery_candidate_route_creation_scope",
    )
    target_resolution = _candidate_route_target_lines(project, scope, selected_line_ids)
    target_line_ids = tuple(getattr(line, "id", "") for line in target_resolution["target_lines"])
    signature = {
        "scope": scope,
        "target_line_ids": target_line_ids,
    }
    for warning in target_resolution.get("warnings", []):
        st.warning(warning)

    if scope == "current_route":
        route_resolution = target_resolution.get("route_resolution")
        if route_resolution and route_resolution.get("route_id"):
            st.caption(
                f"現在のシーン: {route_resolution.get('route_label') or 'Scene'} "
                f"({route_resolution.get('line_count', 0)} lines)"
            )

    preview_disabled = not target_line_ids
    if st.button(
        "別案シーン作成をプレビュー",
        disabled=preview_disabled,
        key="gallery_candidate_route_creation_preview_btn",
    ):
        st.session_state.gallery_candidate_route_creation_preview = {
            "signature": signature,
            "preview": preview_candidate_route_creation(
                project,
                scope,
                selected_line_ids=selected_line_ids,
            ),
        }

    preview_state = st.session_state.get("gallery_candidate_route_creation_preview")
    preview_current = (
        preview_state
        and preview_state.get("signature") == signature
    )
    if preview_state and not preview_current:
        st.caption("別案シーン作成プレビューが古くなっています。もう一度プレビューしてください。")
    if not preview_current:
        return

    preview = preview_state["preview"]
    metric_cols = st.columns(5)
    metric_cols[0].metric("対象イラスト", preview["target_line_count"])
    metric_cols[1].metric("Candidateありイラスト", preview["candidate_line_count"])
    metric_cols[2].metric("作成予定シーン", preview["route_count"])
    metric_cols[3].metric("追加予定イラスト", preview["add_line_count"])
    metric_cols[4].metric("スキップ", preview["skip_count"])
    if preview.get("missing_count"):
        st.caption(f"画像ファイルなし: {preview['missing_count']} 件")
    if preview.get("duplicate_count"):
        st.caption(f"重複skip: {preview['duplicate_count']} 件")
    if preview.get("no_candidate_count"):
        st.caption(f"Candidateなしイラスト: {preview['no_candidate_count']} 件")
    if preview["add_line_count"] == 0:
        st.info("作成予定の別案シーンはありません。")

    for example in preview["examples"]:
        st.markdown(f"**{example['display_id']}**")
        st.caption(f"Illustration id: `{example['line_id']}` / index: {example['line_index']}")
        st.caption(f"作成シーン: {example['route_label']}")
        st.caption(f"追加Candidate: {example['candidate_count']} 件")
        for candidate_path in example.get("candidate_paths", []):
            st.caption(f"- {_short_preview(candidate_path, 180)}")

    confirm_creation = st.checkbox(
        "プレビューを確認し、Candidatesから別案シーンを作成します。",
        key="gallery_candidate_route_creation_confirm",
    )
    if st.button(
        "別案シーンを作成",
        type="primary",
        disabled=preview["add_line_count"] == 0 or not confirm_creation,
        key="gallery_candidate_route_creation_apply_btn",
    ):
        result = apply_candidate_route_creation(
            st.session_state.project,
            scope,
            selected_line_ids=selected_line_ids,
        )
        st.session_state.pop("gallery_candidate_route_creation_preview", None)
        st.session_state.gallery_feedback = (
            f"{result['route_count']}件のシーンと{result['line_count']}件のCandidate由来イラストを追加しました。"
        )
        if result["skipped_count"]:
            st.session_state.gallery_feedback += f" スキップ: {result['skipped_count']}件。"
        st.session_state.gallery_feedback_kind = "success"
        st.rerun()


def render_gallery_prompt_revert_section(project) -> None:
    st.markdown("#### Prompt Revert")
    st.caption("対象イラストの編集中Positive Promptを、保存されている元画像Promptへ戻します。画像参照とNegative Promptは変更しません。")

    selected_line_ids = get_selected_line_ids(project)
    scope = st.radio(
        "対象",
        ["all_lines", "current_route", "selected_route", "selected_lines"],
        format_func=_gallery_operation_scope_label,
        horizontal=True,
        key="gallery_prompt_revert_scope",
    )
    route_options = _gallery_route_options_with_counts(project)
    route_option_lookup = {route.get("route_id", ""): route for route in route_options}
    selected_route_id = ""
    if scope == "selected_route":
        if route_options:
            selected_route_id = st.selectbox(
                "シーンを選択",
                [route.get("route_id", "") for route in route_options],
                format_func=lambda route_id: _format_gallery_route_option(route_option_lookup.get(route_id, {})),
                key="gallery_prompt_revert_selected_route_id",
            )
        else:
            st.warning("このProjectには選択できるシーンがありません。")

    target_resolution = resolve_gallery_operation_targets(
        project,
        scope,
        route_id=selected_route_id,
        selected_line_ids=selected_line_ids,
    )
    target_line_ids = target_resolution["target_line_ids"]
    _render_gallery_operation_target_summary(target_resolution)

    preview_signature = {
        "scope": scope,
        "route_id": selected_route_id,
        "target_line_ids": tuple(target_line_ids),
    }

    if st.button("Prompt Revertをプレビュー", disabled=not target_line_ids, key="gallery_prompt_revert_preview_btn"):
        st.session_state.gallery_prompt_revert_preview = {
            "signature": preview_signature,
            "preview": preview_revert_prompts_to_original(project, target_line_ids=target_line_ids),
        }

    preview_state = st.session_state.get("gallery_prompt_revert_preview")
    if not preview_state:
        return

    preview = preview_state.get("preview", {})
    stale = preview_state.get("signature") != preview_signature
    if stale:
        st.caption("Prompt Revert preview is out of date. Run preview again.")

    metric_cols = st.columns(4)
    metric_cols[0].metric("対象イラスト", preview.get("target_line_count", 0))
    metric_cols[1].metric("変更ありイラスト", preview.get("changed_line_count", 0))
    metric_cols[2].metric("元Promptなし", preview.get("skipped_no_original_count", 0))
    metric_cols[3].metric("変更なし", preview.get("unchanged_count", 0))

    for example in preview.get("examples", [])[:8]:
        with st.container(border=True):
            st.caption(f"{example.get('line_label') or example.get('line_id')}")
            st.caption(f"Before: {_short_preview(example.get('before', ''), 180)}")
            st.caption(f"After: {_short_preview(example.get('after', ''), 180)}")

    confirm = st.checkbox(
        "プレビューされた変更ありイラストのみ、元画像Promptへ戻します。",
        key="gallery_prompt_revert_confirm",
        disabled=stale or preview.get("changed_line_count", 0) <= 0,
    )
    if st.button(
        "元画像Promptへ戻す",
        type="primary",
        disabled=stale or not confirm or preview.get("changed_line_count", 0) <= 0,
        key="gallery_prompt_revert_apply_btn",
    ):
        push_history()
        previous_focused_line_id = st.session_state.get("focused_line_id")
        result = apply_revert_prompts_to_original(project, target_line_ids=target_line_ids)
        st.session_state.project = build_graph(project)
        restore_focus_after_graph_update(previous_focused_line_id)
        _queue_gallery_prompt_widget_sync(result.get("changed_line_ids", []))
        sync_text_areas()
        save_current_project_if_possible("gallery prompts reverted to original")
        st.session_state.gallery_feedback = f"{result.get('changed_line_count', 0)}件のイラストを元画像Promptへ戻しました。"
        st.session_state.gallery_feedback_kind = "success"
        st.session_state.pop("gallery_prompt_revert_preview", None)
        st.rerun()


def _render_selected_routes_attribute_group_swap_preview(
    preview,
    from_group_key,
    to_group_key,
    require_full_match,
    *,
    key_prefix: str,
    preview_state_key: str,
    feedback_mode: str,
) -> None:
    st.markdown("**Selected Scenes Attribute Group Swap Preview**")
    summary_cols = st.columns(4)
    summary_cols[0].metric("Scenes", preview.get("selected_route_count", 0))
    summary_cols[1].metric("Target Illustrations", preview.get("target_line_count", 0))
    summary_cols[2].metric("Changed Illustrations", preview.get("changed_line_count", 0))
    summary_cols[3].metric("Drift risk", preview.get("drift_count", 0))
    match_cols = st.columns(4)
    match_cols[0].metric("Full match", preview.get("full_match_count", 0))
    match_cols[1].metric("Partial match", preview.get("partial_match_count", 0))
    match_cols[2].metric("No match", preview.get("no_match_count", 0))
    match_cols[3].metric("No-op", preview.get("no_op_count", 0))
    st.caption(
        f"Slot: {preview.get('from_slot') or '(missing)'} -> "
        f"{preview.get('to_slot') or '(missing)'} / "
        f"Compatible: {'yes' if preview.get('slot_compatible') else 'no'} / "
        f"Require full match: {'yes' if preview.get('require_full_match') else 'no'}"
    )
    st.caption(
        "Project order: "
        + (" -> ".join(preview.get("selected_route_labels") or []) or "(none)")
    )
    st.warning(
        "この操作はpositive Promptだけを変更します。現在の本編画像、Candidate、Gallery Variant、"
        "source_generation_info、lineage_infoは変更しません。"
    )
    st.info(
        "Negative Promptは変更しません。Attribute Groupのnegative_tags、negative_when_disabled、"
        "negative_notesはmetadata previewのみです。"
    )
    for diagnostic in preview.get("diagnostics") or []:
        st.warning(format_core_message_for_display(diagnostic))
    if not preview.get("valid"):
        st.warning(
            format_core_message_for_display(preview.get("reason"))
            or "Selected Scenes Attribute Group Swap preview is invalid."
        )
    elif preview.get("changed_line_count", 0) == 0:
        st.info("Attribute Group Swapで変更されるイラストはありません。")

    st.caption(
        f"Tokens to remove: {_short_preview(', '.join(preview.get('tokens_to_remove') or []) or '(none)', 220)}"
    )
    st.caption(
        f"Tokens to add: {_short_preview(', '.join(preview.get('tokens_to_add') or []) or '(none)', 220)}"
    )
    st.caption(
        f"Shared tokens preserved: {_short_preview(', '.join(preview.get('shared_tokens') or []) or '(none)', 220)}"
    )
    source_metadata = preview.get("from_group_snapshot") or {}
    replacement_metadata = preview.get("to_group_snapshot") or {}
    st.caption(
        "Negative metadata preview only / source disabled tags: "
        f"{_short_preview(', '.join(source_metadata.get('negative_when_disabled') or []) or '(none)', 180)} / "
        "replacement disabled tags: "
        f"{_short_preview(', '.join(replacement_metadata.get('negative_when_disabled') or []) or '(none)', 180)}"
    )
    st.caption(
        "Source / replacement negative tags: "
        f"{_short_preview(', '.join(source_metadata.get('negative_tags') or []) or '(none)', 180)} / "
        f"{_short_preview(', '.join(replacement_metadata.get('negative_tags') or []) or '(none)', 180)}"
    )
    st.caption(
        "Source / replacement negative notes: "
        f"{_short_preview(source_metadata.get('negative_notes') or '(none)', 180)} / "
        f"{_short_preview(replacement_metadata.get('negative_notes') or '(none)', 180)}"
    )

    st.markdown("**Scene / Illustration diff**")
    entries = list(preview.get("entries") or [])
    max_line_previews = 40
    rendered_count = 0
    for route_summary in preview.get("route_summaries") or []:
        route_id = route_summary.get("route_id", "")
        route_entries = [entry for entry in entries if entry.get("route_id") == route_id]
        label = route_summary.get("route_label") or route_id or "Scene"
        with st.expander(
            f"{label}: {route_summary.get('changed_line_count', 0)} changed / "
            f"{route_summary.get('target_line_count', 0)} targets",
            expanded=False,
        ):
            st.caption(
                f"Scene order: {route_summary.get('route_order', 0) + 1} / "
                f"full: {route_summary.get('full_match_count', 0)} / "
                f"partial: {route_summary.get('partial_match_count', 0)} / "
                f"no match: {route_summary.get('no_match_count', 0)} / "
                f"drift: {route_summary.get('drift_count', 0)}"
            )
            for entry in route_entries:
                if rendered_count >= max_line_previews:
                    continue
                rendered_count += 1
                st.markdown(f"**{entry.get('line_label') or entry.get('line_id')}**")
                st.caption(
                    f"Illustration id: `{entry.get('line_id', '')}` / "
                    f"project order: {entry.get('project_order')} / "
                    f"Scene illustration order: {entry.get('route_line_order')} / "
                    f"match: {entry.get('match_classification')} / "
                    f"result: {entry.get('operation')}"
                )
                if entry.get("skip_reason"):
                    st.caption(f"Reason: {format_core_message_for_display(entry['skip_reason'])}")
                st.caption(
                    f"Removed: {_short_preview(', '.join(entry.get('positive_removed_tokens') or []) or '(none)', 180)}"
                )
                st.caption(
                    f"Added: {_short_preview(', '.join(entry.get('positive_added_tokens') or []) or '(none)', 180)}"
                )
                st.caption(
                    f"Shared: {_short_preview(', '.join(entry.get('shared_tokens') or []) or '(none)', 180)}"
                )
                st.caption("Before positive Prompt")
                render_batch_preview_text(
                    entry.get("before_positive_prompt", ""),
                    "attribute_group_swap_selected_routes",
                    "",
                    "exact_token",
                    "exact_token",
                    highlight=False,
                )
                st.caption("After positive Prompt")
                render_batch_preview_text(
                    entry.get("after_positive_prompt", ""),
                    "attribute_group_swap_selected_routes",
                    "",
                    "exact_token",
                    "exact_token",
                    highlight=False,
                )
                st.caption("Negative Prompt: unchanged (metadata preview only)")
                source_negative = entry.get("source_negative_metadata_preview") or {}
                replacement_negative = entry.get("replacement_negative_metadata_preview") or {}
                st.caption(
                    "Source / replacement disabled metadata: "
                    f"{_short_preview(', '.join(source_negative.get('negative_when_disabled') or []) or '(none)', 150)} / "
                    f"{_short_preview(', '.join(replacement_negative.get('negative_when_disabled') or []) or '(none)', 150)}"
                )
                st.caption(
                    "Source / replacement negative metadata notes: "
                    f"{_short_preview(source_negative.get('negative_notes') or '(none)', 150)} / "
                    f"{_short_preview(replacement_negative.get('negative_notes') or '(none)', 150)}"
                )
                st.caption(
                    f"Main image: {entry.get('main_image_field') or '(none)'} / "
                    f"{_short_preview(entry.get('main_image_path') or '(none)', 160)}"
                )
                st.caption(f"Drift risk: {entry.get('drift_risk')}")
    hidden_count = max(0, len(entries) - rendered_count)
    if hidden_count:
        st.caption(f"{hidden_count} additional Illustration previews are hidden.")

    st.markdown("**Final confirmation**")
    st.caption(
        f"{preview.get('selected_route_count', 0)} Scenes / "
        f"{preview.get('changed_line_count', 0)} changed Illustrations / "
        f"{preview.get('drift_count', 0)} Drift risks"
    )
    confirm_key = f"{key_prefix}_selected_routes_confirm"
    confirmed = st.checkbox(
        "このPreviewのPrompt変更、negative metadata preview、image / Prompt Drift riskを確認しました",
        key=confirm_key,
    )
    if st.button(
        "Selected ScenesへAttribute Group Swapを適用",
        type="primary",
        disabled=(
            not preview.get("valid")
            or not preview.get("slot_compatible")
            or preview.get("changed_line_count", 0) == 0
            or not confirmed
        ),
        key=f"{key_prefix}_apply_btn",
    ):
        previous_focus = st.session_state.get("focused_line_id")
        result = apply_selected_routes_attribute_group_swap(
            st.session_state.project,
            st.session_state.get("gallery_selected_route_ids", []),
            expected_signature=preview.get("signature", ""),
            from_group_key=from_group_key,
            to_group_key=to_group_key,
            require_full_match=require_full_match,
            project_path=st.session_state.get("current_project_path", ""),
        )
        if result.get("applied"):
            push_history()
            st.session_state.project = result["updated_project"]
            restore_focus_after_graph_update(previous_focus)
            sync_text_areas()
            st.session_state.pop(preview_state_key, None)
            st.session_state.pop(confirm_key, None)
            if feedback_mode == "gallery":
                st.session_state.gallery_feedback = (
                    f"Attribute Group Swap applied to {result['applied_count']} line(s)."
                )
                st.session_state.gallery_feedback_kind = "success"
            else:
                st.session_state.attribute_group_swap_notice = (
                    f"Attribute Group Swap applied to {result['applied_count']} line(s)."
                )
            save_current_project_if_possible("selected Routes attribute group swap applied")
            st.rerun()
        elif result.get("stale_preview"):
            st.warning("Previewが古くなりました。Fresh Previewを実行してください。")
        else:
            st.error(
                format_core_message_for_display(result.get("error"))
                or "Selected Scenes Attribute Group Swap failed."
            )


def _render_selected_routes_attribute_group_swap_flow(
    project,
    groups,
    from_group_key,
    to_group_key,
    require_full_match,
    *,
    key_prefix: str,
    preview_state_key: str,
    feedback_mode: str,
) -> None:
    selected_routes_state = sanitize_selected_route_ids(
        project,
        st.session_state.get("gallery_selected_route_ids", []),
    )
    selected_route_ids = list(selected_routes_state.get("selected_route_ids") or [])
    st.caption(
        f"Selected Scenes: {selected_routes_state.get('selected_route_count', 0)} / "
        f"target Illustrations: {selected_routes_state.get('selected_main_line_count', 0)}"
    )
    st.caption(
        "Project order: "
        + (" -> ".join(selected_routes_state.get("selected_route_labels") or []) or "(none)")
    )
    for diagnostic in selected_routes_state.get("diagnostics") or []:
        st.warning(format_core_message_for_display(diagnostic))

    from_group = groups.get(from_group_key, {}) or {}
    to_group = groups.get(to_group_key, {}) or {}
    from_slot = normalize_attribute_slot(from_group.get("slot"))
    to_slot = normalize_attribute_slot(to_group.get("slot"))
    slot_compatible = bool(from_slot and to_slot and from_slot == to_slot)
    st.caption(
        f"Attribute Slot: {from_slot or '(missing)'} -> {to_slot or '(missing)'} / "
        f"Compatible: {'yes' if slot_compatible else 'no'}"
    )

    current_signature = build_selected_routes_attribute_group_swap_signature(
        project,
        selected_route_ids,
        from_group_key=from_group_key,
        to_group_key=to_group_key,
        require_full_match=require_full_match,
        project_path=st.session_state.get("current_project_path", ""),
    )
    validation_error = None
    if from_group_key == to_group_key:
        validation_error = "FromとToには異なるAttribute Groupを選択してください。"
    elif not selected_route_ids:
        validation_error = "Selected Scenesがありません。Gallery上部から対象シーンを選択してください。"
    elif not slot_compatible:
        validation_error = (
            f"Attribute Slotが一致しません。source: {from_slot or '(missing)'} / "
            f"replacement: {to_slot or '(missing)'}"
        )
    if validation_error:
        st.warning(validation_error)

    if st.button(
        "Fresh Preview Attribute Swap",
        disabled=bool(validation_error),
        key=f"{key_prefix}_preview_btn",
    ):
        st.session_state[f"{key_prefix}_selected_routes_confirm"] = False
        st.session_state[preview_state_key] = {
            "signature": current_signature,
            "preview": build_selected_routes_attribute_group_swap_plan(
                project,
                selected_route_ids,
                from_group_key=from_group_key,
                to_group_key=to_group_key,
                require_full_match=require_full_match,
                project_path=st.session_state.get("current_project_path", ""),
            ),
        }

    preview_state = st.session_state.get(preview_state_key)
    preview_current = preview_state and preview_state.get("signature") == current_signature
    if not preview_current:
        if preview_state:
            st.caption("Attribute Group Swap preview is stale. Fresh Preview is required before applying.")
        return
    _render_selected_routes_attribute_group_swap_preview(
        preview_state["preview"],
        from_group_key,
        to_group_key,
        require_full_match,
        key_prefix=key_prefix,
        preview_state_key=preview_state_key,
        feedback_mode=feedback_mode,
    )


def _gallery_attribute_group_swap_scope_label(scope: str) -> str:
    return GALLERY_SCOPE_DISPLAY_LABELS.get(scope, "Current Scene")


def _gallery_attribute_group_swap_selected_line_ids(project) -> list[str]:
    gallery_selected_line_ids = [
        line_id
        for line_id, selected in st.session_state.get("gallery_move_targets", {}).items()
        if selected
    ]
    return gallery_selected_line_ids or get_selected_line_ids(project)


def render_gallery_attribute_group_swap_section(project) -> None:
    st.markdown("#### Attribute Group Swap")
    st.caption(
        "Galleryのシーンや選択中のイラストを見ながら、Project内Attribute Group同士をPreview後に差し替えます。"
        "positive prompt tokensのみ対象で、negative metadataは変更しません。"
    )
    if is_free():
        st.info("Attribute Group Swap is available in Pro.")
        return

    groups = get_attribute_groups_snapshot(project)
    group_keys = sorted(groups)
    if len(group_keys) < 2:
        st.info("Attribute Group Swap requires at least two Attribute Groups.")
        return

    selected_line_ids = _gallery_attribute_group_swap_selected_line_ids(project)
    group_cols = st.columns(2)
    with group_cols[0]:
        from_group_key = st.selectbox(
            "From Attribute Group",
            options=group_keys,
            format_func=lambda key: _format_attribute_group_swap_option(groups, key),
            key="gallery_attribute_group_swap_from",
        )
    with group_cols[1]:
        to_group_key = st.selectbox(
            "To Attribute Group",
            options=group_keys,
            index=1 if len(group_keys) > 1 else 0,
            format_func=lambda key: _format_attribute_group_swap_option(groups, key),
            key="gallery_attribute_group_swap_to",
        )

    scope = st.radio(
        "Target scope",
        options=["current_route", "selected_route", "selected_routes", "selected_lines", "all_lines"],
        format_func=_gallery_attribute_group_swap_scope_label,
        horizontal=True,
        key="gallery_attribute_group_swap_scope",
    )

    route_options = _gallery_route_options_with_counts(project)
    route_lookup = {route.get("route_id", ""): route for route in route_options}
    selected_route_id = ""
    if scope == "selected_route":
        if route_options:
            selected_route_id = st.selectbox(
                "Scene",
                [route.get("route_id", "") for route in route_options],
                format_func=lambda route_id: _format_gallery_route_option(route_lookup.get(route_id, {})),
                key="gallery_attribute_group_swap_selected_route_id",
            )
        else:
            st.warning("No Scenes are available in this project.")

    require_full_match = st.checkbox(
        "From Groupが完全一致するイラストだけ対象にする",
        value=False,
        key="gallery_attribute_group_swap_require_full_match",
    )

    if scope == "selected_routes":
        _render_selected_routes_attribute_group_swap_flow(
            project,
            groups,
            from_group_key,
            to_group_key,
            require_full_match,
            key_prefix="gallery_attribute_group_swap",
            preview_state_key="gallery_attribute_group_swap_preview",
            feedback_mode="gallery",
        )
        return

    target_resolution = resolve_gallery_operation_targets(
        project,
        scope,
        route_id=selected_route_id,
        selected_line_ids=selected_line_ids,
    )
    target_line_ids = target_resolution["target_line_ids"]
    st.caption(f"Target scope: {_gallery_attribute_group_swap_scope_label(scope)}")
    if target_resolution.get("route_id"):
        st.caption(
            f"Scene: {target_resolution.get('route_label') or '(unnamed)'} "
            f"({target_resolution.get('route_line_count') or len(target_line_ids)} lines)"
        )
    st.caption(f"Target lines: {len(target_line_ids)}")
    for warning in target_resolution.get("warnings", [])[:3]:
        st.warning(warning)

    preview_signature = {
        "from_group_key": from_group_key,
        "to_group_key": to_group_key,
        "scope": scope,
        "selected_route_id": selected_route_id,
        "target_line_ids": tuple(target_line_ids),
        "require_full_match": bool(require_full_match),
    }

    validation_error = None
    if from_group_key == to_group_key:
        validation_error = "FromとToには異なるAttribute Groupを選択してください。"
    elif scope == "selected_lines" and not selected_line_ids:
        validation_error = "Selected Illustrations scope requires at least one selected illustration."
    elif not target_line_ids:
        validation_error = "対象イラストがありません。"
    if validation_error:
        st.warning(validation_error)

    if st.button(
        "Preview Attribute Swap",
        disabled=bool(validation_error),
        key="gallery_attribute_group_swap_preview_btn",
    ):
        st.session_state.gallery_attribute_group_swap_preview = {
            "signature": preview_signature,
            "preview": preview_attribute_group_swap(
                project,
                from_group_key,
                to_group_key,
                target_line_ids=target_line_ids,
                require_full_match=require_full_match,
            ),
        }

    preview_state = st.session_state.get("gallery_attribute_group_swap_preview")
    preview_current = preview_state and preview_state.get("signature") == preview_signature
    if preview_state and not preview_current:
        st.caption("Attribute Group Swap preview is stale. Preview again before applying.")
    if not preview_current:
        return

    preview = preview_state["preview"]
    for warning in preview.get("warnings", []):
        st.warning(warning)

    st.markdown("**Preview Summary**")
    metric_cols = st.columns(5)
    metric_cols[0].metric("Target", preview["target_line_count"])
    metric_cols[1].metric("Affected", preview["affected_line_count"])
    metric_cols[2].metric("Full", preview["full_match_line_count"])
    metric_cols[3].metric("Partial", preview["partial_match_line_count"])
    metric_cols[4].metric("No match", preview["no_match_line_count"])
    st.caption(f"Tokens to remove: {_short_preview(', '.join(preview['tokens_to_remove']) or '(none)', 220)}")
    st.caption(f"Tokens to add: {_short_preview(', '.join(preview['tokens_to_add']) or '(none)', 220)}")
    st.caption(f"Shared tokens preserved: {_short_preview(', '.join(preview['shared_tokens']) or '(none)', 220)}")
    st.caption(
        "Already present To tokens: "
        f"{_short_preview(', '.join(preview['already_present_to_tokens']) or '(none)', 220)}"
    )

    if preview["affected_line_count"] == 0:
        st.info("Attribute Group Swapで変更されるイラストはありません。")

    if st.button(
        "Apply Attribute Swap",
        type="primary",
        disabled=preview["affected_line_count"] == 0,
        key="gallery_attribute_group_swap_apply_btn",
    ):
        push_history()
        prev_focus = st.session_state.get("focused_line_id")
        st.session_state.project = apply_attribute_group_swap(
            st.session_state.project,
            from_group_key,
            to_group_key,
            target_line_ids=target_line_ids,
            require_full_match=require_full_match,
        )
        restore_focus_after_graph_update(prev_focus)
        sync_text_areas()
        st.session_state.pop("gallery_attribute_group_swap_preview", None)
        st.session_state.gallery_feedback = f"Attribute Group Swap applied to {preview['affected_line_count']} line(s)."
        st.session_state.gallery_feedback_kind = "success"
        save_current_project_if_possible("gallery attribute group swap applied")
        st.rerun()

    st.markdown("**Examples**")
    for example in preview.get("examples", [])[:8]:
        st.markdown(f"**{example['display_id']}**")
        st.caption(
            f"Illustration id: `{example['line_id']}` / index: {example['line_index']} / "
            f"matched: {_short_preview(', '.join(example['matched_from_tokens']), 160)}"
        )
        st.caption(f"Removed: {_short_preview(', '.join(example['removed_tokens']) or '(none)', 160)}")
        st.caption(f"Added: {_short_preview(', '.join(example['added_tokens']) or '(none)', 160)}")
        st.caption("Before")
        render_batch_preview_text(
            example["before"],
            "gallery_attribute_group_swap",
            "",
            "exact_token",
            "exact_token",
            highlight=False,
        )
        st.caption("After")
        render_batch_preview_text(
            example["after"],
            "gallery_attribute_group_swap",
            "",
            "exact_token",
            "exact_token",
            highlight=False,
        )


def _lightweight_fork_selected_line_ids(project) -> list[str]:
    gallery_selected_line_ids = [
        line_id
        for line_id, selected in st.session_state.get("gallery_move_targets", {}).items()
        if selected
    ]
    return gallery_selected_line_ids or get_selected_line_ids(project)


def _render_lightweight_fork_preview_summary(preview: dict) -> None:
    metric_cols = st.columns(5)
    metric_cols[0].metric("Targets", preview.get("target_line_count", 0))
    metric_cols[1].metric("Materializable", preview.get("materializable_count", 0))
    metric_cols[2].metric("Skipped", preview.get("skipped_count", 0))
    metric_cols[3].metric("Scenes", preview.get("affected_route_count", 0))
    metric_cols[4].metric("All phrase", "FORK FINAL" if preview.get("all_scope_phrase_required") else "-")

    if preview.get("scope") == "selected_routes":
        selected_labels = preview.get("selected_route_labels", [])
        if selected_labels:
            st.caption(
                "Selected Scenes in Project order: "
                + ", ".join(str(label) for label in selected_labels)
            )
        st.caption(
            "Selected Scene blocks: "
            f"{preview.get('selected_route_count', 0)} / "
            f"Workbench excluded: {preview.get('selected_workbench_count', 0)} / "
            f"Deleted members excluded: {preview.get('selected_deleted_member_count', 0)} / "
            f"Candidates cleared in Derived Project: {preview.get('candidate_removal_count', 0)} / "
            f"Gallery Variants cleared in Derived Project: {preview.get('gallery_variant_removal_count', 0)} / "
            f"Trash records excluded: {preview.get('trash_removal_count', 0)} / "
            f"Copied main images: {preview.get('copied_main_image_count', 0)} / "
            f"Unresolved: {preview.get('unresolved_main_image_count', 0)}"
        )
        for diagnostic in preview.get("selected_route_diagnostics", [])[:3]:
            st.warning(format_core_message_for_display(diagnostic))

    if preview.get("drift_warning"):
        st.warning(
            "派生Projectは画像参照だけをmaterializeし、Prompt textは変更せずコピーします。"
            "作成前に、表示画像とPromptの意味が一致しているか確認してください。"
        )
    if preview.get("all_scope_phrase_required"):
        st.caption("All-scope Derived Project creation requires the compatibility phrase `FORK FINAL`.")

    skipped_reasons = preview.get("skipped_reasons", {})
    if skipped_reasons:
        st.caption(
            "Skipped reasons: "
            + ", ".join(
                f"{format_core_message_for_display(reason)}: {count}"
                for reason, count in sorted(skipped_reasons.items())
            )
        )

    rows = []
    for entry in preview.get("entries", []):
        rows.append({
            "illustration": entry.get("display_id") or entry.get("line_id"),
            "scene": entry.get("route_label") or "",
            "status": "materializable" if entry.get("materializable") else "skipped",
            "source field": entry.get("source_field") or "",
            "skip reason": format_core_message_for_display(entry.get("skipped_reason")),
            "resolved image": entry.get("resolved_image_path") or "",
            "planned destination": entry.get("planned_destination_path") or "",
            "prompt": _short_preview(entry.get("prompt_preview", ""), 120),
        })
    if rows:
        st.dataframe(rows, hide_index=True, width="stretch")


def _render_lightweight_fork_apply_result(result: dict) -> None:
    if not result:
        return

    if result.get("success"):
        st.success(f"派生Projectを作成しました: {result.get('fork_name', '')}")
        st.caption(f"Destination: {result.get('destination_directory', '')}")
        result_rows = [
            {"item": "project.json", "path": result.get("project_path", "")},
            {"item": "manifest.json", "path": result.get("manifest_path", "")},
            {"item": "materialized illustrations", "path": result.get("materialized_count", 0)},
            {"item": "skipped illustrations", "path": result.get("skipped_count", 0)},
            {"item": "copied files", "path": len(result.get("copied_files", []))},
            {"item": "commit attempts", "path": result.get("commit_attempts", 0)},
            {"item": "commit retry", "path": "yes" if result.get("commit_retry_performed") else "no"},
        ]
        st.dataframe(result_rows, hide_index=True, width="stretch")
        skipped_reasons = result.get("skipped_reasons", {})
        if skipped_reasons:
            st.caption(
                "Skipped reasons: "
                + ", ".join(
                    f"{format_core_message_for_display(reason)}: {count}"
                    for reason, count in sorted(skipped_reasons.items())
                )
            )
        affected_routes = result.get("affected_routes", [])
        if affected_routes:
            st.caption(
                "Affected scenes: "
                + ", ".join(route.get("route_label") or route.get("route_id", "") for route in affected_routes)
            )
        project_path = result.get("project_path", "")
        if project_path and os.path.isfile(project_path):
            if st.button("作成した派生Projectを開く", key=f"lightweight_fork_open_{hash(project_path)}"):
                if load_project_json_into_session(project_path):
                    st.session_state.pop("gallery_operations_active", None)
                    st.rerun()
        else:
            st.warning("The generated Derived Project project.json could not be found.")
        return

    st.error(
        "派生Projectを作成できませんでした: "
        f"{format_core_message_for_display(result.get('error')) or 'unknown error'}"
    )
    if result.get("stale_preview"):
        st.warning("Preview is stale. Run preview again.")
    if result.get("conflict"):
        st.warning("A Derived Project with this name already exists. Choose another name.")
    if result.get("cleanup_performed"):
        st.caption("Staging cleanup completed.")
    if result.get("cleanup_error"):
        st.warning(f"Staging cleanup reported an error: {result['cleanup_error']}")


def _lightweight_fork_input_signature(
    *,
    project_path: str,
    fork_name: str,
    scope: str,
    selected_route_id: str,
    selected_route_ids: list[str],
    selected_line_ids: list[str],
    target_line_ids: list[str],
    current_route_anchor_id: str,
) -> tuple:
    return (
        os.path.abspath(project_path or ""),
        fork_name,
        scope,
        selected_route_id,
        tuple(selected_route_ids or []),
        tuple(sorted(selected_line_ids or [])),
        tuple(target_line_ids or []),
        current_route_anchor_id,
    )


def _render_lightweight_fork_append_preview(preview: dict) -> None:
    existing_cols = st.columns(5)
    existing_cols[0].metric("Existing Scenes", preview.get("existing_route_count", 0))
    existing_cols[1].metric("Existing Illustrations", preview.get("existing_line_count", 0))
    existing_cols[2].metric("Existing Images", preview.get("existing_image_count", 0))
    existing_cols[3].metric("Manifest", f"v{preview.get('manifest_version', '-')}")
    existing_cols[4].metric("Append history", preview.get("append_history_count", 0))
    st.caption(f"既存の派生Project: {preview.get('existing_fork_project_path', '')}")
    st.caption(f"Source Project: {preview.get('source_project_path', '')}")
    st.caption(f"Source match: {'yes' if preview.get('source_match') else 'no'}")

    selection_cols = st.columns(6)
    selection_cols[0].metric("Selected", preview.get("selected_route_count", 0))
    selection_cols[1].metric("Appendable", preview.get("appendable_route_count", 0))
    selection_cols[2].metric("Already present", preview.get("already_materialized_route_count", 0))
    selection_cols[3].metric("Blocked", preview.get("blocked_route_count", 0))
    selection_cols[4].metric("New Illustrations", preview.get("materializable_count", 0))
    selection_cols[5].metric("Missing Images", preview.get("missing_image_count", 0))
    labels = preview.get("selected_route_labels", [])
    if labels:
        st.caption("Selected Scenes in Project order: " + " -> ".join(str(label) for label in labels))

    route_rows = []
    for summary in preview.get("route_summaries", []):
        route_rows.append({
            "Scene": summary.get("route_label") or summary.get("separator_label") or summary.get("route_handle"),
            "Source handle": summary.get("route_handle", ""),
            "Status": summary.get("status", ""),
            "Materializable": summary.get("materializable_line_count", 0),
            "Skipped": summary.get("skipped_line_count", 0),
            "Planned images": ", ".join(summary.get("planned_image_filenames", [])),
        })
    if route_rows:
        st.dataframe(route_rows, hide_index=True, width="stretch")

    line_rows = []
    for entry in preview.get("entries", []):
        line_rows.append({
            "Illustration": entry.get("display_id") or entry.get("line_id"),
            "Scene": entry.get("route_label", ""),
            "Status": "append" if entry.get("materializable") else "skip",
            "Source field": entry.get("source_field", ""),
            "Source image": entry.get("resolved_image_path", ""),
            "Destination": entry.get("planned_destination_filename", ""),
            "Skip reason": format_core_message_for_display(entry.get("skipped_reason", "")),
            "Prompt": _short_preview(entry.get("prompt_preview", ""), 120),
            "Negative Prompt": _short_preview(entry.get("negative_prompt_preview", ""), 80),
        })
    if line_rows:
        st.dataframe(line_rows, hide_index=True, width="stretch")

    st.info(
        "既存の派生Projectの編集内容とシーンは保持されます。新しいシーンはfresh IDで末尾へ追加されます。"
        "Candidate、Gallery Variant、transient provenance stateは新しく追加されるイラストだけでclearされます。"
        "The source Project remains unchanged and the filesystem update is atomic."
    )
    for diagnostic in preview.get("warning_diagnostics", []):
        st.warning(format_core_message_for_display(diagnostic))
    for diagnostic in preview.get("fatal_diagnostics", []):
        st.error(format_core_message_for_display(diagnostic))
    if preview.get("selected_route_count") and not preview.get("appendable_route_count"):
        st.info("Selected Scenesはすでにこの派生Projectに存在するか、追加可能な画像がありません。")


def _render_lightweight_fork_append_result(result: dict) -> None:
    if not result:
        return
    if result.get("success"):
        st.success(
            f"{result.get('appended_route_count', 0)} Scenes / "
            f"{result.get('appended_line_count', 0)} Illustrations / "
            f"{result.get('appended_image_count', 0)} Imagesを既存の派生Projectへ追加しました。"
        )
        st.caption(f"更新した派生Project: {result.get('existing_fork_project_path', '')}")
        return
    st.error(
        "シーンを追加できませんでした: "
        f"{format_core_message_for_display(result.get('error')) or 'unknown error'}"
    )
    if result.get("stale_preview"):
        st.warning("Preview is stale. Run Fresh Preview again.")
    if result.get("rollback_performed"):
        st.caption("filesystem transaction失敗後、既存の派生Projectを復元しました。")


def _render_lightweight_fork_candidate_summary(candidate: dict) -> None:
    summary_cols = st.columns(4)
    summary_cols[0].metric("Scenes", candidate.get("materialized_route_count", 0))
    summary_cols[1].metric("Illustrations", candidate.get("materialized_line_count", 0))
    summary_cols[2].metric("Append history", candidate.get("append_history_count", 0))
    summary_cols[3].metric("Manifest", f"v{candidate.get('manifest_version', '-')}")
    st.caption(f"Current source Project: {candidate.get('source_project_path', '')}")
    st.caption(f"Source match: {'yes' if candidate.get('source_match') else 'no'}")
    created_at = candidate.get("created_at") or "unknown"
    updated_at = candidate.get("updated_at") or created_at
    st.caption(f"Created: {created_at} / Updated: {updated_at}")
    st.caption(f"派生Project project.json: {candidate.get('project_path', '')}")
    if candidate.get("currently_open"):
        st.warning("この派生Projectは現在開かれています。Fresh Previewでは外部appendをblockします。")


def _lightweight_fork_append_scope_label(scope: str) -> str:
    return {
        "selected_route": "Selected Scene",
        "selected_routes": "Selected Scenes",
    }.get(scope, scope)


def _on_lightweight_fork_single_route_widget_changed() -> None:
    sync_lightweight_fork_single_route_widget_state(st.session_state)


def _render_lightweight_fork_single_route_selector(project) -> str:
    route_options = _gallery_route_options_with_counts(project)
    route_option_lookup = {}
    route_option_ids = []
    for route in route_options:
        route_id = str(route.get("route_id") or "").strip()
        if route_id and route_id not in route_option_lookup:
            route_option_lookup[route_id] = route
            route_option_ids.append(route_id)

    selected_route_id = str(st.session_state.get("lightweight_fork_selected_route_id", "") or "").strip()
    if not selected_route_id:
        selected_route_id = next(
            (
                route_id
                for route_id in route_option_ids
                if resolve_lightweight_fork_append_targets(
                    project,
                    scope="selected_route",
                    selected_route_id=route_id,
                    selected_route_ids=[],
                ).get("valid")
            ),
            "",
        )
        if selected_route_id:
            st.session_state.lightweight_fork_selected_route_id = selected_route_id

    selectbox_route_ids = list(route_option_ids)
    if selected_route_id and selected_route_id not in selectbox_route_ids:
        selectbox_route_ids.insert(0, selected_route_id)
    if not selectbox_route_ids:
        st.warning("No Scenes are available in this project.")
        return selected_route_id
    initialize_lightweight_fork_single_route_widget_state(st.session_state)
    return st.selectbox(
        "Scene",
        selectbox_route_ids,
        format_func=lambda route_id: (
            _format_gallery_route_option(route_option_lookup[route_id])
            if route_id in route_option_lookup
            else f"Invalid Scene ({route_id})"
        ),
        key=LIGHTWEIGHT_FORK_SELECTED_ROUTE_WIDGET_KEY,
        on_change=_on_lightweight_fork_single_route_widget_changed,
    )


def _render_lightweight_fork_append_section(project) -> None:
    st.caption(
        "同じ元Projectから作成された派生Projectへ、まだ追加されていないSelected Scenesを末尾に追加します。"
        "既存の編集内容は再構築・置換されません。"
    )
    current_project_path = os.path.abspath(st.session_state.get("current_project_path", "") or "")
    if st.session_state.pop("lightweight_fork_append_confirmation_pending_reset", False):
        st.session_state.lightweight_fork_append_confirmation = False
    source_project_saved = bool(current_project_path and os.path.isfile(current_project_path))
    gallery_selected_route_ids = list(st.session_state.get("gallery_selected_route_ids", []))
    requested_scope = st.session_state.get("lightweight_fork_scope", "")
    requested_single_route_id = st.session_state.get("lightweight_fork_selected_route_id", "")
    initial_target_resolution = resolve_lightweight_fork_append_targets(
        project,
        scope=requested_scope,
        selected_route_id=requested_single_route_id,
        selected_route_ids=gallery_selected_route_ids,
    )
    normalized_scope = initial_target_resolution["scope"]
    if requested_scope != normalized_scope:
        st.session_state.lightweight_fork_scope = normalized_scope

    scope = st.radio(
        "Target Scenes",
        ["selected_route", "selected_routes"],
        format_func=_lightweight_fork_append_scope_label,
        horizontal=True,
        key="lightweight_fork_scope",
    )
    selected_route_id = str(st.session_state.get("lightweight_fork_selected_route_id", "") or "").strip()
    if scope == "selected_route":
        selected_route_id = _render_lightweight_fork_single_route_selector(project)

    target_resolution = resolve_lightweight_fork_append_targets(
        project,
        scope=scope,
        selected_route_id=selected_route_id,
        selected_route_ids=gallery_selected_route_ids,
    )
    append_route_ids = list(target_resolution.get("raw_route_ids", []))
    if scope == "selected_route":
        st.caption("Target Scenes: Selected Scene")
    else:
        st.caption(
            "Selected Scenes source: Gallery session selection / Project order. "
            f"Scenes: {target_resolution.get('selected_route_count', 0)} / "
            f"Target Illustrations: {len(target_resolution.get('target_line_ids', []))}"
        )
    if target_resolution.get("resolved_route_labels"):
        st.caption("Selected in Project order: " + " -> ".join(target_resolution["resolved_route_labels"]))
    for diagnostic in target_resolution.get("diagnostics", [])[:3]:
        st.warning(format_core_message_for_display(diagnostic))

    refresh_clicked = st.button("派生Project一覧を更新", key="lightweight_fork_refresh_list")
    if refresh_clicked:
        _invalidate_lightweight_fork_discovery_cache()
    discovery = _get_lightweight_fork_discovery_snapshot(current_project_path)
    candidates = list(discovery.get("candidates", []))
    candidate_by_path = {candidate.get("project_path", ""): candidate for candidate in candidates}
    if candidates:
        fork_options = list(candidate_by_path) + [LIGHTWEIGHT_FORK_BROWSE_OPTION]
        if st.session_state.get("lightweight_fork_append_candidate") not in fork_options:
            st.session_state.lightweight_fork_append_candidate = fork_options[0]
        selected_fork_option = st.selectbox(
            "既存の派生Project",
            fork_options,
            format_func=lambda value: (
                "別の派生Projectを指定..."
                if value == LIGHTWEIGHT_FORK_BROWSE_OPTION
                else candidate_by_path[value].get("display_label", value)
            ),
            key="lightweight_fork_append_candidate",
        )
    else:
        if st.session_state.get("lightweight_fork_append_candidate") != LIGHTWEIGHT_FORK_NO_MATCH_OPTION:
            st.session_state.lightweight_fork_append_candidate = LIGHTWEIGHT_FORK_NO_MATCH_OPTION
        selected_fork_option = st.selectbox(
            "既存の派生Project",
            [LIGHTWEIGHT_FORK_NO_MATCH_OPTION],
            format_func=lambda _value: "一致する派生Projectがありません",
            key="lightweight_fork_append_candidate",
            disabled=True,
        )

    st.caption(f"Discovery location: {discovery.get('search_root', '')}")
    if discovery.get("reason"):
        st.warning(format_core_message_for_display(discovery["reason"]))
    elif discovery.get("rejected"):
        st.caption(f"対象外の派生Project候補: {len(discovery['rejected'])}")

    selected_candidate = candidate_by_path.get(selected_fork_option)
    use_manual_path = not candidates or selected_fork_option == LIGHTWEIGHT_FORK_BROWSE_OPTION
    if selected_candidate:
        existing_fork_project_path = selected_candidate.get("project_path", "")
        _render_lightweight_fork_candidate_summary(selected_candidate)
    else:
        existing_fork_project_path = st.text_input(
            "既存の派生Project project.json",
            key="lightweight_fork_append_project_path",
            placeholder=r"C:\path\to\forks\existing_fork\project.json",
        ) if use_manual_path else ""
    input_signature = build_lightweight_fork_append_input_signature(
        source_project_path=current_project_path,
        destination_project_path=existing_fork_project_path,
        target_resolution=target_resolution,
    )
    if st.session_state.get("lightweight_fork_append_input_signature") != input_signature:
        st.session_state.lightweight_fork_append_input_signature = input_signature
        st.session_state.pop("lightweight_fork_append_preview", None)
        st.session_state.pop("lightweight_fork_append_result", None)
        st.session_state.lightweight_fork_append_confirmation = False

    preview_blocker = ""
    if not source_project_saved:
        preview_blocker = "シーンを追加する前に元Projectを保存してください。"
    elif not target_resolution.get("valid"):
        preview_blocker = (
            format_core_message_for_display(target_resolution.get("reason"))
            or "有効なシーンを選択してください。"
        )
    elif not existing_fork_project_path:
        preview_blocker = "既存の派生Project project.jsonを選択してください。"
    if preview_blocker:
        st.warning(preview_blocker)

    if st.button(
        "Fresh Preview",
        key="lightweight_fork_append_preview_button",
        disabled=bool(preview_blocker),
    ):
        with st.spinner("既存の派生Projectを検証し、追加シーンを計画しています..."):
            append_preview = build_lightweight_fork_append_preview(
                project,
                source_project_path=current_project_path,
                selected_route_ids=append_route_ids,
                existing_fork_project_path=existing_fork_project_path,
                current_open_project_path=current_project_path,
            )
        st.session_state.lightweight_fork_append_preview = {
            "input_signature": input_signature,
            "preview": append_preview,
        }
        st.session_state.lightweight_fork_append_confirmation = False
        st.session_state.pop("lightweight_fork_append_result", None)

    preview_state = st.session_state.get("lightweight_fork_append_preview") or {}
    preview = preview_state.get("preview") or {}
    preview_current = bool(preview) and preview_state.get("input_signature") == input_signature
    if preview and not preview_current:
        st.warning("Preview inputs changed. Run Fresh Preview again.")
    if not preview:
        st.info("Fresh Previewで派生Projectを検証し、追加計画を確認してください。")
    else:
        _render_lightweight_fork_append_preview(preview)

    confirmation_checked = False
    append_ready = (
        preview_current
        and preview.get("valid")
        and preview.get("appendable_route_count", 0) > 0
        and not st.session_state.get("lightweight_fork_apply_running", False)
    )
    if append_ready:
        confirmation_checked = st.checkbox(
            "既存の派生Projectの末尾へ未追加シーンだけを追加し、Project/manifest/imagesをatomic更新することを確認しました。",
            key="lightweight_fork_append_confirmation",
        )
    append_clicked = st.button(
        "選択中のシーンを追加",
        type="primary",
        key="lightweight_fork_append_apply_button",
        disabled=not (append_ready and confirmation_checked),
    )
    if append_clicked:
        st.session_state.lightweight_fork_apply_running = True
        try:
            with st.spinner("Selected Scenesをatomicに追加しています..."):
                result = append_selected_routes_to_existing_fork(
                    project,
                    source_project_path=current_project_path,
                    selected_route_ids=append_route_ids,
                    existing_fork_project_path=existing_fork_project_path,
                    stored_preview=preview,
                    current_open_project_path=current_project_path,
                )
        except Exception:
            LOGGER.exception("Append Selected Routes to Existing Fork failed")
            result = {"success": False, "error": "Append failed. See the application log for details."}
        finally:
            st.session_state.lightweight_fork_apply_running = False
        st.session_state.lightweight_fork_append_result = result
        st.session_state.lightweight_fork_append_confirmation_pending_reset = True
        if result.get("success"):
            st.session_state.pop("lightweight_fork_append_preview", None)
            _remember_materialized_fork_project(result.get("existing_fork_project_path", ""))
            _invalidate_lightweight_fork_discovery_cache()
            st.rerun()

    _render_lightweight_fork_append_result(st.session_state.get("lightweight_fork_append_result"))


def render_lightweight_fork_preview_section(project) -> None:
    st.markdown("#### 派生Project / 最終シーケンス確認")
    st.caption(
        "各イラストの最終画像を確認し、元Projectを変更せずに独立した派生Projectを作成します。"
        "作成した派生Projectを明示的に開くまで、元Projectは開いたまま変更されません。"
    )

    if st.session_state.pop("lightweight_fork_append_widget_reset_pending", False):
        for key in (
            "lightweight_fork_action_mode",
            "lightweight_fork_append_candidate",
            "lightweight_fork_append_project_path",
            "lightweight_fork_append_confirmation",
        ):
            st.session_state.pop(key, None)

    mode = st.radio(
        "派生Projectの操作",
        ["create_new", "append_existing"],
        format_func=lambda value: (
            "派生Projectを作成" if value == "create_new" else "既存の派生Projectへ追加"
        ),
        horizontal=True,
        key="lightweight_fork_action_mode",
    )
    if mode == "append_existing":
        _render_lightweight_fork_append_section(project)
        return

    selected_line_ids = _lightweight_fork_selected_line_ids(project)
    current_project_path = os.path.abspath(st.session_state.get("current_project_path", "") or "")
    source_project_saved = bool(current_project_path and os.path.isfile(current_project_path))
    if not source_project_saved:
        st.warning("派生Projectを作成する前に、元Projectを保存してください。")
    fork_name = st.text_input(
        "派生Project名",
        value=st.session_state.get("lightweight_fork_name", "final_sequence_fork"),
        key="lightweight_fork_name",
    )
    scope = st.radio(
        "Target scope",
        ["all_lines", "current_route", "selected_route", "selected_routes", "selected_lines"],
        format_func=_gallery_operation_scope_label,
        horizontal=True,
        key="lightweight_fork_scope",
    )

    selected_route_id = ""
    selected_route_ids = []
    selected_route_plan = None
    if scope == "selected_route":
        selected_route_id = _render_lightweight_fork_single_route_selector(project)

    if scope == "selected_routes":
        selected_route_plan = resolve_selected_routes_fork_plan(
            project,
            st.session_state.get("gallery_selected_route_ids", []),
        )
        selected_route_ids = list(selected_route_plan.get("selected_route_ids", []))
        target_line_ids = list(selected_route_plan.get("target_line_ids", []))
        st.caption(
            "Selected Scenes source: Gallery session selection / Project order. "
            f"Scenes: {selected_route_plan.get('selected_route_count', 0)} / "
            f"Target Illustrations: {len(target_line_ids)}"
        )
        labels = selected_route_plan.get("resolved_route_labels", [])
        if labels:
            st.caption("Selected in Project order: " + ", ".join(labels))
        st.caption(
            "Workbench excluded: "
            f"{selected_route_plan.get('selected_workbench_count', 0)} / "
            "Deleted members excluded: "
            f"{selected_route_plan.get('selected_deleted_member_count', 0)} / "
            "Candidates and Gallery Variants are cleared from the Derived Project copy."
        )
        st.caption(
            "Trash records excluded: "
            f"{selected_route_plan.get('trash_removal_count', 0)}"
        )
        for diagnostic in selected_route_plan.get("diagnostics", [])[:3]:
            st.warning(format_core_message_for_display(diagnostic))
    else:
        target_resolution = resolve_gallery_operation_targets(
            project,
            scope,
            route_id=selected_route_id,
            selected_line_ids=selected_line_ids,
        )
        target_line_ids = target_resolution["target_line_ids"]
        _render_gallery_operation_target_summary(target_resolution)

    validation_error = None
    if scope == "selected_lines" and not selected_line_ids:
        validation_error = "Selected Illustrations scope requires at least one selected illustration."
    elif scope == "selected_route" and not selected_route_id:
        validation_error = "Selected Scene scope requires a scene."
    elif scope == "selected_routes" and not selected_route_plan.get("valid"):
        validation_error = (
            format_core_message_for_display(selected_route_plan.get("reason"))
            or "Selected Scenes are not available for this preview."
        )
    elif not target_line_ids:
        validation_error = "No target illustrations are available for this preview."
    if validation_error:
        st.warning(validation_error)

    current_preview = None
    if not validation_error:
        current_route_anchor_id = ""
        if scope == "current_route":
            current_route_anchor_id = _gallery_route_anchor_line_id(project, selected_line_ids)
        current_preview = build_lightweight_fork_preview(
            project.prompt_lines,
            fork_name=fork_name,
            scope=scope,
            project_path=current_project_path,
            target_line_ids=target_line_ids,
            selected_line_ids=selected_line_ids,
            selected_route_id=selected_route_id,
            selected_route_ids=selected_route_ids,
            current_route_anchor_id=current_route_anchor_id,
            path_exists=os.path.exists,
        )

    input_signature = _lightweight_fork_input_signature(
        project_path=current_project_path,
        fork_name=fork_name,
        scope=scope,
        selected_route_id=selected_route_id,
        selected_route_ids=selected_route_ids,
        selected_line_ids=selected_line_ids,
        target_line_ids=target_line_ids,
        current_route_anchor_id=current_route_anchor_id if not validation_error else "",
    )
    if st.session_state.get("lightweight_fork_input_signature") != input_signature:
        st.session_state.lightweight_fork_input_signature = input_signature
        st.session_state.pop("lightweight_fork_apply_result", None)
        st.session_state.lightweight_fork_confirmation = False
        st.session_state.lightweight_fork_all_phrase = ""

    if st.button(
        "派生Projectをプレビュー",
        disabled=bool(validation_error),
        key="lightweight_fork_preview_btn",
    ):
        st.session_state.lightweight_fork_preview = {
            "signature": current_preview.get("signature", {}) if current_preview else {},
            "preview": current_preview or {},
            "project_path": current_project_path,
        }
        st.session_state.lightweight_fork_confirmation = False
        st.session_state.lightweight_fork_all_phrase = ""
        st.session_state.pop("lightweight_fork_apply_result", None)

    preview_state = st.session_state.get("lightweight_fork_preview")
    if not preview_state:
        st.info("派生Projectをプレビューして、作成内容を確認してください。")
    preview_state = preview_state or {}

    preview_current = (
        bool(preview_state)
        and bool(current_preview)
        and preview_state.get("signature") == current_preview.get("signature")
        and os.path.abspath(preview_state.get("project_path", "") or "") == current_project_path
    )
    if preview_state and not preview_current:
        st.session_state.lightweight_fork_confirmation = False
        st.session_state.pop("lightweight_fork_apply_result", None)
        st.warning("Preview is stale. 派生Projectを作成する前に再Previewしてください。")

    preview = preview_state.get("preview", {})
    if preview:
        _render_lightweight_fork_preview_summary(preview)

    confirmation_checked = False
    if preview_current:
        confirmation_checked = st.checkbox(
            "I reviewed the final image sequence and understand that prompt text is copied unchanged.",
            key="lightweight_fork_confirmation",
        )

    all_scope_phrase = ""
    if scope == "all_lines":
        all_scope_phrase = st.text_input(
            f"Type {ALL_SCOPE_CONFIRM_PHRASE} to confirm All scope",
            key="lightweight_fork_all_phrase",
        )

    validation = None
    if preview_current and source_project_saved:
        validation = validate_lightweight_fork_apply(
            project,
            source_project_path=current_project_path,
            stored_preview=preview,
            current_preview=current_preview,
            destination_parent_dir=os.path.dirname(current_project_path),
            fork_name=fork_name,
            path_exists=os.path.exists,
        )

    blockers = get_lightweight_fork_create_blockers(
        fork_name=fork_name,
        source_project_saved=source_project_saved,
        stored_preview=preview,
        current_preview=current_preview if preview_current else None,
        preview_project_path=preview_state.get("project_path", ""),
        current_project_path=current_project_path,
        confirmation_checked=confirmation_checked,
        all_scope_phrase=all_scope_phrase,
        destination_conflict=bool(validation and validation.get("conflict")),
        validation=validation,
        materialization_running=bool(st.session_state.get("lightweight_fork_apply_running", False)),
    )
    if blockers:
        st.caption("派生Projectの作成はblockされています: " + "; ".join(blockers))
    else:
        st.success("派生Projectを作成できます。")

    create_clicked = st.button(
        "派生Projectを作成",
        type="primary",
        disabled=bool(blockers),
        key="lightweight_fork_create",
    )
    if create_clicked:
        st.session_state.lightweight_fork_apply_running = True
        try:
            with st.spinner("派生Projectを作成しています..."):
                result = materialize_lightweight_fork(
                    project,
                    source_project_path=current_project_path,
                    stored_preview=preview,
                    current_preview=current_preview,
                    destination_parent_dir=os.path.dirname(current_project_path),
                    fork_name=fork_name,
                )
        except Exception:
            LOGGER.exception("Lightweight Fork materialization failed")
            result = {
                "success": False,
                "error": "派生Projectを作成できませんでした。application logを確認してください。",
            }
        finally:
            st.session_state.lightweight_fork_apply_running = False
        st.session_state.lightweight_fork_apply_result = result
        if result.get("success"):
            _remember_materialized_fork_project(
                result.get("project_path", ""),
                result.get("fork_name", ""),
            )
            _invalidate_lightweight_fork_discovery_cache()
            request_project_directory_discovery_refresh()
            st.rerun()

    _render_lightweight_fork_apply_result(st.session_state.get("lightweight_fork_apply_result"))


def _gallery_operation_workflow_group(action_key: str) -> str:
    if action_key in {"module_swap", "attribute_group_swap", "batch_edit", "lightweight_fork"}:
        return "route"
    if action_key == "gallery_generation":
        return "generation"
    if action_key == "batch_candidate_adoption":
        return "adoption"
    if action_key in {"candidate_route_creation", "prompt_revert", "module_candidates"}:
        return "line"
    return ""


def _render_gallery_operation_buttons(actions) -> None:
    action_cols = st.columns(len(actions))
    for column, (action_key, label, help_text) in zip(action_cols, actions):
        with column:
            if st.button(
                label,
                key=f"gallery_operations_open_{action_key}",
                help=help_text,
                width="stretch",
            ):
                if st.session_state.get("gallery_operations_active") != action_key:
                    _clear_gallery_operation_safety_confirmation()
                st.session_state.gallery_operations_active = action_key
                st.rerun()


def _render_gallery_operation_context(project, selected_line_ids) -> None:
    focused_line = get_line_by_id(project, st.session_state.get("focused_line_id"))
    expanded_line = get_line_by_id(project, st.session_state.get("gallery_expanded_line_id"))
    route_anchor_id = (
        getattr(focused_line, "id", "")
        or (selected_line_ids[0] if selected_line_ids else "")
        or st.session_state.get("gallery_expanded_line_id", "")
    )
    route_context = resolve_gallery_route_for_line(project, route_anchor_id) if route_anchor_id else None
    context_parts = []
    if route_context and route_context.get("route_id"):
        context_parts.append(
            f"現在のシーン: {route_context.get('route_label') or 'Scene'} "
            f"({route_context.get('line_count', 0)} illustrations)"
        )
    if selected_line_ids:
        context_parts.append(f"選択イラスト: {len(selected_line_ids)}")
    selected_routes_state = sanitize_selected_route_ids(
        project,
        st.session_state.get("gallery_selected_route_ids", []),
    )
    if selected_routes_state.get("selected_route_count"):
        context_parts.append(f"Selected Scenes: {selected_routes_state['selected_route_count']}")
    if focused_line:
        context_parts.append(f"フォーカス中のイラスト: {get_prompt_line_label(focused_line)}")
    if expanded_line and expanded_line is not focused_line:
        context_parts.append(f"展開中のイラスト: {get_prompt_line_label(expanded_line)}")
    if context_parts:
        st.caption(" / ".join(context_parts))


def _render_gallery_operation_scope_capability(action_key: str) -> None:
    entry = get_gallery_operation_scope_presentation(action_key)
    if not entry:
        return
    st.caption(
        "Supported targets / 対応対象: "
        + " · ".join(entry["supported_scope_labels"])
    )
    if entry["uses_shared_selected_scenes"]:
        st.caption(
            "Choose “Selected Scenes / 操作対象シーン” in this operation to use the shared selection above."
        )
    else:
        st.caption("The shared Selected Scenes selection does not control this operation.")


def _render_gallery_active_operation_for_workflow(project, workflow_group: str) -> None:
    active_operation = st.session_state.get("gallery_operations_active", "")
    if _gallery_operation_workflow_group(active_operation) == workflow_group:
        render_gallery_active_operation_panel(project)


def render_gallery_operations_launcher(project) -> None:
    active_lines = get_visible_prompt_lines(project)
    operation_selected_line_ids = [
        line.id
        for line in active_lines
        if st.session_state.get("gallery_move_targets", {}).get(line.id)
        and is_gallery_operation_prompt_line(line)
    ]
    st.markdown("#### シーンのプロンプト・構造編集")
    st.caption(
        "既存シーンを編集し、再生成して、Candidateを本編へ反映する順に操作します。"
    )
    st.markdown("##### 1. Prompt／構造を編集")
    st.caption(
        "ModuleやAttribute、Promptを調整し、必要に応じて派生Projectを作成します。"
    )
    _render_gallery_operation_buttons(
        [
            (
                "module_swap",
                "モジュール差し替え",
                "シーンまたはプロジェクト全体のキャラクター・服装・構造モジュールを入れ替えます。",
            ),
            (
                "attribute_group_swap",
                "Attribute Group Swap",
                "Galleryのシーンや選択イラストを見ながら、衣装・表情・ポーズなどのAttribute差分を差し替えます。",
            ),
            (
                "batch_edit",
                "一括編集",
                "選択・シーン・プロジェクト全体のプロンプトをプレビュー付きで一括修正します。",
            ),
            (
                "lightweight_fork",
                "派生Project",
                "確定した最終シーケンスから、元Projectを変更せずに派生Projectを作成します。",
            ),
        ]
    )
    _render_gallery_active_operation_for_workflow(project, "route")

    st.markdown("##### 2. Scene Generation / シーンを一括生成")
    st.caption(
        "編集後のPromptを使って、すべてのイラストまたは選択中のシーンを一括生成します。"
    )
    _render_gallery_operation_buttons(
        [
            (
                "gallery_generation",
                "一括生成を開く",
                "既存のScene Generationをsingle active operation panelで開きます。",
            ),
        ]
    )
    _render_gallery_active_operation_for_workflow(project, "generation")

    st.markdown("##### 3. Candidateを本編へ反映")
    st.caption(
        "一括生成後に各イラストのCandidateを確認し、選択した画像を本編へ反映します。"
    )
    _render_gallery_operation_buttons(
        [
            (
                "batch_candidate_adoption",
                "Candidate Adoptionを開く",
                "既存のScene Batch Candidate Adoptionをsingle active operation panelで開きます。",
            ),
        ]
    )
    _render_gallery_active_operation_for_workflow(project, "adoption")

    st.divider()
    st.markdown("#### イラスト／Workbenchベースの作成・拡張")
    st.caption(
        "個別イラストやWorkbenchからCandidate／Variantを使って、本編イラストや別案シーンを増やします。"
    )
    st.caption(
        "These operations use Illustration, Candidate, Variant, or Workbench context rather than the shared "
        "Scene selection unless the operation explicitly offers Selected Scenes / 操作対象シーン."
    )
    render_gallery_batch_variant_promotion(project, active_lines, operation_selected_line_ids)
    st.caption(
        "Batch Promote Variantsはシーン区切りを作らず通常のGalleryイラストを追加します。"
        "候補から別案シーンを作成はシーン区切り付きの別案シーンを追加します。"
    )
    _render_gallery_operation_buttons(
        [
            (
                "candidate_route_creation",
                "候補から別案シーンを作成",
                "イラストのCandidatesをシーン区切り付きの別案シーンとして展開します。Candidate自体は削除しません。",
            ),
            (
                "prompt_revert",
                "Prompt Revert",
                "対象イラストの編集中Positive Promptを元画像Promptへ戻します。画像参照とNegative Promptは変更しません。",
            ),
            (
                "module_candidates",
                "モジュール候補検索",
                "共通トークン列をモジュール候補として検索し、モジュール参照を適用します。",
            ),
        ]
    )
    _render_gallery_active_operation_for_workflow(project, "line")


def render_gallery_active_operation_panel(project) -> None:
    active_operation = st.session_state.get("gallery_operations_active")
    labels = {
        "attribute_group_swap": "Attribute Group Swap",
        "module_swap": "モジュール差し替え",
        "batch_edit": "一括編集",
        "gallery_generation": "Scene Generation / シーンを一括生成",
        "batch_candidate_adoption": "Scene Batch Candidate Adoption",
        "prompt_revert": "Prompt Revert",
        "module_candidates": "モジュール候補検索",
        "candidate_route_creation": "候補から別案シーンを作成",
        "lightweight_fork": "派生Project / 最終シーケンスPreview",
    }
    if active_operation not in labels:
        return

    with st.container(border=True):
        header_cols = st.columns([3, 1])
        header_cols[0].markdown(f"#### Gallery操作: {labels[active_operation]}")
        if header_cols[1].button("閉じる", key="gallery_operations_close"):
            if active_operation == "lightweight_fork":
                reset_lightweight_fork_session_state()
            _clear_gallery_operation_safety_confirmation()
            st.session_state.pop("gallery_operation_focus", None)
            st.session_state.pop("gallery_operations_active", None)
            st.rerun()
        st.caption(
            "選択・シーン・プロジェクト全体への適用はすべてプレビュー確認付きです。Galleryのページ・選択・フォーカス・シーンコンテキストはそのまま保持されます。"
        )
        _render_gallery_operation_context(project, get_selected_line_ids(project))
        _render_gallery_operation_scope_capability(active_operation)
        if active_operation == "module_swap":
            render_module_swap_section(project)
        elif active_operation == "attribute_group_swap":
            render_gallery_attribute_group_swap_section(project)
        elif active_operation == "batch_edit":
            render_batch_editing_section(project)
        elif active_operation == "gallery_generation":
            active_lines = get_visible_prompt_lines(project)
            selected_line_ids = [
                line.id
                for line in active_lines
                if st.session_state.get("gallery_move_targets", {}).get(line.id)
                and is_gallery_operation_prompt_line(line)
            ]
            render_gallery_global_generation_controls(
                project,
                active_lines,
                selected_line_ids,
                embedded=True,
            )
        elif active_operation == "batch_candidate_adoption":
            active_lines = get_visible_prompt_lines(project)
            selected_line_ids = [
                line.id
                for line in active_lines
                if st.session_state.get("gallery_move_targets", {}).get(line.id)
                and is_gallery_operation_prompt_line(line)
            ]
            render_gallery_batch_candidate_adoption(
                project,
                active_lines,
                selected_line_ids,
                embedded=True,
            )
        elif active_operation == "prompt_revert":
            render_gallery_prompt_revert_section(project)
        elif active_operation == "module_candidates":
            render_global_module_candidate_scanner_section(project)
        elif active_operation == "candidate_route_creation":
            render_candidate_route_creation_section(project)
        elif active_operation == "lightweight_fork":
            render_lightweight_fork_preview_section(project)


def render_prompt_import_export_panel(project) -> None:
    with st.expander("プロンプト読み込み・書き出し", expanded=False):
        import_mode = st.radio(
            "プロンプト読み込みモード",
            ["Directory of TXT files", "Single TXT file"],
            format_func=lambda value: {
                "Directory of TXT files": "TXTフォルダ",
                "Single TXT file": "単一TXTファイル",
            }[value],
            horizontal=False,
            help="TXTフォルダは .txt ファイルを名前順で読み込みます。単一TXTは1ファイル内の1行以上のプロンプトを読み込みます。",
            key="main_prompt_import_mode",
        )

        if import_mode == "Directory of TXT files":
            target_dir = st.text_input(
                "読み込み元フォルダ",
                st.session_state.settings.get("last_source_directory", "./dummy_data"),
                key="main_prompt_import_source_directory",
            )
            import_button_label = "フォルダを読み込む"
        else:
            target_file = st.text_input(
                "読み込み元TXT",
                st.session_state.settings.get("last_source_file", "prompts.txt"),
                key="main_prompt_import_source_file",
            )
            import_button_label = "TXTファイルを読み込む"

        if st.button(import_button_label, key="main_prompt_import_button"):
            if import_mode == "Directory of TXT files" and os.path.isdir(target_dir):
                st.session_state.history = []
                with st.spinner("Building full graph..."):
                    with profile_block("Project load: directory import"):
                        loaded_project = load_directory(target_dir, max_depth=None)
                    ensure_original_image_set_route(loaded_project)
                    with profile_block("Project load: build graph"):
                        loaded_project = build_graph(loaded_project)
                reset_management_workspace_session_state()
                reset_graph_project_session_state()
                reset_project_assets_operation_state()
                reset_module_attribute_authoring_project_session_state()
                reset_insert_module_reference_project_session_state()
                reset_module_candidate_project_session_state()
                reset_attribute_group_swap_project_session_state()
                reset_module_edit_scope_project_session_state()
                st.session_state.project = loaded_project
                st.session_state.current_project_path = ""
                reset_lightweight_fork_session_state()
                reset_gallery_route_action_session_state()
                reset_gallery_selected_route_session_state()
                st.session_state.focused_line_id = None
                st.session_state.selected_node_ids = []
                st.session_state.connect_mode = False
                clear_module_rename_preview()
                st.session_state.settings["last_source_directory"] = target_dir
                save_settings(st.session_state.settings)
                st.success(f"{target_dir} から読み込みました。")
                st.rerun()
            elif import_mode == "Single TXT file" and os.path.isfile(target_file):
                st.session_state.history = []
                with st.spinner("Building graph from TXT file..."):
                    with profile_block("Project load: TXT import"):
                        loaded_project = load_prompt_file(target_file, max_depth=None)
                    ensure_original_image_set_route(loaded_project)
                    with profile_block("Project load: build graph"):
                        loaded_project = build_graph(loaded_project)
                reset_management_workspace_session_state()
                reset_graph_project_session_state()
                reset_project_assets_operation_state()
                reset_module_attribute_authoring_project_session_state()
                reset_insert_module_reference_project_session_state()
                reset_module_candidate_project_session_state()
                reset_attribute_group_swap_project_session_state()
                reset_module_edit_scope_project_session_state()
                st.session_state.project = loaded_project
                st.session_state.current_project_path = ""
                reset_lightweight_fork_session_state()
                reset_gallery_route_action_session_state()
                reset_gallery_selected_route_session_state()
                st.session_state.focused_line_id = None
                st.session_state.selected_node_ids = []
                st.session_state.connect_mode = False
                clear_module_rename_preview()
                st.session_state.settings["last_source_file"] = target_file
                st.session_state.settings["last_source_directory"] = os.path.dirname(target_file) or "."
                save_settings(st.session_state.settings)
                st.success(f"{target_file} から読み込みました。")
                st.rerun()
            else:
                st.error("読み込みパスが正しくありません。")

        st.divider()
        export_mode = st.radio(
            "プロンプト書き出しモード",
            ["Combined TXT", "One prompt per file"],
            format_func=lambda value: {
                "Combined TXT": "1つのTXTへまとめる",
                "One prompt per file": "1プロンプト1ファイル",
            }[value],
            horizontal=False,
            help="まとめ書き出しは1つのTXTに保存します。1プロンプト1ファイルは順番付きTXTを書き出します。",
            key="main_prompt_export_mode",
        )
        export_disabled = not bool(project)
        if export_mode == "Combined TXT":
            export_path = st.text_input(
                "まとめTXTの書き出し先",
                st.session_state.settings.get("last_export_path", "prompts.txt"),
                key="main_prompt_export_combined_path",
            )
            if st.button("まとめTXTを書き出す", disabled=export_disabled, key="main_prompt_export_combined_button"):
                export_to_txt(project, export_path, disabled_modules=st.session_state.disabled_modules)
                st.session_state.settings["last_export_path"] = export_path
                save_settings(st.session_state.settings)
                st.success(f"{export_path} へ書き出しました。")
        else:
            export_dir = st.text_input(
                "書き出しフォルダ",
                st.session_state.settings.get("last_export_directory", "prompt_exports"),
                key="main_prompt_export_folder",
            )
            st.caption("0001_source-name.txt のようなファイルを書き出します。同名ファイルは置き換えられます。")
            if st.button("プロンプトファイルを書き出す", disabled=export_disabled, key="main_prompt_export_files_button"):
                exported_paths = export_to_prompt_files(
                    project,
                    export_dir,
                    disabled_modules=st.session_state.disabled_modules,
                )
                st.session_state.settings["last_export_directory"] = export_dir
                save_settings(st.session_state.settings)
                st.success(f"{len(exported_paths)}件のプロンプトファイルを {export_dir} へ書き出しました。")
        if export_disabled:
            st.caption("プロンプトを書き出すには、プロジェクトを読み込むか作成してください。")


def render_image_metadata_import_panel(project) -> None:
    with st.expander("画像・メタデータ読み込み", expanded=False):
        st.caption("PNGメタ情報を読み取り、Galleryで編集できるイラストへ変換します。ComfyUI埋め込みワークフローがある場合は生成時に利用できます。")
        image_import_default = st.session_state.settings.get(
            "last_image_import_directory",
            st.session_state.settings.get("last_source_directory", "."),
        )
        if "image_import_root_directory" not in st.session_state:
            st.session_state.image_import_root_directory = st.session_state.settings.get("image_root_directory", "")
        image_root_dir = st.text_input(
            "画像Rootフォルダ",
            key="image_import_root_directory",
            help=f"画像を含むサブフォルダを Image Set として最大 {IMAGE_SET_MAX_SCAN_DEPTH} 階層まで一覧化します。",
        )
        if image_root_dir != st.session_state.settings.get("image_root_directory", ""):
            st.session_state.settings["image_root_directory"] = image_root_dir
            save_settings(st.session_state.settings)

        image_sets = list_image_sets(image_root_dir)
        image_set_options = [""] + image_sets
        stored_image_set = st.session_state.settings.get("image_set", "")
        if stored_image_set not in image_set_options:
            stored_image_set = ""
        if "image_import_set" not in st.session_state:
            st.session_state.image_import_set = stored_image_set
        if st.session_state.image_import_set not in image_set_options:
            st.session_state.image_import_set = ""
        selected_image_set = st.selectbox(
            "Image Set",
            options=image_set_options,
            format_func=lambda value: "(なし)" if not value else value,
            key="image_import_set",
            help="画像Rootフォルダと、選択した相対サブフォルダを組み合わせて使います。",
        )
        if selected_image_set != st.session_state.settings.get("image_set", ""):
            st.session_state.settings["image_set"] = selected_image_set
            save_settings(st.session_state.settings)

        selected_image_set_path = resolve_image_set_path(selected_image_set, image_root_dir)
        if selected_image_set_path:
            st.caption(f"解決されたImage Set: {selected_image_set_path}")
        elif selected_image_set:
            st.caption("選択したImage Setが使えないため、手動指定の画像フォルダを使います。")

        image_import_dir = st.text_input(
            "画像フォルダ",
            selected_image_set_path or image_import_default,
            help="Image Set未選択、または選択したsetが使えない場合に使います。",
            key="main_image_import_directory",
        )
        effective_image_import_dir = selected_image_set_path or image_import_dir
        scan_disabled = not bool(project)
        if st.button("画像フォルダをスキャン", disabled=scan_disabled, key="main_image_import_scan_button"):
            import_summary = add_image_metadata_import(project, effective_image_import_dir)
            st.session_state.settings["last_image_import_directory"] = effective_image_import_dir
            save_settings(st.session_state.settings)
            if import_summary.get("warnings"):
                st.warning(import_summary["warnings"][0])
            st.success(f"{import_summary['image_count']}件の画像ファイルをスキャンしました。")

        if project:
            image_imports = project.project_metadata.get("image_imports", [])
            if image_imports:
                latest_image_import = image_imports[-1]
                metric_cols = st.columns(3)
                metric_cols[0].metric("画像", latest_image_import.get("image_count", 0))
                metric_cols[1].metric("メタデータあり", latest_image_import.get("metadata_count", 0))
                metric_cols[2].metric("ComfyUI", latest_image_import.get("comfy_workflow_count", 0))
                if latest_image_import.get("warnings"):
                    st.caption(f"警告: {len(latest_image_import['warnings'])}")
            else:
                st.caption("画像メタデータ読み込みはまだありません。")

            line_import_summary = summarize_image_metadata_line_import(project)
            if line_import_summary["has_import"]:
                convert_cols = st.columns(2)
                convert_cols[0].metric("作成可能イラスト", line_import_summary["line_count"])
                convert_cols[1].metric("スキップ", line_import_summary["skipped_count"])
                image_line_mode = st.radio(
                    "PNGメタ情報の読み込み方法",
                    ["Append to current project", "Replace current lines"],
                    horizontal=False,
                    format_func=lambda value: "追加読み込み" if value == "Append to current project" else "上書き読み込み",
                    key="main_image_import_line_mode",
                )
                if line_import_summary["line_count"] == 0:
                    st.caption("最新の読み込みにPromptメタデータが見つかりません。")
                if st.button(
                    "最新の読み込みからイラストを作成",
                    disabled=line_import_summary["line_count"] == 0,
                    key="main_image_import_create_lines_button",
                ):
                    push_history()
                    st.session_state.project, conversion_summary = create_prompt_lines_from_latest_image_import(
                        project,
                        replace=image_line_mode == "Replace current lines",
                    )
                    if ensure_original_image_set_route(st.session_state.project):
                        st.session_state.project = build_graph(st.session_state.project)
                    st.session_state.focused_line_id = None
                    st.session_state.selected_node_ids = []
                    st.session_state.connect_mode = False
                    clear_module_rename_preview()
                    clear_module_edit_scope_if_missing(st.session_state.project)
                    sync_text_areas()
                    st.success(f"PNGメタ情報から {conversion_summary['created_count']} 件のイラストを作成しました。")
                    st.rerun()
        else:
            st.caption("画像をスキャンする前に、プロジェクトを読み込むか作成してください。")


def render_gallery_import_export_section(project) -> None:
    operation_focus = st.session_state.get("gallery_operation_focus") == "final_export"
    with st.expander("読み込み・書き出し", expanded=operation_focus):
        st.caption("Gallery制作対象への読み込みと、制作結果の書き出しをここにまとめています。Projectファイルの新規作成・保存・読み込みは左側Sidebarにあります。")
        render_prompt_import_export_panel(project)
        render_image_metadata_import_panel(project)
        render_gallery_final_image_export(project)
    if operation_focus:
        st.session_state.pop("gallery_operation_focus", None)


def render_gallery_final_image_export(project) -> None:
    operation_focus = st.session_state.get("gallery_operation_focus") == "final_export"
    with st.expander("最終画像を書き出し", expanded=operation_focus):
        current_project_path = st.session_state.get("current_project_path", "")
        project_export_root = _project_final_image_export_dir()
        if not current_project_path or not project_export_root:
            st.info("project-local exports/final へ書き出すには、先にプロジェクトを保存してください。")
            return

        timestamp_project_key = "final_image_export_timestamp_project_path"
        if (
            "final_image_export_timestamp" not in st.session_state
            or st.session_state.get(timestamp_project_key) != current_project_path
        ):
            st.session_state.final_image_export_timestamp = datetime.now().strftime("%Y-%m-%d_%H%M")
            st.session_state[timestamp_project_key] = current_project_path

        use_timestamp_subfolder = st.checkbox(
            "日時フォルダを使う",
            value=True,
            key="gallery_final_export_use_timestamp",
            help="推奨。書き出しごとに exports/final 配下へ個別フォルダを作ります。",
        )
        if use_timestamp_subfolder:
            timestamp_folder = st.text_input(
                "日時フォルダ名",
                key="final_image_export_timestamp",
                help="今回の書き出しで使う exports/final 配下のフォルダ名です。",
            ).strip()
        else:
            timestamp_folder = ""

        output_dir = os.path.join(project_export_root, timestamp_folder) if timestamp_folder else project_export_root
        export_scope = st.radio(
            "書き出し対象",
            ["all_lines", "current_route", "selected_route", "selected_routes"],
            format_func=_final_export_scope_label,
            horizontal=True,
            key="gallery_final_export_scope",
        )
        route_options = _final_export_route_options(project)
        route_option_lookup = {route.get("route_id", ""): route for route in route_options}
        selected_export_route_id = ""
        if export_scope == "selected_route":
            if route_options:
                selected_export_route_id = st.selectbox(
                    "シーンを選択",
                    [route.get("route_id", "") for route in route_options],
                    format_func=lambda route_id: _format_final_export_route_option(route_option_lookup.get(route_id, {})),
                    key="gallery_final_export_selected_route_id",
                )
            else:
                st.warning("このProjectには選択できるSceneがありません。")

        col_a, col_b, col_c = st.columns([2, 1, 1])
        with col_a:
            base_filename = st.text_input("ファイル名ベース", value="final", key="gallery_final_export_base_filename")
        with col_b:
            start_index = st.number_input("開始番号", min_value=1, value=1, step=1, key="gallery_final_export_start_index")
        with col_c:
            digits = st.number_input("桁数", min_value=1, max_value=8, value=4, step=1, key="gallery_final_export_digits")
        strip_metadata = st.checkbox(
            "PNGメタデータを削除して出力",
            value=True,
            key="gallery_final_export_strip_metadata",
            help="書き出しコピーだけを再保存します。プロジェクト内のsource/Candidate画像は変更しません。",
        )
        gallery_selected_line_ids = [
            line_id
            for line_id, selected in st.session_state.get("gallery_move_targets", {}).items()
            if selected
        ]
        selected_line_ids = gallery_selected_line_ids or get_selected_line_ids(project)
        selected_route_ids = st.session_state.get("gallery_selected_route_ids", [])
        target_resolution = resolve_final_export_lines(
            project,
            export_scope,
            route_id=selected_export_route_id,
            selected_line_ids=selected_line_ids,
            selected_route_ids=selected_route_ids,
        )

        preview = preview_final_image_export(
            project,
            output_dir,
            project_path=current_project_path,
            base_filename=base_filename,
            start_index=int(start_index),
            digits=int(digits),
            target_line_ids=None if export_scope == "all_lines" else target_resolution["line_ids"],
            export_scope=target_resolution["scope"],
            route_id=target_resolution["route_id"],
            route_label=target_resolution["route_label"],
            route_line_count=target_resolution["route_line_count"],
            selected_route_handles=target_resolution["resolved_route_handles"],
            selected_route_labels=target_resolution["resolved_route_labels"],
            selected_route_count=target_resolution["selected_route_count"],
            route_summaries=target_resolution["route_summaries"],
            use_timestamp_subfolder=use_timestamp_subfolder,
        )
        destination_profile = preview.get("destination_profile", {})
        st.caption(f"書き出し対象: {_final_export_scope_label(target_resolution['scope'])}")
        if export_scope == "selected_routes":
            st.caption(
                f"Selected Scenes: {target_resolution['selected_route_count']} / "
                f"main Illustrations: {target_resolution['selected_main_line_count']}"
            )
            if target_resolution["resolved_route_labels"]:
                st.caption(
                    "Scenes in Project order: "
                    + ", ".join(target_resolution["resolved_route_labels"])
                )
        if target_resolution.get("route_id"):
            st.caption(
                f"Scene: {target_resolution.get('route_label') or '(名称なし)'} "
                f"({target_resolution.get('route_id')}, {target_resolution.get('route_line_count') or 0} illustrations)"
            )
        st.caption(f"対象イラスト: {len(target_resolution['lines'])}")
        metric_a, metric_b, metric_c = st.columns(3)
        metric_a.metric("Exportable images", preview["exportable_count"])
        metric_b.metric("Skipped illustrations", preview["skipped_count"])
        metric_c.metric(
            "Source total size / 出力前合計容量",
            _format_project_assets_bytes(
                preview.get("source_total_bytes", 0)
            ),
        )
        metric_d, metric_e, metric_f = st.columns(3)
        metric_d.metric(
            "Destination free",
            (
                _format_project_assets_bytes(
                    destination_profile.get("disk_free_bytes", 0)
                )
                if destination_profile.get("disk_usage_available")
                else "Unknown"
            ),
        )
        metric_e.metric(
            "Planned overwrite",
            destination_profile.get("existing_output_count", 0),
        )
        metric_f.metric(
            "Destination profile",
            destination_profile.get(
                "destination_label",
                "Unavailable / unknown",
            ),
        )
        st.caption(f"出力先フォルダ: {preview['output_dir']}")
        st.caption(
            "Destination profile: "
            f"{destination_profile.get('destination_label', 'Unavailable / unknown')}"
        )
        st.caption(
            "Nearest existing filesystem: "
            f"{destination_profile.get('nearest_existing_parent') or 'Unknown'}"
        )
        if strip_metadata:
            st.caption(
                "PNGメタデータ削除が有効な場合、画像の再保存により"
                "実際の出力容量はPreview値から変化することがあります。"
            )
        st.caption(
            "Preview容量はmanifest、filesystem overhead、"
            "metadata strip後の再保存差分を含みません。"
        )
        capacity_status = destination_profile.get("capacity_status")
        if capacity_status == "insufficient":
            st.warning(
                "出力前合計容量が、現在確認できる出力先空き容量を"
                "超えています。Exportは失敗または途中完了になる"
                "可能性があります。"
            )
        elif capacity_status == "unknown":
            st.warning(
                "一部source容量または出力先空き容量を確認できないため、"
                "必要容量を正確に判定できません。"
            )
        if destination_profile.get("destination_kind") == "final_root":
            st.warning(
                "日時フォルダを使わず共有exports/final rootへ書き出します。"
                "以前の同名画像やmanifestを上書きする可能性があります。"
                "日時フォルダの利用を推奨します。"
            )
        overwrite_count = int(
            destination_profile.get("existing_output_count", 0) or 0
        )
        manifest_exists = bool(
            destination_profile.get("manifest_exists")
        )
        if overwrite_count or manifest_exists:
            overwrite_parts = []
            if overwrite_count:
                overwrite_parts.append(f"既存画像 {overwrite_count}件")
            if manifest_exists:
                overwrite_parts.append("manifest")
            st.warning(
                "と".join(overwrite_parts)
                + "を上書きする可能性があります。"
            )
        for warning in destination_profile.get("warnings", [])[:3]:
            st.warning(warning)
        for warning in target_resolution.get("warnings", [])[:3]:
            st.warning(warning)
        for warning in preview.get("warnings", [])[:3]:
            st.warning(warning)
        preview_rows = [
            {
                "output": item.get("output_filename", ""),
                "line": item.get("source_original_filename", ""),
                "source": item.get("source_image_path", ""),
                "size": (
                    _format_project_assets_bytes(
                        item.get("source_size_bytes", 0)
                    )
                    if item.get("source_size_available")
                    else "Unknown"
                ),
                "route": (item.get("route") or {}).get("route_label", ""),
            }
            for item in preview.get("items", [])[:5]
        ]
        if preview_rows:
            st.dataframe(preview_rows, hide_index=True, width="stretch")
        else:
            st.info("現在のGallery本編列に、書き出し可能な最終画像がありません。")
        if preview.get("skipped_items"):
            st.caption(f"{len(preview['skipped_items'])}件のイラストは本編画像がないためスキップされます。")

        render_sequence_preview_panel(project, preview)

        selected_routes_preview_current = True
        if export_scope == "selected_routes":
            current_preview_signature = _final_export_preview_signature(
                target_resolution,
                preview,
                output_dir=output_dir,
                base_filename=base_filename,
                start_index=int(start_index),
                digits=int(digits),
                strip_metadata=strip_metadata,
            )
            selected_routes_preview_current = (
                st.session_state.get("gallery_final_export_selected_routes_preview_signature")
                == current_preview_signature
            )
            if st.button(
                "Selected ScenesのPreviewを更新",
                key="gallery_final_export_selected_routes_preview_button",
                disabled=not target_resolution["selected_route_count"],
            ):
                st.session_state.gallery_final_export_selected_routes_preview_signature = current_preview_signature
                st.rerun()
            if not selected_routes_preview_current:
                st.warning(
                    "Selected ScenesまたはExport設定が変わりました。Fresh Previewを実行してからExportしてください。"
                )

        if st.button(
            "最終画像を書き出す",
            key="gallery_final_export_button",
            type="primary",
            disabled=(
                preview["exportable_count"] == 0
                or (export_scope != "all_lines" and not target_resolution["line_ids"])
                or not selected_routes_preview_current
            ),
        ):
            summary = export_final_images(
                project,
                output_dir,
                project_path=current_project_path,
                strip_metadata=strip_metadata,
                base_filename=base_filename,
                start_index=int(start_index),
                digits=int(digits),
                target_line_ids=None if export_scope == "all_lines" else target_resolution["line_ids"],
                export_scope=target_resolution["scope"],
                route_id=target_resolution["route_id"],
                route_label=target_resolution["route_label"],
                route_line_count=target_resolution["route_line_count"],
                selected_route_handles=target_resolution["resolved_route_handles"],
                selected_route_labels=target_resolution["resolved_route_labels"],
                selected_route_count=target_resolution["selected_route_count"],
                route_summaries=target_resolution["route_summaries"],
            )
            if summary["exported_count"]:
                st.success(
                    f"{_final_export_scope_label(target_resolution['scope'])}から"
                    f"{summary['exported_count']}件の最終画像を {summary['output_dir']} へ書き出しました。"
                    f"スキップ: {summary['skipped_count']}件。"
                )
            else:
                st.warning(f"最終画像は書き出されませんでした。スキップ: {summary['skipped_count']}件。")
            if summary.get("manifest_path"):
                st.caption(f"Manifestファイル: {summary['manifest_path']}")
            for warning in summary.get("warnings", [])[:5]:
                st.warning(warning)


def _gallery_route_line_count(active_lines: list, separator_line_id: str) -> int:
    separator_index = next(
        (index for index, line in enumerate(active_lines) if getattr(line, "id", "") == separator_line_id),
        None,
    )
    if separator_index is None:
        return 0
    next_separator_index = next(
        (
            index
            for index, line in enumerate(active_lines[separator_index + 1:], start=separator_index + 1)
            if is_route_separator(line)
        ),
        len(active_lines),
    )
    return sum(
        1
        for line in active_lines[separator_index + 1:next_separator_index]
        if is_gallery_operation_prompt_line(line)
    )


def _dispatch_gallery_route_action(project, separator_line, action: str) -> dict:
    route_block = resolve_route_block(project, getattr(separator_line, "id", ""))
    dispatch = get_route_action_dispatch_updates(
        action,
        route_block.route_handle,
        is_valid=route_block.is_valid,
        is_deleted=route_block.deleted,
    )
    if not dispatch.get("dispatch"):
        return dispatch

    pending = dict(dispatch["pending"])
    pending["route_label"] = route_block.separator_label
    st.session_state.gallery_route_action_pending = pending
    return dispatch


def _apply_pending_gallery_route_action(project) -> None:
    """Apply a queued Route shortcut before any Gallery operation widgets render."""

    pending = st.session_state.pop("gallery_route_action_pending", None)
    if not isinstance(pending, dict):
        return

    route_handle = str(pending.get("route_handle") or "").strip()
    route_block = resolve_route_block(project, route_handle)
    if not route_block.is_valid or route_block.deleted:
        return

    pending["route_label"] = route_block.separator_label
    result = get_route_action_pending_updates(pending)
    if not result.get("apply"):
        return
    if result.get("updates", {}).get("gallery_operations_active") != st.session_state.get(
        "gallery_operations_active"
    ):
        _clear_gallery_operation_safety_confirmation()
    for key in result.get("remove", []):
        st.session_state.pop(key, None)
    for key, value in result.get("updates", {}).items():
        st.session_state[key] = value


def _apply_pending_gallery_route_remove_reset(project) -> None:
    """Clear operation widget state before Gallery panels are instantiated."""

    pending = st.session_state.pop("gallery_route_remove_pending_reset", None)
    if not isinstance(pending, dict):
        return

    preserved_selected_route = st.session_state.get("gallery_selected_route_separator_id")
    reset_gallery_route_action_session_state()
    reset_gallery_route_move_preview_state()
    confirmation_key = str(pending.get("confirmation_key") or "").strip()
    if confirmation_key:
        st.session_state.pop(confirmation_key, None)
    restored_state = get_route_remove_ui_state(
        project,
        route_handle=str(pending.get("route_handle") or ""),
        selected_route_separator_id=preserved_selected_route,
    )
    st.session_state.gallery_selected_route_separator_id = restored_state[
        "gallery_selected_route_separator_id"
    ]
    # Route collapse state is session-only and keyed by separator id. Keep it
    # so an atomic restore can reuse the user's previous collapsed state.


def _apply_pending_gallery_route_duplicate_reset(project) -> None:
    """Reset operation widgets before panels render after Route duplication."""

    pending = st.session_state.pop("gallery_route_duplicate_pending_reset", None)
    if not isinstance(pending, dict):
        return

    reset_gallery_route_action_session_state()
    reset_gallery_route_move_preview_state()
    for key_name in ("label_key", "confirmation_key"):
        widget_key = str(pending.get(key_name) or "").strip()
        if widget_key:
            st.session_state.pop(widget_key, None)

    restored_state = get_route_duplicate_ui_state(
        project,
        source_route_handle=str(pending.get("source_route_handle") or ""),
        new_route_handle=str(pending.get("new_route_handle") or ""),
        focused_line_id=st.session_state.get("focused_line_id"),
        highlighted_line_id=st.session_state.get("highlighted_line_id"),
        expanded_line_id=st.session_state.get("gallery_expanded_line_id"),
        collapsed_routes=st.session_state.get("gallery_collapsed_routes"),
    )
    st.session_state.gallery_selected_route_separator_id = restored_state[
        "gallery_selected_route_separator_id"
    ]
    st.session_state.focused_line_id = restored_state["focused_line_id"]
    st.session_state.highlighted_line_id = restored_state["highlighted_line_id"]
    st.session_state.gallery_expanded_line_id = restored_state["gallery_expanded_line_id"]
    st.session_state.gallery_collapsed_routes = restored_state["gallery_collapsed_routes"]


def _move_gallery_route_block_from_ui(project, separator_line, direction: str) -> dict:
    separator_id = getattr(separator_line, "id", "")
    direction_key = str(direction or "").strip().lower()
    previous_focus = st.session_state.get("focused_line_id")
    previous_highlight = st.session_state.get("highlighted_line_id")
    previous_expanded = st.session_state.get("gallery_expanded_line_id")
    availability = get_route_block_move_availability(project, separator_id)
    can_move_key = f"can_move_{direction_key}"
    if not availability.get(can_move_key, False):
        return move_route_block(project, separator_id, direction_key)

    history_length = len(st.session_state.get("history", []))
    push_history()
    result = move_route_block(project, separator_id, direction_key)
    if not result.get("moved"):
        history = st.session_state.get("history", [])
        del history[history_length:]
        return result

    route_label = route_separator_label(separator_line)
    reset_gallery_route_move_preview_state()
    st.session_state.project = build_graph(project)
    _set_gallery_selected_route_ids_after_structure_change(st.session_state.project)
    restored_state = get_route_move_ui_state(
        st.session_state.project,
        route_handle=separator_id,
        focused_line_id=previous_focus,
        highlighted_line_id=previous_highlight,
        expanded_line_id=previous_expanded,
    )
    st.session_state.gallery_selected_route_separator_id = restored_state[
        "gallery_selected_route_separator_id"
    ]
    st.session_state.focused_line_id = restored_state["focused_line_id"]
    st.session_state.highlighted_line_id = restored_state["highlighted_line_id"]
    st.session_state.gallery_expanded_line_id = restored_state["gallery_expanded_line_id"]
    restore_focus_after_graph_update(restored_state["focused_line_id"])
    save_current_project_if_possible(f"route block moved {direction_key}")
    st.session_state.gallery_feedback = f"Moved Scene '{route_label}' {direction_key}."
    st.session_state.gallery_feedback_kind = "success"
    return result


def _remove_gallery_route_block_from_ui(project, separator_line, confirmation_key: str) -> dict:
    separator_id = str(getattr(separator_line, "id", "") or "")
    previous_focus = st.session_state.get("focused_line_id")
    previous_highlight = st.session_state.get("highlighted_line_id")
    previous_expanded = st.session_state.get("gallery_expanded_line_id")
    previous_selected_route = st.session_state.get("gallery_selected_route_separator_id")
    history_length = len(st.session_state.get("history", []))
    push_history()
    result = remove_route_block(project, separator_id)
    if not result.get("removed"):
        history = st.session_state.get("history", [])
        del history[history_length:]
        return result

    route_label = route_separator_label(separator_line)
    reset_gallery_route_move_preview_state()
    st.session_state.project = build_graph(project)
    _set_gallery_selected_route_ids_after_structure_change(
        st.session_state.project,
        removed_route_handles=(separator_id,),
    )
    restored_state = get_route_remove_ui_state(
        st.session_state.project,
        route_handle=separator_id,
        focused_line_id=previous_focus,
        highlighted_line_id=previous_highlight,
        expanded_line_id=previous_expanded,
        selected_route_separator_id=previous_selected_route,
    )
    st.session_state.gallery_selected_route_separator_id = restored_state[
        "gallery_selected_route_separator_id"
    ]
    st.session_state.focused_line_id = restored_state["focused_line_id"]
    st.session_state.highlighted_line_id = restored_state["highlighted_line_id"]
    st.session_state.gallery_expanded_line_id = restored_state["gallery_expanded_line_id"]
    st.session_state.selected_node_ids = [
        nid for nid in st.session_state.selected_node_ids
        if nid in st.session_state.project.nodes
    ]
    affected_line_ids = set(result.get("affected_line_ids", []))
    st.session_state.gallery_move_targets = {
        line_id: selected
        for line_id, selected in st.session_state.get("gallery_move_targets", {}).items()
        if line_id not in affected_line_ids
    }
    # Operation panels render before separator cards, so reset their widget
    # keys on the next run instead of mutating them after instantiation.
    st.session_state.gallery_route_remove_pending_reset = {
        "route_handle": separator_id,
        "confirmation_key": confirmation_key,
    }
    restore_focus_after_graph_update(restored_state["focused_line_id"])
    save_current_project_if_possible(f"route removed: {route_label}")
    st.session_state.gallery_feedback = f"Moved Scene '{route_label}' to Trash."
    st.session_state.gallery_feedback_kind = "success"
    return result


def _duplicate_gallery_route_from_ui(project, separator_line, label_key: str, confirmation_key: str) -> dict:
    """Duplicate a Route and defer operation-widget cleanup to the next run."""

    separator_id = str(getattr(separator_line, "id", "") or "")
    source_route_handle = separator_id
    requested_label = st.session_state.get(label_key, "")
    previous_focus = st.session_state.get("focused_line_id")
    previous_highlight = st.session_state.get("highlighted_line_id")
    previous_expanded = st.session_state.get("gallery_expanded_line_id")
    previous_collapsed_routes = st.session_state.get("gallery_collapsed_routes")
    history_length = len(st.session_state.get("history", []))
    push_history()
    result = duplicate_route_as_baseline(
        project,
        separator_id,
        label=requested_label,
    )
    if not result.get("duplicated"):
        history = st.session_state.get("history", [])
        del history[history_length:]
        return result

    new_route_handle = str(result.get("new_route_handle") or "")
    reset_gallery_route_move_preview_state()
    st.session_state.project = build_graph(project)
    _set_gallery_selected_route_ids_after_structure_change(st.session_state.project)
    restored_state = get_route_duplicate_ui_state(
        st.session_state.project,
        source_route_handle=source_route_handle,
        new_route_handle=new_route_handle,
        focused_line_id=previous_focus,
        highlighted_line_id=previous_highlight,
        expanded_line_id=previous_expanded,
        collapsed_routes=previous_collapsed_routes,
    )
    st.session_state.gallery_selected_route_separator_id = restored_state[
        "gallery_selected_route_separator_id"
    ]
    st.session_state.focused_line_id = restored_state["focused_line_id"]
    st.session_state.highlighted_line_id = restored_state["highlighted_line_id"]
    st.session_state.gallery_expanded_line_id = restored_state["gallery_expanded_line_id"]
    st.session_state.gallery_collapsed_routes = restored_state["gallery_collapsed_routes"]
    st.session_state.gallery_route_duplicate_pending_reset = {
        "source_route_handle": source_route_handle,
        "new_route_handle": new_route_handle,
        "label_key": label_key,
        "confirmation_key": confirmation_key,
    }
    restore_focus_after_graph_update(restored_state["focused_line_id"])
    save_current_project_if_possible(f"Route duplicated as baseline: {requested_label.strip()}")
    st.session_state.gallery_feedback = (
        f"Duplicated Scene '{route_separator_label(separator_line)}' as '{requested_label.strip()}'."
    )
    st.session_state.gallery_feedback_kind = "success"
    return result


def _render_gallery_route_action_shortcuts(project, separator_line) -> None:
    route_block = resolve_route_block(project, getattr(separator_line, "id", ""))
    if not route_block.is_valid:
        st.caption("Scene Actions are unavailable for this separator.")
        return

    with st.expander(f"Scene Actions · {route_block.route_handle}", expanded=False):
        st.caption(
            "Open the existing operation panel with this Scene preselected. "
            "No generation, adoption, export, Derived Project creation, or prompt mutation starts here."
        )
        action_specs = (
            ("generation", "Scene Generation"),
            ("candidate_adoption", "Scene Candidate Adoption"),
            ("final_export", "Scene Final Images Export"),
            ("lightweight_fork", "派生Project"),
        )
        action_cols = st.columns(2)
        for index, (action, label) in enumerate(action_specs):
            with action_cols[index % 2]:
                if st.button(
                    label,
                    key=f"pro_gallery_route_action_{action}_{separator_line.id}",
                    width="stretch",
                ):
                    dispatch = _dispatch_gallery_route_action(project, separator_line, action)
                    if dispatch.get("dispatch"):
                        st.rerun()
                    st.warning(
                        format_core_message_for_display(dispatch.get("reason"))
                        or "Scene Action could not be opened."
                    )

        st.divider()
        st.caption(
            f"Scene Remove preview: {route_block.separator_label} / "
            f"{route_block.total_block_line_count} illustrations / "
            f"{route_block.candidate_count} Candidates / "
            f"{route_block.gallery_variant_count} Gallery Variants / "
            f"{route_block.workbench_count} Workbench / "
            f"{route_block.deleted_member_count} already deleted."
        )
        confirmation_key = f"pro_gallery_route_remove_confirm_{separator_line.id}"
        confirmed = st.checkbox(
            "I understand this moves the entire Scene block to Trash without deleting files.",
            key=confirmation_key,
        )
        if st.button(
            "Scene Remove",
            key=f"pro_gallery_route_remove_{separator_line.id}",
            disabled=not confirmed,
            width="stretch",
        ):
            result = _remove_gallery_route_block_from_ui(project, separator_line, confirmation_key)
            if result.get("removed"):
                st.rerun()
            st.warning(
                format_core_message_for_display(result.get("reason"))
                or "Scene Remove could not be completed."
            )

        st.divider()
        st.caption(
            f"Duplicate Scene as Baseline preview: {route_block.separator_label} / "
            f"{route_block.total_block_line_count} illustrations / "
            f"Workbench: {route_block.workbench_count} / "
            f"deleted: {route_block.deleted_member_count} / "
            f"Candidates: {route_block.candidate_count} / "
            f"Gallery Variants: {route_block.gallery_variant_count}."
        )
        st.caption(
            "The source Scene stays unchanged. Candidates and Gallery Variants are not copied; "
            "image files are not copied, moved, or deleted."
        )
        duplicate_label_key = f"pro_gallery_duplicate_route_label_{separator_line.id}"
        if duplicate_label_key not in st.session_state:
            st.session_state[duplicate_label_key] = f"{route_block.separator_label} Baseline"
        duplicate_label = st.text_input(
            "New Scene label",
            key=duplicate_label_key,
        )
        duplicate_confirmation_key = f"pro_gallery_duplicate_route_confirm_{separator_line.id}"
        duplicate_confirmed = st.checkbox(
            "I understand this creates a new baseline Scene without copying asset files.",
            key=duplicate_confirmation_key,
        )
        if st.button(
            "Duplicate Scene as Baseline",
            key=f"pro_gallery_duplicate_route_{separator_line.id}",
            disabled=not duplicate_confirmed or not str(duplicate_label or "").strip(),
            width="stretch",
        ):
            result = _duplicate_gallery_route_from_ui(
                project,
                separator_line,
                duplicate_label_key,
                duplicate_confirmation_key,
            )
            if result.get("duplicated"):
                st.rerun()
            st.warning(
                format_core_message_for_display(result.get("reason"))
                or "Duplicate Scene as Baseline could not be completed."
            )


def render_gallery_route_separator_header(project, line, line_index: int, active_lines: list, collapsed_hidden_count: int) -> None:
    label = route_separator_label(line)
    color = route_separator_color(line)
    color_badge = route_color_badge(color)
    is_collapsed = _gallery_route_is_collapsed(line.id)
    line_count = _gallery_route_line_count(active_lines, line.id)
    route_move_state = get_route_block_move_availability(project, line.id)

    with st.container(border=True):
        header_cols = st.columns([0.45, 0.75, 0.45, 4.2, 1.2, 0.5, 0.5, 0.8, 0.8])
        with header_cols[0]:
            collapse_label = "▶" if is_collapsed else "▼"
            if st.button(collapse_label, key=f"pro_gallery_toggle_route_collapse_{line.id}", help="シーンを折りたたみ/展開"):
                st.session_state.gallery_collapsed_routes[line.id] = not is_collapsed
                st.rerun()
        with header_cols[1]:
            widget_key = _initialize_gallery_selected_route_widget(line.id)
            st.checkbox(
                "選択",
                key=widget_key,
                on_change=_on_gallery_route_selection_changed,
                args=(line.id,),
                help="Selected Scenesのsession-only集合に追加/解除",
            )
        with header_cols[2]:
            st.markdown(color_badge)
        with header_cols[3]:
            st.markdown(f"**{label}**")
        with header_cols[4]:
            hidden_suffix = f" / 折りたたみ {collapsed_hidden_count}" if collapsed_hidden_count else ""
            st.caption(f"{line_count} illustrations{hidden_suffix}")
        with header_cols[5]:
            if st.button(
                "↑",
                key=f"pro_gallery_move_up_{line.id}",
                disabled=not route_move_state.get("can_move_up", False),
                help="Move the entire Scene block up.",
            ):
                result = _move_gallery_route_block_from_ui(project, line, "up")
                if result.get("moved"):
                    st.rerun()
        with header_cols[6]:
            if st.button(
                "↓",
                key=f"pro_gallery_move_down_{line.id}",
                disabled=not route_move_state.get("can_move_down", False),
                help="Move the entire Scene block down.",
            ):
                result = _move_gallery_route_block_from_ui(project, line, "down")
                if result.get("moved"):
                    st.rerun()
        with header_cols[7]:
            editing_key = "gallery_route_separator_editing_id"
            is_editing = st.session_state.get(editing_key) == line.id
            if st.button("編集", key=f"pro_gallery_edit_route_separator_{line.id}", help="シーン名と色を編集"):
                st.session_state[editing_key] = "" if is_editing else line.id
                st.rerun()
        with header_cols[8]:
            st.caption("Scene Remove in Actions")

        notice = st.session_state.get("gallery_route_action_notice") or {}
        if notice.get("route_handle") == getattr(line, "id", ""):
            st.info(
                f"Scene Actions selected: {notice.get('operation', '')} / "
                f"Selected Scene: {route_separator_label(line)}"
            )
            st.session_state.pop("gallery_route_action_notice", None)
        _render_gallery_route_action_shortcuts(project, line)

        if st.session_state.get("gallery_route_separator_editing_id") == line.id:
            label_key = f"pro_separator_label_edit_{line.id}"
            edit_cols = st.columns([3, 2, 1])
            with edit_cols[0]:
                st.text_input("区切り名", value=route_separator_label(line), key=label_key)
            with edit_cols[1]:
                color_key = f"pro_separator_color_edit_{line.id}"
                selected_color = st.selectbox(
                    "色",
                    options=list(ROUTE_COLOR_OPTIONS.keys()),
                    index=list(ROUTE_COLOR_OPTIONS.keys()).index(route_separator_color(line)),
                    format_func=route_color_name,
                    key=color_key,
                )
                if selected_color != route_separator_color(line):
                    update_route_separator_color(line, selected_color)
                    st.rerun()
            with edit_cols[2]:
                st.write("")
                if st.button("保存", key=f"pro_separator_save_label_{line.id}"):
                    if update_route_separator_label(line, st.session_state.get(label_key, "")):
                        st.session_state.gallery_route_separator_editing_id = ""
                        st.rerun()


def render_gallery_workbench_card(project, line, line_index: int, active_lines: list, move_targets: dict, move_target_ids: list[str], expanded_line_id: str | None) -> None:
    inherited_color = current_route_color_for_line(active_lines, line.id)
    if inherited_color:
        st.caption(route_color_name(inherited_color))
    st.caption("作業場")
    st.markdown(f"**{workbench_title(line)}**")
    st.caption(_workbench_source_label(project, line))
    thumbnail_path = _workbench_thumbnail_path(project, line)
    if thumbnail_path:
        st.image(thumbnail_path, width="stretch")
    else:
        st.info("作業場画像なし")
    candidate_count = _line_generated_candidate_count(line)
    if candidate_count:
        st.caption(f"候補: {candidate_count}")
    else:
        st.caption("候補なし")
    trashed_candidate_count = len(_line_trashed_generated_candidates(line))
    if trashed_candidate_count:
        st.caption(f"Trash: {trashed_candidate_count}")
    title_key = f"gallery_workbench_title_{line.id}"
    if title_key not in st.session_state:
        st.session_state[title_key] = workbench_title(line)
    st.text_input("タイトル", key=title_key)
    note_key = f"gallery_workbench_note_{line.id}"
    if note_key not in st.session_state:
        st.session_state[note_key] = getattr(line, "workbench_note", "") or ""
    st.text_area("メモ", key=note_key, height=70)

    if st.button("作業場を保存", key=f"gallery_workbench_save_note_{line.id}", width="stretch"):
        push_history()
        new_title = (st.session_state.get(title_key, "") or "").strip() or workbench_title(line)
        line.workbench_title = new_title
        line.original_file_name = new_title
        line.workbench_note = st.session_state.get(note_key, "")
        line.edited = True
        save_current_project_if_possible("gallery workbench note updated")
        st.session_state.gallery_feedback = "作業場を保存しました。"
        st.session_state.gallery_feedback_kind = "success"
        st.rerun()

    is_selected = bool(move_targets.get(line.id, False))
    if is_selected:
        st.info("選択中")
    if st.button("解除" if is_selected else "選択", key=f"pro_gallery_select_toggle_{line.id}"):
        if is_selected:
            st.session_state.gallery_move_targets.pop(line.id, None)
        else:
            st.session_state.gallery_move_targets[line.id] = True
        st.rerun()

    move_cols = st.columns(2)
    with move_cols[0]:
        if st.button("↑", key=f"pro_gallery_move_up_{line.id}", disabled=line_index == 0, help="前に移動"):
            push_history()
            if move_prompt_line(project, line.id, "up"):
                st.session_state.project = build_graph(project)
                save_current_project_if_possible("gallery workbench moved")
                st.rerun()
    with move_cols[1]:
        if st.button("↓", key=f"pro_gallery_move_down_{line.id}", disabled=line_index == len(active_lines) - 1, help="後に移動"):
            push_history()
            if move_prompt_line(project, line.id, "down"):
                st.session_state.project = build_graph(project)
                save_current_project_if_possible("gallery workbench moved")
                st.rerun()

    action_cols = st.columns(2)
    with action_cols[0]:
        if st.button("編集", key=f"pro_gallery_edit_{line.id}"):
            st.session_state.highlighted_line_id = line.id
            st.session_state.gallery_expanded_line_id = None if expanded_line_id == line.id else line.id
            st.rerun()
    with action_cols[1]:
        if st.button("一件削除", key=f"pro_gallery_delete_line_{line.id}"):
            delete_lines([line.id])
            st.rerun()

    if st.button(
        "選択イラストをここへ",
        key=f"pro_gallery_insert_after_{line.id}",
        disabled=not move_target_ids,
        help="選択中のイラストをこの作業場の後へ移動",
        width="stretch",
    ):
        if move_gallery_selected_lines_after(project, move_target_ids, line.id):
            st.rerun()


def render_gallery_normal_line_card(project, line, line_index: int, active_lines: list, move_targets: dict, move_target_ids: list[str], expanded_line_id: str | None) -> None:
    if is_workbench_line(line):
        render_gallery_workbench_card(project, line, line_index, active_lines, move_targets, move_target_ids, expanded_line_id)
        return

    inherited_color = current_route_color_for_line(active_lines, line.id)
    if inherited_color:
        st.caption(route_color_name(inherited_color))
    thumbnail_path = _line_thumbnail_path(line)
    if thumbnail_path:
        st.image(thumbnail_path, width="stretch")
    else:
        st.info("画像なし")
    st.caption(f"{line.current_index + 1:04d} / {line.original_file_name}")
    st.caption(_prompt_original_status_label(line))
    candidate_count = _line_generated_candidate_count(line)
    if candidate_count:
        st.caption(f"候補: {candidate_count}")
    trashed_candidate_count = len(_line_trashed_generated_candidates(line))
    if trashed_candidate_count:
        st.caption(f"Trash: {trashed_candidate_count}")
    render_gallery_variant_card_controls(line, key_prefix=f"main_gallery_variant_{line.id}")

    is_selected = bool(move_targets.get(line.id, False))
    if is_selected:
        st.info("選択中")
    if st.button("解除" if is_selected else "選択", key=f"pro_gallery_select_toggle_{line.id}"):
        if is_selected:
            st.session_state.gallery_move_targets.pop(line.id, None)
        else:
            st.session_state.gallery_move_targets[line.id] = True
        st.rerun()
    move_cols = st.columns(2)
    with move_cols[0]:
        if st.button("↑", key=f"pro_gallery_move_up_{line.id}", disabled=line_index == 0, help="前に移動"):
            push_history()
            if move_prompt_line(project, line.id, "up"):
                st.session_state.project = build_graph(project)
                save_current_project_if_possible("gallery line moved")
                st.rerun()
    with move_cols[1]:
        if st.button("↓", key=f"pro_gallery_move_down_{line.id}", disabled=line_index == len(active_lines) - 1, help="後に移動"):
            push_history()
            if move_prompt_line(project, line.id, "down"):
                st.session_state.project = build_graph(project)
                save_current_project_if_possible("gallery line moved")
                st.rerun()

    action_cols = st.columns(2)
    with action_cols[0]:
        if st.button("編集", key=f"pro_gallery_edit_{line.id}"):
            st.session_state.gallery_expanded_line_id = None if expanded_line_id == line.id else line.id
            st.rerun()
    with action_cols[1]:
        if st.button("分岐", key=f"pro_gallery_create_route_branch_{line.id}"):
            result = create_route_separator_after_line(project, line.id)
            st.session_state.gallery_feedback = (
                f"分岐を追加したよ: {result['label']}"
                if result.get("created")
                else result.get("message", "分岐を追加できませんでした。")
            )
            st.session_state.gallery_feedback_kind = "success" if result.get("created") else "warning"
            st.rerun()
    if st.button("作業場を作る", key=f"pro_gallery_create_workbench_{line.id}", width="stretch"):
        result = create_workbench_after_line(project, line.id)
        st.session_state.gallery_feedback = result.get("message", "Workbenchを作成できませんでした。")
        st.session_state.gallery_feedback_kind = "success" if result.get("created") else "warning"
        st.rerun()
    if st.button(
        "選択イラストをここへ",
        key=f"pro_gallery_insert_after_{line.id}",
        disabled=not move_target_ids,
        help="選択中のイラストをこのカードの後へ移動",
        width="stretch",
    ):
        if move_gallery_selected_lines_after(project, move_target_ids, line.id):
            st.rerun()
    delete_cols = st.columns(2)
    with delete_cols[0]:
        if st.button("一件削除", key=f"pro_gallery_delete_line_{line.id}"):
            delete_lines([line.id])
            st.rerun()
    with delete_cols[1]:
        if st.button("選択を削除", key=f"pro_gallery_delete_selected_{line.id}", disabled=not move_target_ids):
            deleted_count = delete_lines(move_target_ids)
            st.session_state.gallery_move_targets = {}
            if deleted_count:
                st.session_state.gallery_feedback = f"{deleted_count}件を削除しました。"
            st.rerun()


def _active_route_separator_ids(active_lines: list) -> list[str]:
    return [
        getattr(line, "id", "")
        for line in active_lines
        if getattr(line, "id", "") and is_route_separator(line) and not getattr(line, "deleted", False)
    ]


def _render_gallery_select_all_routes_button(project, selectable_count: int, selected_count: int) -> None:
    if st.button(
        "すべてのシーンを選択",
        key="gallery_selected_routes_select_all",
        disabled=not selectable_count or selected_count == selectable_count,
        width="stretch",
    ):
        st.session_state.gallery_selected_route_ids = select_all_routes(project)
        st.rerun()


def _bounded_gallery_selected_scene_summary(selection_state: dict, limit: int = 3) -> str:
    selected_summaries = list(selection_state.get("selected_route_summaries") or [])
    selectable_summaries = list(selection_state.get("selectable_route_summaries") or [])
    label_counts = Counter(
        str(summary.get("label") or "Scene")
        for summary in selectable_summaries
    )
    labels = []
    for summary in selected_summaries[:limit]:
        label = str(summary.get("label") or "Scene")
        if label_counts[label] > 1:
            label = f"{label} ({summary.get('route_handle') or 'unknown'})"
        labels.append(label)
    remaining_count = max(0, len(selected_summaries) - limit)
    suffix = f" +{remaining_count}" if remaining_count else ""
    return ", ".join(labels) + suffix


def _render_gallery_operation_scope_matrix() -> None:
    rows = []
    for entry in iter_gallery_operation_scope_presentations():
        rows.append(
            {
                "Operation": entry["title"],
                "Supported targets / 対応対象": " · ".join(entry["supported_scope_labels"]),
                "Shared Selected Scenes": (
                    "Supported / 対応" if entry["uses_shared_selected_scenes"] else "Not used / 使用しない"
                ),
                "Note": entry["note"],
            }
        )
    st.dataframe(rows, hide_index=True, width="stretch")


def render_gallery_selected_routes_controls(project, selection_state: dict | None = None) -> None:
    state = selection_state or _sanitize_gallery_selected_route_session_state(project)
    selected_count = state["selected_route_count"]
    selectable_count = len(state["selectable_route_ids"])
    with st.container(border=True):
        st.markdown("**Operation Scope / 操作対象**")
        st.caption(f"Selected Scenes: {selected_count} / {selectable_count}")
        if selected_count:
            st.caption(f"Selected: {_bounded_gallery_selected_scene_summary(state)}")
            st.caption(
                f"Main Illustrations: {state['selected_main_line_count']} / "
                f"Candidates: {state['selected_candidate_count']} / "
                f"Gallery Variants: {state['selected_gallery_variant_count']}"
            )

        control_cols = st.columns(3)
        with control_cols[0]:
            _render_gallery_select_all_routes_button(project, selectable_count, selected_count)
        with control_cols[1]:
            if st.button(
                "選択を反転",
                key="gallery_selected_routes_invert",
                disabled=not selectable_count,
                width="stretch",
            ):
                st.session_state.gallery_selected_route_ids = invert_selected_routes(
                    project,
                    state["selected_route_ids"],
                )
                st.rerun()
        with control_cols[2]:
            if st.button(
                "選択をクリア",
                key="gallery_selected_routes_clear",
                disabled=not selected_count,
                width="stretch",
            ):
                st.session_state.gallery_selected_route_ids = clear_selected_routes(project)
                st.rerun()

        st.caption(
            "Scene-based scopes include only Illustrations owned by those Scene separators. "
            "Illustrations outside Scenes are not included."
        )
        st.caption(
            "All Illustrations / 全イラスト and Selected Scenes / 操作対象シーン are therefore different targets."
        )
        st.caption(
            "The shared Selected Scenes selection is used only when an operation’s own Target / Scope "
            "is set to Selected Scenes / 操作対象シーン."
        )
        with st.expander("Scope support by operation / 操作別の対応対象", expanded=False):
            _render_gallery_operation_scope_matrix()


def render_gallery_route_bulk_collapse_controls(active_lines: list) -> None:
    route_separator_ids = _active_route_separator_ids(active_lines)
    collapsed_routes = _gallery_collapsed_routes_state()
    collapsed_route_ids = {route_id for route_id in route_separator_ids if _gallery_route_is_collapsed(route_id)}
    all_collapsed = bool(route_separator_ids) and len(collapsed_route_ids) == len(route_separator_ids)
    all_expanded = bool(route_separator_ids) and not collapsed_route_ids

    control_cols = st.columns([1, 1, 3])
    with control_cols[0]:
        if st.button(
            "すべてのシーンを閉じる",
            key="gallery_collapse_all_routes",
            disabled=not route_separator_ids or all_collapsed,
            width="stretch",
        ):
            route_separator_id_set = set(route_separator_ids)
            preserved_routes = {
                route_id: bool(collapsed)
                for route_id, collapsed in collapsed_routes.items()
                if route_id not in route_separator_id_set
            }
            preserved_routes.update({route_id: True for route_id in route_separator_ids})
            st.session_state.gallery_collapsed_routes = preserved_routes
            st.session_state.gallery_feedback = "すべてのシーンを閉じました。"
            st.session_state.gallery_feedback_kind = "success"
            st.rerun()
    with control_cols[1]:
        if st.button(
            "すべてのシーンを開く",
            key="gallery_expand_all_routes",
            disabled=not route_separator_ids or all_expanded,
            width="stretch",
        ):
            route_separator_id_set = set(route_separator_ids)
            preserved_routes = {
                route_id: bool(collapsed)
                for route_id, collapsed in collapsed_routes.items()
                if route_id not in route_separator_id_set
            }
            preserved_routes.update({route_id: False for route_id in route_separator_ids})
            st.session_state.gallery_collapsed_routes = preserved_routes
            st.session_state.gallery_feedback = "すべてのシーンを開きました。"
            st.session_state.gallery_feedback_kind = "success"
            st.rerun()
    with control_cols[2]:
        if route_separator_ids:
            st.caption(f"Scene: {len(route_separator_ids)}件 / 閉じているScene: {len(collapsed_route_ids)}件")
        else:
            st.caption("Scene Separatorはまだありません。")


def render_pro_gallery_mode(project):
    _apply_pending_gallery_selected_route_widget_reset()
    selected_route_state = _sanitize_gallery_selected_route_session_state(project)
    _apply_pending_gallery_route_remove_reset(project)
    _apply_pending_gallery_route_duplicate_reset(project)
    apply_pending_lightweight_fork_single_route_widget_reset(st.session_state)
    _apply_pending_gallery_route_action(project)
    active_lines = get_visible_prompt_lines(project)
    active_line_ids = [line.id for line in active_lines]
    move_targets = st.session_state.get("gallery_move_targets", {})
    if not isinstance(move_targets, dict):
        move_targets = {}
    active_ids = {line.id for line in active_lines}
    move_targets = {line_id: bool(value) for line_id, value in move_targets.items() if line_id in active_ids}
    st.session_state.gallery_move_targets = move_targets

    st.subheader("ギャラリー編集モード")
    st.caption("画像を見ながら並び替え・生成ソース編集・候補管理・シーン整理を行います。シーンはseparatorカードで折りたためます。")
    if st.session_state.get("gallery_feedback"):
        feedback_kind = st.session_state.get("gallery_feedback_kind", "success")
        if feedback_kind == "warning":
            st.warning(st.session_state.gallery_feedback)
        else:
            st.success(st.session_state.gallery_feedback)
        st.session_state.gallery_feedback = ""
        st.session_state.gallery_feedback_kind = "success"

    st.divider()
    st.markdown("### Illustration Import / Source")
    render_gallery_prompt_line_creator(project, expanded=not active_lines)
    render_gallery_import_export_section(project)
    if not active_lines:
        st.divider()
        st.markdown("### Gallery")
        st.info("まだイラストがありません。生成ソース（プロンプト）を入力するか、「読み込み・書き出し」から読み込んでください。")
        return

    pending_route_separator_id = st.session_state.pop("gallery_selected_route_separator_id_pending", None)
    if pending_route_separator_id:
        st.session_state.gallery_selected_route_separator_id = pending_route_separator_id

    display_lines, collapsed_hidden_counts = route_collapsed_display_lines(active_lines)
    display_ids = {line.id for line in display_lines}
    move_target_ids = [line.id for line in display_lines if move_targets.get(line.id)]

    st.divider()
    st.markdown("### Gallery Operations")
    render_gallery_selected_routes_controls(project, selected_route_state)
    render_gallery_operations_launcher(project)

    st.divider()
    st.markdown("### Gallery")
    st.caption(f"Items: {len(active_lines)} / Visible: {len(display_lines)}")
    render_gallery_route_bulk_collapse_controls(active_lines)
    # 「選択: N件 | 全解除」をページレベルのヘッダーに統合
    header_sel_cols = st.columns([3, 1])
    with header_sel_cols[0]:
        st.write(f"選択: {len(move_target_ids)}件")
    with header_sel_cols[1]:
        if move_target_ids:
            if st.button("全解除", key="pro_gallery_clear_move_targets_header"):
                st.session_state.gallery_move_targets = {}
                st.rerun()
    visible_page_lines, _gallery_page, _gallery_total_pages = render_gallery_pagination_controls(display_lines)
    if st.session_state.get("gallery_expanded_line_id") not in display_ids:
        st.session_state.gallery_expanded_line_id = None
    expanded_line_id = st.session_state.get("gallery_expanded_line_id")

    gallery_card_loop_start = time.perf_counter() if _ui_profiling_enabled() else None
    normal_row = []

    def render_normal_gallery_row(row_lines):
        cols = st.columns(4)
        for offset, line in enumerate(row_lines):
            line_index = active_line_ids.index(line.id)
            with cols[offset]:
                with st.container(border=True):
                    render_gallery_normal_line_card(
                        project,
                        line,
                        line_index,
                        active_lines,
                        move_targets,
                        move_target_ids,
                        expanded_line_id,
                    )

        row_expanded = next((line for line in row_lines if line.id == st.session_state.get("gallery_expanded_line_id")), None)
        if row_expanded and not is_route_separator(row_expanded):
            with st.container(border=True):
                render_gallery_line_editor(row_expanded, project)

    for line in visible_page_lines:
        if is_route_separator(line):
            if normal_row:
                render_normal_gallery_row(normal_row)
                normal_row = []
            line_index = active_line_ids.index(line.id)
            render_gallery_route_separator_header(
                project,
                line,
                line_index,
                active_lines,
                collapsed_hidden_counts.get(line.id, 0),
            )
        else:
            normal_row.append(line)
            if len(normal_row) == 4:
                render_normal_gallery_row(normal_row)
                normal_row = []
    if normal_row:
        render_normal_gallery_row(normal_row)
    if gallery_card_loop_start is not None:
        record_profile_timing("Gallery visible card loop", time.perf_counter() - gallery_card_loop_start)
    render_gallery_pagination_footer(display_lines)

def _restore_gallery_route_from_trash(project, record: dict) -> dict:
    route_handle = str(record.get("route_handle") or record.get("separator_line_id") or "").strip()
    previous_focus = st.session_state.get("focused_line_id")
    previous_highlight = st.session_state.get("highlighted_line_id")
    previous_expanded = st.session_state.get("gallery_expanded_line_id")
    history_length = len(st.session_state.get("history", []))
    push_history()
    result = restore_removed_route(project, str(record.get("id") or route_handle))
    if not result.get("restored"):
        history = st.session_state.get("history", [])
        del history[history_length:]
        return result

    reset_gallery_route_action_session_state()
    reset_gallery_route_move_preview_state()
    st.session_state.pop(
        f"pro_trash_restore_route_confirm_{record.get('id') or route_handle}",
        None,
    )
    st.session_state.project = build_graph(project)
    _set_gallery_selected_route_ids_after_structure_change(st.session_state.project)
    restored_state = get_route_move_ui_state(
        st.session_state.project,
        route_handle=route_handle,
        focused_line_id=previous_focus,
        highlighted_line_id=previous_highlight,
        expanded_line_id=previous_expanded,
    )
    st.session_state.gallery_selected_route_separator_id = restored_state[
        "gallery_selected_route_separator_id"
    ]
    st.session_state.focused_line_id = restored_state["focused_line_id"]
    st.session_state.highlighted_line_id = restored_state["highlighted_line_id"]
    st.session_state.gallery_expanded_line_id = restored_state["gallery_expanded_line_id"]
    affected_line_ids = set(record.get("line_ids") or [])
    st.session_state.gallery_move_targets = {
        line_id: selected
        for line_id, selected in st.session_state.get("gallery_move_targets", {}).items()
        if line_id not in affected_line_ids
    }
    restore_focus_after_graph_update(restored_state["focused_line_id"])
    save_current_project_if_possible("route restored")
    st.session_state.gallery_feedback = f"Restored Scene '{route_handle}'."
    st.session_state.gallery_feedback_kind = "success"
    return result


def render_pro_trash_view_mode(project):
    route_removal_diagnostics = get_route_removal_diagnostics(project)
    for diagnostic in route_removal_diagnostics:
        st.warning(format_core_message_for_display(diagnostic))
    active_route_removals = get_active_route_removal_records(project)
    if active_route_removals:
        st.subheader("Scene Removals")
        st.caption("Restore a Scene block atomically. Illustrations deleted before the Scene removal remain deleted.")
        for record in active_route_removals:
            route_handle = str(record.get("route_handle") or record.get("separator_line_id") or "").strip()
            separator = next(
                (line for line in project.prompt_lines if getattr(line, "id", "") == route_handle),
                None,
            )
            route_label = (
                route_separator_label(separator)
                if separator
                else str(record.get("route_label") or route_handle)
            )
            line_ids = record.get("line_ids") or []
            project_line_ids = {
                str(getattr(line, "id", "") or "")
                for line in project.prompt_lines
                if getattr(line, "id", "")
            }
            missing_line_ids = [line_id for line_id in line_ids if line_id not in project_line_ids]
            already_deleted_ids = record.get("already_deleted_line_ids") or [
                line_id
                for line_id in line_ids
                if (record.get("pre_remove_deleted") or {}).get(line_id)
            ]
            confirmation_key = f"pro_trash_restore_route_confirm_{record.get('id') or route_handle}"
            with st.container(border=True):
                st.markdown(f"### Scene: {route_label}")
                st.caption(
                    f"Handle: {route_handle} / "
                    f"{record.get('removed_line_count') or len(line_ids)} lines / "
                    f"Workbench: {record.get('workbench_line_count') or 0} / "
                    f"active before remove: {record.get('active_line_count_before_remove') or 0} / "
                    f"already deleted: {len(already_deleted_ids)} / "
                    f"removed at: {record.get('removed_at') or record.get('created_at') or 'unknown'}"
                )
                if missing_line_ids:
                    st.warning("Missing Scene illustration ids: " + ", ".join(missing_line_ids))
                for diagnostic in record.get("diagnostics") or []:
                    st.warning(format_core_message_for_display(diagnostic))
                confirmed = st.checkbox(
                    "Confirm Atomic Restore for this Scene.",
                    key=confirmation_key,
                )
                if st.button(
                    "Restore Scene",
                    key=f"pro_trash_restore_route_{record.get('id') or route_handle}",
                    disabled=not confirmed,
                    width="stretch",
                ):
                    result = _restore_gallery_route_from_trash(project, record)
                    if result.get("restored"):
                        st.rerun()
                    st.warning(
                        format_core_message_for_display(result.get("reason"))
                        or "Scene restore could not be completed."
                    )

    deleted_lines = [line for line in project.prompt_lines if getattr(line, "deleted", False)]
    st.subheader("ゴミ箱")
    st.write(f"削除済み: {len(deleted_lines)}件")
    if st.button("ギャラリー編集モードへ戻る", key="pro_trash_return_top"):
        st.session_state.trash_view_mode_enabled = False
        st.session_state.gallery_main_mode_enabled = True
        st.rerun()
    if not deleted_lines:
        st.info("削除済みイラストはありません。")
        return
    for row_start in range(0, len(deleted_lines), 4):
        cols = st.columns(4)
        for offset, line in enumerate(deleted_lines[row_start: row_start + 4]):
            with cols[offset]:
                with st.container(border=True):
                    if is_route_separator(line):
                        st.markdown(f"### {route_color_badge(route_separator_color(line))} ━ {route_separator_label(line)} ━")
                    else:
                        thumbnail_path = _line_thumbnail_path(line)
                        if thumbnail_path:
                            st.image(thumbnail_path, width="stretch")
                        else:
                            st.info("画像なし")
                        st.caption(f"{line.current_index + 1:04d} / {line.original_file_name}")
                    if st.button("復帰", key=f"pro_trash_restore_{line.id}"):
                        if restore_gallery_line(line.id):
                            st.rerun()

def _make_route_snapshot(project, name=None):
    created_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
    display_time = datetime.now().strftime("%Y-%m-%d %H:%M")
    snapshot_name = name or f"Sequence {display_time}"
    return {
        "id": f"route_{uuid.uuid4().hex[:8]}",
        "name": snapshot_name,
        "created_at": created_at,
        "items": [
            {
                "line_id": getattr(line, "id", ""),
                "line_index": getattr(line, "current_index", None),
                "selected_candidate_path": getattr(line, "selected_candidate_path", None),
                "generated_image_path": getattr(line, "generated_image_path", None),
                "reference_image_path": getattr(line, "image_path", None),
                "prompt_text": getattr(line, "current_text", "") or "",
            }
            for line in get_visible_prompt_lines(project)
            if is_gallery_operation_prompt_line(line)
        ],
    }

def _append_route_snapshot(project, snapshot):
    snapshots = getattr(project, "route_snapshots", None)
    if not isinstance(snapshots, list):
        snapshots = []
    snapshots.append(snapshot)
    project.route_snapshots = snapshots


def _apply_route_snapshot(project, snapshot):
    line_by_id = {
        getattr(line, "id", ""): line
        for line in getattr(project, "prompt_lines", [])
        if not getattr(line, "deleted", False)
    }
    applied = 0
    skipped = 0
    for item in snapshot.get("items", []) if isinstance(snapshot, dict) else []:
        line = line_by_id.get(item.get("line_id") if isinstance(item, dict) else None)
        if not line:
            skipped += 1
            continue

        changed = False
        selected_candidate_path = item.get("selected_candidate_path")
        generated_image_path = item.get("generated_image_path")
        if selected_candidate_path:
            line.selected_candidate_path = selected_candidate_path
            changed = True
        if generated_image_path:
            line.generated_image_path = generated_image_path
            changed = True
        if changed:
            applied += 1
        else:
            skipped += 1
    return {"applied": applied, "skipped": skipped}


def _route_snapshot_label(index, snapshot):
    name = snapshot.get("name", "Untitled sequence") if isinstance(snapshot, dict) else "Untitled sequence"
    created_at = snapshot.get("created_at", "") if isinstance(snapshot, dict) else ""
    favorite_prefix = "★ " if isinstance(snapshot, dict) and snapshot.get("favorite") else ""
    return f"{index + 1}. {favorite_prefix}{name} {created_at}".strip()


def _ensure_route_snapshot_metadata(snapshot):
    if not isinstance(snapshot, dict):
        return {}
    metadata = {
        "favorite": bool(snapshot.get("favorite", False)),
        "notes": snapshot.get("notes") if isinstance(snapshot.get("notes"), str) else "",
        "tags": snapshot.get("tags") if isinstance(snapshot.get("tags"), str) else "",
    }
    score = snapshot.get("score")
    if score in ("", None):
        metadata["score"] = None
    elif isinstance(score, (int, float)):
        metadata["score"] = max(0.0, min(10.0, float(score)))
    else:
        try:
            metadata["score"] = max(0.0, min(10.0, float(score)))
        except (TypeError, ValueError):
            metadata["score"] = None
    return metadata


def _save_route_snapshot_metadata(snapshot, favorite, use_score, score, notes, tags):
    snapshot["favorite"] = bool(favorite)
    snapshot["score"] = float(score) if use_score else None
    snapshot["notes"] = notes or ""
    snapshot["tags"] = tags or ""


def _route_snapshot_image_path(item):
    if not isinstance(item, dict):
        return ""
    return item.get("selected_candidate_path") or item.get("generated_image_path") or ""


def _route_compare_line_label(item):
    line_index = item.get("line_index") if isinstance(item, dict) else None
    prompt_text = item.get("prompt_text", "") if isinstance(item, dict) else ""
    prompt_preview = _short_preview(prompt_text, 80) if prompt_text else "Untitled illustration"
    if not isinstance(line_index, int):
        return prompt_preview
    return f"Illustration {line_index + 1}: {prompt_preview}"


def _compare_route_snapshots(snapshot_a, snapshot_b):
    items_a = {
        item.get("line_id"): item
        for item in snapshot_a.get("items", []) if isinstance(item, dict) and item.get("line_id")
    } if isinstance(snapshot_a, dict) else {}
    items_b = {
        item.get("line_id"): item
        for item in snapshot_b.get("items", []) if isinstance(item, dict) and item.get("line_id")
    } if isinstance(snapshot_b, dict) else {}

    rows = []
    for line_id in items_a:
        if line_id not in items_b:
            continue
        item_a = items_a[line_id]
        item_b = items_b[line_id]
        path_a = _route_snapshot_image_path(item_a)
        path_b = _route_snapshot_image_path(item_b)
        if path_a == path_b:
            continue
        rows.append({
            "line_id": line_id,
            "label": _route_compare_line_label(item_a),
            "path_a": path_a,
            "path_b": path_b,
        })
    return rows


def _render_route_compare_image(label, image_path):
    st.caption(label)
    if not image_path:
        st.caption("No image")
        return
    display_path = _runtime_asset_path(image_path)
    if not os.path.exists(display_path):
        st.caption("Missing")
        return
    try:
        st.image(display_path, width=180)
    except Exception:
        st.caption("Could not show image.")


def _sorted_route_snapshot_items(snapshot):
    if not isinstance(snapshot, dict):
        return []
    indexed_items = [
        (index, item)
        for index, item in enumerate(snapshot.get("items", []) or [])
        if isinstance(item, dict)
    ]
    indexed_items.sort(
        key=lambda indexed_item: (
            not isinstance(indexed_item[1].get("line_index"), int),
            indexed_item[1].get("line_index") if isinstance(indexed_item[1].get("line_index"), int) else indexed_item[0],
            indexed_item[0],
        )
    )
    return [item for _index, item in indexed_items]


def _render_route_storyboard(snapshot):
    items = _sorted_route_snapshot_items(snapshot)
    if not items:
        st.caption("No sequence items.")
        return

    image_paths = [_route_snapshot_image_path(item) for item in items]
    if not any(image_paths):
        st.caption("No image selections in this sequence.")

    items_per_row = 5
    for row_start in range(0, len(items), items_per_row):
        row_items = items[row_start:row_start + items_per_row]
        cols = st.columns(len(row_items))
        for offset, item in enumerate(row_items):
            image_path = _route_snapshot_image_path(item)
            with cols[offset]:
                st.caption(_route_compare_line_label(item))
                if not image_path:
                    st.caption("No image")
                    continue
                display_path = _runtime_asset_path(image_path)
                if not os.path.exists(display_path):
                    st.caption("Missing")
                    continue
                try:
                    st.image(display_path, width="stretch")
                except Exception:
                    st.caption("Could not show image.")


def render_route_snapshot_section(project):
    if not project:
        return

    snapshots = getattr(project, "route_snapshots", None)
    if not isinstance(snapshots, list):
        snapshots = []
        project.route_snapshots = snapshots

    with st.expander("Sequence Snapshot", expanded=False):
        apply_summary = st.session_state.pop("route_snapshot_apply_summary", None)
        if apply_summary:
            st.success(
                f"Applied {apply_summary['applied']} illustration(s); "
                f"skipped {apply_summary['skipped']}."
            )
        st.caption(f"{len(snapshots)} snapshot(s) saved.")
        if snapshots:
            latest = snapshots[-1]
            latest_name = latest.get("name", "Untitled sequence")
            latest_created_at = latest.get("created_at", "")
            st.caption(f"Latest: {latest_name} {latest_created_at}")
            selected_snapshot_index = st.selectbox(
                "Saved Sequence Snapshot",
                options=list(range(len(snapshots))),
                format_func=lambda index: _route_snapshot_label(index, snapshots[index]),
                key="route_snapshot_apply_select",
            )
            selected_snapshot = snapshots[selected_snapshot_index]
            selected_metadata = _ensure_route_snapshot_metadata(selected_snapshot)
            metadata_key = selected_snapshot.get("id") or selected_snapshot_index
            st.markdown("##### Sequence Snapshot Metadata")
            favorite_col, score_col = st.columns(2)
            with favorite_col:
                favorite = st.checkbox(
                    "Favorite",
                    value=selected_metadata.get("favorite", False),
                    key=f"route_metadata_favorite_{metadata_key}",
                )
            with score_col:
                use_score = st.checkbox(
                    "Use score",
                    value=selected_metadata.get("score") is not None,
                    key=f"route_metadata_use_score_{metadata_key}",
                )
            score = st.number_input(
                "Score",
                min_value=0.0,
                max_value=10.0,
                value=float(selected_metadata.get("score") or 0.0),
                step=0.5,
                disabled=not use_score,
                key=f"route_metadata_score_{metadata_key}",
            )
            notes = st.text_area(
                "Notes",
                value=selected_metadata.get("notes", ""),
                height=80,
                key=f"route_metadata_notes_{metadata_key}",
            )
            tags = st.text_input(
                "Tags",
                value=selected_metadata.get("tags", ""),
                key=f"route_metadata_tags_{metadata_key}",
            )
            if st.button("Save Snapshot Metadata", key=f"route_metadata_save_{metadata_key}"):
                _save_route_snapshot_metadata(selected_snapshot, favorite, use_score, score, notes, tags)
                save_current_project_if_possible("route metadata saved")
                st.success("Sequence Snapshot metadata saved.")
                st.rerun()
            if st.button("Apply Selected Sequence Snapshot", key="apply_selected_route_snapshot"):
                push_history()
                summary = _apply_route_snapshot(project, snapshots[selected_snapshot_index])
                st.session_state.route_snapshot_apply_summary = summary
                save_current_project_if_possible("route snapshot applied")
                st.rerun()
            if len(snapshots) >= 2:
                compare_col_a, compare_col_b = st.columns(2)
                with compare_col_a:
                    compare_a_index = st.selectbox(
                        "Compare Snapshot A",
                        options=list(range(len(snapshots))),
                        format_func=lambda index: _route_snapshot_label(index, snapshots[index]),
                        key="route_compare_a_select",
                    )
                with compare_col_b:
                    compare_b_index = st.selectbox(
                        "Compare Snapshot B",
                        options=list(range(len(snapshots))),
                        index=1 if len(snapshots) > 1 else 0,
                        format_func=lambda index: _route_snapshot_label(index, snapshots[index]),
                        key="route_compare_b_select",
                    )
                if st.button("Compare Selected Sequence Snapshots", key="compare_selected_routes"):
                    st.session_state.route_compare_selection = (compare_a_index, compare_b_index)

                compare_selection = st.session_state.get("route_compare_selection")
                if compare_selection:
                    compare_a_index, compare_b_index = compare_selection
                    if compare_a_index < len(snapshots) and compare_b_index < len(snapshots):
                        compare_rows = _compare_route_snapshots(
                            snapshots[compare_a_index],
                            snapshots[compare_b_index],
                        )
                        st.markdown("##### Sequence Snapshot Compare")
                        if not compare_rows:
                            st.caption("No differing sequence selections found.")
                        for row in compare_rows:
                            st.caption(row["label"])
                            route_a_col, route_b_col = st.columns(2)
                            with route_a_col:
                                _render_route_compare_image("Snapshot A", row["path_a"])
                            with route_b_col:
                                _render_route_compare_image("Snapshot B", row["path_b"])
            storyboard_index = st.selectbox(
                "Sequence Storyboard",
                options=list(range(len(snapshots))),
                format_func=lambda index: _route_snapshot_label(index, snapshots[index]),
                key="route_storyboard_select",
            )
            if st.button("Show Sequence Storyboard", key="show_route_storyboard"):
                st.session_state.route_storyboard_selection = storyboard_index

            storyboard_selection = st.session_state.get("route_storyboard_selection")
            if storyboard_selection is not None and storyboard_selection < len(snapshots):
                st.markdown("##### Sequence Storyboard")
                _render_route_storyboard(snapshots[storyboard_selection])
        if st.button("Save Current Sequence Snapshot", key="save_current_route_snapshot"):
            _append_route_snapshot(project, _make_route_snapshot(project))
            save_current_project_if_possible("route snapshot saved")
            st.success("Sequence Snapshot saved.")
            st.rerun()

def focus_line_has_unsaved_edits(line):
    if not line:
        return False
    current_text = st.session_state.get(f"focus_text_{line.id}", line.current_text)
    current_negative_prompt = st.session_state.get(
        f"focus_negative_text_{line.id}",
        getattr(line, "negative_prompt", "") or "",
    )
    stored_negative_prompt = getattr(line, "negative_prompt", "") or ""
    return current_text != line.current_text or current_negative_prompt != stored_negative_prompt

def sync_focus_text_area_state(line):
    if not line:
        return
    st.session_state[f"focus_text_{line.id}"] = line.current_text
    st.session_state[f"focus_negative_text_{line.id}"] = getattr(line, "negative_prompt", "") or ""

def get_node_match_terms(project, node_id):
    node = getattr(project, "nodes", {}).get(node_id)
    if not node:
        return set()

    from core.parser import extract_node_metadata
    terms = {
        getattr(node, "display", ""),
        getattr(node, "word", ""),
        getattr(node, "original", ""),
    }
    for value in list(terms):
        if value:
            terms.add(extract_node_metadata(value)["base_word"])
    return {term.strip().lower() for term in terms if term and term.strip()}

def remap_selected_nodes_for_line(project, line, selected_node_ids):
    if not project or not line or not selected_node_ids:
        return []

    line_node_ids = [
        node_id
        for node_id in getattr(line, "node_path", [])
        if node_id in getattr(project, "nodes", {})
    ]
    exact_matches = [
        node_id
        for node_id in selected_node_ids
        if node_id in line_node_ids
    ]
    if exact_matches:
        return exact_matches

    selected_terms = set()
    for node_id in selected_node_ids:
        selected_terms.update(get_node_match_terms(project, node_id))
    if not selected_terms:
        return []

    remapped_node_ids = []
    for node_id in line_node_ids:
        if node_id in remapped_node_ids:
            continue
        if get_node_match_terms(project, node_id) & selected_terms:
            remapped_node_ids.append(node_id)

    return remapped_node_ids

def preserve_focus_selection_context(project, line, selected_node_ids):
    remapped_node_ids = remap_selected_nodes_for_line(project, line, selected_node_ids)
    st.session_state.selected_node_ids = remapped_node_ids
    st.session_state.connect_nodes = [
        node_id
        for node_id in st.session_state.get("connect_nodes", [])
        if node_id in remapped_node_ids
    ]
    sanitize_selected_node_ids(project)

def focus_line(line_id):
    project = st.session_state.get("project")
    line = get_line_by_id(project, line_id)
    if not line:
        return

    selected_node_ids = list(st.session_state.get("selected_node_ids", []))
    st.session_state.focused_line_id = line.id
    st.session_state.highlighted_line_id = line.id
    st.session_state.connect_mode = False
    preserve_focus_selection_context(project, line, selected_node_ids)
    sync_focus_text_area_state(line)

def get_prompt_line_label(line):
    line_number = getattr(line, "current_index", None)
    if line_number is None:
        return line.original_file_name
    return f"{line.original_file_name}:{line_number + 1}"

def _line_thumbnail_path(line, include_generated=True):
    if include_generated:
        display_path = _resolved_line_main_image_path(line)
        if display_path:
            return _gallery_thumbnail_display_path(display_path)
        return None
    for attr_name in ("image_path",):
        path = getattr(line, attr_name, None)
        display_path = _runtime_asset_path(path)
        if path and profiled_path_exists(display_path):
            return _gallery_thumbnail_display_path(display_path)
    return None

def render_line_list_reorder_controls(project, line, disabled=False):
    previous_line_id, next_line_id = get_adjacent_focus_line_ids(project, line.id)
    up_col, down_col = st.columns(2)
    with up_col:
        if st.button("↑", key=f"line_list_move_up_{line.id}", disabled=disabled or previous_line_id is None):
            push_history()
            prev_focus = st.session_state.get("focused_line_id")
            if move_prompt_line(project, line.id, "up"):
                st.session_state.project = build_graph(project)
                restore_focus_after_graph_update(prev_focus)
                st.rerun()
    with down_col:
        if st.button("↓", key=f"line_list_move_down_{line.id}", disabled=disabled or next_line_id is None):
            push_history()
            prev_focus = st.session_state.get("focused_line_id")
            if move_prompt_line(project, line.id, "down"):
                st.session_state.project = build_graph(project)
                restore_focus_after_graph_update(prev_focus)
                st.rerun()
    if disabled:
        st.caption("Reorder disabled while filtered")


def get_graph_edit_browser_unsaved_line_ids(project) -> list[str]:
    """Return current-page IDs whose existing editor widgets differ from Project."""

    if not project:
        return []
    page_line_ids = st.session_state.get(
        GRAPH_EDIT_BROWSER_PAGE_LINE_IDS_KEY,
        [],
    )
    if not isinstance(page_line_ids, (list, tuple)):
        return []

    unsaved_line_ids = []
    seen = set()
    for raw_line_id in page_line_ids:
        line_id = str(raw_line_id or "")
        if not line_id or line_id in seen:
            continue
        seen.add(line_id)
        line = get_line_by_id(project, line_id)
        if not line or getattr(line, "deleted", False):
            continue
        stored_text = getattr(line, "current_text", "") or ""
        stored_negative = getattr(line, "negative_prompt", "") or ""
        draft_text = st.session_state.get(f"text_{line_id}", stored_text)
        draft_negative = st.session_state.get(
            f"negative_text_{line_id}",
            stored_negative,
        )
        if draft_text != stored_text or draft_negative != stored_negative:
            unsaved_line_ids.append(line_id)
    return unsaved_line_ids


def block_graph_edit_browser_navigation_if_unsaved(project) -> bool:
    """Block Browser-only navigation while current-page editor drafts exist."""

    if not get_graph_edit_browser_unsaved_line_ids(project):
        return False
    st.session_state[GRAPH_EDIT_BROWSER_NOTICE_KEY] = (
        GRAPH_EDIT_BROWSER_UNSAVED_WARNING
    )
    return True


def discard_graph_edit_browser_current_page_drafts(project) -> list[str]:
    """Restore current-page editor widgets from Project without mutating Project."""

    discarded_line_ids = []
    for line_id in get_graph_edit_browser_unsaved_line_ids(project):
        line = get_line_by_id(project, line_id)
        if not line or getattr(line, "deleted", False):
            continue
        st.session_state[f"text_{line_id}"] = (
            getattr(line, "current_text", "") or ""
        )
        st.session_state[f"negative_text_{line_id}"] = (
            getattr(line, "negative_prompt", "") or ""
        )
        discarded_line_ids.append(line_id)
    st.session_state[GRAPH_EDIT_BROWSER_NOTICE_KEY] = ""
    return discarded_line_ids


def _reset_graph_edit_browser_page() -> None:
    st.session_state[GRAPH_EDIT_BROWSER_PAGE_KEY] = 1
    st.session_state.pop(GRAPH_EDIT_BROWSER_PAGE_TOP_WIDGET_KEY, None)


def _on_graph_edit_browser_filter_changed() -> None:
    if block_graph_edit_browser_navigation_if_unsaved(
        st.session_state.get("project")
    ):
        st.session_state[GRAPH_EDIT_BROWSER_FILTER_WIDGET_KEY] = (
            st.session_state.get(
                GRAPH_EDIT_BROWSER_FILTER_KEY,
                GRAPH_EDIT_BROWSER_FILTER_ALL,
            )
        )
        return
    st.session_state[GRAPH_EDIT_BROWSER_FILTER_KEY] = st.session_state.get(
        GRAPH_EDIT_BROWSER_FILTER_WIDGET_KEY,
        GRAPH_EDIT_BROWSER_FILTER_ALL,
    )
    _reset_graph_edit_browser_page()
    st.session_state[GRAPH_EDIT_BROWSER_NOTICE_KEY] = ""


def _on_graph_edit_browser_page_size_changed() -> None:
    if block_graph_edit_browser_navigation_if_unsaved(
        st.session_state.get("project")
    ):
        st.session_state[GRAPH_EDIT_BROWSER_PAGE_SIZE_WIDGET_KEY] = (
            st.session_state.get(
                GRAPH_EDIT_BROWSER_PAGE_SIZE_KEY,
                GRAPH_EDIT_BROWSER_DEFAULT_PAGE_SIZE,
            )
        )
        return
    page_size = st.session_state.get(
        GRAPH_EDIT_BROWSER_PAGE_SIZE_WIDGET_KEY,
        GRAPH_EDIT_BROWSER_DEFAULT_PAGE_SIZE,
    )
    st.session_state[GRAPH_EDIT_BROWSER_PAGE_SIZE_KEY] = (
        page_size
        if page_size in GRAPH_EDIT_BROWSER_PAGE_SIZE_OPTIONS
        else GRAPH_EDIT_BROWSER_DEFAULT_PAGE_SIZE
    )
    _reset_graph_edit_browser_page()


def _on_graph_edit_browser_page_input_changed(widget_key: str) -> None:
    if block_graph_edit_browser_navigation_if_unsaved(
        st.session_state.get("project")
    ):
        st.session_state[widget_key] = st.session_state.get(
            GRAPH_EDIT_BROWSER_PAGE_KEY,
            1,
        )
        return
    try:
        page = int(st.session_state.get(widget_key, 1))
    except (TypeError, ValueError, OverflowError):
        page = 1
    st.session_state[GRAPH_EDIT_BROWSER_PAGE_KEY] = max(1, page)


def _set_graph_edit_browser_page(page: int, page_count: int) -> bool:
    if block_graph_edit_browser_navigation_if_unsaved(
        st.session_state.get("project")
    ):
        return False
    st.session_state[GRAPH_EDIT_BROWSER_PAGE_KEY] = max(
        1,
        min(max(1, int(page_count or 1)), int(page or 1)),
    )
    st.session_state.pop(GRAPH_EDIT_BROWSER_PAGE_TOP_WIDGET_KEY, None)
    return True


def _set_graph_edit_browser_collapsed_group_keys(group_keys) -> bool:
    """Apply one typed collapse set unless current-page drafts block navigation."""

    if block_graph_edit_browser_navigation_if_unsaved(
        st.session_state.get("project")
    ):
        return False
    st.session_state[GRAPH_EDIT_BROWSER_COLLAPSED_KEY] = {
        str(group_key)
        for group_key in (group_keys or set())
        if str(group_key or "")
    }
    _reset_graph_edit_browser_page()
    return True


def _reveal_graph_edit_browser_current(filter_value: str, page: int) -> None:
    """Apply an explicit reveal before the next widget-rendering pass."""

    if block_graph_edit_browser_navigation_if_unsaved(
        st.session_state.get("project")
    ):
        return
    st.session_state[GRAPH_EDIT_BROWSER_FILTER_KEY] = str(filter_value or "")
    st.session_state[GRAPH_EDIT_BROWSER_PAGE_KEY] = max(1, int(page or 1))
    st.session_state[GRAPH_EDIT_BROWSER_NOTICE_KEY] = (
        "現在のイラストを含むSceneとpageを表示しました。"
    )
    st.session_state.pop(GRAPH_EDIT_BROWSER_FILTER_WIDGET_KEY, None)
    st.session_state.pop(GRAPH_EDIT_BROWSER_PAGE_TOP_WIDGET_KEY, None)


def _graph_edit_browser_group_widget_suffix(handle: str) -> str:
    return hashlib.sha1(str(handle or "").encode("utf-8")).hexdigest()[:12]


def _render_graph_edit_browser_visibility_controls(plan: dict) -> None:
    if plan.get("filter_value") != GRAPH_EDIT_BROWSER_FILTER_ALL:
        st.caption("個別Scene filterでは、そのSceneの表示設定を一時的に無視します。")
        return

    collapsed = set(plan.get("collapsed_group_keys") or [])
    with st.expander("Scene表示設定", expanded=False):
        action_cols = st.columns(2)
        action_cols[0].button(
            "すべて表示",
            key="graph_edit_browser_expand_all",
            width="stretch",
            on_click=_set_graph_edit_browser_collapsed_group_keys,
            args=(set(),),
        )
        collapsed_all = {
            summary["group_key"]
            for summary in plan.get("scene_summaries") or []
            if summary.get("count", 0) > 0
        }
        if (plan.get("outside_summary") or {}).get("count", 0) > 0:
            collapsed_all.add(
                (plan.get("outside_summary") or {})["group_key"]
            )
        action_cols[1].button(
            "すべて閉じる",
            key="graph_edit_browser_collapse_all",
            width="stretch",
            on_click=_set_graph_edit_browser_collapsed_group_keys,
            args=(collapsed_all,),
        )

        summaries = list(plan.get("scene_summaries") or []) + [
            plan.get("outside_summary") or {}
        ]
        for summary in summaries:
            group_key = str(summary.get("group_key") or "")
            if not group_key:
                continue
            row_cols = st.columns([4, 1])
            row_cols[0].caption(
                f"{summary.get('display_label') or summary.get('label') or 'Scene'}"
                f" — {summary.get('count', 0)}"
            )
            is_collapsed = group_key in collapsed
            updated = set(collapsed)
            if is_collapsed:
                updated.discard(group_key)
            else:
                updated.add(group_key)
            row_cols[1].button(
                "表示" if is_collapsed else "閉じる",
                key=(
                    "graph_edit_browser_group_visibility_"
                    f"{_graph_edit_browser_group_widget_suffix(group_key)}"
                ),
                width="stretch",
                on_click=_set_graph_edit_browser_collapsed_group_keys,
                args=(updated,),
            )


def _render_graph_edit_browser_page_controls(plan: dict, *, position: str) -> None:
    page = int(plan.get("page", 1) or 1)
    page_count = int(plan.get("page_count", 1) or 1)
    visible_count = int(plan.get("visible_count", 0) or 0)
    page_start = int(plan.get("page_start", 0) or 0)
    page_end = int(plan.get("page_end", 0) or 0)
    st.caption(
        f"{page_start}–{page_end} / {visible_count} Illustrations · "
        f"Page {page} / {page_count}"
    )

    if position == "footer":
        footer_cols = st.columns([1, 3, 1])
        footer_cols[0].button(
            "Previous",
            key="graph_edit_browser_footer_previous",
            disabled=page <= 1,
            width="stretch",
            on_click=_set_graph_edit_browser_page,
            args=(page - 1, page_count),
        )
        footer_cols[1].caption(f"Page {page} / {page_count}")
        footer_cols[2].button(
            "Next",
            key="graph_edit_browser_footer_next",
            disabled=page >= page_count,
            width="stretch",
            on_click=_set_graph_edit_browser_page,
            args=(page + 1, page_count),
        )
        return

    st.session_state[GRAPH_EDIT_BROWSER_PAGE_TOP_WIDGET_KEY] = page
    control_cols = st.columns([1, 1, 1.4, 1, 1])
    control_cols[0].button(
        "First",
        key="graph_edit_browser_first",
        disabled=page <= 1,
        width="stretch",
        on_click=_set_graph_edit_browser_page,
        args=(1, page_count),
    )
    control_cols[1].button(
        "Previous",
        key="graph_edit_browser_previous",
        disabled=page <= 1,
        width="stretch",
        on_click=_set_graph_edit_browser_page,
        args=(page - 1, page_count),
    )
    control_cols[2].number_input(
        "Page",
        min_value=1,
        max_value=max(1, page_count),
        step=1,
        key=GRAPH_EDIT_BROWSER_PAGE_TOP_WIDGET_KEY,
        on_change=_on_graph_edit_browser_page_input_changed,
        args=(GRAPH_EDIT_BROWSER_PAGE_TOP_WIDGET_KEY,),
        label_visibility="collapsed",
    )
    control_cols[3].button(
        "Next",
        key="graph_edit_browser_next",
        disabled=page >= page_count,
        width="stretch",
        on_click=_set_graph_edit_browser_page,
        args=(page + 1, page_count),
    )
    control_cols[4].button(
        "Last",
        key="graph_edit_browser_last",
        disabled=page >= page_count,
        width="stretch",
        on_click=_set_graph_edit_browser_page,
        args=(page_count, page_count),
    )


def render_graph_edit_illustration_editor(project, line, *, reorder_disabled=False) -> None:
    """Render the existing Graph Edit record editor with unchanged widget keys."""

    text_widget_key = f"text_{line.id}"
    negative_text_widget_key = f"negative_text_{line.id}"
    if text_widget_key not in st.session_state:
        st.session_state[text_widget_key] = line.current_text
    if negative_text_widget_key not in st.session_state:
        st.session_state[negative_text_widget_key] = (
            getattr(line, "negative_prompt", "") or ""
        )

    title = f"[{line.original_file_name}] Illustration {line.original_index}"
    if line.edited:
        title += " (Edited)"
    if line.duplicated_from:
        title += " (Duplicated)"

    col_chk, col_thumb, col_exp, col_move = st.columns([0.05, 0.14, 0.71, 0.10])
    with col_chk:
        was_selected = st.session_state.selected_lines.get(line.id, False)
        is_selected = st.checkbox(
            "Select",
            value=was_selected,
            key=f"chk_{line.id}",
            label_visibility="collapsed",
        )
        st.session_state.selected_lines[line.id] = is_selected
        if is_selected and not was_selected:
            st.session_state.highlighted_line_id = line.id
            st.rerun()
    with col_thumb:
        thumbnail_path = _line_thumbnail_path(line)
        if thumbnail_path:
            st.image(thumbnail_path, width="stretch")
        else:
            st.caption("No image")
    with col_move:
        render_line_list_reorder_controls(
            project,
            line,
            disabled=reorder_disabled,
        )

    with col_exp:
        with st.expander(title):
            if st.button("Highlight Path", key=f"highlight_btn_{line.id}"):
                st.session_state.highlighted_line_id = line.id
                st.rerun()
            if st.button("🎯 Focus Edit", key=f"focus_btn_{line.id}"):
                st.session_state.focused_line_id = line.id
                st.session_state.highlighted_line_id = line.id
                st.rerun()

            thumbnail_path = _line_thumbnail_path(line)
            if thumbnail_path:
                c_img, c_txt = st.columns([1, 2])
                with c_img:
                    st.image(thumbnail_path, width="stretch")
                with c_txt:
                    new_text = st.text_area(
                        "Prompt Text",
                        key=text_widget_key,
                        label_visibility="collapsed",
                    )
            else:
                new_text = st.text_area(
                    "Prompt Text",
                    key=text_widget_key,
                )

            new_negative_prompt = st.text_area(
                "Negative Prompt",
                key=negative_text_widget_key,
                height=100,
                help="Optional. Stored per line and exported, but not graphed in v1.",
            )

            prompt_changed = new_text != line.current_text
            negative_prompt_changed = new_negative_prompt != (
                getattr(line, "negative_prompt", "") or ""
            )
            if prompt_changed or negative_prompt_changed:
                if st.button("Save Changes", key=f"save_{line.id}"):
                    if prompt_changed and is_free() and not st.session_state.get(
                        "focused_line_id"
                    ):
                        st.error(
                            "「Free版では編集にFocus Edit Modeが必要です。Focus Edit を押して "
                            "Focus Edit Modeに入ってから編集してください。」"
                        )
                        st.stop()
                    update_line_prompts(
                        line.id,
                        new_text=new_text if prompt_changed else _UNCHANGED,
                        new_negative_prompt=(
                            new_negative_prompt
                            if negative_prompt_changed
                            else _UNCHANGED
                        ),
                    )
                    st.rerun()

            c1, c2 = st.columns(2)
            if c1.button("Duplicate", key=f"dup_{line.id}"):
                if is_free() and not st.session_state.get("focused_line_id"):
                    st.error(
                        "「Free版では編集にFocus Edit Modeが必要です。Focus Edit を押して "
                        "Focus Edit Modeに入ってから編集してください。」"
                    )
                    st.stop()
                duplicate_line(line.id)
                st.rerun()
            if c2.button("Delete", key=f"del_{line.id}"):
                if is_free() and not st.session_state.get("focused_line_id"):
                    st.error(
                        "「Free版では編集にFocus Edit Modeが必要です。Focus Edit を押して "
                        "Focus Edit Modeに入ってから編集してください。」"
                    )
                    st.stop()
                delete_line(line.id)
                st.rerun()


def render_graph_edit_illustration_browser_page(
    project,
    plan: dict,
    *,
    reorder_disabled=False,
    editor_renderer=None,
) -> None:
    """Dispatch only current-page records to the existing editor renderer."""

    renderer = editor_renderer or render_graph_edit_illustration_editor
    previous_group = None
    for entry in plan.get("page_entries") or []:
        group = entry.get("group_filter_value")
        if group != previous_group:
            st.markdown(f"**{entry.get('scene_label') or 'Scene外のイラスト'}**")
            previous_group = group
        renderer(
            project,
            entry["line"],
            reorder_disabled=reorder_disabled,
        )


def render_graph_edit_illustration_browser(
    project,
    illustration_lines,
    *,
    reorder_disabled=False,
    current_illustration_id="",
) -> dict:
    """Render Graph Edit-only filter/collapse/pagination and current page."""

    with profile_block("Graph Edit browser plan"):
        plan = build_graph_edit_illustration_browser_plan(
            project,
            illustration_lines,
            filter_value=st.session_state.get(
                GRAPH_EDIT_BROWSER_FILTER_KEY,
                GRAPH_EDIT_BROWSER_FILTER_ALL,
            ),
            collapsed_group_keys=st.session_state.get(
                GRAPH_EDIT_BROWSER_COLLAPSED_KEY,
                set(),
            ),
            page=st.session_state.get(GRAPH_EDIT_BROWSER_PAGE_KEY, 1),
            page_size=st.session_state.get(
                GRAPH_EDIT_BROWSER_PAGE_SIZE_KEY,
                GRAPH_EDIT_BROWSER_DEFAULT_PAGE_SIZE,
            ),
            current_illustration_id=current_illustration_id,
        )

    if plan.get("filter_fallback"):
        st.session_state[GRAPH_EDIT_BROWSER_NOTICE_KEY] = (
            "選択していたSceneを利用できないため、すべてのイラストへ戻しました。"
        )
        st.session_state[GRAPH_EDIT_BROWSER_PAGE_KEY] = 1
    st.session_state[GRAPH_EDIT_BROWSER_FILTER_KEY] = plan["filter_value"]
    st.session_state[GRAPH_EDIT_BROWSER_PAGE_KEY] = plan["page"]
    st.session_state[GRAPH_EDIT_BROWSER_PAGE_SIZE_KEY] = plan["page_size"]
    st.session_state[GRAPH_EDIT_BROWSER_COLLAPSED_KEY] = set(
        plan.get("collapsed_group_keys") or []
    )

    st.markdown("#### Graph Edit Illustration Browser")
    st.caption(
        "このfilterとpageはIllustration一覧の表示だけを変更します。"
        "Graph、PromptCloud、Batch Edit、Module操作は従来どおりProject全体を対象にします。"
    )
    notice = st.session_state.get(GRAPH_EDIT_BROWSER_NOTICE_KEY, "")
    if notice == GRAPH_EDIT_BROWSER_UNSAVED_WARNING:
        if get_graph_edit_browser_unsaved_line_ids(project):
            st.warning(notice)
            st.button(
                "このpageの未保存変更を破棄",
                key="graph_edit_browser_discard_current_page_drafts",
                on_click=discard_graph_edit_browser_current_page_drafts,
                args=(project,),
            )
        else:
            st.session_state[GRAPH_EDIT_BROWSER_NOTICE_KEY] = ""
    elif notice:
        st.session_state[GRAPH_EDIT_BROWSER_NOTICE_KEY] = ""
        st.info(notice)

    option_labels = {
        option["value"]: option["label"]
        for option in plan.get("filter_options") or []
    }
    st.session_state[GRAPH_EDIT_BROWSER_FILTER_WIDGET_KEY] = plan["filter_value"]
    st.selectbox(
        "表示するScene",
        list(option_labels),
        key=GRAPH_EDIT_BROWSER_FILTER_WIDGET_KEY,
        format_func=lambda value: option_labels.get(value, value),
        on_change=_on_graph_edit_browser_filter_changed,
    )
    st.session_state[GRAPH_EDIT_BROWSER_PAGE_SIZE_WIDGET_KEY] = plan["page_size"]
    st.radio(
        "Page size",
        list(GRAPH_EDIT_BROWSER_PAGE_SIZE_OPTIONS),
        key=GRAPH_EDIT_BROWSER_PAGE_SIZE_WIDGET_KEY,
        horizontal=True,
        on_change=_on_graph_edit_browser_page_size_changed,
    )
    _render_graph_edit_browser_visibility_controls(plan)

    if plan.get("current_entry") and not plan.get("current_on_page"):
        st.info(
            "現在のイラストは、このfilterまたはpageでは表示されていません。"
        )
        if plan.get("current_reveal_available"):
            st.button(
                "現在のイラストを表示",
                key="graph_edit_browser_reveal_current",
                on_click=_reveal_graph_edit_browser_current,
                args=(plan["reveal_filter_value"], plan["reveal_page"]),
            )

    _render_graph_edit_browser_page_controls(plan, position="top")
    if plan.get("all_groups_collapsed"):
        st.info(
            "すべてのSceneが閉じられています。"
            "Scene表示設定から対象を開いてください。"
        )
    elif not plan.get("visible_count"):
        st.info("現在の表示条件に該当するイラストはありません。")
    else:
        with profile_block("Graph Edit browser render"):
            render_graph_edit_illustration_browser_page(
                project,
                plan,
                reorder_disabled=reorder_disabled,
            )
    st.session_state[GRAPH_EDIT_BROWSER_PAGE_LINE_IDS_KEY] = [
        entry["line_id"]
        for entry in plan.get("page_entries") or []
        if entry.get("line_id")
    ]
    _render_graph_edit_browser_page_controls(plan, position="footer")
    return plan


def get_graph_node_ids_for_line(project, line):
    if not project or not line:
        return set()
    return {
        node_id
        for node_id in getattr(line, "node_path", [])
        if node_id in getattr(project, "nodes", {})
    }

def sort_graph_node_ids_for_display(project, node_ids, focused_line=None):
    focused_order = {}
    if focused_line:
        for index, node_id in enumerate(getattr(focused_line, "node_path", [])):
            if node_id in getattr(project, "nodes", {}) and node_id not in focused_order:
                focused_order[node_id] = index

    def sort_key(node_id):
        node = project.nodes[node_id]
        if node_id in focused_order:
            return (0, focused_order[node_id], node.depth, node.display)
        return (1, node.depth, node.display)

    return sorted(
        [node_id for node_id in node_ids if node_id in getattr(project, "nodes", {})],
        key=sort_key,
    )

def get_wrapped_graph_positions(ordered_node_ids, row_size=6, x_gap=115, y_gap=90):
    positions = {}
    for index, node_id in enumerate(ordered_node_ids):
        row = index // row_size
        col = index % row_size
        row_count = min(row_size, len(ordered_node_ids) - row * row_size)
        x_offset = ((row_count - 1) * x_gap) / 2
        positions[node_id] = {
            "x": int(col * x_gap - x_offset),
            "y": int(row * y_gap),
        }
    return positions

def get_initial_graph_display_node_ids(project):
    if not project:
        return set()
    if getattr(project, "merge_by_word_only", False):
        # In merged-word mode depth is only the first observed token position.
        # Use count-ranked nodes so the meta-level repeated-word graph stays visible.
        node_counts = {
            node_id: getattr(node, "count", 0)
            for node_id, node in getattr(project, "nodes", {}).items()
        }
        return {
            node_id
            for node_id, _count in sorted(node_counts.items(), key=lambda item: item[1], reverse=True)[:80]
        }
    return {nid for nid, node in project.nodes.items() if node.depth <= 2}

def get_branch_visual_hints(project, displayed_node_ids):
    displayed_node_ids = {
        node_id
        for node_id in displayed_node_ids
        if node_id in getattr(project, "nodes", {})
    }
    if not project or not displayed_node_ids:
        return set(), set(), set()

    ranked_counts = sorted(
        (
            getattr(project.nodes[node_id], "count", 0)
            for node_id in displayed_node_ids
        ),
        reverse=True,
    )
    if not ranked_counts:
        return set(), set(), set()

    threshold_index = min(len(ranked_counts) - 1, max(0, len(ranked_counts) // 4))
    spine_threshold = max(2, ranked_counts[threshold_index])
    spine_node_ids = {
        node_id
        for node_id in displayed_node_ids
        if getattr(project.nodes[node_id], "count", 0) >= spine_threshold
        and (
            getattr(project.nodes[node_id], "prev_node_ids", set())
            or getattr(project.nodes[node_id], "next_node_ids", set())
        )
    }

    divergence_origin_node_ids = set()
    weaker_branch_edges = set()
    for node_id in displayed_node_ids:
        parent_node = project.nodes[node_id]
        parent_count = max(1, getattr(parent_node, "count", 0))
        displayed_children = [
            child_id
            for child_id in getattr(parent_node, "next_node_ids", set())
            if child_id in displayed_node_ids and child_id in project.nodes
        ]
        if len(displayed_children) < 2:
            continue

        weaker_children = [
            child_id
            for child_id in displayed_children
            if getattr(project.nodes[child_id], "count", 0) <= parent_count * 0.6
        ]
        if weaker_children:
            divergence_origin_node_ids.add(node_id)
            weaker_branch_edges.update((node_id, child_id) for child_id in weaker_children)

    return divergence_origin_node_ids, spine_node_ids, weaker_branch_edges

def get_cooccurrence_overlay_edges(
    project,
    ordered_display_node_ids,
    min_count=3,
    max_nodes_per_line=14,
    max_edges_per_node=1,
    max_edges=30,
):
    display_order = {
        node_id: index
        for index, node_id in enumerate(ordered_display_node_ids)
        if node_id in getattr(project, "nodes", {})
    }
    displayed_node_ids = set(display_order)
    if not project or len(displayed_node_ids) < 2:
        return []

    syntax_edges = set(getattr(project, "edges", []))
    pair_counts = {}
    for line in getattr(project, "prompt_lines", []):
        if getattr(line, "deleted", False):
            continue
        line_node_ids = []
        seen_in_line = set()
        for node_id in getattr(line, "node_path", []):
            if node_id in displayed_node_ids and node_id not in seen_in_line:
                seen_in_line.add(node_id)
                line_node_ids.append(node_id)
        if len(line_node_ids) < 2:
            continue
        line_node_ids = sorted(line_node_ids, key=lambda node_id: display_order[node_id])[:max_nodes_per_line]
        for index, source in enumerate(line_node_ids):
            for target in line_node_ids[index + 1:]:
                if (source, target) in syntax_edges or (target, source) in syntax_edges:
                    continue
                pair = tuple(sorted((source, target), key=lambda node_id: display_order[node_id]))
                pair_counts[pair] = pair_counts.get(pair, 0) + 1

    ranked_pairs = sorted(
        (
            (source, target, count)
            for (source, target), count in pair_counts.items()
            if count >= min_count
        ),
        key=lambda item: (-item[2], display_order[item[0]], display_order[item[1]]),
    )
    overlay_edges = []
    per_node_counts = {}
    for source, target, count in ranked_pairs:
        if per_node_counts.get(source, 0) >= max_edges_per_node:
            continue
        if per_node_counts.get(target, 0) >= max_edges_per_node:
            continue
        overlay_edges.append((source, target, count))
        per_node_counts[source] = per_node_counts.get(source, 0) + 1
        per_node_counts[target] = per_node_counts.get(target, 0) + 1
        if len(overlay_edges) >= max_edges:
            break
    return overlay_edges

