def render_focus_edit_navigation_controls(project, focused_line):
    if not focused_line:
        return

    previous_line_id, next_line_id = get_adjacent_focus_line_ids(project, focused_line.id)
    has_unsaved_edits = focus_line_has_unsaved_edits(focused_line)

    st.markdown("#### Finish / Move to another line")
    if has_unsaved_edits:
        st.warning("Save changes before navigating.")

    reorder_up_col, reorder_down_col = st.columns(2)
    with reorder_up_col:
        if st.button(
            "Move Illustration Up",
            key="focus_move_line_up",
            disabled=has_unsaved_edits or previous_line_id is None,
        ):
            push_history()
            prev_focus = st.session_state.get("focused_line_id")
            if move_prompt_line(project, focused_line.id, "up"):
                st.session_state.project = build_graph(project)
                restore_focus_after_graph_update(prev_focus)
                st.rerun()
            else:
                st.info("Illustration is already at the top.")
    with reorder_down_col:
        if st.button(
            "Move Illustration Down",
            key="focus_move_line_down",
            disabled=has_unsaved_edits or next_line_id is None,
        ):
            push_history()
            prev_focus = st.session_state.get("focused_line_id")
            if move_prompt_line(project, focused_line.id, "down"):
                st.session_state.project = build_graph(project)
                restore_focus_after_graph_update(prev_focus)
                st.rerun()
            else:
                st.info("Illustration is already at the bottom.")

    previous_col, next_col, exit_col = st.columns(3)
    with previous_col:
        if st.button(
            "Previous Illustration",
            key="focus_previous_line_top",
            disabled=has_unsaved_edits or previous_line_id is None,
        ):
            focus_line(previous_line_id)
            st.rerun()
    with next_col:
        if st.button(
            "Next Illustration",
            key="focus_next_line_top",
            disabled=has_unsaved_edits or next_line_id is None,
        ):
            focus_line(next_line_id)
            st.rerun()
    with exit_col:
        if st.button("Exit Focus Edit Mode", type="primary", key="exit_focus_edit_top"):
            st.session_state.focused_line_id = None
            st.rerun()

