def get_selected_line_ids(project):
    if not project:
        return []
    valid_line_ids = {
        line.id
        for line in project.prompt_lines
        if is_gallery_operation_prompt_line(line)
    }
    return [
        line_id
        for line_id, selected in st.session_state.get("selected_lines", {}).items()
        if selected and line_id in valid_line_ids
    ]

def resolve_batch_edit_target_line_ids(project, scope_key, route_id=None, selected_line_ids=None):
    if scope_key == "all":
        resolution = resolve_gallery_operation_targets(project, "all_lines")
        return resolution["target_line_ids"]
    if scope_key == "focus":
        focused_line = get_line_by_id(project, st.session_state.get("focused_line_id"))
        return [focused_line.id] if is_gallery_operation_prompt_line(focused_line) else []
    if scope_key == "selected":
        resolution = resolve_gallery_operation_targets(
            project,
            "selected_lines",
            selected_line_ids=selected_line_ids if selected_line_ids is not None else get_selected_line_ids(project),
        )
        return resolution["target_line_ids"]
    if scope_key == "current_route":
        resolution = resolve_gallery_operation_targets(
            project,
            "current_route",
            selected_line_ids=selected_line_ids or get_selected_line_ids(project),
        )
        return resolution["target_line_ids"]
    if scope_key == "selected_route":
        resolution = resolve_gallery_operation_targets(
            project,
            "selected_route",
            route_id=route_id,
            selected_line_ids=selected_line_ids or get_selected_line_ids(project),
        )
        return resolution["target_line_ids"]
    if scope_key.startswith("group::"):
        return resolve_line_group_ids(project, scope_key[len("group::"):])
    return []

def render_selected_line_batch_actions(project, selected_line_ids):
    if not selected_line_ids:
        return

    st.markdown("---")
    st.markdown("**Selected Illustration Actions**")
    st.caption(f"{len(selected_line_ids)} illustration(s) selected. Use these actions with the Illustrations checklist.")
    c_del, c_dup = st.columns(2)
    with c_del:
        if st.button("Delete Selected Illustrations", key="delete_selected_lines_context"):
            if not require_pro("Batch line operations are available in Pro."):
                st.stop()

            push_history()
            for lid in selected_line_ids:
                for line in st.session_state.project.prompt_lines:
                    if line.id == lid:
                        line.deleted = True
                        break
            prev_focus = st.session_state.get("focused_line_id")
            st.session_state.project = build_graph(st.session_state.project)
            restore_focus_after_graph_update(prev_focus)
            st.session_state.selected_node_ids = [
                nid for nid in st.session_state.selected_node_ids
                if nid in st.session_state.project.nodes
            ]
            st.session_state.selected_lines = {}
            st.rerun()
    with c_dup:
        if st.button("Duplicate Selected Illustrations", key="duplicate_selected_lines_context"):
            if not require_pro("Batch line operations are available in Pro."):
                st.stop()

            push_history()
            new_lines = []
            for line in st.session_state.project.prompt_lines:
                new_lines.append(line)
                if line.id in selected_line_ids:
                    new_line = copy.deepcopy(line)
                    new_line.id = f"line_{uuid.uuid4().hex[:8]}"
                    new_line.duplicated_from = line.id
                    new_line.edited = True
                    new_lines.append(new_line)
            st.session_state.project.prompt_lines = new_lines
            for i, l in enumerate(st.session_state.project.prompt_lines):
                l.current_index = i
            prev_focus = st.session_state.get("focused_line_id")
            st.session_state.project = build_graph(st.session_state.project)
            restore_focus_after_graph_update(prev_focus)
            st.session_state.selected_lines = {}
            st.rerun()

def batch_scope_options(project, include_routes: bool = False, selected_line_ids=None):
    selected_line_ids = selected_line_ids if selected_line_ids is not None else get_selected_line_ids(project)
    focused_line = get_line_by_id(project, st.session_state.get("focused_line_id"))
    scope_options = {
        "all": "All lines",
    }
    if focused_line:
        scope_options["focus"] = "Focus line only"
    if selected_line_ids:
        scope_options["selected"] = f"Selected lines ({len(selected_line_ids)})"
    if include_routes and _gallery_route_options_with_counts(project):
        scope_options["current_route"] = "Current route"
        scope_options["selected_route"] = "Selected route"
    scope_options.update(line_group_scope_options(project))
    return scope_options

def render_batch_token_reorder_section(project):
    selected_node_ids = [
        nid for nid in st.session_state.get("selected_node_ids", [])
        if nid in project.nodes
    ]
    if not selected_node_ids:
        return

    if selected_node_ids != st.session_state.selected_node_ids:
        st.session_state.selected_node_ids = selected_node_ids

    st.markdown("---")
    st.markdown("**Token Reorder**")
    st.caption("Move selected tokens from Graph or PromptCloud before or after another token in the selected prompt scope.")

    if st.session_state.get("connect_mode", False):
        st.warning("Connect Mode is active. Finish connecting or clear the selection before reordering tokens.")
        return

    target_options = {
        node.id: node.display
        for node in project.nodes.values()
        if node.id not in selected_node_ids
    }
    if not target_options:
        st.info("No other tokens are available as a move target.")
        return

    scope_options = batch_scope_options(project)
    if is_free():
        st.caption("Free mode can reorder tokens only in the active Focus Edit line.")
    elif st.session_state.get("batch_reorder_scope") not in scope_options:
        st.session_state.batch_reorder_scope = "all"

    c1, c2, c3 = st.columns([2, 1, 1.5])
    with c1:
        target_id = st.selectbox(
            "Move relative to",
            options=list(target_options.keys()),
            format_func=lambda value: target_options[value],
            key="batch_reorder_target_node",
        )
    with c2:
        move_pos = st.radio(
            "Position",
            ["before", "after"],
            format_func=lambda value: value.title(),
            horizontal=True,
            key="batch_reorder_position",
        )
    with c3:
        if is_free():
            scope_key = "focus"
            st.caption("Target: Focus line only")
        else:
            scope_key = st.selectbox(
                "Target",
                options=list(scope_options.keys()),
                format_func=lambda value: scope_options[value],
                key="batch_reorder_scope",
            )

    if st.button("Move Selected Tokens", key="batch_reorder_apply_btn"):
        target_line_ids = get_free_target_lines_or_block() if is_free() else resolve_batch_edit_target_line_ids(project, scope_key)
        if target_line_ids is None and is_free():
            st.stop()
        if target_line_ids == []:
            st.warning("No target lines.")
            st.stop()

        push_history()
        prev_focus = st.session_state.get("focused_line_id")
        st.session_state.project = move_nodes(
            st.session_state.project,
            selected_node_ids,
            target_id,
            move_pos,
            target_line_ids,
        )
        restore_focus_after_graph_update(prev_focus)
        st.session_state.selected_node_ids = []
        sync_text_areas()
        st.rerun()

def line_group_scope_options(project):
    options = {}
    for group_name in sorted(get_project_line_groups(project)):
        valid_line_ids = resolve_line_group_ids(project, group_name)
        options[f"group::{group_name}"] = f"Group: {group_name} ({len(valid_line_ids)} lines)"
    return options

def _highlight_literal_matches(text, query, style="background-color:#ffb3b3;color:#7a0000;"):
    query = (query or "")
    if not query:
        return html.escape(text)

    parts = []
    start = 0
    while True:
        match_index = text.find(query, start)
        if match_index < 0:
            parts.append(html.escape(text[start:]))
            break
        parts.append(html.escape(text[start:match_index]))
        match_text = html.escape(text[match_index:match_index + len(query)])
        parts.append(f"<span style='{style}'>{match_text}</span>")
        start = match_index + len(query)
    return "".join(parts)

def _batch_token_query(search_text, match_mode):
    query = (search_text or "").strip()
    if match_mode != "exact_token":
        return query

    from core.parser import extract_node_metadata

    tokens = parse_prompt(search_text or "")
    if len(tokens) != 1:
        return ""
    return extract_node_metadata(tokens[0])["base_word"].strip()

def _highlight_token_matches(text, search_text, match_mode):
    query = _batch_token_query(search_text, match_mode)
    if not query:
        return html.escape(text)

    from core.parser import extract_node_metadata, is_structural_mod_marker

    rendered_tokens = []
    for token in parse_prompt(text):
        if is_structural_mod_marker(token):
            rendered_tokens.append(html.escape(token))
            continue

        token_base = extract_node_metadata(token)["base_word"].strip()
        matched = token_base == query if match_mode == "exact_token" else query in token_base
        if not matched:
            rendered_tokens.append(html.escape(token))
            continue

        token_html = html.escape(token)
        if match_mode == "contains_token":
            token_html = _highlight_literal_matches(token, query)
        rendered_tokens.append(f"<span style='background-color:#fff3a3;'>{token_html}</span>")

    return ", ".join(rendered_tokens)

def _highlight_replace_result_tokens(text, replace_text):
    tokens = parse_prompt(replace_text or "")
    if len(tokens) != 1:
        return html.escape(text)

    from core.parser import extract_node_metadata, is_structural_mod_marker

    replacement_base = extract_node_metadata(tokens[0])["base_word"].strip()
    if not replacement_base:
        return html.escape(text)

    rendered_tokens = []
    for token in parse_prompt(text):
        if is_structural_mod_marker(token):
            rendered_tokens.append(html.escape(token))
            continue

        token_html = html.escape(token)
        token_base = extract_node_metadata(token)["base_word"].strip()
        if token_base == replacement_base:
            token_html = f"<span style='background-color:#cfe8ff;color:#003b73;'>{token_html}</span>"
        rendered_tokens.append(token_html)

    return ", ".join(rendered_tokens)

def _highlight_duplicate_tokens(duplicate_token_marks):
    rendered_tokens = []
    for mark in duplicate_token_marks:
        token_html = html.escape(mark["token"])
        if mark["status"] == "remove":
            rendered_tokens.append(
                f"<span style='background-color:#ffd6a5;color:#7a0000;"
                f"border:1px solid #ff9f1c;'>{token_html}</span>"
            )
        elif mark["status"] == "preserve":
            rendered_tokens.append(
                f"<span style='background-color:#d8f3dc;color:#064e3b;"
                f"border:1px solid #95d5b2;'>{token_html}</span>"
            )
        else:
            rendered_tokens.append(token_html)
    return ", ".join(rendered_tokens)

def _shorten_preview_text(text: str, center_text: str = "", max_chars: int = 220) -> str:
    text = text or ""
    center_text = (center_text or "").strip()
    if len(text) <= max_chars:
        return text

    center_index = text.lower().find(center_text.lower()) if center_text else -1
    if center_index < 0:
        return text[:max_chars - 1].rstrip() + "..."

    half = max_chars // 2
    start = max(center_index - half, 0)
    end = min(start + max_chars, len(text))
    start = max(end - max_chars, 0)
    prefix = "... " if start > 0 else ""
    suffix = " ..." if end < len(text) else ""
    return prefix + text[start:end].strip() + suffix

def _batch_preview_focus_text(example, operation, search_text, edit_text):
    if operation in ("replace", "remove"):
        return search_text
    if operation == "add":
        return edit_text
    if operation == "remove_duplicates":
        for mark in example.get("duplicate_token_marks") or []:
            if mark.get("status") == "remove":
                return mark.get("token", "")
    return ""

def _removed_marker_preview(before: str, after: str, search_text: str, match_mode: str) -> str:
    if match_mode == "literal":
        query = (search_text or "").strip()
        if query and query in before:
            return before.replace(query, f"<removed: {query}>", 1)
        return before

    query = _batch_token_query(search_text, match_mode)
    if not query:
        return before

    from core.parser import extract_node_metadata, is_structural_mod_marker

    rendered_tokens = []
    marked = False
    for token in parse_prompt(before):
        if is_structural_mod_marker(token):
            rendered_tokens.append(token)
            continue
        token_base = extract_node_metadata(token)["base_word"].strip()
        matched = token_base == query if match_mode == "exact_token" else query in token_base
        if matched and not marked:
            rendered_tokens.append(f"<removed: {token}>")
            marked = True
        else:
            rendered_tokens.append(token)
    return ", ".join(rendered_tokens)

def render_batch_preview_text(
    text,
    operation,
    search_text,
    remove_match_mode,
    replace_match_mode,
    highlight=True,
    preview_side="before",
    replace_text="",
    duplicate_token_marks=None,
):
    match_mode = replace_match_mode if operation == "replace" else remove_match_mode
    if not highlight or operation == "add":
        body = html.escape(text)
    elif operation == "remove_duplicates" and preview_side == "before":
        body = _highlight_duplicate_tokens(
            duplicate_token_marks or get_duplicate_token_marks(text)
        )
    elif operation == "remove_duplicates":
        body = html.escape(text)
    elif preview_side == "after" and operation == "replace":
        if match_mode == "literal":
            body = _highlight_literal_matches(
                text,
                replace_text,
                style="background-color:#cfe8ff;color:#003b73;",
            )
        else:
            body = _highlight_replace_result_tokens(text, replace_text)
    elif match_mode == "literal":
        body = _highlight_literal_matches(text, search_text)
    else:
        body = _highlight_token_matches(text, search_text, match_mode)

    st.markdown(
        (
            "<div style='font-family:monospace;white-space:pre-wrap;"
            "background-color:#f6f8fa;border:1px solid #e5e7eb;"
            "border-radius:6px;padding:0.6rem 0.75rem;margin:0.15rem 0 0.5rem 0;'>"
            f"{body}</div>"
        ),
        unsafe_allow_html=True,
    )

def render_compact_batch_preview_example(
    example,
    operation,
    search_text,
    edit_text,
    remove_match_mode,
    replace_match_mode,
):
    focus_text = _batch_preview_focus_text(example, operation, search_text, edit_text)
    before_text = example["before"]
    after_text = example["after"]
    if operation == "remove":
        before_text = _removed_marker_preview(before_text, after_text, search_text, remove_match_mode)

    before_snippet = _shorten_preview_text(before_text, focus_text)
    after_snippet = _shorten_preview_text(after_text, edit_text if operation in ("add", "replace") else focus_text)

    with st.container(border=True):
        st.caption(f"{example['file']}:{example['line_number']}")
        if focus_text:
            st.caption(f"Matched: `{_short_preview(focus_text, 120)}`")
        placement = example.get("placement", {})
        if placement.get("reason"):
            st.caption(format_core_message_for_display(placement["reason"]))
        left_col, right_col = st.columns(2)
        with left_col:
            st.caption("Before")
            render_batch_preview_text(
                before_snippet,
                operation,
                search_text,
                remove_match_mode,
                replace_match_mode,
                highlight=operation in ("replace", "remove", "remove_duplicates"),
                preview_side="before",
                replace_text=edit_text,
                duplicate_token_marks=example.get("duplicate_token_marks"),
            )
        with right_col:
            st.caption("After")
            render_batch_preview_text(
                after_snippet,
                operation,
                search_text,
                remove_match_mode,
                replace_match_mode,
                highlight=operation == "replace",
                preview_side="after",
                replace_text=edit_text,
            )
        with st.expander("Full before / after", expanded=False):
            st.caption("Before")
            st.text(example["before"])
            st.caption("After")
            st.text(example["after"])

def sanitize_promptcloud_word(word) -> str:
    return " ".join(str(word or "").split())


def sanitize_promptcloud_frequencies(freq: dict) -> tuple[dict, int, int]:
    sanitized_freq = {}
    sanitized_count = 0
    dropped_count = 0
    for raw_word, count in (freq or {}).items():
        clean_word = sanitize_promptcloud_word(raw_word)
        if not clean_word:
            dropped_count += 1
            continue
        if clean_word != str(raw_word or ""):
            sanitized_count += 1
        sanitized_freq[clean_word] = sanitized_freq.get(clean_word, 0) + count
    return sanitized_freq, sanitized_count, dropped_count


def line_ids_containing_word(project, word: str):
    from core.parser import extract_node_metadata, is_structural_mod_marker

    target = (word or "").strip()
    if not project or not target:
        return []
    target_promptcloud_key = sanitize_promptcloud_word(target)

    result = []
    for line in project.prompt_lines:
        if not is_gallery_operation_prompt_line(line):
            continue
        line_tokens = [
            str(token or "").strip()
            for token in (getattr(line, "tokens", []) or [])
        ]
        line_promptcloud_keys = [sanitize_promptcloud_word(token) for token in line_tokens]
        if target in line_tokens or target_promptcloud_key in line_promptcloud_keys:
            result.append(line.id)
            continue

        matched = False
        for token in parse_prompt(line.current_text):
            if is_structural_mod_marker(token):
                continue
            token_base = extract_node_metadata(token)["base_word"].strip()
            if (
                token == target
                or token_base == target
                or sanitize_promptcloud_word(token) == target_promptcloud_key
                or sanitize_promptcloud_word(token_base) == target_promptcloud_key
            ):
                matched = True
                break
        if matched:
            result.append(line.id)
    return result

def build_promptcloud_token_frequencies(project):
    from core.parser import extract_node_metadata, is_structural_mod_marker

    token_freq = {}
    token_group_freq = {}
    if not project:
        return token_freq, token_group_freq

    for line in getattr(project, "prompt_lines", []):
        if not is_gallery_operation_prompt_line(line):
            continue
        for token in getattr(line, "tokens", []) or []:
            token_key = str(token or "").strip()
            if not token_key or is_structural_mod_marker(token_key):
                continue
            meta = extract_node_metadata(token_key)
            group = meta.get("group", "default")
            token_freq[token_key] = token_freq.get(token_key, 0) + 1
            token_group_freq.setdefault(group, {})
            token_group_freq[group][token_key] = token_group_freq[group].get(token_key, 0) + 1

    return token_freq, token_group_freq

def render_line_groups_section(project):
    st.markdown("---")
    with st.expander("Illustration Groups", expanded=False):
        if is_free():
            st.info("Illustration Groups are available in Pro.")
            return

        selected_line_ids = get_selected_line_ids(project)
        groups = get_project_line_groups(project)
        selected_set = set(selected_line_ids)
        valid_selected = [
            line
            for line in project.prompt_lines
            if line.id in selected_set and is_gallery_operation_prompt_line(line)
        ]

        st.caption(f"Selected lines: {len(valid_selected)}")
        if valid_selected:
            selected_preview = ", ".join(
                f"{line.original_file_name}:{line.original_index + 1}"
                for line in valid_selected[:5]
            )
            if len(valid_selected) > 5:
                selected_preview += f", +{len(valid_selected) - 5} more"
            st.caption(selected_preview)

        group_name = st.text_input("Group name", key="line_group_name")
        clean_group_name = group_name.strip()
        create_error = None
        if not clean_group_name:
            create_error = "Group name is required."
        elif clean_group_name in groups:
            create_error = "A group with this name already exists."
        elif not valid_selected:
            create_error = "Select lines before creating a group."

        if create_error:
            st.caption(create_error)

        if st.button("Create Group from Selected Illustrations", disabled=bool(create_error), key="line_group_create_btn"):
            push_history()
            if create_line_group(st.session_state.project, clean_group_name, selected_line_ids):
                st.session_state.pop("batch_edit_preview", None)
                st.rerun()
            st.warning("Could not create group.")

        if not groups:
            st.info("No line groups yet.")
            return

        st.markdown("**Existing groups**")
        for group_name in sorted(groups):
            valid_ids = resolve_line_group_ids(project, group_name)
            sample_lines = [
                get_line_by_id(project, line_id)
                for line_id in valid_ids[:3]
            ]
            sample_label = ", ".join(
                f"{line.original_file_name}:{line.original_index + 1}"
                for line in sample_lines
                if line
            )
            if len(valid_ids) > 3:
                sample_label += f", +{len(valid_ids) - 3} more"
            if not sample_label:
                sample_label = "Empty"

            c1, c2 = st.columns([0.8, 0.2])
            with c1:
                st.write(f"**{group_name}** ({len(valid_ids)} lines)")
                st.caption(sample_label)
            with c2:
                if st.button("Delete", key=f"delete_line_group_{group_name}"):
                    push_history()
                    delete_line_group(st.session_state.project, group_name)
                    st.session_state.pop("batch_edit_preview", None)
                    st.rerun()

def initialize_batch_edit_defaults():
    defaults = {
        "batch_edit_replace_match_mode": "contains_token",
        "batch_edit_remove_mode": "all",
    }
    for key, value in defaults.items():
        if key not in st.session_state:
            st.session_state[key] = value

def get_focus_token_node_pairs(project, target_line):
    pairs = []
    node_path = list(getattr(target_line, "node_path", []) or [])
    for index, token in enumerate(getattr(target_line, "tokens", []) or []):
        node_id = node_path[index] if index < len(node_path) else None
        selectable = (
            bool(node_id)
            and node_id in getattr(project, "nodes", {})
            and not token.startswith("<mod:")
            and not token.startswith("</mod:")
        )
        pairs.append({
            "index": index,
            "token": token,
            "node_id": node_id,
            "selectable": selectable,
        })
    return pairs

def render_focus_edit_token_picker(project, target_line, label="Raw Prompt Tokens"):
    token_pairs = get_focus_token_node_pairs(project, target_line)
    if not token_pairs:
        return

    with st.expander(label, expanded=False):
        st.caption("Select a focused-line token for graph operations and Propagate Edit.")
        selected_ids = set(st.session_state.get("selected_node_ids", []))
        selected_pair = next(
            (
                pair
                for pair in token_pairs
                if pair["selectable"] and pair["node_id"] in selected_ids
            ),
            None,
        )
        if selected_pair:
            st.caption(f"Selected: `{selected_pair['token']}`")

        columns_per_row = 4
        for row_start in range(0, len(token_pairs), columns_per_row):
            cols = st.columns(columns_per_row)
            for offset, pair in enumerate(token_pairs[row_start:row_start + columns_per_row]):
                token = pair["token"]
                node_id = pair["node_id"]
                is_selected = pair["selectable"] and node_id in selected_ids
                label = f"{'✓ ' if is_selected else ''}{_short_preview(token, 32)}"
                help_text = token
                with cols[offset]:
                    if st.button(
                        label,
                        key=f"focus_token_picker_{target_line.id}_{pair['index']}",
                        disabled=not pair["selectable"],
                        help=help_text,
                        width="stretch",
                    ):
                        st.session_state.selected_node_ids = [node_id]
                        st.session_state.highlighted_line_id = target_line.id
                        st.session_state.connect_mode = False
                        st.session_state.connect_nodes = []
                        st.session_state.pop("focus_propagation_preview", None)
                        st.rerun()

def render_focus_prompt_preview_tokens(project, target_line):
    token_pairs = get_focus_token_node_pairs(project, target_line)
    if not token_pairs:
        st.caption("No prompt tokens available.")
        return

    selected_ids = set(st.session_state.get("selected_node_ids", []))
    selectable_pairs = [pair for pair in token_pairs if pair["selectable"]]
    if not selectable_pairs:
        st.caption(", ".join(pair["token"] for pair in token_pairs))
        return

    option_lookup = {pair["index"]: pair for pair in selectable_pairs}
    selected_index = next(
        (
            pair["index"]
            for pair in selectable_pairs
            if pair["node_id"] in selected_ids
        ),
        None,
    )
    selected_index = st.pills(
        "Prompt Preview tokens",
        options=[pair["index"] for pair in selectable_pairs],
        default=selected_index,
        format_func=lambda index: f"{option_lookup[index]['token']},",
        key=f"focus_prompt_preview_tokens_{target_line.id}_{selected_index if selected_index is not None else 'none'}",
        label_visibility="collapsed",
        width="stretch",
    )

    if selected_index is None:
        return

    selected_pair = option_lookup[selected_index]
    node_id = selected_pair["node_id"]
    if selected_ids == {node_id}:
        return

    st.session_state.selected_node_ids = [node_id]
    st.session_state.highlighted_line_id = target_line.id
    st.session_state.connect_mode = False
    st.session_state.connect_nodes = []
    st.session_state.pop("focus_propagation_preview", None)
    st.rerun()

def render_focus_edit_propagation_section(project, target_line):
    st.markdown("#### Propagate Edit")
    if is_free():
        st.info("Propagate Edit is available in Pro.")
        return

    st.caption("Apply a tested one-token insert or replacement from this focused line to other lines.")

    selected_source_node_ids = [
        node_id
        for node_id in st.session_state.get("selected_node_ids", [])
        if node_id in getattr(target_line, "node_path", []) and node_id in getattr(project, "nodes", {})
    ]
    if not selected_source_node_ids:
        st.info("Select one token in the focused line graph before propagating.")
        return

    source_node = project.nodes[selected_source_node_ids[0]]
    st.caption(f"Source token: `{source_node.display}`")

    selected_line_ids = get_selected_line_ids(project)
    scope_options = {"all": "All Illustrations"}
    groups = get_project_line_groups(project)
    for group_name in sorted(groups):
        valid_ids = resolve_line_group_ids(project, group_name)
        if valid_ids:
            scope_options[f"group::{group_name}"] = f"Illustration Group: {group_name} ({len(valid_ids)} illustrations)"
    if selected_line_ids:
        scope_options["selected"] = f"Selected Illustrations ({len(selected_line_ids)})"

    if st.session_state.get("focus_propagation_scope") not in scope_options:
        st.session_state.focus_propagation_scope = "all"

    c1, c2, c3 = st.columns([1, 1, 1.3])
    with c1:
        operation = st.selectbox(
            "Operation",
            options=["insert", "replace"],
            format_func=lambda value: {
                "insert": "Insert token",
                "replace": "Replace token",
            }[value],
            key="focus_propagation_operation",
        )
    with c2:
        scope_key = st.selectbox(
            "Target",
            options=list(scope_options.keys()),
            format_func=lambda value: scope_options[value],
            key="focus_propagation_scope",
        )
    with c3:
        edit_token = st.text_input(
            "Token",
            key="focus_propagation_edit_token",
            help="One prompt token only. Module tags and multi-token propagation are out of scope for v1.",
        )

    if scope_key == "all":
        target_line_ids = None
    elif scope_key == "selected":
        target_line_ids = selected_line_ids
    elif scope_key.startswith("group::"):
        target_line_ids = resolve_line_group_ids(project, scope_key[len("group::"):])
    else:
        target_line_ids = []

    validation_error = None
    edit_tokens = parse_prompt(edit_token or "")
    if not edit_token.strip():
        validation_error = "Token is required."
    elif len(edit_tokens) != 1:
        validation_error = "Propagation supports one prompt token."
    elif edit_tokens[0].startswith("<mod:") or edit_tokens[0].startswith("</mod:"):
        validation_error = "Module tags are not supported in propagation v1."
    elif target_line_ids == []:
        validation_error = "No target lines."
    elif focus_line_has_unsaved_edits(target_line):
        validation_error = "Save Focus Edit changes before propagating."

    signature = {
        "source_line_id": target_line.id,
        "selected_node_ids": tuple(selected_source_node_ids),
        "operation": operation,
        "scope_key": scope_key,
        "target_line_ids": tuple(target_line_ids) if target_line_ids is not None else None,
        "edit_token": edit_token,
    }

    if validation_error:
        st.warning(validation_error)

    if st.button("Preview Propagation", disabled=bool(validation_error), key="focus_propagation_preview_btn"):
        preview = preview_focus_edit_propagation(
            project,
            target_line.id,
            selected_source_node_ids,
            operation,
            edit_token,
            target_line_ids=target_line_ids,
        )
        st.session_state.focus_propagation_preview = {
            "signature": signature,
            "preview": preview,
        }

    preview_state = st.session_state.get("focus_propagation_preview")
    preview_current = preview_state and preview_state.get("signature") == signature
    if not preview_current:
        if preview_state:
            st.caption("Propagation preview is out of date. Run preview again.")
        return

    preview = preview_state["preview"]
    if preview.get("error"):
        st.warning(preview["error"])
        return

    metric_cols = st.columns(3)
    metric_cols[0].metric("Target lines", preview["target_line_count"])
    metric_cols[1].metric("Affected lines", preview["affected_line_count"])
    metric_cols[2].metric("Skipped tags", preview["skipped_module_structure_count"])

    if preview["affected_line_count"] == 0:
        st.warning("No lines will change.")
    if preview["skipped_module_structure_count"]:
        st.warning("Some lines were skipped because the edit would change module tag structure.")

    if st.button(
        "Apply Propagation",
        type="primary",
        disabled=preview["affected_line_count"] == 0,
        key="focus_propagation_apply_btn",
    ):
        push_history()
        prev_focus = st.session_state.get("focused_line_id")
        st.session_state.project = apply_focus_edit_propagation(
            st.session_state.project,
            target_line.id,
            selected_source_node_ids,
            operation,
            edit_token,
            target_line_ids=target_line_ids,
        )
        restore_focus_after_graph_update(prev_focus)
        sanitize_selected_node_ids(st.session_state.project)
        sync_text_areas()
        st.session_state.pop("focus_propagation_preview", None)
        st.rerun()

    for example in preview["examples"]:
        render_compact_batch_preview_example(
            example,
            "add" if operation == "insert" else "replace",
            preview.get("source_context", {}).get("token", ""),
            edit_token,
            "exact_token",
            "exact_token",
        )

