def sync_project_module_inspector_type_widget_state(module_name) -> None:
    widget_key = (
        f"_project_module_inspector_type_widget_{module_name}"
    )
    durable_key = f"project_module_inspector_type_{module_name}"
    widget_type = st.session_state.get(widget_key)
    if widget_type in MODULE_TYPES:
        st.session_state[durable_key] = widget_type


def prepare_project_module_inspector_min_match_widget_state(
    module_library,
    module_name,
    body_tokens,
) -> int:
    durable_key = f"project_module_inspector_min_match_{module_name}"
    widget_key = (
        f"_project_module_inspector_min_match_widget_{module_name}"
    )
    maximum = max(1, len(body_tokens))
    saved_min_match = get_module_min_match_tokens(module_library, module_name)
    try:
        default_min_match = int(saved_min_match)
    except (TypeError, ValueError):
        default_min_match = maximum
    if not default_min_match:
        default_min_match = maximum
    default_min_match = max(1, min(default_min_match, maximum))

    durable_value = st.session_state.get(durable_key, default_min_match)
    try:
        durable_min_match = int(durable_value)
    except (TypeError, ValueError):
        durable_min_match = default_min_match
    durable_min_match = max(1, min(durable_min_match, maximum))
    st.session_state[durable_key] = durable_min_match
    st.session_state[widget_key] = durable_min_match
    return durable_min_match


def sync_project_module_inspector_min_match_widget_state(
    module_name,
) -> None:
    widget_key = (
        f"_project_module_inspector_min_match_widget_{module_name}"
    )
    durable_key = f"project_module_inspector_min_match_{module_name}"
    try:
        st.session_state[durable_key] = int(
            st.session_state.get(widget_key, 1)
        )
    except (TypeError, ValueError):
        st.session_state[durable_key] = 1


@profiled_render("Project Module Inspector render")
def render_project_module_inspector_section(project):
    with st.expander("Project Module Editor", expanded=False):
        if not project:
            st.info("Load project first.")
            return
        if is_free():
            st.info("Project Module Inspector is available in Pro.")
            return

        module_library = get_project_module_library(project)
        module_names = sorted(module_library)
        if not module_names:
            st.info("Create or load a project module before editing it.")
            return

        prepare_project_module_inspector_selection_widget_state(module_names)
        module_name = st.selectbox(
            "Project module",
            options=module_names,
            key="_project_module_inspector_name_widget",
            on_change=sync_project_module_inspector_selection_widget_state,
        )
        body_key = f"project_module_inspector_body_{module_name}"
        core_key = f"project_module_inspector_core_{module_name}"
        type_key = f"project_module_inspector_type_{module_name}"
        min_match_key = (
            f"project_module_inspector_min_match_{module_name}"
        )
        body_widget_key = (
            f"_project_module_inspector_body_widget_{module_name}"
        )
        core_widget_key = (
            f"_project_module_inspector_core_widget_{module_name}"
        )
        type_widget_key = (
            f"_project_module_inspector_type_widget_{module_name}"
        )
        min_match_widget_key = (
            f"_project_module_inspector_min_match_widget_{module_name}"
        )

        edited_body = prepare_project_module_inspector_body_widget_state(
            module_library,
            module_name,
        )
        edited_core_text = (
            prepare_project_module_inspector_core_widget_state(
                module_library,
                module_name,
            )
        )
        edited_type = prepare_project_module_inspector_type_widget_state(
            module_library,
            module_name,
        )
        edited_body_tokens = _module_tokens_from_body(edited_body)
        edited_min_match = (
            prepare_project_module_inspector_min_match_widget_state(
                module_library,
                module_name,
                edited_body_tokens,
            )
        )

        st.selectbox(
            "Module type",
            options=MODULE_TYPES,
            key=type_widget_key,
            on_change=sync_project_module_inspector_type_widget_state,
            args=(module_name,),
        )
        render_module_token_inspector(project, "project_module_inspector", module_name, body_key, core_key)

        with st.expander("Module Body (Advanced)", expanded=False):
            st.text_area(
                "Module body",
                height=110,
                key=body_widget_key,
                on_change=sync_project_module_inspector_body_widget_state,
                args=(module_name,),
            )
            edited_body = st.session_state[body_key]
            edited_body_tokens = _module_tokens_from_body(edited_body)
            st.text_area(
                "Core tokens",
                height=90,
                help="Enter one token per line or comma-separated tokens. Leave empty to use the default first body token.",
                key=core_widget_key,
                on_change=sync_project_module_inspector_core_widget_state,
                args=(module_name,),
            )
            edited_core_text = st.session_state[core_key]
        edited_core_tokens = _parse_module_rule_text(edited_core_text)
        st.number_input(
            "Minimum Matched Tokens",
            min_value=1,
            max_value=max(1, len(edited_body_tokens)),
            step=1,
            key=min_match_widget_key,
            on_change=sync_project_module_inspector_min_match_widget_state,
            args=(module_name,),
        )
        edited_type = st.session_state[type_key]
        edited_min_match = st.session_state[min_match_key]

        validation_error = None
        if not edited_body_tokens:
            validation_error = "Module body must contain at least one prompt token."
        else:
            validation_error = validate_library_module_body(module_name, edited_body)
        if validation_error:
            st.warning(validation_error)

        if st.button(
            "Save Project Module",
            type="primary",
            disabled=bool(validation_error),
            key=f"project_module_inspector_save_{module_name}",
        ):
            push_history()
            prev_focus = st.session_state.get("focused_line_id")
            set_module_entry(
                st.session_state.project,
                module_name,
                edited_body,
                edited_type,
                edited_core_tokens,
                int(edited_min_match),
            )
            st.session_state.project = build_graph(st.session_state.project)
            restore_focus_after_graph_update(prev_focus)
            sync_text_areas()
            st.session_state.pop("global_module_candidate_scan", None)
            st.success("Project module saved.")


def render_module_usage_inspection(selected_module, selected_report) -> None:
    status = "Enabled" if selected_report["enabled"] else "Disabled"
    st.caption(f"Type: {selected_report.get('module_type', 'generic')}")

    metric_cols = st.columns(3)
    metric_cols[0].metric("Illustrations", selected_report["line_count"])
    metric_cols[1].metric("Occurrences", selected_report["occurrence_count"])
    metric_cols[2].metric("Status", status)

    affected_lines = selected_report["lines"]
    if selected_report.get("library_body"):
        st.caption(f"Library: {_short_preview(selected_report['library_body'])}")
    st.caption(f"Showing {min(len(affected_lines), 20)} of {len(affected_lines)} affected lines.")
    for line_info in affected_lines[:20]:
        st.markdown(f"**{line_info['file']}:{line_info['line_number']}**")
        contents = line_info["inline_contents"] + line_info["range_contents"]
        if contents:
            st.caption(f"Contents: {_short_preview(', '.join(contents))}")
        if line_info["malformed"]:
            st.warning(" ".join(line_info["malformed"]))
        st.caption(f"Raw: {_short_preview(line_info['raw_text'])}")
        st.caption(f"Active: {_short_preview(line_info['active_preview'])}")
    if len(affected_lines) > 20:
        st.caption("Additional affected lines are hidden.")


def render_module_edit_scope_controls(selected_module) -> None:
    st.markdown("**Module Edit Scope**")
    if is_free():
        st.caption("Module Edit Scope is available in Pro.")
    else:
        if st.button("Use as Module Edit Scope", key="module_scope_use_btn"):
            st.session_state.module_edit_scope_name = selected_module
            st.rerun()

        active_scope = st.session_state.get("module_edit_scope_name")
        if active_scope:
            scope_preview = preview_module_scope(st.session_state.project, active_scope)
            st.caption(f"Current scope: {active_scope}")
            scope_metric_cols = st.columns(3)
            scope_metric_cols[0].metric("Illustrations", scope_preview["affected_line_count"])
            scope_metric_cols[1].metric("Tokens", scope_preview["token_count"])
            scope_metric_cols[2].metric("Malformed", scope_preview["malformed_count"])
            scope_detail_cols = st.columns(2)
            scope_detail_cols[0].metric("Inline", scope_preview["inline_module_count"])
            scope_detail_cols[1].metric("Range tokens", scope_preview["range_token_count"])

            for example in scope_preview["examples"][:10]:
                st.markdown(f"**{example['file']}:{example['line_number']}**")
                if example["inline_contents"]:
                    st.caption(f"Inline: {_short_preview(', '.join(example['inline_contents']))}")
                if example["range_tokens"]:
                    st.caption(f"Range: {_short_preview(', '.join(example['range_tokens']))}")
                if example["malformed_count"]:
                    st.warning(f"Malformed markers: {example['malformed_count']}")
                st.caption(f"Raw: {_short_preview(example['raw_text'])}")


def render_active_module_edit_scope_summary() -> None:
    active_scope = st.session_state.get("module_edit_scope_name")
    if not active_scope:
        st.caption("Active Edit Scope: none")
        return

    st.info(
        f"Active Edit Scope: {active_scope}\n\n"
        "Prompt editing is currently limited to this Module scope."
    )
    if st.button(
        "Clear Active Edit Scope",
        key="clear_active_module_edit_scope",
    ):
        clear_module_edit_scope()
        st.rerun()


def render_module_rename_controls(selected_module, module_names) -> None:
    if is_free():
        st.caption("Module Rename is available in Pro.")
    else:
        initialize_module_rename_new_name_draft()
        st.text_input(
            "New module name",
            key="_module_rename_new_name_widget",
            on_change=sync_module_rename_new_name_widget,
        )
        new_module_name = str(
            st.session_state.get("module_rename_new_name", "") or ""
        ).strip()
        rename_preview_state = st.session_state.get("module_rename_preview")
        if rename_preview_state and (
            rename_preview_state.get("old_name") != selected_module
            or rename_preview_state.get("new_name") != new_module_name
        ):
            clear_module_rename_preview()
            rename_preview_state = None

        invalid_new_name = (
            not new_module_name.strip()
            or any(ch in new_module_name for ch in ("<", ">", ",", "\n", "\r"))
        )
        name_exists = new_module_name in module_names and new_module_name != selected_module

        if invalid_new_name and new_module_name:
            st.warning("Use a non-empty name without <, >, comma, or newline.")
        if name_exists:
            st.warning("A module with that name already exists. Merge is not supported.")

        if st.button("Rename Module Preview", key="module_rename_preview_btn"):
            if invalid_new_name:
                st.warning("Use a non-empty name without <, >, comma, or newline.")
            elif name_exists:
                st.warning("A module with that name already exists. Merge is not supported.")
            elif new_module_name == selected_module:
                st.warning("Choose a different module name.")
            else:
                st.session_state.module_rename_preview = preview_rename_module(
                    st.session_state.project,
                    selected_module,
                    new_module_name,
                )
                st.rerun()

        rename_preview_state = st.session_state.get("module_rename_preview")
        if rename_preview_state:
            st.caption(f"{rename_preview_state['old_name']} -> {rename_preview_state['new_name']}")
            preview_cols = st.columns(2)
            preview_cols[0].metric("Affected lines", rename_preview_state["affected_line_count"])
            preview_cols[1].metric("Markers", rename_preview_state["marker_occurrence_count"])
            marker_cols = st.columns(3)
            marker_cols[0].metric("Inline", rename_preview_state["inline_occurrence_count"])
            marker_cols[1].metric("Open", rename_preview_state["open_marker_count"])
            marker_cols[2].metric("Close", rename_preview_state["close_marker_count"])
            if rename_preview_state["malformed_marker_count"]:
                st.warning(f"Malformed markers: {rename_preview_state['malformed_marker_count']}")

            for example in rename_preview_state["examples"]:
                st.markdown(f"**{example['file']}:{example['line_number']}**")
                st.caption(f"Before: {_short_preview(example['before'])}")
                st.caption(f"After: {_short_preview(example['after'])}")

            confirm_cols = st.columns(2)
            with confirm_cols[0]:
                if st.button("Confirm Rename Module", key="module_rename_confirm_btn"):
                    current_modules = get_available_modules(st.session_state.project)
                    if rename_preview_state.get("old_name") != selected_module or rename_preview_state.get("new_name") != new_module_name:
                        st.warning("Generate a new preview before confirming.")
                    elif new_module_name in current_modules and new_module_name != selected_module:
                        st.warning("A module with that name already exists. Merge is not supported.")
                    else:
                        old_module_was_disabled = selected_module in st.session_state.disabled_modules
                        push_history()
                        prev_focus = st.session_state.get("focused_line_id")
                        st.session_state.project = rename_module(
                            st.session_state.project,
                            selected_module,
                            new_module_name,
                        )
                        if st.session_state.get("module_edit_scope_name") == selected_module:
                            st.session_state.module_edit_scope_name = new_module_name
                        if old_module_was_disabled:
                            st.session_state.disabled_modules.discard(selected_module)
                            st.session_state.disabled_modules.add(new_module_name)
                        else:
                            st.session_state.disabled_modules.discard(new_module_name)
                        st.session_state.module_rename_selected = new_module_name
                        restore_focus_after_graph_update(prev_focus)
                        sync_text_areas()
                        clear_module_rename_preview()
                        st.rerun()
            with confirm_cols[1]:
                if st.button("Cancel", key="module_rename_cancel_btn"):
                    clear_module_rename_preview()
                    st.rerun()


def render_module_inspector_edit_scope_section() -> None:
    with st.sidebar.expander(
        "Module Inspector / Active Edit Scope",
        expanded=False,
    ):
        if st.session_state.project:
            module_report = inspect_modules(st.session_state.project, st.session_state.disabled_modules)
            module_names = sorted(module_report.keys())
            clear_module_edit_scope_if_missing(st.session_state.project)
            render_active_module_edit_scope_summary()
            if module_names:
                selected_module = st.selectbox("Module", module_names, key="module_inspector_selected")
                selected_report = module_report[selected_module]
                render_module_usage_inspection(selected_module, selected_report)

                st.markdown("---")
                render_module_edit_scope_controls(selected_module)
            else:
                clear_module_edit_scope()
                st.info("No modules detected.")
        else:
            st.info("Load project first.")


def render_module_rename_authoring_section(project) -> None:
    with st.expander("Rename Module", expanded=False):
        module_report = inspect_modules(
            project,
            st.session_state.disabled_modules,
        )
        module_names = sorted(module_report.keys())
        if not module_names:
            initialize_module_rename_selection(module_names)
            st.info("No modules detected.")
            return

        initialize_module_rename_selection(module_names)
        selected_module = st.selectbox(
            "Module",
            module_names,
            key="_module_rename_selected_widget",
            on_change=sync_module_rename_selected_widget,
        )
        if st.session_state.get("module_rename_selected") != selected_module:
            st.session_state.module_rename_selected = selected_module
        render_module_rename_controls(selected_module, module_names)


def _attribute_group_tokens_from_text(text: str) -> list[str]:
    return _parse_module_rule_text(text)


def _format_attribute_group_tokens(tokens) -> str:
    return "\n".join(str(token or "").strip() for token in tokens or [] if str(token or "").strip())


def _attribute_group_slot_options(current_slot: str = "") -> list[str]:
    options = [slot for slot in SUGGESTED_ATTRIBUTE_SLOTS if slot != "custom"]
    if current_slot and current_slot not in options:
        options.append(current_slot)
    options.append("custom")
    return options


def _create_attribute_group_from_tokens(project, group_name: str, slot: str, tokens: list[str]) -> str | None:
    group_key = normalize_attribute_group_name(group_name)
    normalized_slot = normalize_attribute_slot(slot)
    normalized_tokens = _attribute_group_tokens_from_text("\n".join(tokens or []))
    if not group_key or not normalized_slot or not normalized_tokens:
        return None
    groups = get_project_attribute_groups(project)
    if group_key in groups:
        return None
    groups[group_key] = {
        "name": str(group_name or "").strip(),
        "slot": normalized_slot,
        "tokens": normalized_tokens,
        "created_from": "sidebar_manager",
        "negative_tags": [],
        "negative_when_disabled": [],
        "negative_notes": "",
    }
    return group_key


@profiled_render("Attribute Group Sidebar Manager render")
def render_attribute_group_sidebar_manager(project):
    with st.expander("Attribute Groups", expanded=False):
        if not project:
            st.info("Load project first.")
            return
        if is_free():
            st.info("Attribute Groups are available in Pro.")
            return

        notice = st.session_state.pop("attribute_group_sidebar_notice", "")
        if notice:
            st.success(notice)

        groups = get_project_attribute_groups(project)
        selected_node_ids = [
            node_id for node_id in st.session_state.get("selected_node_ids", [])
            if node_id in getattr(project, "nodes", {})
        ]
        st.caption(f"選択中Node: {len(selected_node_ids)}")

        st.markdown("**新規Attribute Group**")
        new_group_name = st.text_input(
            "Group name",
            key="attribute_group_sidebar_create_name",
            placeholder="Milk Swimsuit",
        ).strip()
        create_slot_options = _attribute_group_slot_options()
        create_slot = st.selectbox(
            "Slot",
            options=create_slot_options,
            index=create_slot_options.index("outfit") if "outfit" in create_slot_options else 0,
            key="attribute_group_sidebar_create_slot",
        )
        create_custom_slot = st.text_input(
            "Custom Slot",
            key="attribute_group_sidebar_create_custom_slot",
            placeholder="optional_custom_slot",
        ).strip()
        create_slot_to_apply = create_custom_slot if create_slot == "custom" else create_slot
        create_tokens_text = st.text_area(
            "Tokens",
            key="attribute_group_sidebar_create_tokens",
            height=80,
            placeholder="1行1token、または comma-separated tokens",
        )
        create_tokens = _attribute_group_tokens_from_text(create_tokens_text)
        create_group_key = normalize_attribute_group_name(new_group_name)
        create_slot_key = normalize_attribute_slot(create_slot_to_apply)
        create_error = None
        if new_group_name and not create_group_key:
            create_error = "Use a group name with letters, numbers, underscores, hyphens, or spaces."
        elif create_group_key and create_group_key in groups:
            create_error = "同名のAttribute Groupが既にあります。"
        elif create_slot_to_apply and not create_slot_key:
            create_error = "Use a slot name with letters, numbers, underscores, hyphens, or spaces."
        elif new_group_name and not create_tokens:
            create_error = "Tokensを1つ以上入力してください。"
        if create_error:
            st.caption(create_error)
        if st.button(
            "Create Attribute Group",
            disabled=not new_group_name or bool(create_error),
            key="attribute_group_sidebar_create_btn",
        ):
            push_history()
            created_key = _create_attribute_group_from_tokens(
                st.session_state.project,
                new_group_name,
                create_slot_to_apply,
                create_tokens,
            )
            if not created_key:
                st.warning("Attribute Groupを作成できませんでした。")
                st.stop()
            st.session_state.attribute_group_sidebar_selected_pending = created_key
            st.session_state.attribute_group_sidebar_notice = f"Created Attribute Group: {new_group_name}"
            save_current_project_if_possible("attribute group created")
            st.rerun()

        st.divider()
        groups = get_project_attribute_groups(project)
        group_keys = sorted(groups)
        if not group_keys:
            st.caption("No Attribute Groups yet.")
            return

        pending_selection = st.session_state.pop("attribute_group_sidebar_selected_pending", "")
        if pending_selection in group_keys:
            st.session_state.attribute_group_sidebar_selected = pending_selection
        selected_state = st.session_state.get("attribute_group_sidebar_selected")
        if selected_state and selected_state not in group_keys:
            st.session_state.attribute_group_sidebar_selected = group_keys[0]
        selected_group_key = st.selectbox(
            "既存Attribute Group",
            options=group_keys,
            format_func=lambda key: (
                f"{groups[key].get('name', key)} [{groups[key].get('slot', '')}] · "
                f"{len(groups[key].get('tokens', []) or [])} tokens"
            ),
            key="attribute_group_sidebar_selected",
        )
        group = groups[selected_group_key]
        current_name = str(group.get("name", selected_group_key) or selected_group_key).strip()
        current_slot = str(group.get("slot", "") or "").strip()
        current_tokens = list(group.get("tokens", []) or [])
        current_token_keys = [get_token_attribute_key(token) for token in current_tokens]
        current_token_key_set = {token_key for token_key in current_token_keys if token_key}
        addable_selected_node_ids = [
            node_id for node_id in selected_node_ids
            if get_node_attribute_key(project, node_id) and get_node_attribute_key(project, node_id) not in current_token_key_set
        ]
        st.caption(f"Key: `{selected_group_key}`")
        st.caption(f"Created from: {group.get('created_from', 'unknown')}")

        edit_name = st.text_input(
            "Group name",
            value=current_name,
            key=f"attribute_group_sidebar_edit_name_{selected_group_key}",
        ).strip()
        edit_slot_options = _attribute_group_slot_options(current_slot)
        edit_slot = st.selectbox(
            "Slot",
            options=edit_slot_options,
            index=edit_slot_options.index(current_slot) if current_slot in edit_slot_options else 0,
            key=f"attribute_group_sidebar_edit_slot_{selected_group_key}_{current_slot}",
        )
        edit_custom_slot_default = current_slot if current_slot not in [slot for slot in SUGGESTED_ATTRIBUTE_SLOTS if slot != "custom"] else ""
        edit_custom_slot = st.text_input(
            "Custom Slot",
            value=edit_custom_slot_default,
            key=f"attribute_group_sidebar_edit_custom_slot_{selected_group_key}_{current_slot}",
            placeholder="optional_custom_slot",
        ).strip()
        edit_slot_to_apply = edit_custom_slot if edit_slot == "custom" else edit_slot
        edit_tokens_text = st.text_area(
            "Tokens",
            value=_format_attribute_group_tokens(current_tokens),
            height=110,
            key=f"attribute_group_sidebar_edit_tokens_{selected_group_key}",
        )
        edit_tokens = _attribute_group_tokens_from_text(edit_tokens_text)
        edit_group_key = normalize_attribute_group_name(edit_name)
        edit_slot_key = normalize_attribute_slot(edit_slot_to_apply)
        edit_error = None
        if not edit_name:
            edit_error = "Group name cannot be empty."
        elif not edit_group_key:
            edit_error = "Use a group name with letters, numbers, underscores, hyphens, or spaces."
        elif edit_group_key != selected_group_key and edit_group_key in groups:
            edit_error = "同名のAttribute Groupが既にあります。"
        elif not edit_slot_to_apply or not edit_slot_key:
            edit_error = "Slotを入力してください。"
        elif not edit_tokens:
            edit_error = "Tokensを1つ以上入力してください。"
        if edit_error:
            st.caption(edit_error)
        if st.button(
            "Save Attribute Group",
            type="primary",
            disabled=bool(edit_error),
            key=f"attribute_group_sidebar_save_{selected_group_key}",
        ):
            push_history()
            working_key = selected_group_key
            if edit_group_key != selected_group_key or edit_name != current_name:
                renamed_key = rename_attribute_group(st.session_state.project, selected_group_key, edit_name)
                if not renamed_key:
                    st.warning("Attribute Group名を保存できませんでした。")
                    st.stop()
                working_key = renamed_key
            if edit_slot_key != current_slot:
                if not set_attribute_group_slot(st.session_state.project, working_key, edit_slot_to_apply):
                    st.warning("Attribute Group slotを保存できませんでした。")
                    st.stop()
            next_token_keys = [get_token_attribute_key(token) for token in edit_tokens]
            if next_token_keys != current_token_keys:
                if not set_attribute_group_tokens(st.session_state.project, working_key, edit_tokens):
                    st.warning("Attribute Group tokensを保存できませんでした。")
                    st.stop()
            st.session_state.attribute_group_sidebar_selected_pending = working_key
            st.session_state.attribute_group_sidebar_notice = f"Saved Attribute Group: {edit_name}"
            save_current_project_if_possible("attribute group edited")
            st.rerun()

        if st.button(
            "選択中NodeをこのGroupへ追加",
            disabled=not addable_selected_node_ids,
            key=f"attribute_group_sidebar_add_selected_{selected_group_key}",
        ):
            push_history()
            added_count = add_nodes_to_attribute_group(
                st.session_state.project,
                selected_group_key,
                addable_selected_node_ids,
            )
            if added_count:
                st.session_state.attribute_group_sidebar_notice = f"{added_count} token(s)をAttribute Groupへ追加しました。"
                save_current_project_if_possible("selected nodes added to attribute group")
                st.rerun()
            st.info("追加できる新しいtokenはありません。")

        st.markdown("**Delete**")
        delete_confirm = st.checkbox(
            "削除を確認",
            value=False,
            key=f"attribute_group_sidebar_delete_confirm_{selected_group_key}",
        )
        if st.button(
            "Delete Attribute Group",
            disabled=not delete_confirm,
            key=f"attribute_group_sidebar_delete_{selected_group_key}",
        ):
            push_history()
            if not delete_attribute_group(st.session_state.project, selected_group_key):
                st.warning("Attribute Groupを削除できませんでした。")
                st.stop()
            st.session_state.attribute_group_sidebar_notice = f"Deleted Attribute Group: {current_name}"
            save_current_project_if_possible("attribute group deleted")
            st.rerun()


def _format_attribute_group_swap_option(groups: dict, group_key: str) -> str:
    group = groups.get(group_key, {}) or {}
    name = group.get("name", group_key) or group_key
    slot = group.get("slot", "") or ""
    token_count = len(group.get("tokens", []) or [])
    return f"{name} [{slot}] · {token_count} tokens"


def _attribute_group_swap_scope_label(scope: str) -> str:
    return {
        **GALLERY_SCOPE_DISPLAY_LABELS,
        "focused_line": "Focused Illustration",
    }.get(scope, "All Illustrations")


def _resolve_attribute_group_swap_targets(project, scope: str, selected_route_id: str = "") -> dict:
    selected_line_ids = get_selected_line_ids(project)
    if scope == "focused_line":
        focused_line = get_line_by_id(project, st.session_state.get("focused_line_id"))
        target_lines = [focused_line] if is_gallery_operation_prompt_line(focused_line) else []
        warnings = [] if target_lines else ["Focused Illustration is not available for Attribute Group Swap."]
        return {
            "scope": scope,
            "route_id": "",
            "route_label": "",
            "route_line_count": None,
            "target_lines": target_lines,
            "target_line_ids": [line.id for line in target_lines],
            "warnings": warnings,
        }
    if scope == "selected_route":
        return resolve_gallery_operation_targets(
            project,
            "selected_route",
            route_id=selected_route_id,
            selected_line_ids=selected_line_ids,
        )
    return resolve_gallery_operation_targets(
        project,
        scope if scope in {"all_lines", "current_route", "selected_lines"} else "all_lines",
        selected_line_ids=selected_line_ids,
    )


