@profiled_render("Attribute Group Swap render")
def render_attribute_group_swap_section(project):
    with st.expander("Attribute Group Swap", expanded=False):
        if not project:
            st.info("Load project first.")
            return
        if is_free():
            st.info("Attribute Group Swap is available in Pro.")
            return

        notice = st.session_state.pop("attribute_group_swap_notice", "")
        if notice:
            st.success(notice)

        groups = get_attribute_groups_snapshot(project)
        group_keys = sorted(groups)
        if len(group_keys) < 2:
            st.info("Attribute Group Swap requires at least two Attribute Groups.")
            return

        st.caption(
            "Project内Attribute Group同士をPreview後に差し替えます。"
            "positive prompt tokensのみ対象で、negative metadataは変更しません。"
        )

        prepare_attribute_group_swap_from_widget_state(group_keys)
        from_group_key = st.selectbox(
            "From Attribute Group",
            options=group_keys,
            format_func=lambda key: _format_attribute_group_swap_option(groups, key),
            key="_attribute_group_swap_from_widget",
            on_change=sync_attribute_group_swap_from_widget_state,
        )
        prepare_attribute_group_swap_to_widget_state(
            group_keys,
            from_group_key,
        )
        to_group_key = st.selectbox(
            "To Attribute Group",
            options=group_keys,
            format_func=lambda key: _format_attribute_group_swap_option(groups, key),
            key="_attribute_group_swap_to_widget",
            on_change=sync_attribute_group_swap_to_widget_state,
        )

        scope_options = [
            "all_lines",
            "current_route",
            "selected_route",
            "selected_routes",
            "selected_lines",
            "focused_line",
        ]
        prepare_attribute_group_swap_scope_widget_state(scope_options)
        scope = st.radio(
            "Target scope",
            options=scope_options,
            format_func=_attribute_group_swap_scope_label,
            horizontal=False,
            key="_attribute_group_swap_scope_widget",
            on_change=sync_attribute_group_swap_scope_widget_state,
        )

        route_options = _gallery_route_options_with_counts(project)
        route_lookup = {route.get("route_id", ""): route for route in route_options}
        selected_route_id = ""
        if scope == "selected_route":
            if route_options:
                route_ids = [
                    route.get("route_id", "")
                    for route in route_options
                ]
                prepare_attribute_group_swap_selected_route_widget_state(
                    route_ids,
                )
                selected_route_id = st.selectbox(
                    "Scene",
                    route_ids,
                    format_func=lambda route_id: _format_gallery_route_option(route_lookup.get(route_id, {})),
                    key="_attribute_group_swap_selected_route_id_widget",
                    on_change=sync_attribute_group_swap_selected_route_widget_state,
                )
            else:
                prepare_attribute_group_swap_selected_route_widget_state([])
                st.warning("No Scenes are available in this project.")

        prepare_attribute_group_swap_require_full_match_widget_state()
        require_full_match = st.checkbox(
            "From Groupが完全一致するイラストだけ対象にする",
            key="_attribute_group_swap_require_full_match_widget",
            on_change=sync_attribute_group_swap_require_full_match_widget_state,
        )

        if scope == "selected_routes":
            _render_selected_routes_attribute_group_swap_flow(
                project,
                groups,
                from_group_key,
                to_group_key,
                require_full_match,
                key_prefix="attribute_group_swap",
                preview_state_key="attribute_group_swap_preview",
                feedback_mode="sidebar",
            )
            return

        target_resolution = _resolve_attribute_group_swap_targets(project, scope, selected_route_id)
        target_line_ids = target_resolution["target_line_ids"]
        st.caption(f"Target scope: {_attribute_group_swap_scope_label(scope)}")
        if target_resolution.get("route_id"):
            st.caption(
                f"Scene: {target_resolution.get('route_label') or '(unnamed)'} "
                f"({target_resolution.get('route_line_count') or len(target_line_ids)} illustrations)"
            )
        st.caption(f"Target illustrations: {len(target_line_ids)}")
        for warning in target_resolution.get("warnings", [])[:3]:
            st.warning(warning)

        preview_signature = {
            "from_group_key": from_group_key,
            "to_group_key": to_group_key,
            "scope": scope,
            "selected_route_id": selected_route_id,
            "target_line_ids": tuple(target_line_ids),
            "require_full_match": bool(require_full_match),
        }

        validation_error = None
        if from_group_key == to_group_key:
            validation_error = "FromとToには異なるAttribute Groupを選択してください。"
        elif not target_line_ids:
            validation_error = "Target Illustrationがありません。"
        if validation_error:
            st.warning(validation_error)

        if st.button(
            "Preview Attribute Swap",
            disabled=bool(validation_error),
            key="attribute_group_swap_preview_btn",
        ):
            st.session_state.attribute_group_swap_preview = {
                "signature": preview_signature,
                "preview": preview_attribute_group_swap(
                    project,
                    from_group_key,
                    to_group_key,
                    target_line_ids=target_line_ids,
                    require_full_match=require_full_match,
                ),
            }

        preview_state = st.session_state.get("attribute_group_swap_preview")
        preview_current = preview_state and preview_state.get("signature") == preview_signature
        if not preview_current:
            if preview_state:
                st.caption("Attribute Group Swap preview is stale. Preview again before applying.")
            return

        preview = preview_state["preview"]
        for warning in preview.get("warnings", []):
            st.warning(warning)

        st.markdown("**Preview Summary**")
        cols = st.columns(3)
        cols[0].metric("Target lines", preview["target_line_count"])
        cols[1].metric("Affected", preview["affected_line_count"])
        cols[2].metric("No match", preview["no_match_line_count"])
        cols2 = st.columns(2)
        cols2[0].metric("Full match", preview["full_match_line_count"])
        cols2[1].metric("Partial match", preview["partial_match_line_count"])

        st.caption(f"Tokens to remove: {_short_preview(', '.join(preview['tokens_to_remove']) or '(none)', 220)}")
        st.caption(f"Tokens to add: {_short_preview(', '.join(preview['tokens_to_add']) or '(none)', 220)}")
        st.caption(f"Shared tokens preserved: {_short_preview(', '.join(preview['shared_tokens']) or '(none)', 220)}")
        st.caption(
            "Already present To tokens: "
            f"{_short_preview(', '.join(preview['already_present_to_tokens']) or '(none)', 220)}"
        )

        if preview["affected_line_count"] == 0:
            st.info("Attribute Group Swapで変更されるイラストはありません。")

        if st.button(
            "Apply Attribute Swap",
            type="primary",
            disabled=preview["affected_line_count"] == 0,
            key="attribute_group_swap_apply_btn",
        ):
            push_history()
            prev_focus = st.session_state.get("focused_line_id")
            st.session_state.project = apply_attribute_group_swap(
                st.session_state.project,
                from_group_key,
                to_group_key,
                target_line_ids=target_line_ids,
                require_full_match=require_full_match,
            )
            restore_focus_after_graph_update(prev_focus)
            st.session_state.attribute_group_swap_notice = (
                f"Attribute Group Swap applied to {preview['affected_line_count']} line(s)."
            )
            st.session_state.pop("attribute_group_swap_preview", None)
            save_current_project_if_possible("attribute group swap applied")
            st.rerun()

        st.markdown("**Examples**")
        for example in preview.get("examples", [])[:10]:
            st.markdown(f"**{example['display_id']}**")
            st.caption(
                f"Illustration id: `{example['line_id']}` / index: {example['line_index']} / "
                f"matched: {_short_preview(', '.join(example['matched_from_tokens']), 160)}"
            )
            st.caption(f"Removed: {_short_preview(', '.join(example['removed_tokens']) or '(none)', 160)}")
            st.caption(f"Added: {_short_preview(', '.join(example['added_tokens']) or '(none)', 160)}")
            st.caption("Before")
            render_batch_preview_text(
                example["before"],
                "attribute_group_swap",
                "",
                "exact_token",
                "exact_token",
                highlight=False,
            )
            st.caption("After")
            render_batch_preview_text(
                example["after"],
                "attribute_group_swap",
                "",
                "exact_token",
                "exact_token",
                highlight=False,
            )


def get_selected_line_for_attribute_preview(project):
    if not project:
        return None
    candidate_ids = [
        st.session_state.get("focused_line_id"),
        st.session_state.get("highlighted_line_id"),
        st.session_state.get("gallery_expanded_line_id"),
    ]
    selected_lines = st.session_state.get("selected_lines", {})
    if isinstance(selected_lines, dict):
        candidate_ids.extend(line_id for line_id, selected in selected_lines.items() if selected)
    for line_id in candidate_ids:
        line = get_line_by_id(project, line_id)
        if line:
            return line
    return None

def _attribute_group_token_keys(tokens) -> list[str]:
    normalized_tokens = []
    seen = set()
    for token in tokens or []:
        token_key = get_token_attribute_key(token)
        if not token_key or token_key in seen:
            continue
        normalized_tokens.append(token_key)
        seen.add(token_key)
    return normalized_tokens


def render_attribute_group_add_tokens_and_propagate(project, selected_group: str, group: dict, rows: list[dict]) -> None:
    group_key = normalize_attribute_group_name(selected_group)
    current_tokens = _attribute_group_token_keys([row.get("token") for row in rows] or group.get("tokens", []))
    current_token_set = set(current_tokens)

    st.markdown("**Add Tokens to Group**")
    st.caption("改行区切り、または comma-separated tokens で追加できます。既存tokenは重複追加されません。")
    add_tokens_text = st.text_area(
        "Tokens to add",
        key=f"attribute_group_manual_add_tokens_{group_key}",
        height=80,
        placeholder="bra\nribbon",
    )
    parsed_add_tokens = _attribute_group_token_keys(_attribute_group_tokens_from_text(add_tokens_text))
    newly_added_tokens = [token for token in parsed_add_tokens if token not in current_token_set]
    duplicate_add_tokens = [token for token in parsed_add_tokens if token in current_token_set]
    if duplicate_add_tokens:
        st.caption(f"Already in group: {_short_preview(', '.join(duplicate_add_tokens), 180)}")
    if parsed_add_tokens and not newly_added_tokens:
        st.info("No new tokens were added. Input tokens may already be in this group.")
    if st.button(
        "Add Tokens to Group",
        key=f"attribute_group_manual_add_btn_{group_key}",
        disabled=not newly_added_tokens,
    ):
        previous_tokens = list(current_tokens)
        next_tokens = previous_tokens + newly_added_tokens
        push_history()
        if not set_attribute_group_tokens(st.session_state.project, selected_group, next_tokens):
            st.warning("Attribute group tokens could not be updated.")
            st.stop()
        st.session_state.attribute_group_last_added_tokens = {
            "group_key": group_key,
            "previous_tokens": previous_tokens,
            "added_tokens": newly_added_tokens,
            "next_tokens": next_tokens,
        }
        st.session_state.attribute_group_propagate_nonce = st.session_state.get("attribute_group_propagate_nonce", 0) + 1
        st.session_state.attribute_group_inspector_notice = (
            f"Added {len(newly_added_tokens)} token(s) to {group.get('name', selected_group)}."
        )
        save_current_project_if_possible("attribute group tokens added")
        st.rerun()

    st.markdown("**Propagate Added Tokens**")
    last_added = st.session_state.get("attribute_group_last_added_tokens", {})
    last_added_for_group = last_added if last_added.get("group_key") == group_key else {}
    if last_added_for_group.get("added_tokens"):
        st.caption(f"Last added: {_short_preview(', '.join(last_added_for_group['added_tokens']), 180)}")
    else:
        st.caption("Manual tokens can be propagated even when there is no recent Add Tokens action.")

    nonce = st.session_state.get("attribute_group_propagate_nonce", 0)
    default_propagate_tokens = _format_attribute_group_tokens(last_added_for_group.get("added_tokens", []))
    propagate_tokens_text = st.text_area(
        "Tokens to propagate",
        value=default_propagate_tokens,
        key=f"attribute_group_propagate_tokens_{group_key}_{nonce}",
        height=70,
        placeholder="bra, ribbon",
    )
    tokens_to_propagate = _attribute_group_token_keys(_attribute_group_tokens_from_text(propagate_tokens_text))
    if last_added_for_group.get("previous_tokens"):
        previous_tokens = _attribute_group_token_keys(last_added_for_group.get("previous_tokens", []))
    else:
        propagate_set = set(tokens_to_propagate)
        previous_tokens = [token for token in current_tokens if token not in propagate_set]

    st.caption(f"Previous group tokens: {_short_preview(', '.join(previous_tokens) or '(none)', 180)}")
    st.caption(f"Tokens to propagate: {_short_preview(', '.join(tokens_to_propagate) or '(none)', 180)}")

    scope_options = ["all_lines", "current_route", "selected_route", "selected_lines", "focused_line"]
    scope = st.radio(
        "Target scope",
        options=scope_options,
        format_func=_attribute_group_swap_scope_label,
        horizontal=False,
        key=f"attribute_group_propagate_scope_{group_key}",
    )
    route_options = _gallery_route_options_with_counts(project)
    route_lookup = {route.get("route_id", ""): route for route in route_options}
    selected_route_id = ""
    if scope == "selected_route":
        if route_options:
            selected_route_id = st.selectbox(
                "Scene",
                [route.get("route_id", "") for route in route_options],
                format_func=lambda route_id: _format_gallery_route_option(route_lookup.get(route_id, {})),
                key=f"attribute_group_propagate_selected_route_id_{group_key}",
            )
        else:
            st.warning("No Scenes are available in this project.")

    require_full_match = st.checkbox(
        "追加前Group tokensが完全一致するイラストだけ対象にする",
        value=False,
        key=f"attribute_group_propagate_require_full_match_{group_key}",
    )
    target_resolution = _resolve_attribute_group_swap_targets(project, scope, selected_route_id)
    target_line_ids = target_resolution["target_line_ids"]
    st.caption(f"Target scope: {_attribute_group_swap_scope_label(scope)}")
    if target_resolution.get("route_id"):
        st.caption(
            f"Scene: {target_resolution.get('route_label') or '(unnamed)'} "
            f"({target_resolution.get('route_line_count') or len(target_line_ids)} illustrations)"
        )
    st.caption(f"Target illustrations: {len(target_line_ids)}")
    for warning in target_resolution.get("warnings", [])[:3]:
        st.warning(warning)

    preview_signature = {
        "group_key": group_key,
        "previous_tokens": tuple(previous_tokens),
        "tokens_to_propagate": tuple(tokens_to_propagate),
        "scope": scope,
        "selected_route_id": selected_route_id,
        "target_line_ids": tuple(target_line_ids),
        "require_full_match": bool(require_full_match),
    }

    validation_error = None
    if not previous_tokens:
        validation_error = "Previous group tokens are required for propagation matching."
    elif not tokens_to_propagate:
        validation_error = "Tokens to propagate are required."
    elif not target_line_ids:
        validation_error = "Target Illustrationがありません。"
    if validation_error:
        st.warning(validation_error)

    if st.button(
        "Preview Propagate Added Tokens",
        key=f"attribute_group_propagate_preview_btn_{group_key}",
        disabled=bool(validation_error),
    ):
        st.session_state.attribute_group_propagate_preview = {
            "signature": preview_signature,
            "preview": preview_propagate_attribute_group_tokens(
                project,
                selected_group,
                previous_tokens,
                tokens_to_propagate,
                target_line_ids=target_line_ids,
                require_full_match=require_full_match,
            ),
        }

    preview_state = st.session_state.get("attribute_group_propagate_preview")
    preview_current = preview_state and preview_state.get("signature") == preview_signature
    if preview_state and not preview_current:
        st.caption("Propagate Added Tokens preview is stale. Preview again before applying.")
    if not preview_current:
        return

    preview = preview_state["preview"]
    for warning in preview.get("warnings", []):
        st.warning(warning)

    metric_cols = st.columns(4)
    metric_cols[0].metric("Target", preview["target_line_count"])
    metric_cols[1].metric("Matched", preview["matched_line_count"])
    metric_cols[2].metric("Affected", preview["affected_line_count"])
    metric_cols[3].metric("No match", preview["no_match_line_count"])
    st.caption(f"Already present tokens: {_short_preview(', '.join(preview['already_present_tokens']) or '(none)', 180)}")
    if preview["affected_line_count"] == 0:
        st.info("Propagate Added Tokensで変更されるイラストはありません。")

    if st.button(
        "Apply Propagate Added Tokens",
        key=f"attribute_group_propagate_apply_btn_{group_key}",
        type="primary",
        disabled=preview["affected_line_count"] == 0,
    ):
        push_history()
        prev_focus = st.session_state.get("focused_line_id")
        st.session_state.project = apply_propagate_attribute_group_tokens(
            st.session_state.project,
            selected_group,
            previous_tokens,
            tokens_to_propagate,
            target_line_ids=target_line_ids,
            require_full_match=require_full_match,
        )
        restore_focus_after_graph_update(prev_focus)
        sync_text_areas()
        st.session_state.pop("attribute_group_propagate_preview", None)
        st.session_state.attribute_group_inspector_notice = (
            f"Propagated added tokens to {preview['affected_line_count']} line(s)."
        )
        save_current_project_if_possible("attribute group added tokens propagated")
        st.rerun()

    st.markdown("**Propagate Examples**")
    for example in preview.get("examples", [])[:10]:
        st.markdown(f"**{example['display_id']}**")
        st.caption(
            f"Illustration id: `{example['line_id']}` / index: {example['line_index']} / "
            f"matched: {_short_preview(', '.join(example['matched_previous_tokens']), 160)}"
        )
        st.caption(f"Added: {_short_preview(', '.join(example['added_tokens']) or '(none)', 160)}")
        st.caption("Before")
        render_batch_preview_text(
            example["before"],
            "attribute_group_propagate",
            "",
            "exact_token",
            "exact_token",
            highlight=False,
        )
        st.caption("After")
        render_batch_preview_text(
            example["after"],
            "attribute_group_propagate",
            "",
            "exact_token",
            "exact_token",
            highlight=False,
        )

def render_attribute_group_inspector_section(project):
    with st.expander("Attribute Group Inspector", expanded=False):
        if not project:
            st.info("Load project first.")
            return
        if is_free():
            st.info("Attribute Group Inspector is available in Pro.")
            return

        notice = st.session_state.pop("attribute_group_inspector_notice", "")
        if notice:
            st.success(notice)

        groups = get_project_attribute_groups(project)
        group_names = sorted(groups)
        if not group_names:
            st.info("Create an attribute group from selected PromptCloud tokens first.")
            return

        selected_key_state = st.session_state.get("attribute_group_inspector_selected")
        if selected_key_state and selected_key_state not in group_names:
            st.session_state.attribute_group_inspector_selected = group_names[0]

        selected_group = st.selectbox(
            "Attribute group",
            options=group_names,
            format_func=lambda key: groups[key].get("name", key),
            key="attribute_group_inspector_selected",
        )
        group = groups[selected_group]
        group_key = normalize_attribute_group_name(selected_group)
        current_group_name = group.get("name", selected_group)
        st.caption(f"Group: {group.get('name', selected_group)}")
        st.caption(f"Key: `{group_key}`")
        st.caption(f"Slot: `{group.get('slot', '')}`")
        st.caption(f"Created from: {group.get('created_from', 'unknown')}")

        rows = get_attribute_group_rows(project, selected_group)
        if not rows:
            st.info("This attribute group has no tokens.")

        st.markdown("**Rename**")
        rename_value = st.text_input(
            "Group display/name",
            value=current_group_name,
            key=f"attribute_group_rename_input_{group_key}",
        ).strip()
        normalized_rename = normalize_attribute_group_name(rename_value)
        rename_error = None
        if not rename_value:
            rename_error = "Group name cannot be empty."
        elif not normalized_rename:
            rename_error = "Use a group name with letters, numbers, underscores, hyphens, or spaces."
        elif normalized_rename != group_key and normalized_rename in groups:
            rename_error = "An attribute group with that name already exists."
        if rename_error:
            st.caption(rename_error)
        if st.button(
            "Rename Group",
            key=f"attribute_group_rename_btn_{group_key}",
            disabled=bool(rename_error) or (normalized_rename == group_key and rename_value == str(current_group_name or "").strip()),
        ):
            if rename_error:
                st.warning(rename_error)
                st.stop()
            push_history()
            renamed_key = rename_attribute_group(st.session_state.project, selected_group, rename_value)
            if not renamed_key:
                st.warning("Attribute group could not be renamed.")
                st.stop()
            st.session_state.attribute_group_inspector_selected = renamed_key
            st.session_state.attribute_group_inspector_notice = f"Renamed attribute group to {rename_value}."
            st.rerun()

        st.markdown("**Slot**")
        current_slot = group.get("slot", "")
        suggested_non_custom_slots = [slot for slot in SUGGESTED_ATTRIBUTE_SLOTS if slot != "custom"]
        slot_options = list(suggested_non_custom_slots)
        if current_slot and current_slot not in slot_options:
            slot_options.append(current_slot)
        slot_options.append("custom")
        default_slot_index = slot_options.index(current_slot) if current_slot in slot_options else slot_options.index("custom")
        selected_slot = st.selectbox(
            "Slot",
            options=slot_options,
            index=default_slot_index,
            key=f"attribute_group_slot_edit_select_{group_key}_{current_slot}",
        )
        custom_slot_default = current_slot if current_slot not in suggested_non_custom_slots else ""
        custom_slot = st.text_input(
            "Custom Slot",
            value=custom_slot_default,
            key=f"attribute_group_slot_edit_custom_{group_key}_{current_slot}",
            placeholder="optional_custom_slot",
        ).strip()
        slot_to_apply = custom_slot if selected_slot == "custom" else selected_slot
        normalized_slot = normalize_attribute_slot(slot_to_apply)
        slot_error = None
        if not slot_to_apply:
            slot_error = "Slot cannot be empty."
        elif not normalized_slot:
            slot_error = "Use a slot name with letters, numbers, underscores, hyphens, or spaces."
        if slot_error:
            st.caption(slot_error)
        if st.button(
            "Save Slot",
            key=f"attribute_group_slot_save_btn_{group_key}",
            disabled=bool(slot_error) or normalized_slot == current_slot,
        ):
            if slot_error:
                st.warning(slot_error)
                st.stop()
            push_history()
            if not set_attribute_group_slot(st.session_state.project, selected_group, slot_to_apply):
                st.warning("Attribute group slot could not be updated.")
                st.stop()
            st.session_state.attribute_group_inspector_notice = f"Updated slot to {normalized_slot}."
            st.rerun()

        st.markdown("**Included Tokens**")
        kept_tokens = []
        if rows:
            header_cols = st.columns([0.7, 2.1, 1.4])
            header_cols[0].caption("Keep")
            header_cols[1].caption("Token")
            header_cols[2].caption("Label")
            for row_index, row in enumerate(rows):
                token_key = row.get("token_key") or row.get("token", "")
                token_key_safe = normalize_attribute_group_name(token_key) or f"row_{row_index}"
                row_cols = st.columns([0.7, 2.1, 1.4])
                keep_row = row_cols[0].checkbox(
                    "Keep",
                    value=True,
                    key=f"attribute_group_keep_{group_key}_{row_index}_{token_key_safe}",
                    label_visibility="collapsed",
                )
                row_cols[1].markdown(f"`{row['token']}`")
                row_cols[2].markdown(f"`{row['attribute_label']}`")
                if keep_row:
                    kept_tokens.append(row["token"])
            if not kept_tokens:
                st.warning("Attribute Groups cannot be saved with zero tokens. Delete the group instead.")
            if st.button(
                "Save Token Membership",
                key=f"attribute_group_membership_save_btn_{group_key}",
                disabled=not kept_tokens or kept_tokens == [row["token"] for row in rows],
            ):
                if not kept_tokens:
                    st.warning("Attribute Groups cannot be saved with zero tokens. Delete the group instead.")
                    st.stop()
                push_history()
                if not set_attribute_group_tokens(st.session_state.project, selected_group, kept_tokens):
                    st.warning("Attribute group tokens could not be updated.")
                    st.stop()
                st.session_state.attribute_group_inspector_notice = f"Updated token membership for {group.get('name', selected_group)}."
                st.rerun()

        render_attribute_group_add_tokens_and_propagate(project, selected_group, group, rows)

        if rows:
            st.markdown("**Token Attribute Labels**")
            st.caption("Attribute labels are shared per normalized token. Changes here may affect the same token in other groups.")
            add_group_custom_suggestions = st.checkbox(
                "Add custom labels to project suggestions",
                value=True,
                key=f"attribute_group_label_add_custom_suggestions_{group_key}",
            )
            label_rows = []
            label_header_cols = st.columns([2.0, 1.3, 1.6, 1.6])
            label_header_cols[0].caption("Token")
            label_header_cols[1].caption("Current")
            label_header_cols[2].caption("New Label")
            label_header_cols[3].caption("Custom")
            for row_index, row in enumerate(rows):
                token = row["token"]
                current_label = row["attribute_label"]
                token_key = row.get("token_key") or token
                token_key_safe = normalize_attribute_group_name(token_key) or f"row_{row_index}"
                label_options = get_attribute_label_options(project, [current_label])
                selected_index = label_options.index(current_label) if current_label in label_options else 0
                row_cols = st.columns([2.0, 1.3, 1.6, 1.6])
                row_cols[0].markdown(f"`{token}`")
                row_cols[1].markdown(f"`{current_label}`")
                selected_label = row_cols[2].selectbox(
                    "New Label",
                    options=label_options,
                    index=selected_index,
                    key=f"attribute_group_label_select_{group_key}_{row_index}_{token_key_safe}",
                    label_visibility="collapsed",
                )
                custom_label = row_cols[3].text_input(
                    "Custom",
                    value="",
                    key=f"attribute_group_label_custom_{group_key}_{row_index}_{token_key_safe}",
                    placeholder="optional_custom_label",
                    label_visibility="collapsed",
                ).strip()
                label_rows.append((token_key, custom_label or selected_label, custom_label))

            if st.button(
                "Save Token Attribute Labels",
                type="primary",
                key=f"attribute_group_label_save_btn_{group_key}",
            ):
                push_history()
                changed_keys = []
                usage_labels = []
                custom_labels_to_add = []
                for token_key, label_to_apply, custom_label in label_rows:
                    row_changed_keys = set_token_attribute_label(
                        st.session_state.project,
                        token_key,
                        label_to_apply,
                    )
                    changed_keys.extend(row_changed_keys)
                    if row_changed_keys and label_to_apply != ATTRIBUTE_LABEL_UNASSIGNED:
                        usage_labels.extend([label_to_apply] * len(row_changed_keys))
                    if custom_label:
                        custom_labels_to_add.append(custom_label)
                added_labels = []
                if add_group_custom_suggestions:
                    added_labels = add_project_custom_attribute_labels(
                        st.session_state.project,
                        custom_labels_to_add,
                    )
                if usage_labels:
                    increment_attribute_label_usage_counts(st.session_state.project, usage_labels)
                changed_count = len(set(changed_keys))
                if changed_count or added_labels:
                    st.session_state.attribute_group_inspector_notice = (
                        f"Updated attribute labels for {changed_count} token(s). "
                        f"Added {len(added_labels)} custom suggestion(s)."
                    )
                else:
                    st.session_state.attribute_group_inspector_notice = "No token attribute labels changed."
                st.rerun()

        st.markdown("**Negative Attribute Metadata**")
        st.caption("Metadata only. These tags are not applied to prompts yet.")
        current_negative_tags = group.get("negative_tags", [])
        current_negative_when_disabled = group.get("negative_when_disabled", [])
        current_negative_notes = str(group.get("negative_notes", "") or "")
        negative_tags_text = st.text_area(
            "Negative tags",
            value=_format_comma_tags(current_negative_tags),
            key=f"attribute_group_negative_tags_{group_key}",
            height=70,
            placeholder="ribbon, hairclip",
        )
        negative_when_disabled_text = st.text_area(
            "Negative when disabled",
            value=_format_comma_tags(current_negative_when_disabled),
            key=f"attribute_group_negative_when_disabled_{group_key}",
            height=70,
            placeholder="ribbon, hairclip",
        )
        negative_notes = st.text_area(
            "Negative notes",
            value=current_negative_notes,
            key=f"attribute_group_negative_notes_{group_key}",
            height=80,
            placeholder="LoRA tends to reintroduce hairclip in bath scenes.",
        ).strip()
        parsed_negative_tags = _parse_comma_tags(negative_tags_text)
        parsed_negative_when_disabled = _parse_comma_tags(negative_when_disabled_text)
        negative_metadata_changed = (
            parsed_negative_tags != list(current_negative_tags or [])
            or parsed_negative_when_disabled != list(current_negative_when_disabled or [])
            or negative_notes != current_negative_notes
        )
        preview_positive_tags = [row["token"] for row in rows] if rows else []
        st.table([
            {
                "Metadata": "positive/group tags",
                "Tags": _short_preview(", ".join(preview_positive_tags), 160),
                "Applied now": "current group tokens only",
            },
            {
                "Metadata": "negative_tags",
                "Tags": _short_preview(", ".join(parsed_negative_tags), 160),
                "Applied now": "no",
            },
            {
                "Metadata": "negative_when_disabled",
                "Tags": _short_preview(", ".join(parsed_negative_when_disabled), 160),
                "Applied now": "no",
            },
        ])
        if st.button(
            "Save Negative Metadata",
            key=f"attribute_group_negative_metadata_save_{group_key}",
            disabled=not negative_metadata_changed,
        ):
            push_history()
            if not set_attribute_group_negative_metadata(
                st.session_state.project,
                selected_group,
                parsed_negative_tags,
                parsed_negative_when_disabled,
                negative_notes,
            ):
                st.warning("Attribute group negative metadata could not be updated.")
                st.stop()
            st.session_state.attribute_group_inspector_notice = (
                "Updated negative metadata. Metadata only; prompts and negative prompts were not changed."
            )
            st.rerun()

        with st.expander("NegativeAttribute Preview", expanded=False):
            st.caption("Preview only. No prompts or negative prompts are changed.")
            preview_line = get_selected_line_for_attribute_preview(project)
            if not preview_line:
                st.info("Select or focus a line to preview disabled-state negative behavior.")
            else:
                preview = build_attribute_group_negative_preview(project, selected_group, preview_line)
                if not preview:
                    st.info("No preview is available for this Attribute Group.")
                else:
                    st.caption(f"Selected line: `{preview['line_label']}`")
                    st.caption("If this Attribute Group were disabled in the selected line:")
                    preview_rows = [
                        {
                            "Area": "positive/group tokens",
                            "Tokens": _short_preview(", ".join(preview["group_tokens"]), 180),
                        },
                        {
                            "Area": "found in selected line",
                            "Tokens": _short_preview(", ".join(preview["found_positive_tokens"]), 180),
                        },
                        {
                            "Area": "missing in selected line",
                            "Tokens": _short_preview(", ".join(preview["missing_positive_tokens"]), 180),
                        },
                        {
                            "Area": "negative_tags metadata",
                            "Tokens": _short_preview(", ".join(preview["negative_tags"]), 180),
                        },
                        {
                            "Area": "negative_when_disabled metadata",
                            "Tokens": _short_preview(", ".join(preview["negative_when_disabled"]), 180),
                        },
                        {
                            "Area": "existing per-line negative",
                            "Tokens": _short_preview(", ".join(preview["existing_negative_tokens"]), 180),
                        },
                        {
                            "Area": "new negative tokens",
                            "Tokens": _short_preview(", ".join(preview["new_negative_tokens"]), 180),
                        },
                    ]
                    st.table(preview_rows)
                    if not preview["negative_when_disabled"]:
                        st.info("No disabled-state negative tags are defined for this group.")
                    if preview["effective_negative_preview"]:
                        st.markdown("**Effective negative preview**")
                        st.code(preview["effective_negative_preview"], language="text")
                    else:
                        st.caption("Effective negative preview is empty.")

        selected_node_ids = [
            nid for nid in st.session_state.get("selected_node_ids", [])
            if nid in getattr(project, "nodes", {})
        ]
        selection_reset_nonce = st.session_state.get("promptcloud_selection_reset_nonce", 0)
        selected_signature = "_".join(nid.replace(":", "_").replace("-", "_") for nid in selected_node_ids)
        selected_tokens_preview = [
            getattr(project.nodes[nid], "display", "")
            or getattr(project.nodes[nid], "word", "")
            or getattr(project.nodes[nid], "original", "")
            for nid in selected_node_ids
        ]
        if selected_tokens_preview:
            st.caption(f"Selected PromptCloud tokens: {_short_preview(', '.join(selected_tokens_preview), 120)}")
        if st.button(
            "Add Selected Tokens to Group",
            key=f"attribute_group_add_selected_{group_key}_{selection_reset_nonce}_{selected_signature}",
            disabled=not selected_node_ids,
        ):
            if not selected_node_ids:
                st.warning("Select PromptCloud tokens before adding them to this group.")
                st.stop()
            existing_token_keys = {
                row.get("token_key") or row.get("token", "")
                for row in get_attribute_group_rows(project, selected_group)
            }
            selected_new_token_keys = {
                get_node_attribute_key(project, nid)
                for nid in selected_node_ids
                if get_node_attribute_key(project, nid)
            }
            new_token_count = len(selected_new_token_keys - existing_token_keys)
            if not new_token_count:
                st.info("No new tokens were added. Selected tokens may already be in this group.")
                st.stop()
            push_history()
            added_count = add_nodes_to_attribute_group(st.session_state.project, selected_group, selected_node_ids)
            st.session_state.attribute_group_inspector_notice = f"Added {added_count} selected token(s) to {group.get('name', selected_group)}."
            st.rerun()

        st.markdown("**Delete**")
        confirm_delete = st.checkbox(
            "Confirm delete this Attribute Group",
            key=f"attribute_group_delete_confirm_{group_key}",
        )
        if st.button(
            "Delete Group",
            key=f"attribute_group_delete_btn_{group_key}",
            disabled=not confirm_delete,
        ):
            if not confirm_delete:
                st.warning("Confirm deletion before deleting this Attribute Group.")
                st.stop()
            push_history()
            if not delete_attribute_group(st.session_state.project, selected_group):
                st.warning("Attribute group could not be deleted.")
                st.stop()
            st.session_state.pop("attribute_group_inspector_selected", None)
            st.session_state.attribute_group_inspector_notice = f"Deleted attribute group {group.get('name', selected_group)}."
            st.rerun()


