def prepare_module_candidate_selection_widget_state(
    module_names,
) -> str:
    durable_key = "module_candidate_selection_name"
    widget_key = "_module_candidate_selection_name_widget"
    durable_name = st.session_state.get(durable_key)
    durable_repaired = durable_name not in module_names
    if durable_repaired:
        durable_name = module_names[0]
        st.session_state[durable_key] = durable_name

    st.session_state[widget_key] = durable_name
    return durable_name


def sync_module_candidate_selection_widget_state() -> None:
    widget_name = st.session_state.get("_module_candidate_selection_name_widget")
    if widget_name:
        st.session_state.module_candidate_selection_name = widget_name


def prepare_module_candidate_core_tokens_widget_state(
    module_name,
    module_tokens,
    current_core_tokens,
) -> list:
    durable_key = f"module_candidate_core_tokens_{module_name}"
    widget_key = f"_module_candidate_core_tokens_widget_{module_name}"
    durable_exists = durable_key in st.session_state
    durable_value = st.session_state.get(durable_key)
    if not durable_exists or not isinstance(durable_value, (list, tuple)):
        durable_tokens = list(current_core_tokens)
    else:
        durable_tokens = [
            token for token in durable_value if token in module_tokens
        ]
        if durable_value and not durable_tokens:
            durable_tokens = list(current_core_tokens)
    st.session_state[durable_key] = durable_tokens

    st.session_state[widget_key] = list(durable_tokens)
    return durable_tokens


def sync_module_candidate_core_tokens_widget_state(module_name) -> None:
    widget_key = f"_module_candidate_core_tokens_widget_{module_name}"
    durable_key = f"module_candidate_core_tokens_{module_name}"
    st.session_state[durable_key] = list(
        st.session_state.get(widget_key, [])
    )


def prepare_module_candidate_min_match_widget_state(
    module_name,
    module_tokens,
    current_min_match,
) -> int:
    durable_key = f"module_candidate_min_match_tokens_{module_name}"
    widget_key = f"_module_candidate_min_match_tokens_widget_{module_name}"
    durable_value = st.session_state.get(durable_key, current_min_match)
    try:
        durable_min_match = int(durable_value)
    except (TypeError, ValueError):
        durable_min_match = int(current_min_match)
    normalized_min_match = max(
        1,
        min(durable_min_match, len(module_tokens)),
    )
    durable_min_match = normalized_min_match
    st.session_state[durable_key] = durable_min_match

    st.session_state[widget_key] = durable_min_match
    return durable_min_match


def sync_module_candidate_min_match_widget_state(module_name) -> None:
    widget_key = f"_module_candidate_min_match_tokens_widget_{module_name}"
    durable_key = f"module_candidate_min_match_tokens_{module_name}"
    st.session_state[durable_key] = int(st.session_state[widget_key])


def render_module_candidate_selection_section(project):
    with st.expander("Module Candidate Selection", expanded=False):
        if not project:
            st.info("Load project first.")
            return
        if is_free():
            st.info("Module Candidate Selection is available in Pro.")
            return

        module_library = get_project_module_library(project)
        module_names = sorted(module_library)
        if not module_names:
            st.info("Create or load a project module before previewing candidates.")
            return

        st.caption("Preview prompt lines that could become candidates for a saved module.")
        pending_module = st.session_state.get("pending_module_candidate_selection")
        if pending_module in module_names:
            if st.session_state.get("module_candidate_pending_applied") != pending_module:
                st.session_state.module_candidate_selection_name = pending_module
                st.session_state._module_candidate_selection_name_widget = (
                    pending_module
                )
                st.session_state.module_candidate_pending_applied = pending_module
            st.info(
                f"Recently created module: `{pending_module}`. "
                "Preview candidate lines and apply only after checking before/after results."
            )
        prepare_module_candidate_selection_widget_state(module_names)
        module_name = st.selectbox(
            "Project module",
            options=module_names,
            key="_module_candidate_selection_name_widget",
            on_change=sync_module_candidate_selection_widget_state,
        )
        module_body = get_module_body(module_library, module_name)
        module_tokens = [token for token in parse_prompt(module_body) if token.strip()]
        if not module_tokens:
            st.info("This module has no tokens to match.")
            return

        current_core_tokens = [
            token
            for token in get_module_core_tokens(module_library, module_name)
            if token in module_tokens
        ]
        if not current_core_tokens:
            current_core_tokens = module_tokens[:1]
        current_min_match = get_module_min_match_tokens(module_library, module_name)
        current_min_match = max(1, min(current_min_match, len(module_tokens)))

        st.caption(f"Module body: `{_short_preview(module_body, 140)}`")
        prepare_module_candidate_core_tokens_widget_state(
            module_name,
            module_tokens,
            current_core_tokens,
        )
        core_tokens = st.multiselect(
            "Core Tokens",
            options=module_tokens,
            key=f"_module_candidate_core_tokens_widget_{module_name}",
            on_change=sync_module_candidate_core_tokens_widget_state,
            args=(module_name,),
        )
        prepare_module_candidate_min_match_widget_state(
            module_name,
            module_tokens,
            current_min_match,
        )
        min_match_tokens = st.number_input(
            "Minimum Matched Tokens",
            min_value=1,
            max_value=len(module_tokens),
            step=1,
            key=f"_module_candidate_min_match_tokens_widget_{module_name}",
            on_change=sync_module_candidate_min_match_widget_state,
            args=(module_name,),
        )
        st.caption("Illustrations missing any core token are excluded before the minimum match threshold is checked.")

        save_cols = st.columns(2)
        with save_cols[0]:
            if st.button("Save Rules", key="module_candidate_save_rules_btn"):
                push_history()
                saved = set_module_candidate_rules(
                    st.session_state.project,
                    module_name,
                    core_tokens,
                    min_match_tokens,
                )
                if not saved:
                    st.warning("Candidate rules could not be saved.")
                    st.stop()
                st.success("Candidate rules saved.")
        with save_cols[1]:
            if st.button("Preview Candidates", key="module_candidate_preview_btn"):
                st.session_state.pop("pending_module_candidate_selection", None)
                st.session_state.module_candidate_preview = {
                    "signature": {
                        "module_name": module_name,
                        "core_tokens": tuple(core_tokens),
                        "min_match_tokens": int(min_match_tokens),
                    },
                    "preview": preview_module_candidates(
                        project,
                        module_name,
                        core_tokens=core_tokens,
                        min_match_tokens=int(min_match_tokens),
                    ),
                }

        preview_state = st.session_state.get("module_candidate_preview")
        preview_signature = {
            "module_name": module_name,
            "core_tokens": tuple(core_tokens),
            "min_match_tokens": int(min_match_tokens),
        }
        preview_current = (
            preview_state
            and preview_state.get("signature") == preview_signature
        )
        if not preview_current:
            if preview_state:
                st.caption("Candidate preview is out of date. Run preview again.")
            return

        preview = preview_state["preview"]
        st.metric("Candidate lines", preview["total_candidate_count"])
        st.caption(f"Core: {_short_preview(', '.join(preview['core_tokens']), 120)}")
        st.caption(f"Minimum match: {preview['min_match_tokens']}/{len(preview['module_tokens'])} tokens")

        if preview["total_candidate_count"] == 0:
            st.info("No prompt lines match these candidate rules.")
            return

        for example in preview["examples"]:
            ratio = round(example["match_ratio"] * 100)
            st.markdown(f"**{example['display_id']}**")
            st.caption(
                f"Score: {example['matched_count']}/{example['total_token_count']} ({ratio}%)"
            )
            st.caption(f"Matched: {_short_preview(', '.join(example['matched_tokens']), 160)}")
            if example["missing_tokens"]:
                st.caption(f"Missing: {_short_preview(', '.join(example['missing_tokens']), 160)}")
            st.caption(f"Text: {_short_preview(example['text'], 180)}")

        st.divider()
        st.caption("Preview Apply replaces only matched module tokens with the module reference. Missing tokens are not inserted.")
        if st.button("Preview Apply Candidates", key="module_candidate_apply_preview_btn"):
            st.session_state.module_candidate_apply_preview = {
                "signature": preview_signature,
                "preview": preview_apply_module_candidates(
                    project,
                    module_name,
                    core_tokens=core_tokens,
                    min_match_tokens=int(min_match_tokens),
                ),
            }

        apply_preview_state = st.session_state.get("module_candidate_apply_preview")
        apply_preview_current = (
            apply_preview_state
            and apply_preview_state.get("signature") == preview_signature
        )
        if not apply_preview_current:
            if apply_preview_state:
                st.caption("Apply preview is out of date. Run preview apply again.")
            return

        apply_preview = apply_preview_state["preview"]
        apply_cols = st.columns(4)
        apply_cols[0].metric("Candidates", apply_preview["candidate_line_count"])
        apply_cols[1].metric("Will change", apply_preview["affected_line_count"])
        apply_cols[2].metric("Already referenced", apply_preview["skipped_existing_reference_count"])
        apply_cols[3].metric("Module blocks skipped", apply_preview["skipped_existing_module_block_count"])
        st.caption(f"Reference: `{apply_preview['module_reference']}`")

        if apply_preview["affected_line_count"] == 0:
            st.info("No candidate lines will change.")
            return

        for example in apply_preview["examples"]:
            ratio = round(example["match_ratio"] * 100)
            st.markdown(f"**{example['display_id']}**")
            st.caption(f"Score: {example['matched_count']}/{example['total_token_count']} ({ratio}%)")
            st.caption(f"Matched to replace: {_short_preview(', '.join(example['matched_tokens']), 160)}")
            if example["missing_tokens"]:
                st.caption(f"Missing, not inserted: {_short_preview(', '.join(example['missing_tokens']), 160)}")
            st.caption(f"Before: {_short_preview(example['before'], 180)}")
            st.caption(f"After: {_short_preview(example['after'], 180)}")

        if st.button(
            "Confirm Apply Candidates",
            type="primary",
            key="module_candidate_apply_confirm_btn",
        ):
            push_history()
            prev_focus = st.session_state.get("focused_line_id")
            st.session_state.project = apply_module_candidates(
                st.session_state.project,
                module_name,
                core_tokens=core_tokens,
                min_match_tokens=int(min_match_tokens),
            )
            restore_focus_after_graph_update(prev_focus)
            sync_text_areas()
            st.session_state.pop("module_candidate_preview", None)
            st.session_state.pop("module_candidate_apply_preview", None)
            st.rerun()


def render_module_toggle_controls(project) -> None:
    with st.expander("Module Toggles", expanded=False):
        if project:
            available_modules = get_available_modules(project)
            if available_modules:
                st.caption(
                    "Enable or disable module references for active prompt "
                    "previews and generation."
                )
                for mod_id in available_modules:
                    current_val = (
                        mod_id not in st.session_state.disabled_modules
                    )
                    new_val = st.checkbox(
                        f"Module {mod_id}",
                        value=current_val,
                        key=f"mod_toggle_{mod_id}",
                    )
                    if new_val != current_val:
                        if new_val:
                            st.session_state.disabled_modules.discard(mod_id)
                        else:
                            st.session_state.disabled_modules.add(mod_id)
                        st.rerun()
            else:
                st.info("No modules detected.")
        else:
            st.info("Load project first.")


