    project = st.session_state.get("project")
    st.info(
        "Focused production controls. Module Toggles, Saved Module Reference "
        "Insertion, Module Candidate Selection, and Attribute Group Swap are "
        "available here. Module Edit Scope remains in Sidebar Analysis. "
        "Broader contextual Apply inspection ownership remains future work."
    )
    render_module_toggle_controls(project)
    render_insert_saved_module_reference_section(project)
    render_module_candidate_selection_section(project)
    render_attribute_group_swap_section(project)


