def validate_highlighted_line():
    project = st.session_state.get("project")
    highlighted_line_id = st.session_state.get("highlighted_line_id")
    if highlighted_line_id and not get_line_by_id(project, highlighted_line_id):
        st.session_state.highlighted_line_id = None

def render_scope_status_bar(project):
    if not project:
        st.caption("Scope | プロジェクト未読み込み")
        return

    module_scope_name = st.session_state.get("module_edit_scope_name")
    if module_scope_name and module_scope_name not in get_available_modules(project):
        clear_module_edit_scope()
        module_scope_name = None

    selected_count = sum(
        1
        for nid in st.session_state.get("selected_node_ids", [])
        if nid in getattr(project, "nodes", {})
    )

    focused_line_id = st.session_state.get("focused_line_id")
    focused_line = get_line_by_id(project, focused_line_id)
    if focused_line_id and not focused_line:
        st.session_state.focused_line_id = None

    if focused_line:
        line_number = getattr(focused_line, "current_index", None)
        if line_number is None:
            line_label = focused_line.original_file_name
        else:
            line_label = f"{focused_line.original_file_name}:{line_number + 1}"
    else:
        line_label = "Global"

    edition_label = "Lite" if is_free() else "Pro"
    module_label = module_scope_name if module_scope_name else "None"
    token_label = "token" if selected_count == 1 else "tokens"
    st.caption(
        f"Scope | Edition: {edition_label} | Tokens: {selected_count} selected {token_label} | "
        f"Illustration: {line_label} | Module: {module_label}"
    )

def get_neighborhood_node_ids(project, selected_node_ids, steps):
    if not project or not selected_node_ids or steps is None:
        return None

    valid_selected = [
        nid for nid in selected_node_ids
        if nid in getattr(project, "nodes", {})
    ]

    if not valid_selected:
        return set()

    forward = {}
    backward = {}

    for source, target in getattr(project, "edges", []):
        forward.setdefault(source, set()).add(target)
        backward.setdefault(target, set()).add(source)

    result = set(valid_selected)
    frontier = set(valid_selected)

    for _ in range(steps):
        next_frontier = set()
        for nid in frontier:
            next_frontier.update(forward.get(nid, set()))
            next_frontier.update(backward.get(nid, set()))
        next_frontier -= result
        result.update(next_frontier)
        frontier = next_frontier
        if not frontier:
            break

    return result

def clear_selected_nodes():
    st.session_state.selected_node_ids = []
    st.session_state.connect_nodes = []
    st.session_state.pop("selection_action_delete_preview", None)
    st.session_state.pop("selection_action_weight_preview", None)

def clear_promptcloud_selection_state():
    clear_selected_nodes()
    st.session_state.promptcloud_selection_reset_nonce += 1

def resolve_selection_action_target_lines():
    if is_free():
        return get_free_target_lines_or_block()

    focused_line_id = st.session_state.get("focused_line_id")
    if focused_line_id:
        return [focused_line_id]

    return None

def render_selected_token_attribute_labeler(project, selected_node_ids, free_mode=False):
    selected_nodes = [
        (nid, project.nodes[nid])
        for nid in selected_node_ids
        if nid in project.nodes
    ]
    if not selected_nodes:
        return

    notice = st.session_state.pop("node_attribute_label_notice", "")
    if notice:
        st.success(notice)

    st.markdown("**Selected Token Attribute Table**")
    st.caption("Assign a semantic label to each selected token. Labels are metadata only and do not change prompts, modules, generation, or export.")
    if free_mode:
        st.info("Selected Token Attributes are available in Pro.")
        return

    selection_reset_nonce = st.session_state.get("promptcloud_selection_reset_nonce", 0)
    selected_signature = "_".join(nid.replace(":", "_").replace("-", "_") for nid, _node in selected_nodes)
    widget_signature = f"{selection_reset_nonce}_{selected_signature}"
    selected_attribute_keys = [
        get_node_attribute_key(project, nid)
        for nid, _node in selected_nodes
    ]
    duplicate_attribute_keys = sorted({
        key
        for key in selected_attribute_keys
        if key and selected_attribute_keys.count(key) > 1
    })
    if duplicate_attribute_keys:
        duplicate_preview = ", ".join(f"`{key}`" for key in duplicate_attribute_keys[:5])
        more_note = " and more" if len(duplicate_attribute_keys) > 5 else ""
        st.warning(
            "Attribute labels are stored per normalized token, not per selected occurrence. "
            f"Duplicate selected rows share one label: {duplicate_preview}{more_note}."
        )
    custom_suggestions = get_project_custom_attribute_labels(project)
    if custom_suggestions:
        st.caption(f"Project custom suggestions: {', '.join(f'`{label}`' for label in custom_suggestions[:8])}")
    frequent_labels = get_frequent_attribute_labels(project, limit=8)
    if frequent_labels:
        st.caption(f"Frequently used labels: {', '.join(f'`{label}`' for label in frequent_labels)}")
    add_custom_suggestions = st.checkbox(
        "Add custom labels to project suggestions",
        value=True,
        key=f"selected_token_attr_add_custom_suggestions_{widget_signature}",
    )
    st.caption("Custom suggestions are project metadata. They only affect future label dropdowns.")
    table_rows = []
    header_cols = st.columns([2.2, 3.0, 2.0])
    header_cols[0].caption("Token")
    header_cols[1].caption("New Label")
    header_cols[2].caption("Custom")

    for row_index, (nid, node) in enumerate(selected_nodes):
        token = (
            getattr(node, "display", "")
            or getattr(node, "word", "")
            or getattr(node, "original", "")
        )
        current_label = get_node_attribute_label(project, nid)
        attribute_label_options = get_attribute_label_options(project, [current_label])
        selected_index = (
            attribute_label_options.index(current_label)
            if current_label in attribute_label_options
            else attribute_label_options.index(ATTRIBUTE_LABEL_UNASSIGNED)
        )
        token_key = get_node_attribute_key(project, nid)
        token_key_safe = normalize_attribute_group_name(token_key) or f"row_{row_index}"
        current_label_safe = normalize_attribute_group_name(current_label) or ATTRIBUTE_LABEL_UNASSIGNED
        row_key = f"{widget_signature}_{row_index}_{token_key_safe}_{current_label_safe}"
        row_cols = st.columns([2.2, 3.0, 2.0])
        row_cols[0].markdown(f"`{token}`")
        row_cols[0].caption(f"current: {current_label}")
        selected_label = row_cols[1].selectbox(
            "New Label",
            options=attribute_label_options,
            index=selected_index,
            key=f"selected_token_attr_label_{row_key}",
            label_visibility="collapsed",
        )
        custom_label = row_cols[2].text_input(
            "Custom",
            value="",
            key=f"selected_token_attr_custom_{row_key}",
            placeholder="optional_custom_label",
            label_visibility="collapsed",
        ).strip()
        table_rows.append((nid, custom_label or selected_label, custom_label))

    if st.button("Apply Per-token Attribute Labels", type="primary", key=f"selected_token_attr_table_apply_{widget_signature}"):
        push_history()
        changed_keys = []
        custom_labels_to_add = []
        usage_labels = []
        for nid, label_to_apply, custom_label in table_rows:
            row_changed_keys = set_node_attribute_label(st.session_state.project, [nid], label_to_apply)
            changed_keys.extend(row_changed_keys)
            if label_to_apply != ATTRIBUTE_LABEL_UNASSIGNED:
                usage_labels.extend([label_to_apply] * len(row_changed_keys))
            if custom_label:
                custom_labels_to_add.append(custom_label)
        added_labels = []
        if add_custom_suggestions:
            added_labels = add_project_custom_attribute_labels(st.session_state.project, custom_labels_to_add)
        if usage_labels:
            increment_attribute_label_usage_counts(st.session_state.project, usage_labels)
        changed_count = len(set(changed_keys))
        if changed_count or added_labels:
            st.session_state.node_attribute_label_notice = (
                f"Applied per-token attribute labels to {changed_count} token(s). "
                f"Added {len(added_labels)} custom suggestion(s)."
            )
        else:
            st.session_state.node_attribute_label_notice = "No token attribute labels changed."
        st.rerun()

def render_selected_token_batch_attribute_labeler(project, selected_node_ids, free_mode=False):
    selected_nodes = [
        (nid, project.nodes[nid])
        for nid in selected_node_ids
        if nid in project.nodes
    ]
    if not selected_nodes:
        return

    selection_reset_nonce = st.session_state.get("promptcloud_selection_reset_nonce", 0)
    selected_signature = "_".join(nid.replace(":", "_").replace("-", "_") for nid, _node in selected_nodes)
    widget_signature = f"{selection_reset_nonce}_{selected_signature}"

    with st.expander("Batch Set Attribute Label", expanded=False):
        st.caption("Optional batch operation: apply the same semantic label to every selected token.")
        if free_mode:
            st.info("Batch Set Attribute Label is available in Pro.")
            return

        selected_label = st.selectbox(
            "Attribute Label",
            options=get_attribute_label_options(project),
            index=0,
            key=f"node_attribute_label_select_{widget_signature}",
        )
        custom_label = st.text_input(
            "Custom Label",
            key=f"node_attribute_label_custom_{widget_signature}",
            placeholder="optional_custom_label",
        ).strip()
        label_to_apply = custom_label or selected_label
        add_batch_custom_suggestions = st.checkbox(
            "Add custom label to project suggestions",
            value=True,
            key=f"node_attribute_label_add_custom_suggestion_{widget_signature}",
        )

        if st.button("Apply Attribute Label", type="primary", key=f"node_attribute_label_apply_btn_{widget_signature}"):
            push_history()
            changed_keys = set_node_attribute_label(
                st.session_state.project,
                [nid for nid, _node in selected_nodes],
                label_to_apply,
            )
            added_labels = []
            if custom_label and add_batch_custom_suggestions:
                added_labels = add_project_custom_attribute_labels(st.session_state.project, [custom_label])
            if label_to_apply != ATTRIBUTE_LABEL_UNASSIGNED and changed_keys:
                increment_attribute_label_usage_counts(
                    st.session_state.project,
                    {label_to_apply: len(changed_keys)},
                )
            if not changed_keys and not added_labels:
                st.session_state.node_attribute_label_notice = "No token attribute labels changed."
            elif label_to_apply == ATTRIBUTE_LABEL_UNASSIGNED and not custom_label:
                st.session_state.node_attribute_label_notice = f"Cleared attribute labels for {len(changed_keys)} selected token(s)."
            else:
                applied_label = get_node_attribute_label(st.session_state.project, selected_nodes[0][0])
                st.session_state.node_attribute_label_notice = (
                    f"Applied '{applied_label}' to {len(changed_keys)} selected token(s). "
                    f"Added {len(added_labels)} custom suggestion(s)."
                )
            st.rerun()

def render_selected_token_attribute_group_builder(project, selected_node_ids, free_mode=False):
    selected_nodes = [
        (nid, project.nodes[nid])
        for nid in selected_node_ids
        if nid in project.nodes
    ]
    if not selected_nodes:
        return

    created_name = st.session_state.pop("attribute_group_created_name", "")
    if created_name:
        created_count = st.session_state.pop("attribute_group_created_count", None)
        if created_count is None:
            st.success(f"Created attribute group: {created_name}")
        else:
            st.success(f"Created attribute group: {created_name} ({created_count} included token(s))")
    if st.session_state.pop("attribute_group_reset", False):
        st.session_state.attribute_group_create_name = ""
        st.session_state.attribute_group_custom_slot = ""

    with st.expander("Create Attribute Group from Selected Tokens", expanded=False):
        st.caption("Package selected tokens into a named semantic slot. Attribute groups are metadata only and do not change prompts, modules, generation, or export.")
        if free_mode:
            st.info("Create Attribute Group is available in Pro.")
            return

        group_name = st.text_input(
            "Group Name",
            key="attribute_group_create_name",
            placeholder="Milk Normal Hair Style",
        ).strip()
        selected_slot = st.selectbox(
            "Slot",
            options=SUGGESTED_ATTRIBUTE_SLOTS,
            index=SUGGESTED_ATTRIBUTE_SLOTS.index("hair_style"),
            key="attribute_group_slot_select",
        )
        custom_slot = st.text_input(
            "Custom Slot",
            key="attribute_group_custom_slot",
            placeholder="optional_custom_slot",
        ).strip()
        slot_to_apply = custom_slot or selected_slot
        normalized_group_name = normalize_attribute_group_name(group_name)
        normalized_slot = normalize_attribute_slot(slot_to_apply)
        existing_groups = get_project_attribute_groups(project)

        selection_reset_nonce = st.session_state.get("promptcloud_selection_reset_nonce", 0)
        selected_signature = "_".join(nid.replace(":", "_").replace("-", "_") for nid, _node in selected_nodes)
        widget_signature = f"{selection_reset_nonce}_{selected_signature}"
        subset_rows = []

        st.caption("Selected Tokens")
        header_cols = st.columns([0.7, 2.4, 1.5])
        header_cols[0].caption("Use")
        header_cols[1].caption("Token")
        header_cols[2].caption("Current Label")
        for row_index, (nid, node) in enumerate(selected_nodes):
            token = getattr(node, "display", "") or getattr(node, "word", "") or getattr(node, "original", "")
            current_label = get_node_attribute_label(project, nid)
            row_cols = st.columns([0.7, 2.4, 1.5])
            include_token = row_cols[0].checkbox(
                "Use",
                value=True,
                key=f"attribute_group_include_{widget_signature}_{row_index}_{nid}",
                label_visibility="collapsed",
            )
            row_cols[1].markdown(f"`{token}`")
            row_cols[2].markdown(f"`{current_label}`")
            subset_rows.append((nid, token, current_label, include_token))

        included_node_ids = [nid for nid, _token, _label, include_token in subset_rows if include_token]
        if included_node_ids:
            st.caption(f"{len(included_node_ids)} of {len(subset_rows)} selected token(s) will be included.")
        else:
            st.warning("Select at least one token to create an Attribute Group.")

        validation_error = None
        if not included_node_ids:
            validation_error = "Select at least one token to include in the Attribute Group."
        elif group_name and not normalized_group_name:
            validation_error = "Use a group name with letters, numbers, underscores, hyphens, or spaces."
        elif group_name and normalized_group_name in existing_groups:
            validation_error = "An attribute group with that name already exists."
        elif selected_slot == "custom" and not custom_slot:
            validation_error = "Enter a custom slot name."
        elif slot_to_apply and not normalized_slot:
            validation_error = "Use a slot name with letters, numbers, underscores, hyphens, or spaces."

        if normalized_slot:
            st.caption(f"Slot: `{normalized_slot}`")
        if validation_error and included_node_ids:
            st.warning(validation_error)
        if not group_name:
            st.caption("Enter a group name, choose a slot, then confirm creation.")

        if st.button(
            "Confirm Create Attribute Group",
            type="primary",
            disabled=not group_name or not normalized_slot or bool(validation_error),
            key="attribute_group_create_confirm_btn",
        ):
            if not included_node_ids:
                st.warning("Select at least one token to include in the Attribute Group.")
                st.stop()
            if normalize_attribute_group_name(group_name) in get_project_attribute_groups(st.session_state.project):
                st.warning("An attribute group with that name already exists.")
                st.stop()
            push_history()
            group_key = create_attribute_group(
                st.session_state.project,
                group_name,
                slot_to_apply,
                included_node_ids,
            )
            if not group_key:
                st.warning("Attribute group could not be created. Check the name, slot, and selected tokens.")
                st.stop()
            st.session_state.attribute_group_created_name = group_name
            st.session_state.attribute_group_created_count = len(included_node_ids)
            st.session_state.attribute_group_reset = True
            st.rerun()

